def _incomplete_krx_daily_endpoints(counts: dict[str, int], endpoint_keys: tuple[str, ...]) -> list[str]:
    incomplete: list[str] = []
    for endpoint_key in endpoint_keys:
        count = counts.get(endpoint_key, 0)
        minimum = KRX_DAILY_BACKFILL_MIN_ROWS.get(endpoint_key, 1)
        if count < minimum:
            incomplete.append(endpoint_key)
    return incomplete
