def _news_intelligence_observation_run_payload(
    run: NewsIntelligenceRun,
    *,
    all_evidence: list[ReportLinkedNewsEvidenceRecord],
    evidence_per_run: int,
) -> dict[str, object]:
    derived_counts = _news_intelligence_observation_derived_counts(all_evidence)
    candidate_linkage_preview = _news_intelligence_candidate_linkage_preview(
        run,
        evidence_rows=all_evidence,
        derived_counts=derived_counts,
    )
    return {
        "run_id": run.run_id,
        "target_date": run.target_date.isoformat(),
        "stock_name": run.stock_name,
        "stock_code": run.stock_code,
        "aliases": list(run.aliases),
        "source_mode": run.source_mode,
        "page_limit": run.page_limit,
        "full_day_complete": run.full_day_complete,
        "live_fetch": run.live_fetch,
        "parsed_count": run.parsed_count,
        "deduped_count": run.deduped_count,
        "matched_count": run.matched_count,
        "warnings": list(run.warnings),
        "operator_summary_snapshot": run.operator_summary_snapshot,
        "created_at": run.created_at.isoformat(),
        "evidence_count": len(all_evidence),
        "derived_counts": derived_counts,
        "krx_reference_freshness": _news_intelligence_observation_krx_freshness(run, all_evidence),
        "candidate_linkage_hint": str(candidate_linkage_preview["label"]),
        "candidate_linkage_preview": candidate_linkage_preview,
        "candidate_linkage_evaluation": _news_intelligence_candidate_linkage_evaluation(
            run,
            evidence_rows=all_evidence,
            derived_counts=derived_counts,
        ),
        "evidence": [
            _news_intelligence_observation_evidence_payload(row)
            for row in all_evidence[: max(0, evidence_per_run)]
        ],
    }


def _news_intelligence_source_mode_coverage(
    run_payloads: list[dict[str, object]],
    evidence_rows: list[ReportLinkedNewsEvidenceRecord],
    *,
    boundary_payload: dict[str, object],
) -> dict[str, object]:
    source_modes = Counter(
        str(run.get("source_mode") or "unknown")
        for run in run_payloads
    )
    source_lanes = Counter(row.source_lane for row in evidence_rows)
    relevance = Counter(row.relevance for row in evidence_rows)
    for key in ("direct", "indirect", "market_context"):
        relevance.setdefault(key, 0)
    match_scope = Counter(row.match_scope for row in evidence_rows)
    krx_reference_status: Counter[str] = Counter()
    candidate_linkage_labels: Counter[str] = Counter()
    operator_recommendation_support: Counter[str] = Counter()
    for run in run_payloads:
        freshness = run.get("krx_reference_freshness")
        status = "none"
        if isinstance(freshness, dict):
            status = str(freshness.get("status") or "none")
        krx_reference_status[status] += 1
        evaluation = run.get("candidate_linkage_evaluation")
        if isinstance(evaluation, dict):
            label = str(evaluation.get("label") or "")
            recommendation_support = str(evaluation.get("recommendation_support") or "")
            if label:
                candidate_linkage_labels[label] += 1
            if recommendation_support:
                operator_recommendation_support[recommendation_support] += 1
    for key in ("exact", "stale_reference", "missing", "none"):
        krx_reference_status.setdefault(key, 0)
    return {
        "run_count": len(run_payloads),
        "evidence_count": len(evidence_rows),
        "source_modes": dict(sorted(source_modes.items())),
        "source_lanes": dict(sorted(source_lanes.items())),
        "relevance": {
            "direct": relevance["direct"],
            "indirect": relevance["indirect"],
            "market_context": relevance["market_context"],
        },
        "match_scope": dict(sorted(match_scope.items())),
        "krx_reference_status": {
            "exact": krx_reference_status["exact"],
            "stale_reference": krx_reference_status["stale_reference"],
            "missing": krx_reference_status["missing"],
            "none": krx_reference_status["none"],
        },
        "candidate_linkage_labels": dict(sorted(candidate_linkage_labels.items())),
        "operator_recommendation_support": dict(sorted(operator_recommendation_support.items())),
        "boundary": {
            "read_only": bool(boundary_payload.get("read_only")),
            "operator_only": bool(boundary_payload.get("operator_only")),
            "public_safe": bool(boundary_payload.get("public_safe")),
            "live_fetch": bool(boundary_payload.get("live_fetch")),
            "writes_db": bool(boundary_payload.get("writes_db")),
            "sends_telegram": bool(boundary_payload.get("sends_telegram")),
            "registers_scheduler": bool(boundary_payload.get("registers_scheduler")),
            "connects_web_view": bool(boundary_payload.get("connects_web_view")),
        },
    }


def _append_news_intelligence_source_mode_coverage_text(
    lines: list[str],
    payload: dict[str, object],
) -> None:
    coverage = payload.get("source_mode_coverage")
    if not isinstance(coverage, dict):
        return
    lines.append("")
    lines.append("source-mode coverage:")
    lines.append(
        f"runs {coverage.get('run_count', 0)} / evidence {coverage.get('evidence_count', 0)}"
    )
    lines.append(f"source_modes: {_news_intelligence_counter_text(coverage.get('source_modes'))}")
    lines.append(f"source_lanes: {_news_intelligence_counter_text(coverage.get('source_lanes'))}")
    lines.append(f"labels: {_news_intelligence_counter_text(coverage.get('candidate_linkage_labels'))}")
    lines.append(f"KRX: {_news_intelligence_counter_text(coverage.get('krx_reference_status'))}")


def _news_intelligence_counter_text(value: object) -> str:
    if not isinstance(value, dict) or not value:
        return "-"
    return ", ".join(f"{key}={value[key]}" for key in sorted(value))


def _news_intelligence_observation_derived_counts(
    evidence_rows: list[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    relevance = Counter(row.relevance for row in evidence_rows)
    for key in ("direct", "indirect", "market_context"):
        relevance.setdefault(key, 0)
    return {
        "relevance": {
            "direct": relevance["direct"],
            "indirect": relevance["indirect"],
            "market_context": relevance["market_context"],
        },
        "summary_only": sum(1 for row in evidence_rows if row.match_scope == "summary"),
        "evidence_case": dict(Counter(row.evidence_case for row in evidence_rows)),
        "operator_recommendation": dict(Counter(row.operator_recommendation for row in evidence_rows)),
    }


def _news_intelligence_observation_krx_freshness(
    run: NewsIntelligenceRun,
    evidence_rows: list[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    if not evidence_rows:
        return {
            "status": "none",
            "target_date": run.target_date.isoformat(),
            "krx_reference_date": None,
            "exact_date": False,
        }
    reference_dates = [row.krx_reference_date for row in evidence_rows if row.krx_reference_date is not None]
    if not reference_dates:
        return {
            "status": "missing",
            "target_date": run.target_date.isoformat(),
            "krx_reference_date": None,
            "exact_date": False,
        }
    reference_date = max(reference_dates)
    return _news_intelligence_krx_reference_freshness(
        target_date=run.target_date,
        krx_reference_date=reference_date,
    )


def _news_intelligence_candidate_linkage_hint(
    run: NewsIntelligenceRun,
    evidence_rows: list[ReportLinkedNewsEvidenceRecord],
    derived_counts: dict[str, object],
) -> str:
    return str(
        _news_intelligence_candidate_linkage_preview(
            run,
            evidence_rows=evidence_rows,
            derived_counts=derived_counts,
        )["label"]
    )


def _news_intelligence_candidate_linkage_preview(
    run: NewsIntelligenceRun,
    *,
    evidence_rows: list[ReportLinkedNewsEvidenceRecord],
    derived_counts: dict[str, object],
) -> dict[str, object]:
    krx_freshness = _news_intelligence_observation_krx_freshness(run, evidence_rows)
    relevance_counts = derived_counts["relevance"]
    direct_count = int(relevance_counts["direct"]) if isinstance(relevance_counts, dict) else 0
    market_context_count = int(relevance_counts["market_context"]) if isinstance(relevance_counts, dict) else 0
    support_only_count = sum(1 for row in evidence_rows if row.relevance in {"indirect", "market_context"})
    caution_count = sum(
        1
        for row in evidence_rows
        if row.operator_recommendation == "review_with_caution"
        or row.stock_impact == "Caution"
        or row.sentiment in {"Caution", "Mixed"}
        or "Risk/Caution" in row.event_types
    )
    candidate_priority_presence = any(row.candidate_priority_presence for row in evidence_rows)
    if krx_freshness["status"] == "stale_reference":
        label = "stale_krx_check_first"
        reason = "KRX reference is stale; verify market reaction before candidate linkage."
    elif run.matched_count <= 0 or not evidence_rows:
        label = "insufficient_news_evidence"
        reason = "No stored news evidence is available for candidate linkage."
    elif caution_count > 0:
        label = "review_with_caution"
        reason = "Caution or mixed news evidence should temper candidate review."
    elif direct_count <= 0:
        label = "support_only_context"
        reason = "News evidence is indirect or market context only; keep it as support."
    else:
        label = "strengthen_candidate"
        reason = "Direct news evidence can strengthen operator candidate review."
    return {
        "label": label,
        "candidate_priority_presence": candidate_priority_presence,
        "direct_count": direct_count,
        "caution_count": caution_count,
        "support_only_count": support_only_count,
        "market_context_count": market_context_count,
        "krx_reference_status": krx_freshness["status"],
        "reason": reason,
    }


def _news_intelligence_candidate_linkage_evaluation(
    run: NewsIntelligenceRun,
    *,
    evidence_rows: list[ReportLinkedNewsEvidenceRecord],
    derived_counts: dict[str, object],
) -> dict[str, object]:
    krx_freshness = _news_intelligence_observation_krx_freshness(run, evidence_rows)
    relevance_counts = derived_counts["relevance"]
    direct_count = int(relevance_counts["direct"]) if isinstance(relevance_counts, dict) else 0
    market_context_count = int(relevance_counts["market_context"]) if isinstance(relevance_counts, dict) else 0
    caution_count = sum(
        1
        for row in evidence_rows
        if row.operator_recommendation == "review_with_caution"
        or row.stock_impact == "Caution"
        or row.sentiment in {"Caution", "Mixed"}
        or "Risk/Caution" in row.event_types
    )
    candidate_priority_presence = any(row.candidate_priority_presence for row in evidence_rows)
    related_report_count = max((row.related_report_count for row in evidence_rows), default=0)
    if krx_freshness["status"] == "stale_reference":
        label = "stale_krx_check_first"
        recommendation_support = "check_krx_before_linking"
        reason_ko = "KRX 기준일이 대상일과 달라 후보 연결 전에 시장 반응 기준일을 먼저 확인해야 합니다."
    elif run.matched_count <= 0 or not evidence_rows:
        label = "insufficient_evidence"
        recommendation_support = "hold_until_more_news"
        reason_ko = "저장된 뉴스 근거가 부족해 후보 판단에 연결하기 어렵습니다."
    elif caution_count > 0:
        label = "review_existing_candidate_with_caution"
        recommendation_support = "review_with_caution"
        reason_ko = "주의 또는 혼합 뉴스가 있어 기존 후보 판단에 리스크 확인을 함께 붙입니다."
    elif direct_count <= 0:
        label = "support_only_context"
        recommendation_support = "keep_as_supporting_evidence"
        reason_ko = "직접 뉴스가 없어 시장 분위기나 간접 맥락 보조 근거로만 둡니다."
    elif candidate_priority_presence:
        label = "strengthen_existing_candidate"
        recommendation_support = "strengthen_existing_candidate"
        reason_ko = "기존 후보에 직접 뉴스 근거가 붙어 operator 검토 우선도를 강화할 수 있습니다."
    else:
        label = "promote_news_only_candidate"
        recommendation_support = "promote_news_only_candidate"
        reason_ko = "기존 후보에는 없지만 직접 뉴스 근거가 있어 뉴스 단독 후보 검토 대상으로 올릴 수 있습니다."
    return {
        "label": label,
        "target_date": run.target_date.isoformat(),
        "stock_code": run.stock_code,
        "candidate_priority_presence": candidate_priority_presence,
        "related_report_count": related_report_count,
        "direct_count": direct_count,
        "caution_count": caution_count,
        "market_context_count": market_context_count,
        "krx_reference_status": krx_freshness["status"],
        "recommendation_support": recommendation_support,
        "reason_ko": reason_ko,
    }


