def _news_article_with_match_quality(match: object) -> object:
    return replace(
        getattr(match, "article"),
        match_scope=str(getattr(match, "match_scope", "")),
        relevance=str(getattr(match, "relevance", "")),
    )


def _news_intelligence_operator_decision_notes(
    matches: list[object],
    analyzed_articles: list[object],
    *,
    report_context_evaluated: bool,
    source_coverage: dict[str, object] | None = None,
) -> dict[str, object]:
    matched_count = len(matches)
    relevance_counts = Counter(str(getattr(match, "relevance", "")) for match in matches)
    summary_only_count = sum(1 for match in matches if str(getattr(match, "match_scope", "")) == "summary")
    direct_count = relevance_counts.get("direct", 0)
    indirect_count = relevance_counts.get("indirect", 0)
    market_context_count = relevance_counts.get("market_context", 0)
    dominant_relevance = _news_intelligence_dominant_relevance(relevance_counts)
    event_counts: Counter[str] = Counter()
    caution_count = 0
    positive_count = 0
    negative_count = 0
    for analyzed in analyzed_articles:
        sentiment = str(getattr(analyzed, "sentiment", ""))
        stock_impact = str(getattr(analyzed, "stock_impact", ""))
        event_types = tuple(str(event) for event in getattr(analyzed, "event_types", ()))
        event_counts.update(event_types)
        if sentiment in {"Caution", "Mixed"} or stock_impact == "Caution" or "Risk/Caution" in event_types:
            caution_count += 1
        if sentiment == "Positive" or stock_impact in {"Positive", "Strong Positive"}:
            positive_count += 1
        if sentiment == "Negative" or stock_impact in {"Negative", "Strong Negative"}:
            negative_count += 1
    coverage_level = _news_intelligence_coverage_level(matched_count)
    market_context_heavy = matched_count > 0 and market_context_count >= max(1, round(matched_count * 0.5))
    observation_quality = _news_intelligence_observation_quality(
        matched_count=matched_count,
        direct_count=direct_count,
        summary_only_count=summary_only_count,
        market_context_heavy=market_context_heavy,
    )
    source_coverage_payload = source_coverage or {
        "total_source_count": 0,
        "effective_source_count": 0,
        "empty_source_lanes": [],
    }
    return {
        "coverage_level": coverage_level,
        "matched_count": matched_count,
        "direct_count": direct_count,
        "indirect_count": indirect_count,
        "summary_only_count": summary_only_count,
        "market_context_count": market_context_count,
        "dominant_relevance": dominant_relevance,
        "caution_count": caution_count,
        "positive_count": positive_count,
        "negative_count": negative_count,
        "top_event_types": [event for event, _count in event_counts.most_common(5)],
        "market_context_heavy": market_context_heavy,
        "observation_quality": observation_quality,
        "source_coverage": source_coverage_payload,
        "decision_note_ko": _news_intelligence_decision_note_ko(
            coverage_level=coverage_level,
            matched_count=matched_count,
            market_context_heavy=market_context_heavy,
            caution_count=caution_count,
            positive_count=positive_count,
            negative_count=negative_count,
            summary_only_count=summary_only_count,
            source_coverage=source_coverage_payload,
        ),
        "missing_context": {
            "report_krx_context": (
                {
                    "evaluated": True,
                    "reason": "report/KRX context is evaluated because --save-observation is used",
                }
                if report_context_evaluated
                else {
                    "evaluated": False,
                    "reason": "report/KRX context is only evaluated when --save-observation is used",
                }
            ),
            "candidate_evidence": {
                "evaluated": False,
                "reason": "candidate evidence linkage is not part of news-intelligence-preview v1",
            },
        },
    }


def _news_intelligence_observation_quality(
    *,
    matched_count: int,
    direct_count: int,
    summary_only_count: int,
    market_context_heavy: bool,
) -> dict[str, object]:
    if matched_count <= 0:
        return {
            "level": "no_match",
            "matched_count": matched_count,
            "direct_count": direct_count,
            "summary_only_count": summary_only_count,
            "save_warning": "no_match: no stock-matched news evidence; store as an empty observation only",
        }
    if direct_count == 0 and summary_only_count == matched_count:
        return {
            "level": "support_only_indirect",
            "matched_count": matched_count,
            "direct_count": direct_count,
            "summary_only_count": summary_only_count,
            "save_warning": "support_only_indirect: no direct news evidence; interpret as supporting context only",
        }
    if market_context_heavy:
        return {
            "level": "market_context_heavy",
            "matched_count": matched_count,
            "direct_count": direct_count,
            "summary_only_count": summary_only_count,
            "save_warning": "market_context_heavy: market or sector context dominates; do not treat as direct stock evidence",
        }
    if matched_count <= 2:
        return {
            "level": "low_coverage",
            "matched_count": matched_count,
            "direct_count": direct_count,
            "summary_only_count": summary_only_count,
            "save_warning": "low_coverage: too few matched articles; verify with report/KRX context before relying on this observation",
        }
    return {
        "level": "direct_evidence",
        "matched_count": matched_count,
        "direct_count": direct_count,
        "summary_only_count": summary_only_count,
        "save_warning": None,
    }


def _news_intelligence_source_coverage(sources: list[object]) -> dict[str, object]:
    source_payloads = [source.to_dict() for source in sources]
    empty_source_lanes = [
        str(source["source"])
        for source in source_payloads
        if source.get("fetched") is True and int(source.get("parsed_count") or 0) == 0
    ]
    return {
        "total_source_count": len(source_payloads),
        "effective_source_count": sum(1 for source in source_payloads if int(source.get("parsed_count") or 0) > 0),
        "empty_source_lanes": empty_source_lanes,
    }


def _news_intelligence_coverage_level(matched_count: int) -> str:
    if matched_count <= 0:
        return "none"
    if matched_count <= 2:
        return "low"
    if matched_count <= 5:
        return "moderate"
    return "broad"


def _news_intelligence_dominant_relevance(relevance_counts: Counter[str]) -> str:
    for relevance in ("direct", "indirect", "market_context"):
        relevance_counts.setdefault(relevance, 0)
    if not sum(relevance_counts.values()):
        return "none"
    return max(
        ("direct", "indirect", "market_context"),
        key=lambda relevance: (
            relevance_counts[relevance],
            {"direct": 2, "indirect": 1, "market_context": 0}[relevance],
        ),
    )


def _news_intelligence_decision_note_ko(
    *,
    coverage_level: str,
    matched_count: int,
    market_context_heavy: bool,
    caution_count: int,
    positive_count: int,
    negative_count: int,
    summary_only_count: int,
    source_coverage: dict[str, object],
) -> str:
    notes: list[str] = []
    if coverage_level == "none":
        notes.append("매칭된 기사가 없어 판단 보조로 쓰기 어렵습니다.")
    elif coverage_level == "low":
        notes.append(f"coverage 낮음: 매칭 기사 {matched_count}건이라 추가 확인이 필요합니다.")
    else:
        notes.append(f"coverage {coverage_level}: 매칭 기사 {matched_count}건을 기준으로 요약했습니다.")
    if market_context_heavy:
        notes.append("market_context 비중이 높아 종목 직접 판단 근거로 과신하지 말 것.")
    if summary_only_count:
        notes.append(f"summary-only/indirect match {summary_only_count}건은 direct stock news보다 낮은 확신으로 보십시오.")
    if caution_count:
        notes.append(f"주의/혼합 신호 {caution_count}건은 리스크 문구를 먼저 확인하십시오.")
    if positive_count and not market_context_heavy:
        notes.append(f"긍정 신호 {positive_count}건은 리포트/KRX 맥락과 함께 재확인하십시오.")
    if negative_count:
        notes.append(f"부정 신호 {negative_count}건은 원문과 반복 여부를 확인하십시오.")
    total_source_count = int(source_coverage.get("total_source_count") or 0)
    effective_source_count = int(source_coverage.get("effective_source_count") or 0)
    empty_source_lanes = source_coverage.get("empty_source_lanes") or []
    if total_source_count and empty_source_lanes:
        notes.append(
            f"일부 source lane이 해당 mode/date에서 파싱 기여 없음: 유효 {effective_source_count}/{total_source_count}개 lane만 "
            "판단에 반영되어 추가 확인 필요합니다."
        )
    return " ".join(notes)


def _news_intelligence_run_id(
    *,
    target_date: date,
    stock_name: str,
    stock_code: str | None,
    created_at: datetime,
) -> str:
    raw = "|".join(
        [
            target_date.isoformat(),
            stock_code or "",
            stock_name,
            created_at.isoformat(),
        ]
    )
    digest = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12]
    return f"news-{target_date.isoformat()}-{stock_code or stock_name}-{digest}"


def _news_intelligence_observation_context(
    repository: StockMonitorRepository,
    *,
    target_date: date,
    stock_name: str,
    stock_code: str | None,
) -> dict[str, object]:
    if stock_code:
        reports = repository.list_reports_for_stock_on_business_date(target_date, stock_code)
    else:
        reports = [
            report
            for report in repository.list_reports_for_business_date(target_date)
            if report.stock_name == stock_name
        ]
    summaries = [
        summary
        for summary in repository.list_daily_summaries(target_date)
        if (stock_code and summary.stock_code == stock_code) or summary.stock_name == stock_name
    ]
    krx_snapshots = (
        repository.list_stock_market_daily_for_code_on_or_before(target_date, stock_code, limit=1)
        if stock_code
        else []
    )
    investor_flows = repository.list_stock_investor_flow_daily(target_date, stock_code) if stock_code else []
    return {
        "target_date": target_date,
        "stock_name": stock_name,
        "stock_code": stock_code,
        "related_report_count": len(reports),
        "related_report_source_ids": tuple(
            sorted(report.source_id for report in reports if report.source_id)
        ),
        "daily_summary_presence": bool(summaries),
        "candidate_priority_presence": False,
        "candidate_observation_priority": None,
        "krx_reference_presence": bool(krx_snapshots),
        "krx_reference_date": krx_snapshots[0].business_date if krx_snapshots else None,
        "krx_turnover": krx_snapshots[0].turnover if krx_snapshots else None,
        "investor_flow_presence": bool(investor_flows),
    }


def _news_intelligence_krx_reference_freshness(
    *,
    target_date: date,
    krx_reference_date: object,
) -> dict[str, object]:
    if not isinstance(krx_reference_date, date):
        return {
            "status": "missing",
            "target_date": target_date.isoformat(),
            "krx_reference_date": None,
            "exact_date": False,
        }
    exact_date = krx_reference_date == target_date
    return {
        "status": "exact" if exact_date else "stale_reference",
        "target_date": target_date.isoformat(),
        "krx_reference_date": krx_reference_date.isoformat(),
        "exact_date": exact_date,
    }


def _news_intelligence_krx_reference_warning(freshness: dict[str, object]) -> str | None:
    if freshness.get("status") != "stale_reference":
        return None
    return (
        "stale_krx_reference: KRX reference date "
        f"{freshness.get('krx_reference_date')} differs from target date {freshness.get('target_date')}"
    )


def _news_intelligence_evidence_record(
    *,
    run_id: str,
    match: object,
    analyzed: object,
    context: dict[str, object],
    operator_summary_snapshot: str,
    created_at: datetime,
) -> ReportLinkedNewsEvidenceRecord:
    from stock_monitor.news.linked_evidence import (
        ReportLinkedNewsContext,
        ReportLinkedNewsInput,
        build_report_linked_news_evidence,
    )

    article = analyzed.article
    linked_rows = build_report_linked_news_evidence(
        [
            ReportLinkedNewsInput(
                analyzed_article=analyzed,
                relevance=match.relevance,
                match_scope=match.match_scope,
                duplicate_count=1,
            )
        ],
        ReportLinkedNewsContext(
            target_date=context["target_date"],
            stock_name=str(context.get("stock_name") or ""),
            stock_code=context.get("stock_code"),
            related_report_count=int(context["related_report_count"]),
            related_report_source_ids=tuple(context["related_report_source_ids"]),
            daily_summary_presence=bool(context["daily_summary_presence"]),
            candidate_priority_presence=bool(context["candidate_priority_presence"]),
            candidate_observation_priority=context["candidate_observation_priority"],
            krx_reference_presence=bool(context["krx_reference_presence"]),
            krx_reference_date=context["krx_reference_date"],
            krx_turnover=context["krx_turnover"],
            investor_flow_presence=bool(context["investor_flow_presence"]),
        ),
    )
    linked = linked_rows[0]
    return ReportLinkedNewsEvidenceRecord(
        run_id=run_id,
        evidence_key=_news_intelligence_evidence_key(article),
        target_date=linked.target_date,
        stock_code=linked.stock_code,
        stock_name=linked.stock_name,
        related_report_count=linked.related_report_count,
        related_report_source_ids=linked.related_report_source_ids,
        daily_summary_presence=linked.daily_summary_presence,
        candidate_priority_presence=linked.candidate_priority_presence,
        candidate_observation_priority=linked.candidate_observation_priority,
        krx_reference_presence=linked.krx_reference_presence,
        krx_reference_date=linked.krx_reference_date,
        krx_turnover=linked.krx_turnover,
        investor_flow_presence=linked.investor_flow_presence,
        source_lane=article.source_lane or "",
        title=article.title,
        summary=article.summary,
        source=article.source,
        published_at=article.published_at,
        url=article.url,
        matched_alias=match.matched_alias,
        match_reason=match.match_reason,
        match_scope=match.match_scope,
        relevance=match.relevance,
        relevance_reason=match.relevance_reason,
        sentiment=analyzed.sentiment,
        sentiment_score=analyzed.sentiment_score,
        event_types=tuple(analyzed.event_types),
        stock_impact=analyzed.stock_impact,
        impact_explanation=analyzed.impact_explanation,
        evidence_case=linked.evidence_case,
        operator_recommendation=linked.operator_recommendation,
        recommendation_reason=linked.recommendation_reason,
        operator_summary_snapshot=operator_summary_snapshot,
        created_at=created_at,
    )


def _news_intelligence_evidence_key(article: object) -> str:
    raw = "|".join(
        [
            article.source_lane or "",
            article.url,
            article.title,
        ]
    )
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


