def _mini_pc_preflight_environment_status(config: RuntimeConfig) -> dict[str, object]:
    dotenv_path = config.root_dir / ".env"
    telegram_configured = bool(config.telegram_bot_token and config.telegram_chat_id)
    krx_open_api_configured = bool(config.krx_auth_key)
    krx_data_market_login_configured = bool(
        config.krx_data_market_login_id and config.krx_data_market_login_password
    )
    missing: list[str] = []
    if not telegram_configured:
        missing.append("telegram")
    if not krx_open_api_configured:
        missing.append("krx_open_api")
    if not krx_data_market_login_configured:
        missing.append("krx_data_market_login")
    ready = not missing
    detail = "ready" if ready else "missing " + ", ".join(missing)
    return {
        "ready": ready,
        "dotenv_exists": dotenv_path.exists(),
        "dotenv_path": str(dotenv_path),
        "telegram_configured": telegram_configured,
        "krx_open_api_configured": krx_open_api_configured,
        "krx_data_market_login_configured": krx_data_market_login_configured,
        "missing": missing,
        "detail": detail,
    }


def _mini_pc_preflight_operation_profile_status(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    require_mini_pc_profile: bool,
) -> dict[str, object]:
    setting = _effective_safe_setting(config, repository, "operation_profile")
    value = str(setting["effective_value"])
    ready = value == "mini-pc"
    if ready:
        detail = "operation_profile=mini-pc; scheduled shutdown is app-guarded for always-on operation"
    else:
        detail = (
            f"operation_profile={value}; set mini-pc before unattended always-on operation"
            if require_mini_pc_profile
            else f"operation_profile={value}; mini-pc is recommended before unattended always-on operation"
        )
    return {
        "ready": ready,
        "required": require_mini_pc_profile,
        "effective_value": value,
        "source": setting["source"],
        "restart_required": setting["restart_required"],
        "detail": detail,
        "shutdown_policy": (
            "scheduled shutdown is skipped by operation_profile=mini-pc"
            if ready
            else "scheduler wrapper still excludes StockMonitor-Shutdown, but the app-level profile is not mini-pc"
        ),
    }


def _mini_pc_preflight_runtime_status(config: RuntimeConfig) -> dict[str, object]:
    python_executable = str(Path(sys.executable))
    register_script = config.root_dir / "scripts" / "register_mini_pc_scheduler_tasks.ps1"
    scheduler_register_command = (
        'powershell.exe -NoProfile -ExecutionPolicy Bypass '
        f'-File "{register_script}" -PythonExe "{python_executable}"'
    )
    return {
        "python_executable": python_executable,
        "project_root": str(config.root_dir),
        "scheduler_register_command": scheduler_register_command,
        "detail": "Use this Python executable with the mini PC scheduler wrapper on the target host.",
    }


def _run_mini_pc_preflight(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    require_access_code: bool,
    require_backup: bool,
    require_env: bool,
    require_mini_pc_profile: bool,
    as_json: bool,
) -> int:
    snapshot = _build_mini_pc_preflight_snapshot(
        config,
        repository,
        require_access_code=require_access_code,
        require_backup=require_backup,
        require_env=require_env,
        require_mini_pc_profile=require_mini_pc_profile,
    )
    if as_json:
        print(json.dumps(snapshot, ensure_ascii=False, indent=2))
    else:
        print("Mini PC migration preflight")
        print(f"- db: {snapshot['db']['detail']} ({snapshot['db']['path']})")
        print(f"- backup: {snapshot['backup']['detail']} ({snapshot['backup']['backup_dir']})")
        print(f"- scheduler scripts: {snapshot['scheduler_scripts']['detail']} ({snapshot['scheduler_scripts']['scripts_dir']})")
        print(f"- project files: {snapshot['project_files']['detail']}")
        print(f"- web-view assets: {snapshot['web_view_assets']['detail']}")
        print(f"- environment: {snapshot['environment']['detail']} ({snapshot['environment']['dotenv_path']})")
        print(f"- operation profile: {snapshot['operation_profile']['detail']}")
        print(f"- python: {snapshot['runtime']['python_executable']}")
        print(f"- access-code: {snapshot['access_code']['enabled']}")
        print(f"- external sharing ready: {snapshot['external_sharing_ready']}")
        print(f"- external sharing note: {snapshot['external_sharing']['detail']}")
        print("- expected scheduler tasks:")
        for task_name in snapshot["expected_scheduler_tasks"]:
            print(f"  - {task_name}")
        print("- optional scheduler tasks:")
        for task_name in snapshot["optional_scheduler_tasks"]:
            print(f"  - {task_name}")
        print("- desktop validation scheduler tasks:")
        for task_name in snapshot["desktop_validation_scheduler_tasks"]:
            print(f"  - {task_name}")
        print("- checks:")
        for check in snapshot["checks"]:
            print(f"  - {check['name']}: {check['status']} | {check['detail']}")
        print("- recommended commands:")
        for command in snapshot["recommended_commands"]:
            print(f"  - {command}")
        print("- scheduler register command:")
        print(f"  - {snapshot['runtime']['scheduler_register_command']}")
    return 0 if snapshot["exit_ready"] else 1


def _build_db_verify_payload(
    repository: StockMonitorRepository,
    *,
    holiday_overrides: set[date] | frozenset[date] | None = None,
) -> dict[str, object]:
    if not repository.db_path.exists():
        raise FileNotFoundError(f"Database does not exist: {repository.db_path}")
    status = repository.get_schema_migration_status()
    with repository.connect() as connection:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        page_size = int(connection.execute("PRAGMA page_size").fetchone()[0])
        page_count = int(connection.execute("PRAGMA page_count").fetchone()[0])
        freelist_count = int(connection.execute("PRAGMA freelist_count").fetchone()[0])
        tables = _database_table_counts(connection)
        foreign_key_violations = len(connection.execute("PRAGMA foreign_key_check").fetchall())
        duplicate_source_ids = connection.execute(
            """
            SELECT COUNT(*) FROM (
                SELECT source_id
                FROM reports
                WHERE source_id IS NOT NULL
                GROUP BY source_id
                HAVING COUNT(*) > 1
            )
            """
        ).fetchone()[0] if "reports" in tables else 0
        orphan_fragments = connection.execute(
            """
            SELECT COUNT(*)
            FROM daily_summary_delivery_fragments AS fragment
            LEFT JOIN daily_summary_delivery_runs AS run
              ON run.run_id = fragment.run_id
            WHERE run.run_id IS NULL
            """
        ).fetchone()[0] if "daily_summary_delivery_fragments" in tables else 0
        orphan_intraday_batch_reports = connection.execute(
            """
            SELECT COUNT(*)
            FROM intraday_alert_batch_reports AS batch_report
            LEFT JOIN intraday_alert_batches AS batch
              ON batch.batch_id = batch_report.batch_id
            LEFT JOIN reports AS report
              ON report.identity_key = batch_report.report_identity_key
            WHERE batch.batch_id IS NULL
               OR report.identity_key IS NULL
            """
        ).fetchone()[0] if {"intraday_alert_batch_reports", "intraday_alert_batches", "reports"}.issubset(tables) else 0
        partial_krx_snapshot_dates = _partial_krx_daily_snapshot_dates(
            connection,
            tables,
            holiday_overrides=holiday_overrides,
        )
        investor_flow_quality_issues = _investor_flow_quality_issue_counts(connection, tables)
        investor_flow_quality_issue_total = sum(investor_flow_quality_issues.values())
        category_quality_issues = _category_quality_issue_counts(connection, tables)
        category_quality_issue_total = category_quality_issues["orphan_membership_snapshots"]
        category_snapshot_coverage = _category_snapshot_coverage(connection, tables)
        category_snapshot_refreshability = _category_snapshot_refreshability(connection, tables, category_snapshot_coverage)
    return {
        "db_path": str(repository.db_path),
        "integrity_check": integrity,
        "schema_version": status.current_version,
        "target_schema_version": status.target_version,
        "applied_migrations": status.applied_versions,
        "pending_migrations": status.pending_versions,
        "page_size": page_size,
        "page_count": page_count,
        "allocated_bytes": page_size * page_count,
        "freelist_pages": freelist_count,
        "freelist_bytes": page_size * freelist_count,
        "foreign_key_violations": foreign_key_violations,
        "duplicate_source_id_groups": duplicate_source_ids,
        "orphan_daily_summary_fragments": orphan_fragments,
        "orphan_intraday_batch_reports": orphan_intraday_batch_reports,
        "partial_krx_daily_snapshot_dates": partial_krx_snapshot_dates,
        "investor_flow_quality_issues": investor_flow_quality_issues,
        "investor_flow_quality_issue_total": investor_flow_quality_issue_total,
        "category_quality_issues": category_quality_issues,
        "category_quality_issue_total": category_quality_issue_total,
        "category_snapshot_coverage": category_snapshot_coverage,
        "category_snapshot_refreshability": category_snapshot_refreshability,
        "table_counts": tables,
    }


def _db_verify_payload_ready(payload: dict[str, object]) -> bool:
    return (
        payload["integrity_check"] == "ok"
        and not payload["pending_migrations"]
        and payload["foreign_key_violations"] == 0
        and payload["duplicate_source_id_groups"] == 0
        and payload["orphan_daily_summary_fragments"] == 0
        and payload["orphan_intraday_batch_reports"] == 0
        and not payload["partial_krx_daily_snapshot_dates"]
        and payload["investor_flow_quality_issue_total"] == 0
        and payload["category_quality_issue_total"] == 0
    )


def _run_db_verify(
    repository: StockMonitorRepository,
    *,
    as_json: bool,
    holiday_overrides: set[date] | frozenset[date] | None = None,
) -> int:
    payload = _build_db_verify_payload(repository, holiday_overrides=holiday_overrides)
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print("Database verification")
        print(f"- path: {payload['db_path']}")
        print(f"- integrity_check: {payload['integrity_check']}")
        print(f"- schema: {payload['schema_version']}/{payload['target_schema_version']}")
        print("- applied migrations: " + _format_version_tuple(payload["applied_migrations"]))
        print("- pending migrations: " + _format_version_tuple(payload["pending_migrations"]))
        print(f"- allocated: {payload['allocated_bytes']} bytes")
        print(f"- freelist: {payload['freelist_bytes']} bytes")
        print(f"- foreign key violations: {payload['foreign_key_violations']}")
        print(f"- duplicate source_id groups: {payload['duplicate_source_id_groups']}")
        print(f"- orphan delivery fragments: {payload['orphan_daily_summary_fragments']}")
        print(f"- orphan intraday batch reports: {payload['orphan_intraday_batch_reports']}")
        print(f"- partial KRX daily snapshot dates: {len(payload['partial_krx_daily_snapshot_dates'])}")
        print(f"- investor-flow quality issues: {payload['investor_flow_quality_issue_total']}")
        print(f"- category quality issues: {payload['category_quality_issue_total']}")
        category_snapshot_coverage = payload["category_snapshot_coverage"]
        print(
            "- category snapshot coverage: "
            f"summary_dates={category_snapshot_coverage['summary_date_count']}, "
            f"sector_dated={category_snapshot_coverage['sector_dated_count']}, "
            f"theme_dated={category_snapshot_coverage['theme_dated_count']}, "
            f"fallback_dates={category_snapshot_coverage['fallback_date_count']}"
        )
        for warning in payload["category_snapshot_refreshability"]["warnings"]:
            print(f"- category snapshot warning: {warning['code']} | {warning['message']}")
        for key, count in payload["investor_flow_quality_issues"].items():
            if count:
                print(f"  - {key}: {count}")
        for key, count in payload["category_quality_issues"].items():
            if count:
                print(f"  - {key}: {count}")
        for item in payload["partial_krx_daily_snapshot_dates"][:10]:
            print(f"  - {item['business_date']}: missing {', '.join(item['missing_endpoints'])}")
        print("- table counts:")
        for name, count in payload["table_counts"].items():
            print(f"  - {name}: {count}")
    return 0 if _db_verify_payload_ready(payload) else 1


def _run_api_perf_summary(config: RuntimeConfig, *, log_path: Path | None, as_json: bool) -> int:
    target_log_path = log_path or config.root_dir / "logs" / "api_perf.log"
    payload = summarize_api_perf_log(target_log_path)
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0
    print("API performance summary")
    print(f"- log_path: {payload['log_path']}")
    print(f"- records: {payload['record_count']}")
    print(f"- endpoints: {payload['endpoint_count']}")
    for item in payload["endpoints"][:20]:
        print(
            f"  - {item['path']}: count={item['count']}, p50={item['p50_total_ms']}ms, "
            f"p95={item['p95_total_ms']}ms, p99={item['p99_total_ms']}ms, "
            f"avg_db={item['avg_db_ms']}ms, avg_json={item['avg_json_ms']}ms, "
            f"bytes_max={item['max_bytes']}, hit/miss={item['cache_hits']}/{item['cache_misses']}, "
            f"family={item['path_family']}"
        )
    return 0


def _build_docs_hygiene_audit_payload(root_dir: Path, *, paths: Sequence[Path] = ()) -> dict[str, object]:
    target_paths = tuple(paths) if paths else DOCS_HYGIENE_DEFAULT_PATHS
    issue_map: dict[tuple[str, str], dict[str, object]] = {}
    scanned_files: list[str] = []
    for input_path in target_paths:
        absolute_path = input_path if input_path.is_absolute() else root_dir / input_path
        display_path = _docs_hygiene_display_path(root_dir, absolute_path)
        if not absolute_path.exists():
            issue_map[(display_path, "missing_public_doc")] = {
                "code": "missing_public_doc",
                "path": display_path,
                "count": 1,
                "lines": [],
                "redacted": True,
                "message": "Configured public/canonical document is missing.",
            }
            continue
        scanned_files.append(display_path)
        text = absolute_path.read_text(encoding="utf-8")
        for line_number, line in enumerate(text.splitlines(), start=1):
            for code, pattern in _docs_hygiene_patterns():
                match_count = len(pattern.findall(line))
                if match_count == 0:
                    continue
                key = (display_path, code)
                issue = issue_map.setdefault(
                    key,
                    {
                        "code": code,
                        "path": display_path,
                        "count": 0,
                        "lines": [],
                        "redacted": True,
                        "message": _docs_hygiene_issue_message(code),
                    },
                )
                issue["count"] = int(issue["count"]) + match_count
                issue["lines"].append(line_number)
    issues = sorted(issue_map.values(), key=lambda item: (str(item["path"]), str(item["code"])))
    issue_count = sum(int(item["count"]) for item in issues)
    return {
        "surface": "docs-hygiene-audit",
        "read_only": True,
        "live_fetch": False,
        "writes_db": False,
        "sends_telegram": False,
        "registers_scheduler": False,
        "ready": issue_count == 0,
        "scanned_file_count": len(scanned_files),
        "scanned_files": scanned_files,
        "checked_patterns": [
            "local_absolute_path",
            "loopback_url",
            "external_provider_url",
            "secret_like_assignment",
            "raw_access_code",
        ],
        "issue_count": issue_count,
        "issues": issues,
        "verification_commands": [
            "python -m stock_monitor docs-hygiene-audit --json",
            "python -m pytest tests/test_cli_commands.py -q -k docs_hygiene_audit",
            "python -m pytest -q",
        ],
    }


def _run_docs_hygiene_audit(root_dir: Path, *, paths: Sequence[Path], as_json: bool) -> int:
    payload = _build_docs_hygiene_audit_payload(root_dir, paths=paths)
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0 if payload["ready"] else 1
    print("Docs hygiene audit")
    print(f"- ready: {'Y' if payload['ready'] else 'N'}")
    print(f"- scanned files: {payload['scanned_file_count']}")
    print(f"- issues: {payload['issue_count']}")
    for item in payload["issues"]:
        lines = ", ".join(str(line) for line in item["lines"]) or "-"
        print(f"  - {item['path']}:{lines} {item['code']} count={item['count']} redacted=Y")
    print("- verification commands:")
    for command in payload["verification_commands"]:
        print(f"  - {command}")
    return 0 if payload["ready"] else 1


