def _latest_report_business_date(repository: StockMonitorRepository) -> date | None:
    rows = repository.count_reports_by_business_date(limit=1)
    return rows[0][0] if rows else None


_OPERATOR_MEMO_PATTERN = re.compile(
    r"^-\s+\[(?P<marker>[^\]]*)\]\s+"
    r"(?P<timestamp>\d{2}\.\d{2}\.\d{2}\s+\d{2}:\d{2})\s+\|\s+"
    r"(?P<text>.*)$"
)
_PHOTO_INBOX_EXTENSIONS = (".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp")


def _operator_memo_status_from_marker(marker: str) -> str:
    normalized = marker.strip()
    if normalized.upper() == "O":
        return "done"
    if normalized == "△":
        return "partial"
    if normalized == "":
        return "open"
    return "other"


def _build_operator_memo_status_snapshot(memo_path: Path) -> dict[str, object]:
    rows: list[dict[str, object]] = []
    if memo_path.exists():
        for line_number, line in enumerate(memo_path.read_text(encoding="utf-8").splitlines(), start=1):
            match = _OPERATOR_MEMO_PATTERN.match(line.strip())
            if not match:
                continue
            marker = match.group("marker")
            status = _operator_memo_status_from_marker(marker)
            rows.append(
                {
                    "line_number": line_number,
                    "marker": marker,
                    "status": status,
                    "timestamp": match.group("timestamp"),
                    "text": match.group("text").strip(),
                }
            )
    counts = Counter(str(row["status"]) for row in rows)
    status_counts = {
        "done": int(counts.get("done", 0)),
        "partial": int(counts.get("partial", 0)),
        "open": int(counts.get("open", 0)),
        "other": int(counts.get("other", 0)),
    }
    return {
        "surface": "operator-memo-status",
        "read_only": True,
        "memo_path": str(memo_path),
        "memo_path_exists": memo_path.exists(),
        "memo_count": len(rows),
        "status_counts": status_counts,
        "open_memos": [row for row in rows if row["status"] == "open"],
        "partial_memos": [row for row in rows if row["status"] == "partial"],
        "memos": rows,
    }


def _run_operator_memo_status(config: RuntimeConfig, *, memo_path: Path | None, as_json: bool) -> int:
    payload = _build_operator_memo_status_snapshot(memo_path or config.data_dir / "operator_memos.md")
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0
    counts = payload["status_counts"]
    print("Operator memo status")
    print(f"- memo_path: {payload['memo_path']}")
    print(f"- memo_count: {payload['memo_count']}")
    print(
        "- status: "
        f"done={counts['done']} partial={counts['partial']} open={counts['open']} other={counts['other']}"
    )
    open_memos = payload["open_memos"]
    if open_memos:
        print("- open memos:")
        for item in open_memos:
            print(f"  - {item['timestamp']} | {item['text']}")
    return 0


def _operator_task_queue_path(config: RuntimeConfig, queue_path: Path | None = None) -> Path:
    return queue_path or config.data_dir / "operator_progress_requests.jsonl"


def _append_operator_task_record(path: Path, record: dict[str, object]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as file:
        file.write(json.dumps(record, ensure_ascii=False, sort_keys=True) + "\n")


def _read_operator_task_records(path: Path) -> list[dict[str, object]]:
    if not path.exists():
        return []
    records: list[dict[str, object]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        try:
            payload = json.loads(stripped)
        except json.JSONDecodeError:
            continue
        if isinstance(payload, dict):
            records.append(payload)
    return records


def _operator_task_latest_records(records: list[dict[str, object]]) -> dict[str, dict[str, object]]:
    latest: dict[str, dict[str, object]] = {}
    for record in records:
        task_id = str(record.get("task_id") or "").strip()
        if task_id:
            latest[task_id] = record
    return latest


def _build_operator_task_next_snapshot(path: Path, *, include_completed: bool = False) -> dict[str, object]:
    records = _read_operator_task_records(path)
    latest = _operator_task_latest_records(records)
    active_statuses = {"queued", "in_progress", "partial", "blocked"} if not include_completed else {
        "queued",
        "in_progress",
        "partial",
        "blocked",
        "done",
    }
    pending = [
        record
        for record in latest.values()
        if str(record.get("status") or "") in active_statuses
    ]
    pending.sort(key=lambda item: str(item.get("created_at") or item.get("updated_at") or ""))
    return {
        "surface": "operator-task-next",
        "read_only": True,
        "queue_path": str(path),
        "queue_path_exists": path.exists(),
        "record_count": len(records),
        "task_count": len(latest),
        "pending_count": len(pending),
        "next_task": pending[0] if pending else None,
        "pending_tasks": pending,
    }


def _run_operator_task_next(
    config: RuntimeConfig,
    *,
    queue_path: Path | None,
    include_completed: bool,
    as_json: bool,
) -> int:
    payload = _build_operator_task_next_snapshot(
        _operator_task_queue_path(config, queue_path),
        include_completed=include_completed,
    )
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0
    print("Operator task queue")
    print(f"- queue_path: {payload['queue_path']}")
    print(f"- pending_count: {payload['pending_count']}")
    task = payload.get("next_task")
    if isinstance(task, dict):
        print(f"- next: {task.get('task_id')} / {task.get('status')}")
        print(f"- requested: {task.get('request_text')}")
    else:
        print("- next: none")
    return 0


def _format_operator_task_completion_message(record: dict[str, object]) -> str:
    lines = [
        f"{record.get('task_id')} {record.get('status')}",
        "",
        f"완료도: {record.get('progress')}%",
        f"요약: {record.get('summary')}",
    ]
    changed_files = [str(item) for item in record.get("changed_files") or [] if str(item).strip()]
    verifications = [str(item) for item in record.get("verifications") or [] if str(item).strip()]
    next_steps = [str(item) for item in record.get("next_steps") or [] if str(item).strip()]
    if changed_files:
        lines.extend(["", "변경:", *[f"- {item}" for item in changed_files]])
    if verifications:
        lines.extend(["", "검증:", *[f"- {item}" for item in verifications]])
    if next_steps:
        lines.extend(["", "다음:", *[f"- {item}" for item in next_steps]])
    return "\n".join(lines)


def _run_operator_task_complete(
    config: RuntimeConfig,
    *,
    task_id: str,
    status: str,
    progress: int,
    summary: str,
    changed_files: list[str],
    verifications: list[str],
    next_steps: list[str],
    queue_path: Path | None,
    send: bool,
    as_json: bool,
) -> int:
    normalized_id = task_id.strip()
    if not normalized_id:
        raise ValueError("--id is required.")
    clamped_progress = max(0, min(100, int(progress)))
    now = datetime.now(ZoneInfo(config.timezone))
    path = _operator_task_queue_path(config, queue_path)
    record = {
        "task_id": normalized_id,
        "status": status,
        "progress": clamped_progress,
        "summary": summary.strip(),
        "changed_files": [item for item in changed_files if str(item).strip()],
        "verifications": [item for item in verifications if str(item).strip()],
        "next_steps": [item for item in next_steps if str(item).strip()],
        "updated_at": now.isoformat(),
        "source": "codex-cli",
    }
    _append_operator_task_record(path, record)
    message = _format_operator_task_completion_message(record)
    if send:
        if not config.telegram_bot_token or not config.telegram_chat_id:
            raise RuntimeError("Telegram configuration is missing.")
        send_telegram_message(
            config.telegram_bot_token,
            config.telegram_chat_id,
            message,
            timeout_seconds=config.telegram_timeout_seconds,
            max_retries=config.telegram_max_retries,
            retry_delay_seconds=config.telegram_retry_delay_seconds,
        )
    payload = {
        "surface": "operator-task-complete",
        "writes_queue": True,
        "sends_telegram": send,
        "queue_path": str(path),
        "record": record,
        "message": message,
    }
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print(message)
    return 0


def _resolve_stored_business_date(repository: StockMonitorRepository, explicit_date: date | None) -> date | None:
    return explicit_date or _latest_report_business_date(repository)


def _latest_report_business_date_before(repository: StockMonitorRepository, business_date: date) -> date | None:
    candidates = [
        item
        for item, count in repository.count_reports_by_business_date(limit=500)
        if count > 0 and item < business_date
    ]
    return max(candidates) if candidates else None


def _format_market_index_change_label(item: MarketIndexDailySnapshot | None) -> str | None:
    if item is None or item.change_percent is None:
        return None
    sign = "+" if item.change_percent > 0 else ""
    label = item.index_series.upper()
    return f"{label} {sign}{item.change_percent:.2f}%"


def _build_market_reference_label(repository: StockMonitorRepository, business_date: date) -> str:
    indices = repository.list_market_index_daily(business_date, limit=200)
    kospi = _find_named_market_index(indices, series="KOSPI", name="코스피")
    kosdaq = _find_named_market_index(indices, series="KOSDAQ", name="코스닥")
    labels = [
        label
        for label in (_format_market_index_change_label(kospi), _format_market_index_change_label(kosdaq))
        if label
    ]
    return " / ".join(labels) if labels else "저장된 KOSPI/KOSDAQ 지수 참고값 없음"


def _format_commentary_stock_names(summaries: list[DailyStockSummary], *, limit: int = 2) -> str:
    ordered = sorted(summaries, key=lambda item: (-item.mention_count, item.stock_name))
    names = [item.stock_name for item in ordered[: max(limit, 0)] if item.stock_name]
    return ", ".join(names) if names else "확인 후보 없음"


def _build_same_day_report_status(
    business_date: date,
    *,
    report_count: int,
    summary_stock_count: int,
    summary_stock_code_count: int | None = None,
    require_current_business_day: bool = False,
    current_date: date | None = None,
    holiday_overrides: Sequence[date] = (),
) -> dict[str, object]:
    stock_code_count = summary_stock_count if summary_stock_code_count is None else summary_stock_code_count
    if require_current_business_day and (
        current_date is None or business_date != current_date or not is_business_day(current_date, holiday_overrides)
    ):
        can_overlap = False
        reason = "오늘 정규장 시간에만 확인 할 수 있습니다."
    elif summary_stock_count <= 0:
        can_overlap = False
        reason = "당일 리포트 요약이 없어 거래대금 교집합을 만들 수 없습니다."
    elif stock_code_count <= 0:
        can_overlap = False
        reason = "종목 코드가 있는 당일 리포트 요약이 없어 거래대금 교집합을 만들 수 없습니다."
    else:
        can_overlap = True
        reason = f"리포트 요약 {stock_code_count}개 종목 기준으로 Naver 거래대금 상위와 교집합을 확인할 수 있습니다."
    return {
        "business_date": business_date.isoformat(),
        "report_count": report_count,
        "summary_stock_count": summary_stock_count,
        "summary_stock_code_count": stock_code_count,
        "can_overlap_intraday_market_top": can_overlap,
        "reason": reason,
    }


def _build_market_commentary_practice_snapshot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    business_date: date | None,
    *,
    summaries: list[DailyStockSummary] | None = None,
    market_briefing: dict[str, object] | None = None,
    include_intraday_quotes: bool = False,
    intraday_quote_limit: int = 10,
    intraday_quote_delay_seconds: float = 1.0,
    intraday_quote_summaries: list[DailyStockSummary] | None = None,
    include_intraday_market_top: bool = False,
    intraday_market_top_limit: int = 100,
    intraday_market_top_page_size: int = 20,
    intraday_market_top_delay_seconds: float = 0.5,
    require_current_business_day_for_intraday_market_top: bool = False,
    current_date_for_intraday_market_top: date | None = None,
    checked_at: datetime | None = None,
) -> dict[str, object]:
    resolved_date = _resolve_stored_business_date(repository, business_date)
    if resolved_date is None:
        return {
            "surface": "market-commentary-practice",
            "read_only": True,
            "live_fetch": False,
            "sends_telegram": False,
            "registers_scheduler": False,
            "business_date": None,
            "market_reference": "저장된 리포트가 없습니다.",
            "comments": [],
        }
    reports_by_date = dict(repository.count_reports_by_business_date(limit=300))
    report_count = int(reports_by_date.get(resolved_date, 0))
    summaries = summaries if summaries is not None else repository.list_daily_summaries(resolved_date)
    if not summaries and report_count:
        summaries = repository.rebuild_daily_summaries(resolved_date)
    summary_count = len(summaries)
    intraday_checked_at = checked_at or datetime.now(ZoneInfo(config.timezone))
    summary_stock_code_count = len({summary.stock_code for summary in summaries if summary.stock_code})
    same_day_report_status = _build_same_day_report_status(
        resolved_date,
        report_count=report_count,
        summary_stock_count=summary_count,
        summary_stock_code_count=summary_stock_code_count,
        require_current_business_day=require_current_business_day_for_intraday_market_top,
        current_date=current_date_for_intraday_market_top,
        holiday_overrides=config.holiday_overrides,
    )
    notable_names = [summary.stock_name for summary in summaries[:3]]
    notable_label = ", ".join(notable_names) if notable_names else "확인 후보 없음"
    market_reference = _build_market_reference_label(repository, resolved_date)
    opening_reference_date = _latest_report_business_date_before(repository, resolved_date)
    opening_summaries: list[DailyStockSummary] = []
    if opening_reference_date is not None:
        opening_summaries = repository.list_daily_summaries(opening_reference_date)
        if not opening_summaries and int(reports_by_date.get(opening_reference_date, 0)):
            opening_summaries = repository.rebuild_daily_summaries(opening_reference_date)
    opening_label = _format_commentary_stock_names(opening_summaries, limit=2)
    opening_market_reference = (
        _build_market_reference_label(repository, opening_reference_date)
        if opening_reference_date is not None
        else "전일 저장 리포트 기준 없음"
    )
    briefing_context = market_briefing or _build_web_view_market_briefing_context(
        repository,
        resolved_date,
        summaries=summaries,
    )
    turnover_details = [
        line.replace("- ", "", 1)
        for line in briefing_context.get("turnover_reference_lines", [])[1:4]
        if isinstance(line, str)
    ]
    flow_details = [
        line.replace("- ", "", 1)
        for line in briefing_context.get("flow_reference_lines", [])[1:4]
        if isinstance(line, str)
    ]
    quote_summaries = intraday_quote_summaries if intraday_quote_summaries is not None else summaries
    intraday_quote_reference = (
        _build_intraday_mentioned_quote_reference(
            config,
            quote_summaries,
            limit=intraday_quote_limit,
            delay_seconds=intraday_quote_delay_seconds,
        )
        if include_intraday_quotes
        else _empty_intraday_mentioned_quote_reference(limit=intraday_quote_limit)
    )
    intraday_quote_details = _format_intraday_quote_detail_lines(intraday_quote_reference)
    intraday_quote_label = _format_intraday_quote_stock_names(intraday_quote_reference)
    intraday_market_top_reference = (
        _build_intraday_market_top_reference(
            config,
            summaries,
            limit=intraday_market_top_limit,
            page_size=intraday_market_top_page_size,
            delay_seconds=intraday_market_top_delay_seconds,
            checked_at=intraday_checked_at,
        )
        if include_intraday_market_top and same_day_report_status["can_overlap_intraday_market_top"]
        else _empty_intraday_market_top_reference(
            limit=intraday_market_top_limit,
            page_size=intraday_market_top_page_size,
            empty_reason=(
                None
                if same_day_report_status["can_overlap_intraday_market_top"]
                else str(same_day_report_status["reason"])
            ),
        )
    )
    intraday_market_top_details = _format_intraday_market_top_detail_lines(intraday_market_top_reference)
    intraday_market_top_label = _format_intraday_market_top_stock_names(intraday_market_top_reference)
    intraday_market_top_empty_reason = intraday_market_top_reference.get("empty_reason")
    base = f"리포트 {report_count}건, 언급 종목 {summary_count}개"
    comments = [
        {
            "phase": "opening",
            "time": "09:15",
            "label": "장초반",
            "reference_date": opening_reference_date.isoformat() if opening_reference_date else None,
            "comment": "",
            "opinion": "당일 리포트가 쌓이기 전에는 전일 후보와 지수 참고를 분리해서 봅니다.",
            "details": (
                [
                    f"전일 후보: {opening_label}",
                    f"전일 기준: {opening_reference_date.isoformat()}",
                    f"전일 지수: {opening_market_reference}",
                ]
                if opening_reference_date is not None
                else ["전일 후보: 없음", f"당일 기준: {resolved_date.isoformat()}"]
            ),
        },
        {
            "phase": "midday",
            "time": "12:00",
            "label": "점심",
            "reference_date": resolved_date.isoformat(),
            "comment": (
                f"12:00에는 Naver 거래대금 상위 기준 {intraday_market_top_label} 언급 겹침을 우선 확인합니다."
                if intraday_market_top_details
                else (
                    f"12:00에는 Naver 장중 quote 기준 {intraday_quote_label} 거래대금/등락률을 우선 확인합니다."
                    if intraday_quote_details
                    else f"12:00에는 {notable_label} 리포트 집중과 거래대금 상위가 겹치는지 확인합니다."
                )
            ),
            "opinion": "오전 리포트 집중과 거래대금 상위가 겹치면 종목 탭에서 근거를 먼저 봅니다.",
            "details": (
                intraday_market_top_details[:3]
                if intraday_market_top_details
                else (
                    intraday_quote_details[:3]
                    if intraday_quote_details
                    else (
                        [str(intraday_market_top_empty_reason)]
                        if intraday_market_top_empty_reason
                        else ([f"우선 확인: {notable_label}"] if notable_names else []) + turnover_details[:2]
                    )
                )
            ),
        },
        {
            "phase": "preclose",
            "time": "15:15",
            "label": "장 마감 전",
            "reference_date": resolved_date.isoformat(),
            "comment": "수급 전환이 반복되는 종목만 종목 탭에서 한 번 더 확인합니다.",
            "opinion": "",
            "details": flow_details[:3]
            or intraday_market_top_details[:3]
            or intraday_quote_details[:3]
            or ["종목별 [12009] 수급 저장값 대기"],
        },
    ]
    return {
        "surface": "market-commentary-practice",
        "read_only": True,
        "live_fetch": include_intraday_quotes or include_intraday_market_top,
        "sends_telegram": False,
        "registers_scheduler": False,
        "business_date": resolved_date.isoformat(),
        "market_reference": market_reference,
        "report_count": report_count,
        "summary_stock_count": summary_count,
        "same_day_report_status": same_day_report_status,
        "intraday_market_top_reference": intraday_market_top_reference,
        "intraday_quote_reference": intraday_quote_reference,
        "comments": comments,
        "boundary": {
            "public_numeric_score": False,
            "trading_recommendation": False,
            "telegram_send": False,
        },
    }


def _empty_intraday_mentioned_quote_reference(*, limit: int) -> dict[str, object]:
    return {
        "source": "naver_quote",
        "live_fetch": False,
        "writes_snapshot_tables": False,
        "limit": max(limit, 0),
        "delay_seconds": None,
        "items": [],
        "errors": [],
    }


def _empty_intraday_market_top_reference(
    *,
    limit: int,
    page_size: int,
    empty_reason: str | None = None,
) -> dict[str, object]:
    return {
        "source": "naver_price_top",
        "live_fetch": False,
        "writes_snapshot_tables": False,
        "markets": ["KOSPI", "KOSDAQ"],
        "limit": min(max(limit, 0), 100),
        "page_size": min(max(page_size, 1), 20),
        "delay_seconds": None,
        "checked_at": None,
        "items": [],
        "errors": [],
        "empty_reason": empty_reason,
    }


def _build_intraday_market_top_reference(
    config: RuntimeConfig,
    summaries: list[DailyStockSummary],
    *,
    limit: int,
    page_size: int,
    delay_seconds: float,
    checked_at: datetime | None = None,
) -> dict[str, object]:
    resolved_checked_at = checked_at or datetime.now(ZoneInfo(config.timezone))
    normalized_limit = min(max(limit, 0), 100)
    normalized_page_size = min(max(page_size, 1), 20)
    normalized_delay = max(delay_seconds, 0.0)
    summary_by_code = {
        str(summary.stock_code or "").strip(): summary
        for summary in summaries
        if str(summary.stock_code or "").strip()
    }
    items: list[dict[str, object]] = []
    errors: list[dict[str, str]] = []
    seen_codes: set[str] = set()
    markets = ["KOSPI", "KOSDAQ"]
    call_count = 0
    for market in markets:
        if normalized_limit <= 0:
            break
        page_count = max(math.ceil(normalized_limit / normalized_page_size), 1)
        for page in range(1, page_count + 1):
            if normalized_delay > 0 and call_count > 0:
                time.sleep(normalized_delay)
            try:
                rows = fetch_market_top_stocks(
                    market,
                    page=page,
                    page_size=normalized_page_size,
                    timeout_seconds=config.telegram_timeout_seconds,
                )
            except Exception as exc:
                errors.append({"market": market, "page": str(page), "error": str(exc)})
                break
            call_count += 1
            if not rows:
                break
            for rank_offset, row in enumerate(rows, start=1 + ((page - 1) * normalized_page_size)):
                if row.stock_end_type and row.stock_end_type.lower() != "stock":
                    continue
                summary = summary_by_code.get(row.stock_code)
                if summary is None or row.stock_code in seen_codes:
                    continue
                seen_codes.add(row.stock_code)
                items.append(
                    _intraday_market_top_reference_item(
                        summary,
                        row,
                        rank=rank_offset,
                        checked_at=resolved_checked_at,
                    )
                )
            if len(rows) < normalized_page_size:
                break
    items.sort(
        key=lambda item: (
            int(item.get("trade_amount") or -1),
            int(item.get("mention_count") or 0),
            str(item.get("stock_name") or ""),
        ),
        reverse=True,
    )
    return {
        "source": "naver_price_top",
        "live_fetch": True,
        "writes_snapshot_tables": False,
        "markets": markets,
        "limit": normalized_limit,
        "page_size": normalized_page_size,
        "delay_seconds": normalized_delay,
        "checked_at": resolved_checked_at.isoformat(),
        "calls": call_count,
        "items": items,
        "errors": errors,
        "empty_reason": _intraday_market_top_empty_reason(
            items,
            errors=errors,
            limit=normalized_limit,
        ),
    }


def _intraday_market_top_empty_reason(
    items: list[dict[str, object]],
    *,
    errors: list[dict[str, str]],
    limit: int,
) -> str | None:
    if items:
        return None
    if errors:
        return "Naver 거래대금 상위 확인 중 오류가 발생했습니다."
    return f"거래대금 상위 {limit} 안에는 언급 종목이 없습니다."


def _intraday_market_top_reference_item(
    summary: DailyStockSummary,
    row: NaverMarketTopStock,
    *,
    rank: int,
    checked_at: datetime,
) -> dict[str, object]:
    return {
        "source": "naver_price_top",
        "market": row.market,
        "rank": rank,
        "stock_name": row.stock_name or summary.stock_name,
        "stock_code": row.stock_code,
        "mention_count": summary.mention_count,
        "current_price": row.current_price,
        "change_price": row.change_price,
        "change_percent": row.change_percent,
        "trade_amount": row.trade_amount,
        "trade_volume": row.trade_volume,
        "market_status": row.market_status,
        "trade_time": row.trade_time.isoformat() if row.trade_time else None,
        "checked_at": checked_at.isoformat(),
        "stock_end_type": row.stock_end_type,
    }


def _build_intraday_mentioned_quote_reference(
    config: RuntimeConfig,
    summaries: list[DailyStockSummary],
    *,
    limit: int,
    delay_seconds: float,
) -> dict[str, object]:
    limited_summaries = summaries[: max(limit, 0)]
    items: list[dict[str, object]] = []
    errors: list[dict[str, str]] = []
    seen_codes: set[str] = set()
    fetched_count = 0
    for summary in limited_summaries:
        stock_code = (summary.stock_code or "").strip()
        source = "summary_stock_code"
        if not stock_code:
            lookup = _lookup_intraday_quote_stock_code(summary.stock_name, timeout_seconds=config.telegram_timeout_seconds)
            if lookup is None:
                errors.append({"stock_name": summary.stock_name, "error": "stock_code_not_resolved"})
                continue
            stock_code = lookup.stock_code
            source = "naver_search"
        if stock_code in seen_codes:
            continue
        seen_codes.add(stock_code)
        try:
            quote = fetch_stock_quote_snapshot(stock_code, timeout_seconds=config.telegram_timeout_seconds)
        except Exception as exc:
            errors.append({"stock_name": summary.stock_name, "stock_code": stock_code, "error": str(exc)})
            continue
        fetched_count += 1
        items.append(_intraday_quote_reference_item(summary, quote, source=source))
        if delay_seconds > 0 and fetched_count < len(limited_summaries):
            time.sleep(delay_seconds)
    items.sort(
        key=lambda item: (
            int(item.get("trade_amount") or -1),
            int(item.get("mention_count") or 0),
            str(item.get("stock_name") or ""),
        ),
        reverse=True,
    )
    return {
        "source": "naver_quote",
        "live_fetch": True,
        "writes_snapshot_tables": False,
        "limit": max(limit, 0),
        "delay_seconds": max(delay_seconds, 0.0),
        "items": items,
        "errors": errors,
    }


def _lookup_intraday_quote_stock_code(stock_name: str, *, timeout_seconds: float) -> StockCodeLookupEntry | None:
    try:
        candidates = fetch_stock_code_candidates(stock_name, timeout_seconds=timeout_seconds, limit=1)
    except Exception:
        return None
    return candidates[0] if candidates else None


def _intraday_quote_reference_item(
    summary: DailyStockSummary,
    quote: StockQuoteSnapshot,
    *,
    source: str,
) -> dict[str, object]:
    return {
        "stock_name": quote.stock_name or summary.stock_name,
        "stock_code": quote.stock_code,
        "mention_count": summary.mention_count,
        "current_price": quote.current_price,
        "prev_close_price": quote.prev_close_price,
        "change_price": quote.prev_change_price,
        "change_percent": quote.prev_change_rate,
        "trade_amount": quote.trade_amount,
        "trade_volume": quote.trade_volume,
        "market_status": quote.market_status,
        "trade_time": quote.trade_time.isoformat() if quote.trade_time else None,
        "sector_name": quote.sector_name,
        "resolution_source": source,
    }


def _format_intraday_quote_detail_lines(reference: dict[str, object]) -> list[str]:
    items = reference.get("items")
    if not isinstance(items, list):
        return []
    lines: list[str] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        stock_name = str(item.get("stock_name") or item.get("stock_code") or "-")
        trade_amount = item.get("trade_amount")
        amount_label = _format_krx_flow_amount(int(trade_amount)) if trade_amount is not None else "거래대금 확인불가"
        change_percent = _format_signed_percent(item.get("change_percent"))
        current_price = item.get("current_price")
        price_label = f"현재가 {int(current_price):,}원" if current_price is not None else "현재가 확인불가"
        lines.append(f"{stock_name} 거래대금 {amount_label} · {change_percent} · {price_label}")
    return lines


def _format_intraday_market_top_detail_lines(reference: dict[str, object]) -> list[str]:
    items = reference.get("items")
    if not isinstance(items, list):
        return []
    lines: list[str] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        stock_name = str(item.get("stock_name") or item.get("stock_code") or "-")
        market = str(item.get("market") or "-")
        rank = item.get("rank")
        rank_label = f"{market} 거래대금 {int(rank)}위" if rank is not None else f"{market} 거래대금 상위"
        trade_amount = item.get("trade_amount")
        amount_label = _format_krx_flow_amount(int(trade_amount)) if trade_amount is not None else "거래대금 확인불가"
        change_percent = _format_signed_percent(item.get("change_percent"))
        mention_count = item.get("mention_count")
        mention_label = f"리포트 {int(mention_count)}건" if mention_count is not None else "리포트 언급"
        lines.append(f"{stock_name} 거래대금 {amount_label} · {change_percent} · {rank_label} · {mention_label}")
    return lines


def _format_intraday_market_top_stock_names(reference: dict[str, object]) -> str:
    items = reference.get("items")
    if not isinstance(items, list) or not items:
        return "확인 후보 없음"
    names = [
        str(item.get("stock_name") or item.get("stock_code") or "").strip()
        for item in items[:3]
        if isinstance(item, dict)
    ]
    return ", ".join(name for name in names if name) or "확인 후보 없음"


def _format_intraday_quote_stock_names(reference: dict[str, object]) -> str:
    items = reference.get("items")
    if not isinstance(items, list) or not items:
        return "확인 후보 없음"
    names = [
        str(item.get("stock_name") or item.get("stock_code") or "").strip()
        for item in items[:3]
        if isinstance(item, dict)
    ]
    return ", ".join(name for name in names if name) or "확인 후보 없음"


def _format_signed_percent(value: object) -> str:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "등락률 확인불가"
    sign = "+" if number > 0 else ""
    return f"{sign}{number:.2f}%"


