def _format_observation_summary_preview_message(
    observation_summary: dict,
    *,
    business_date: date,
    limit: int,
) -> str:
    header = f"국장 관찰 요약 · {business_date.strftime('%y.%m.%d')}"
    basis = "기준: 저장 리포트 / KRX·[12009] 저장값"
    sections = [
        "\n".join([header, basis]),
        _format_observation_summary_market_mood_block(observation_summary),
        _format_observation_summary_items_block(
            "리포트 집중",
            (observation_summary.get("report_concentration") or {}).get("items") or [],
            limit=limit,
        ),
        _format_observation_summary_items_block(
            "수급 참고",
            (observation_summary.get("flow_reference") or {}).get("items") or [],
            limit=limit,
        ),
        _format_observation_summary_items_block(
            "과열 참고",
            (observation_summary.get("price_volume_reference") or {}).get("items") or [],
            limit=limit,
        ),
        _format_observation_summary_sector_breadth_block(observation_summary, limit=limit),
        "\n".join(
            [
                "확인 포인트",
                "- 수급과 과열 참고는 저장 데이터 확인용",
                "- 세부 근거는 웹뷰에서 확인",
            ]
        ),
    ]
    return "\n\n".join(section for section in sections if section)


def _format_observation_summary_market_mood_block(observation_summary: dict) -> str:
    mood = observation_summary.get("market_mood") or {}
    display = str(mood.get("display") or "").strip()
    if not display:
        display = "저장된 리포트 요약이 없습니다."
    return "\n".join(["시장 분위기", f"- {display}"])


def _format_observation_summary_items_block(title: str, items: list[object], *, limit: int) -> str:
    lines = [title]
    picked = [item for item in items if isinstance(item, dict)][:limit]
    if not picked:
        lines.append("- 저장값 없음")
        return "\n".join(lines)
    for item in picked:
        display = str(item.get("display") or "").strip()
        if not display:
            stock_name = str(item.get("stock_name") or "-")
            display = stock_name
        lines.append(f"- {display}")
    return "\n".join(lines)


def _format_observation_summary_sector_breadth_block(
    observation_summary: dict,
    *,
    limit: int,
) -> str:
    breadth = observation_summary.get("sector_breadth") or {}
    items = [
        item
        for item in [
            *(breadth.get("sectors") or []),
            *(breadth.get("themes") or []),
        ]
        if isinstance(item, dict)
    ][:limit]
    if not items:
        return ""
    lines = ["업종/테마 폭"]
    for item in items:
        display = str(item.get("display") or "").strip()
        if not display:
            display = str(item.get("category_display_name") or item.get("display_name") or "-")
        lines.append(f"- {display}")
    return "\n".join(lines)


def _run_observation_reaction_distribution(
    repository: StockMonitorRepository,
    *,
    from_date: date | None,
    to_date: date | None,
    mention_threshold: int,
    as_json: bool,
) -> int:
    if (from_date is None) != (to_date is None):
        raise ValueError("--from-date and --to-date must be provided together")

    if from_date is None and to_date is None:
        default_range = _observation_reaction_default_date_range(repository)
        if default_range is None:
            payload = {
                "surface": "cli",
                "read_only": True,
                "scoring": False,
                "recommendation": False,
                "from_date": None,
                "to_date": None,
                "mention_threshold": mention_threshold,
                "candidate_count": 0,
                "horizon_coverage": [],
                "groups": [],
                "interpretation_status": "no_stored_summary_baseline",
                "notice": "Read-only reaction distribution; no scoring or recommendation is produced.",
            }
            if as_json:
                print(json.dumps(payload, ensure_ascii=False, indent=2))
                return 0

            print("Observation reaction distribution")
            print("- range: no stored daily summary baseline")
            print(f"- mention threshold: {mention_threshold}+")
            print("- candidate rows: 0")
            print("- read-only: true")
            print("- scoring: false")
            print("- recommendation: false")
            return 0
        from_date, to_date = default_range

    if from_date > to_date:
        raise ValueError("--from-date must be earlier than or equal to --to-date")

    audit = build_reaction_distribution_audit(
        repository,
        from_date=from_date,
        to_date=to_date,
        mention_threshold=mention_threshold,
    )
    groups = [
        {
            "mention_bucket": group.mention_bucket,
            "target_available": group.target_available,
            "stock_flow_available": group.stock_flow_available,
            "horizon_days": group.horizon_days,
            "candidate_count": group.candidate_count,
            "available_count": group.available_count,
            "rising_count": group.rising_count,
            "falling_count": group.falling_count,
            "flat_count": group.flat_count,
            "missing_count": group.missing_count,
            "average_return_percent": group.average_return_percent,
            "min_return_percent": group.min_return_percent,
            "max_return_percent": group.max_return_percent,
        }
        for group in audit.groups
    ]
    horizon_coverage = _build_reaction_horizon_coverage(audit.groups)
    payload = {
        "surface": "cli",
        "read_only": True,
        "scoring": False,
        "recommendation": False,
        "from_date": audit.from_date.isoformat(),
        "to_date": audit.to_date.isoformat(),
        "mention_threshold": audit.mention_threshold,
        "candidate_count": audit.candidate_count,
        "horizon_coverage": horizon_coverage,
        "groups": groups,
        "notice": "Read-only reaction distribution; no scoring or recommendation is produced.",
    }

    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    print("Observation reaction distribution")
    print(f"- range: {payload['from_date']} ~ {payload['to_date']}")
    print(f"- mention threshold: {audit.mention_threshold}+")
    print(f"- candidate rows: {audit.candidate_count}")
    for coverage in horizon_coverage:
        print(
            f"- coverage D+{coverage['horizon_days']}: "
            f"available={coverage['available_count']}/{coverage['candidate_count']} "
            f"missing={coverage['missing_count']} "
            f"({coverage['available_percent']}%) | {coverage['coverage_label']} | "
            f"{coverage['missing_window_label']}"
        )
    for group in audit.groups:
        average = "-" if group.average_return_percent is None else f"{group.average_return_percent}%"
        min_return = "-" if group.min_return_percent is None else f"{group.min_return_percent}%"
        max_return = "-" if group.max_return_percent is None else f"{group.max_return_percent}%"
        print(
            f"- D+{group.horizon_days} | mention={group.mention_bucket} | "
            f"target={'yes' if group.target_available else 'no'} | "
            f"flow={'yes' if group.stock_flow_available else 'no'} | "
            f"rows={group.candidate_count} available={group.available_count} "
            f"up={group.rising_count} down={group.falling_count} flat={group.flat_count} "
            f"missing={group.missing_count} avg={average} min={min_return} max={max_return}"
        )
    print("- read-only: true")
    print("- scoring: false")
    print("- recommendation: false")
    return 0


def _observation_reaction_default_date_range(repository: StockMonitorRepository) -> tuple[date, date] | None:
    with repository.connect() as connection:
        row = connection.execute(
            """
            SELECT MIN(business_date) AS from_date,
                   MAX(business_date) AS to_date
            FROM daily_stock_summaries
            """
        ).fetchone()
    from_date_raw = row["from_date"] if row else None
    to_date_raw = row["to_date"] if row else None
    if not from_date_raw or not to_date_raw:
        return None
    return date.fromisoformat(str(from_date_raw)), date.fromisoformat(str(to_date_raw))


def _build_reaction_horizon_coverage(groups: tuple[object, ...]) -> list[dict[str, object]]:
    totals: dict[int, dict[str, int]] = {}
    for group in groups:
        horizon_days = int(getattr(group, "horizon_days"))
        bucket = totals.setdefault(
            horizon_days,
            {
                "candidate_count": 0,
                "available_count": 0,
                "missing_count": 0,
                "rising_count": 0,
                "falling_count": 0,
                "flat_count": 0,
            },
        )
        bucket["candidate_count"] += int(getattr(group, "candidate_count"))
        bucket["available_count"] += int(getattr(group, "available_count"))
        bucket["missing_count"] += int(getattr(group, "missing_count"))
        bucket["rising_count"] += int(getattr(group, "rising_count"))
        bucket["falling_count"] += int(getattr(group, "falling_count"))
        bucket["flat_count"] += int(getattr(group, "flat_count"))

    rows: list[dict[str, object]] = []
    for horizon_days in sorted(totals):
        counts = totals[horizon_days]
        candidate_count = counts["candidate_count"]
        available_count = counts["available_count"]
        missing_count = counts["missing_count"]
        available_percent = round(available_count / candidate_count * 100, 2) if candidate_count else 0.0
        if candidate_count == 0:
            coverage_label = "no_candidates"
        elif available_count == 0:
            coverage_label = "no_completed_window"
        elif missing_count == 0:
            coverage_label = "complete_window"
        elif available_percent < 50:
            coverage_label = "thin_completed_window"
        else:
            coverage_label = "partial_completed_window"
        rows.append(
            {
                "horizon_days": horizon_days,
                "candidate_count": candidate_count,
                "available_count": available_count,
                "missing_count": missing_count,
                "available_percent": available_percent,
                "rising_count": counts["rising_count"],
                "falling_count": counts["falling_count"],
                "flat_count": counts["flat_count"],
                "coverage_label": coverage_label,
                "missing_window_label": (
                    f"{missing_count} missing D+{horizon_days} window(s)"
                    if missing_count
                    else f"no missing D+{horizon_days} window"
                ),
            }
        )
    return rows


def _run_observation_feature_comparison(
    repository: StockMonitorRepository,
    *,
    from_date: date,
    to_date: date,
    mention_threshold: int,
    as_json: bool,
) -> int:
    if from_date > to_date:
        raise ValueError("--from-date must be earlier than or equal to --to-date")

    audit = build_feature_comparison_audit(
        repository,
        from_date=from_date,
        to_date=to_date,
        mention_threshold=mention_threshold,
    )
    groups = [
        {
            "feature_name": group.feature_name,
            "feature_value": group.feature_value,
            "horizon_days": group.horizon_days,
            "candidate_count": group.candidate_count,
            "available_count": group.available_count,
            "rising_count": group.rising_count,
            "falling_count": group.falling_count,
            "flat_count": group.flat_count,
            "missing_count": group.missing_count,
            "average_return_percent": group.average_return_percent,
            "min_return_percent": group.min_return_percent,
            "max_return_percent": group.max_return_percent,
        }
        for group in audit.groups
    ]
    payload = {
        "surface": "cli",
        "read_only": True,
        "scoring": False,
        "recommendation": False,
        "from_date": audit.from_date.isoformat(),
        "to_date": audit.to_date.isoformat(),
        "mention_threshold": audit.mention_threshold,
        "candidate_count": audit.candidate_count,
        "groups": groups,
        "notice": "Read-only feature comparison; no scoring or recommendation is produced.",
    }

    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    print("Observation feature comparison")
    print(f"- range: {payload['from_date']} ~ {payload['to_date']}")
    print(f"- mention threshold: {audit.mention_threshold}+")
    print(f"- candidate rows: {audit.candidate_count}")
    for group in audit.groups:
        average = "-" if group.average_return_percent is None else f"{group.average_return_percent}%"
        min_return = "-" if group.min_return_percent is None else f"{group.min_return_percent}%"
        max_return = "-" if group.max_return_percent is None else f"{group.max_return_percent}%"
        print(
            f"- D+{group.horizon_days} | {group.feature_name}={group.feature_value} | "
            f"rows={group.candidate_count} available={group.available_count} "
            f"up={group.rising_count} down={group.falling_count} flat={group.flat_count} "
            f"missing={group.missing_count} avg={average} min={min_return} max={max_return}"
        )
    print("- read-only: true")
    print("- scoring: false")
    print("- recommendation: false")
    return 0


