def _run_observation_hidden_score_prototype(
    repository: StockMonitorRepository,
    *,
    train_from_date: date | None = None,
    train_to_date: date | None = None,
    from_date: date,
    to_date: date,
    mention_threshold: int,
    horizon_days: int,
    min_sample_size: int,
    as_json: bool,
    excluded_features: tuple[str, ...] = (),
) -> int:
    if from_date > to_date:
        raise ValueError("--from-date must be earlier than or equal to --to-date")
    if train_from_date and train_to_date and train_from_date > train_to_date:
        raise ValueError("--train-from-date must be earlier than or equal to --train-to-date")
    if horizon_days < 1:
        raise ValueError("--horizon-days must be greater than or equal to 1")
    if min_sample_size < 1:
        raise ValueError("--min-sample-size must be greater than or equal to 1")

    prototype = build_hidden_score_prototype(
        repository,
        train_from_date=train_from_date,
        train_to_date=train_to_date,
        from_date=from_date,
        to_date=to_date,
        mention_threshold=mention_threshold,
        horizon_days=horizon_days,
        min_sample_size=min_sample_size,
        excluded_features=excluded_features,
    )
    rows = [
        {
            "business_date": row.business_date.isoformat(),
            "stock_code": row.stock_code,
            "stock_name": row.stock_name,
            "mention_count": row.mention_count,
            "horizon_days": row.horizon_days,
            "prototype_value": row.prototype_value,
            "rank": row.rank,
            "components": [
                {
                    "feature_name": component.feature_name,
                    "feature_value": component.feature_value,
                    "draft_weight": component.draft_weight,
                    "direction": component.direction,
                    "caution": component.caution,
                }
                for component in row.components
            ],
        }
        for row in prototype.rows
    ]
    payload = {
        "surface": "cli",
        "read_only": True,
        "internal_only": prototype.internal_only,
        "public_decision": False,
        "scoring": False,
        "recommendation": False,
        "train_from_date": prototype.train_from_date.isoformat(),
        "train_to_date": prototype.train_to_date.isoformat(),
        "from_date": prototype.from_date.isoformat(),
        "to_date": prototype.to_date.isoformat(),
        "mention_threshold": prototype.mention_threshold,
        "horizon_days": prototype.horizon_days,
        "excluded_features": list(prototype.excluded_features),
        "rows": rows,
        "notice": "Hidden internal prototype only; no public decision, rank, scoring, or recommendation is produced.",
    }

    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    print("Observation hidden internal prototype")
    print(f"- train range: {payload['train_from_date']} ~ {payload['train_to_date']}")
    print(f"- range: {payload['from_date']} ~ {payload['to_date']}")
    print(f"- mention threshold: {prototype.mention_threshold}+")
    print(f"- horizon days: {prototype.horizon_days}")
    print(f"- excluded features: {', '.join(prototype.excluded_features) if prototype.excluded_features else '-'}")
    print(f"- internal-only: {str(prototype.internal_only).lower()}")
    print("- public decision: false")
    for row in prototype.rows:
        components = ", ".join(
            f"{component.feature_name}={component.feature_value}:{component.draft_weight}"
            for component in row.components
            if component.draft_weight != 0
        )
        if not components:
            components = "-"
        print(
            f"- {row.business_date.isoformat()} | {row.stock_name}({row.stock_code}) | "
            f"mentions={row.mention_count} prototype_value={row.prototype_value} components={components}"
        )
    print("- read-only: true")
    print("- scoring: false")
    return 0


