def _run_observation_hidden_holdout_sweep(
    repository: StockMonitorRepository,
    *,
    train_from_date: date,
    train_to_date: date,
    holdout_from_date: date,
    holdout_to_date: date,
    mention_threshold: int,
    horizon_days: tuple[int, ...],
    min_sample_size: int,
    window_days: int,
    excluded_features: tuple[str, ...],
    as_json: bool,
) -> int:
    if train_from_date > train_to_date:
        raise ValueError("--train-from-date must be earlier than or equal to --train-to-date")
    if holdout_from_date > holdout_to_date:
        raise ValueError("--holdout-from-date must be earlier than or equal to --holdout-to-date")
    if not horizon_days:
        raise ValueError("--horizon-days must be provided at least once")
    if any(horizon < 1 for horizon in horizon_days):
        raise ValueError("--horizon-days must be greater than or equal to 1")
    if min_sample_size < 1:
        raise ValueError("--min-sample-size must be greater than or equal to 1")
    if window_days < 1:
        raise ValueError("--window-days must be greater than or equal to 1")

    sweep = build_hidden_score_holdout_sweep(
        repository,
        train_from_date=train_from_date,
        train_to_date=train_to_date,
        holdout_from_date=holdout_from_date,
        holdout_to_date=holdout_to_date,
        mention_threshold=mention_threshold,
        horizon_days=horizon_days,
        min_sample_size=min_sample_size,
        window_days=window_days,
        excluded_features=excluded_features,
    )
    validations = [
        {
            "holdout_from_date": validation.holdout_from_date.isoformat(),
            "holdout_to_date": validation.holdout_to_date.isoformat(),
            "horizon_days": validation.horizon_days,
            "candidate_count": validation.candidate_count,
            "available_count": validation.available_count,
            "buckets": [
                {
                    "bucket_name": bucket.bucket_name,
                    "candidate_count": bucket.candidate_count,
                    "available_count": bucket.available_count,
                    "average_return_percent": bucket.average_return_percent,
                    "rising_count": bucket.rising_count,
                    "falling_count": bucket.falling_count,
                    "flat_count": bucket.flat_count,
                    "missing_count": bucket.missing_count,
                    "prototype_value_min": bucket.prototype_value_min,
                    "prototype_value_max": bucket.prototype_value_max,
                }
                for bucket in validation.buckets
            ],
        }
        for validation in sweep.validations
    ]
    payload = {
        "surface": "cli",
        "read_only": True,
        "internal_only": sweep.internal_only,
        "public_decision": False,
        "scoring": sweep.scoring,
        "recommendation": sweep.recommendation,
        "train_from_date": sweep.train_from_date.isoformat(),
        "train_to_date": sweep.train_to_date.isoformat(),
        "holdout_from_date": sweep.holdout_from_date.isoformat(),
        "holdout_to_date": sweep.holdout_to_date.isoformat(),
        "mention_threshold": sweep.mention_threshold,
        "horizon_days": list(sweep.horizon_days),
        "min_sample_size": sweep.min_sample_size,
        "window_days": sweep.window_days,
        "excluded_features": list(sweep.excluded_features),
        "validations": validations,
        "notice": "Hidden internal holdout sweep only; no public score, rank, recommendation, or trading decision is produced.",
    }
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    print("Observation hidden holdout sweep")
    print(f"- train range: {payload['train_from_date']} ~ {payload['train_to_date']}")
    print(f"- holdout range: {payload['holdout_from_date']} ~ {payload['holdout_to_date']}")
    print(f"- horizons: {', '.join(str(item) for item in sweep.horizon_days)}")
    print(f"- window days: {sweep.window_days}")
    print(f"- excluded features: {', '.join(sweep.excluded_features) if sweep.excluded_features else '-'}")
    print("- public decision: false")
    for validation in sweep.validations:
        print(
            f"- {validation.holdout_from_date.isoformat()}~{validation.holdout_to_date.isoformat()} "
            f"D+{validation.horizon_days} candidates={validation.candidate_count} available={validation.available_count}"
        )
    print("- read-only: true")
    print("- scoring: false")
    print("- recommendation: false")
    return 0


