def _run_refresh_theme(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    theme_code: str,
    page_size: int,
    max_pages: int,
    snapshot_date: date | None = None,
) -> int:
    fetched_at = datetime.now(ZoneInfo(config.timezone))
    result = fetch_stock_theme_memberships(
        theme_code,
        timeout_seconds=config.telegram_timeout_seconds,
        page_size=page_size,
        max_pages=max_pages,
        fetched_at=fetched_at,
    )
    repository.upsert_stock_theme_memberships(list(result.memberships))
    snapshot_count = 0
    if snapshot_date is not None:
        repository.upsert_category_catalog_items(
            [
                CategoryCatalogItem(
                    category_type="theme",
                    category_key=result.theme_code,
                    display_name=result.theme_name,
                    source="naver_theme",
                    enabled=True,
                    updated_at=fetched_at,
                )
            ]
        )
        snapshot_count = repository.upsert_category_membership_snapshots(
            [
                CategoryMembershipSnapshot(
                    snapshot_date=snapshot_date,
                    category_type="theme",
                    category_key=result.theme_code,
                    display_name=result.theme_name,
                    stock_code=item.stock_code,
                    stock_name=item.stock_name,
                    fetched_at=fetched_at,
                    source=item.source,
                )
                for item in result.memberships
            ]
        )
    repository.record_operation_event(
        _operation_event(
            config,
            component="theme",
            event_type="refresh",
            status="success",
            detail=(
                f"{result.theme_code}; {result.theme_name}; memberships={len(result.memberships)}; "
                f"snapshot_date={snapshot_date.isoformat() if snapshot_date else '-'}; snapshot_rows={snapshot_count}"
            ),
        )
    )
    print(f"Theme refreshed: {result.theme_name} ({result.theme_code}) / {len(result.memberships)} stocks")
    if snapshot_date is not None:
        print(f"- category snapshot: {snapshot_date.isoformat()} / {snapshot_count} rows")
    return 0


