def _build_news_evidence_coverage_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    recent_business_days: int,
    candidate_limit: int,
) -> dict[str, object]:
    inspected_dates = [
        business_date
        for business_date, _summary_count in repository.count_summaries_by_business_date(
            limit=max(recent_business_days, 0)
        )
    ]
    row_limit = max(candidate_limit, 5, 0)
    top2 = {"candidate_count": 0, "with_digest_count": 0}
    top5 = {"candidate_count": 0, "with_digest_count": 0}
    runs_available_dates = 0
    linked_evidence_dates = 0
    run_count = 0
    completed_without_evidence_count = 0
    linked_evidence_row_count = 0
    relevance_counts: Counter[str] = Counter()
    source_lane_counts: Counter[str] = Counter()
    failure_reasons: Counter[str] = Counter()
    date_rows: list[dict[str, object]] = []

    for business_date in inspected_dates:
        snapshot = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=row_limit,
            include_internal=True,
        )
        rows = list(snapshot.get("rows") or [])
        runs = repository.list_news_intelligence_runs(target_date=business_date, limit=1000)
        evidence_rows = _web_view_unique_news_evidence_rows(
            repository.list_report_linked_news_evidence(target_date=business_date, limit=5000)
        )
        run_count += len(runs)
        if runs:
            runs_available_dates += 1
        if evidence_rows:
            linked_evidence_dates += 1
        linked_evidence_row_count += len(evidence_rows)
        evidence_count_by_run = Counter(row.run_id for row in evidence_rows)
        completed_without_evidence_count += sum(1 for run in runs if evidence_count_by_run.get(run.run_id, 0) == 0)
        for row in evidence_rows:
            relevance_counts[_news_evidence_coverage_relevance_bucket(row.relevance)] += 1
            source_lane_counts[(row.source_lane or "unknown").strip() or "unknown"] += 1
            if not getattr(row, "published_at", None):
                failure_reasons["missing_published_at"] += 1

        top2_rows = rows[:2]
        top5_rows = rows[:5]
        top2["candidate_count"] += len(top2_rows)
        top2["with_digest_count"] += sum(1 for row in top2_rows if _news_evidence_candidate_has_digest(row))
        top5["candidate_count"] += len(top5_rows)
        top5["with_digest_count"] += sum(1 for row in top5_rows if _news_evidence_candidate_has_digest(row))

        candidate_rows: list[dict[str, object]] = []
        for rank, row in enumerate(rows[: max(candidate_limit, 0)], start=1):
            stock_code = str(row.get("stock_code") or "")
            stock_name = str(row.get("stock_name") or "")
            matching_runs = [
                run for run in runs if _news_evidence_run_matches_candidate(run, stock_code=stock_code, stock_name=stock_name)
            ]
            matching_rows = _web_view_news_observation_rows_for_stock(
                repository,
                business_date=business_date,
                stock_code=stock_code,
                stock_name=stock_name,
            )
            candidate_reasons = _news_evidence_candidate_failure_reasons(
                runs=runs,
                matching_runs=matching_runs,
                matching_rows=matching_rows,
            )
            failure_reasons.update(candidate_reasons)
            badge = row.get("news_observation_badge") or {}
            candidate_rows.append(
                {
                    "rank": rank,
                    "stock_code": stock_code,
                    "stock_name": stock_name,
                    "with_digest": _news_evidence_candidate_has_digest(row),
                    "digest_label": badge.get("digest_label"),
                    "direct_count": badge.get("direct_count", 0),
                    "market_context_count": badge.get("market_context_count", 0),
                    "failure_reasons": candidate_reasons,
                }
            )

        date_rows.append(
            {
                "business_date": business_date.isoformat(),
                "candidate_count": len(rows[: max(candidate_limit, 0)]),
                "top2_with_digest_count": sum(1 for row in top2_rows if _news_evidence_candidate_has_digest(row)),
                "top5_with_digest_count": sum(1 for row in top5_rows if _news_evidence_candidate_has_digest(row)),
                "news_run_count": len(runs),
                "linked_evidence_count": len(evidence_rows),
                "candidates": candidate_rows,
            }
        )

    payload = {
        "surface": "news-evidence-coverage-audit",
        "read_only": True,
        "writes_db": False,
        "scoring": False,
        "recommendation": False,
        "recent_business_days": recent_business_days,
        "candidate_limit": candidate_limit,
        "dates": [business_date.isoformat() for business_date in inspected_dates],
        "top2": {
            **top2,
            "coverage_percent": _news_evidence_coverage_percent(
                candidate_count=top2["candidate_count"],
                with_digest_count=top2["with_digest_count"],
            ),
        },
        "top5": {
            **top5,
            "coverage_percent": _news_evidence_coverage_percent(
                candidate_count=top5["candidate_count"],
                with_digest_count=top5["with_digest_count"],
            ),
        },
        "runs": {
            "available_dates": runs_available_dates,
            "missing_dates": len(inspected_dates) - runs_available_dates,
            "run_count": run_count,
            "completed_without_evidence_count": completed_without_evidence_count,
        },
        "linked_evidence": {
            "date_count": linked_evidence_dates,
            "row_count": linked_evidence_row_count,
        },
        "relevance_distribution": _ordered_nonzero_count_map(
            relevance_counts,
            ("direct", "market_context", "reference"),
        ),
        "source_lane_distribution": dict(sorted(source_lane_counts.items())),
        "failure_reasons": _ordered_nonzero_count_map(
            failure_reasons,
            (
                "no_news_run",
                "no_linked_evidence",
                "only_market_context",
                "only_reference",
                "missing_published_at",
                "stock_match_missing",
            ),
        ),
        "bottleneck": _news_evidence_coverage_bottleneck(failure_reasons),
        "date_breakdown": date_rows,
    }
    return payload


def _news_evidence_candidate_has_digest(row: dict[str, object]) -> bool:
    badge = row.get("news_observation_badge") or {}
    if not isinstance(badge, dict):
        return False
    return bool(badge.get("digest_label") or badge.get("news_digest"))


def _news_evidence_coverage_percent(*, candidate_count: int, with_digest_count: int) -> float:
    if candidate_count <= 0:
        return 0.0
    return round((with_digest_count / candidate_count) * 100, 1)


def _news_evidence_coverage_relevance_bucket(value: str | None) -> str:
    if value == "direct":
        return "direct"
    if value == "market_context":
        return "market_context"
    return "reference"


def _news_evidence_run_matches_candidate(
    run: object,
    *,
    stock_code: str,
    stock_name: str,
) -> bool:
    normalized_stock_name = _web_view_normalize_news_identity(stock_name)
    run_stock_code = str(getattr(run, "stock_code", "") or "")
    if stock_code and run_stock_code == stock_code:
        return True
    if run_stock_code:
        return False
    return bool(normalized_stock_name and _web_view_normalize_news_identity(getattr(run, "stock_name", None)) == normalized_stock_name)


def _news_evidence_candidate_failure_reasons(
    *,
    runs: Sequence[object],
    matching_runs: Sequence[object],
    matching_rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> list[str]:
    reasons: list[str] = []
    if not runs:
        return ["no_news_run"]
    if not matching_runs:
        reasons.append("stock_match_missing")
    if matching_runs and not matching_rows:
        reasons.append("no_linked_evidence")
    if matching_rows and not any(row.relevance == "direct" for row in matching_rows):
        if any(row.relevance == "market_context" for row in matching_rows):
            reasons.append("only_market_context")
        else:
            reasons.append("only_reference")
    if any(not getattr(row, "published_at", None) for row in matching_rows):
        reasons.append("missing_published_at")
    return reasons


def _ordered_nonzero_count_map(counts: Counter[str], preferred_order: Sequence[str]) -> dict[str, int]:
    payload: dict[str, int] = {}
    for key in preferred_order:
        value = int(counts.get(key, 0))
        if value:
            payload[key] = value
    for key in sorted(set(counts) - set(preferred_order)):
        value = int(counts.get(key, 0))
        if value:
            payload[key] = value
    return payload


def _news_evidence_coverage_bottleneck(failure_reasons: Counter[str]) -> str:
    ordered = (
        ("no_news_run", "latest_or_date_level_news_runs_missing"),
        ("no_linked_evidence", "news_runs_exist_but_linked_evidence_missing"),
        ("stock_match_missing", "candidate_stock_matching_gap"),
        ("only_market_context", "direct_evidence_sparse"),
        ("only_reference", "direct_evidence_sparse"),
        ("missing_published_at", "published_at_gap"),
    )
    best_key = ""
    best_value = 0
    best_label = "insufficient_gap_signal"
    for key, label in ordered:
        value = int(failure_reasons.get(key, 0))
        if value > best_value:
            best_key = key
            best_value = value
            best_label = label
    if not best_key:
        return best_label
    return best_label


NEWS_EVIDENCE_MATCH_REASON_ORDER = (
    "no_evidence_for_candidate_stock",
    "evidence_stock_name_alias_mismatch",
    "evidence_missing_stock_code",
    "evidence_date_mismatch",
    "evidence_only_market_or_reference",
    "candidate_not_in_news_collection_scope",
    "unknown",
)


def _run_news_evidence_match_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    recent_business_days: int,
    candidate_limit: int,
    as_json: bool,
) -> int:
    payload = _build_news_evidence_match_audit(
        config,
        repository,
        recent_business_days=recent_business_days,
        candidate_limit=candidate_limit,
    )
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    summary = payload["summary"]
    print("News Evidence Digest match audit")
    print("- read_only: true")
    print("- writes_db: false")
    print(f"- candidate count: {summary['candidate_count']}")
    print(f"- missing digest: {summary['missing_digest_count']}")
    print(f"- stock match missing: {summary['stock_match_missing_count']}")
    print(f"- stock match reasons: {_format_count_map(summary['stock_match_missing_reasons'])}")
    print(f"- missing digest reasons: {_format_count_map(summary['missing_digest_reasons'])}")
    print(f"- collection gap: {payload['collection_gap']['count']}")
    print(f"- matching gap: {payload['matching_gap']['count']}")
    return 0


def _build_news_evidence_match_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    recent_business_days: int,
    candidate_limit: int,
) -> dict[str, object]:
    inspected_dates = [
        business_date
        for business_date, _summary_count in repository.count_summaries_by_business_date(
            limit=max(recent_business_days, 0)
        )
    ]
    all_evidence_rows = _web_view_unique_news_evidence_rows(
        repository.list_report_linked_news_evidence(limit=50000)
    )
    evidence_by_date: dict[date, list[ReportLinkedNewsEvidenceRecord]] = defaultdict(list)
    for row in all_evidence_rows:
        evidence_by_date[row.target_date].append(row)

    candidate_count = 0
    missing_digest_count = 0
    stock_match_missing_count = 0
    top2 = {"candidate_count": 0, "missing_digest_count": 0, "stock_match_missing_count": 0}
    top5 = {"candidate_count": 0, "missing_digest_count": 0, "stock_match_missing_count": 0}
    missing_digest_reasons: Counter[str] = Counter()
    stock_match_missing_reasons: Counter[str] = Counter()
    candidate_lists: list[dict[str, object]] = []
    examples: list[dict[str, object]] = []
    examples_by_reason: dict[str, list[dict[str, object]]] = {reason: [] for reason in NEWS_EVIDENCE_MATCH_REASON_ORDER}

    for business_date in inspected_dates:
        snapshot = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=max(candidate_limit, 5, 0),
            include_internal=True,
        )
        rows = list(snapshot.get("rows") or [])[: max(candidate_limit, 0)]
        runs = repository.list_news_intelligence_runs(target_date=business_date, limit=1000)
        same_date_evidence = evidence_by_date.get(business_date, [])
        date_candidates: list[dict[str, object]] = []

        for rank, row in enumerate(rows, start=1):
            candidate_count += 1
            if rank <= 2:
                top2["candidate_count"] += 1
            if rank <= 5:
                top5["candidate_count"] += 1
            stock_code = str(row.get("stock_code") or "")
            stock_name = str(row.get("stock_name") or "")
            with_digest = _news_evidence_candidate_has_digest(row)
            matching_runs = [
                run for run in runs if _news_evidence_run_matches_candidate(run, stock_code=stock_code, stock_name=stock_name)
            ]
            matching_rows = _web_view_news_observation_rows_for_stock(
                repository,
                business_date=business_date,
                stock_code=stock_code,
                stock_name=stock_name,
            )
            stock_match_missing = not matching_runs
            classification = _news_evidence_match_classify_candidate(
                business_date=business_date,
                stock_code=stock_code,
                stock_name=stock_name,
                with_digest=with_digest,
                matching_runs=matching_runs,
                matching_rows=matching_rows,
                same_date_evidence=same_date_evidence,
                all_evidence_rows=all_evidence_rows,
            )
            reason = str(classification["reason"])
            if not with_digest:
                missing_digest_count += 1
                missing_digest_reasons[reason] += 1
                if rank <= 2:
                    top2["missing_digest_count"] += 1
                if rank <= 5:
                    top5["missing_digest_count"] += 1
            if stock_match_missing:
                stock_match_missing_count += 1
                stock_match_missing_reasons[reason] += 1
                if rank <= 2:
                    top2["stock_match_missing_count"] += 1
                if rank <= 5:
                    top5["stock_match_missing_count"] += 1

            candidate_entry = {
                "business_date": business_date.isoformat(),
                "rank": rank,
                "selected_top2": rank <= 2,
                "selected_top5": rank <= 5,
                "stock_code": stock_code,
                "stock_name": stock_name,
                "news_digest": with_digest,
                "matching_run_count": len(matching_runs),
                "matching_evidence_count": len(matching_rows),
                "stock_match_missing": stock_match_missing,
                "missing_reason": None if with_digest else reason,
                "audit_reason": reason,
                "nearby_evidence_names": classification["nearby_evidence_names"],
                "nearby_evidence": classification["nearby_evidence"],
            }
            date_candidates.append(candidate_entry)
            if not with_digest and len(examples) < 20:
                examples.append(candidate_entry)
            if not with_digest and len(examples_by_reason.get(reason, [])) < 10:
                examples_by_reason.setdefault(reason, []).append(candidate_entry)

        candidate_lists.append(
            {
                "business_date": business_date.isoformat(),
                "candidate_count": len(rows),
                "news_run_count": len(runs),
                "evidence_count": len(same_date_evidence),
                "candidates": date_candidates,
            }
        )

    collection_reasons = {"candidate_not_in_news_collection_scope"}
    matching_reasons = {
        "evidence_stock_name_alias_mismatch",
        "evidence_missing_stock_code",
        "evidence_date_mismatch",
    }
    evidence_gap_reasons = {"no_evidence_for_candidate_stock", "evidence_only_market_or_reference", "unknown"}
    stock_match_reason_map = _ordered_nonzero_count_map(
        stock_match_missing_reasons,
        NEWS_EVIDENCE_MATCH_REASON_ORDER,
    )
    missing_digest_reason_map = _ordered_nonzero_count_map(
        missing_digest_reasons,
        NEWS_EVIDENCE_MATCH_REASON_ORDER,
    )
    return {
        "surface": "news-evidence-match-audit",
        "read_only": True,
        "writes_db": False,
        "scoring": False,
        "recommendation": False,
        "recent_business_days": recent_business_days,
        "candidate_limit": candidate_limit,
        "dates": [business_date.isoformat() for business_date in inspected_dates],
        "summary": {
            "candidate_count": candidate_count,
            "missing_digest_count": missing_digest_count,
            "stock_match_missing_count": stock_match_missing_count,
            "top2": top2,
            "top5": top5,
            "stock_match_missing_reasons": stock_match_reason_map,
            "missing_digest_reasons": missing_digest_reason_map,
        },
        "collection_gap": {
            "count": sum(stock_match_missing_reasons.get(reason, 0) for reason in collection_reasons),
            "reasons": {
                reason: int(stock_match_missing_reasons.get(reason, 0))
                for reason in sorted(collection_reasons)
                if stock_match_missing_reasons.get(reason, 0)
            },
        },
        "matching_gap": {
            "count": sum(stock_match_missing_reasons.get(reason, 0) for reason in matching_reasons),
            "reasons": {
                reason: int(stock_match_missing_reasons.get(reason, 0))
                for reason in NEWS_EVIDENCE_MATCH_REASON_ORDER
                if reason in matching_reasons and stock_match_missing_reasons.get(reason, 0)
            },
        },
        "evidence_gap": {
            "count": sum(missing_digest_reasons.get(reason, 0) for reason in evidence_gap_reasons),
            "reasons": {
                reason: int(missing_digest_reasons.get(reason, 0))
                for reason in NEWS_EVIDENCE_MATCH_REASON_ORDER
                if reason in evidence_gap_reasons and missing_digest_reasons.get(reason, 0)
            },
        },
        "evidence_by_date": [
            _news_evidence_match_evidence_date_summary(business_date, evidence_by_date.get(business_date, []))
            for business_date in inspected_dates
        ],
        "candidate_lists": candidate_lists,
        "examples": examples,
        "alias_mismatch_examples": examples_by_reason.get("evidence_stock_name_alias_mismatch", []),
        "stock_code_missing_examples": examples_by_reason.get("evidence_missing_stock_code", []),
        "date_mismatch_examples": examples_by_reason.get("evidence_date_mismatch", []),
    }


def _news_evidence_match_classify_candidate(
    *,
    business_date: date,
    stock_code: str,
    stock_name: str,
    with_digest: bool,
    matching_runs: Sequence[object],
    matching_rows: Sequence[ReportLinkedNewsEvidenceRecord],
    same_date_evidence: Sequence[ReportLinkedNewsEvidenceRecord],
    all_evidence_rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    if matching_rows and not any(row.relevance == "direct" for row in matching_rows):
        return _news_evidence_match_classification("evidence_only_market_or_reference", matching_rows)
    if with_digest:
        return _news_evidence_match_classification("has_digest", matching_rows)
    if matching_runs and not matching_rows:
        return _news_evidence_match_classification("no_evidence_for_candidate_stock", [])

    same_date_related = [
        row for row in same_date_evidence if _news_evidence_match_row_related(row, stock_code=stock_code, stock_name=stock_name)
    ]
    missing_code_rows = [
        row
        for row in same_date_related
        if not (row.stock_code or "").strip()
        and _news_evidence_match_names_similar(stock_name, row.stock_name)
    ]
    if missing_code_rows:
        return _news_evidence_match_classification("evidence_missing_stock_code", missing_code_rows)
    alias_rows = [
        row
        for row in same_date_related
        if (row.stock_code or "").strip() != stock_code
        and _news_evidence_match_names_similar(stock_name, row.stock_name)
    ]
    if alias_rows:
        return _news_evidence_match_classification("evidence_stock_name_alias_mismatch", alias_rows)

    other_date_related = [
        row
        for row in all_evidence_rows
        if row.target_date != business_date
        and _news_evidence_match_row_related(row, stock_code=stock_code, stock_name=stock_name)
    ]
    if other_date_related:
        return _news_evidence_match_classification("evidence_date_mismatch", other_date_related)
    if not matching_runs:
        return _news_evidence_match_classification("candidate_not_in_news_collection_scope", [])
    return _news_evidence_match_classification("unknown", same_date_related)


def _news_evidence_match_classification(
    reason: str,
    rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    nearby_rows = list(rows[:5])
    return {
        "reason": reason,
        "nearby_evidence_names": _web_view_unique_texts([row.stock_name for row in nearby_rows], limit=5),
        "nearby_evidence": [
            {
                "target_date": row.target_date.isoformat(),
                "stock_code": row.stock_code,
                "stock_name": row.stock_name,
                "relevance": _news_evidence_coverage_relevance_bucket(row.relevance),
                "source_lane": row.source_lane,
                "title": row.title,
            }
            for row in nearby_rows
        ],
    }


def _news_evidence_match_row_related(
    row: ReportLinkedNewsEvidenceRecord,
    *,
    stock_code: str,
    stock_name: str,
) -> bool:
    if stock_code and (row.stock_code or "").strip() == stock_code:
        return True
    return _news_evidence_match_names_similar(stock_name, row.stock_name)


def _news_evidence_match_normalize_name(value: str | None) -> str:
    return re.sub(r"[^0-9a-z가-힣]+", "", (value or "").casefold())


def _news_evidence_match_names_similar(left: str | None, right: str | None) -> bool:
    left_normalized = _news_evidence_match_normalize_name(left)
    right_normalized = _news_evidence_match_normalize_name(right)
    if not left_normalized or not right_normalized:
        return False
    if left_normalized == right_normalized:
        return True
    shorter, longer = sorted((left_normalized, right_normalized), key=len)
    if len(shorter) >= 3 and shorter in longer:
        return True
    return SequenceMatcher(None, left_normalized, right_normalized).ratio() >= 0.82


def _news_evidence_match_evidence_date_summary(
    business_date: date,
    rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    return {
        "business_date": business_date.isoformat(),
        "evidence_count": len(rows),
        "stock_code_present_count": sum(1 for row in rows if (row.stock_code or "").strip()),
        "stock_code_missing_count": sum(1 for row in rows if not (row.stock_code or "").strip()),
        "stock_name_present_count": sum(1 for row in rows if (row.stock_name or "").strip()),
        "relevance_distribution": _ordered_nonzero_count_map(
            Counter(_news_evidence_coverage_relevance_bucket(row.relevance) for row in rows),
            ("direct", "market_context", "reference"),
        ),
        "evidence_stock_names": _web_view_unique_texts([row.stock_name for row in rows], limit=30),
    }


def _run_news_evidence_run_scope_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    recent_business_days: int,
    candidate_limit: int,
    as_json: bool,
) -> int:
    payload = _build_news_evidence_run_scope_audit(
        config,
        repository,
        recent_business_days=recent_business_days,
        candidate_limit=candidate_limit,
    )
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    summary = payload["summary"]
    print("News Evidence run scope audit")
    print("- read_only: true")
    print("- writes_db: false")
    print(f"- candidates: {summary['candidate_count']}")
    print(f"- run targets: {summary['run_target_count']}")
    print(f"- overlap: {summary['candidate_run_overlap_count']}")
    print(f"- missing candidates: {summary['missing_candidate_count']}")
    print(f"- non-candidate run targets: {summary['non_candidate_run_target_count']}")
    print(f"- date mismatch candidates: {summary['date_mismatch_candidate_count']}")
    print(f"- candidate not in scope: {summary['candidate_not_in_scope_count']}")
    return 0


def _build_news_evidence_run_scope_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    recent_business_days: int,
    candidate_limit: int,
) -> dict[str, object]:
    inspected_dates = [
        business_date
        for business_date, _summary_count in repository.count_summaries_by_business_date(
            limit=max(recent_business_days, 0)
        )
    ]
    all_evidence_rows = _web_view_unique_news_evidence_rows(
        repository.list_report_linked_news_evidence(limit=50000)
    )
    summary_counts: Counter[str] = Counter()
    run_source_modes: Counter[str] = Counter()
    date_breakdown: list[dict[str, object]] = []
    candidate_not_in_scope_examples: list[dict[str, object]] = []
    date_mismatch_examples: list[dict[str, object]] = []

    for business_date in inspected_dates:
        summaries = repository.list_daily_summaries(business_date)
        reports = repository.list_reports_for_business_date(business_date)
        snapshot = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=max(candidate_limit, 5, 0),
            include_internal=True,
        )
        candidate_rows = list(snapshot.get("rows") or [])[: max(candidate_limit, 0)]
        runs = repository.list_news_intelligence_runs(target_date=business_date, limit=1000)
        evidence_rows = _web_view_unique_news_evidence_rows(
            repository.list_report_linked_news_evidence(target_date=business_date, limit=5000)
        )
        for run in runs:
            run_source_modes[(run.source_mode or "unknown").strip() or "unknown"] += 1

        candidate_entries: list[dict[str, object]] = []
        missing_candidates: list[dict[str, object]] = []
        overlap_stock_codes: list[str] = []
        date_mismatch_candidates: list[dict[str, object]] = []
        for rank, row in enumerate(candidate_rows, start=1):
            stock_code = str(row.get("stock_code") or "")
            stock_name = str(row.get("stock_name") or "")
            matching_runs = [
                run for run in runs if _news_evidence_run_matches_candidate(run, stock_code=stock_code, stock_name=stock_name)
            ]
            other_date_evidence = [
                evidence
                for evidence in all_evidence_rows
                if evidence.target_date != business_date
                and _news_evidence_match_row_related(evidence, stock_code=stock_code, stock_name=stock_name)
            ]
            with_digest = _news_evidence_candidate_has_digest(row)
            entry = {
                "business_date": business_date.isoformat(),
                "rank": rank,
                "selected_top2": rank <= 2,
                "selected_top5": rank <= 5,
                "stock_code": stock_code,
                "stock_name": stock_name,
                "news_digest": with_digest,
                "matching_run_count": len(matching_runs),
                "same_date_run_target": bool(matching_runs),
                "other_date_evidence_count": len(other_date_evidence),
                "other_evidence_dates": _web_view_unique_texts(
                    [evidence.target_date.isoformat() for evidence in other_date_evidence],
                    limit=10,
                ),
            }
            candidate_entries.append(entry)
            if matching_runs:
                if stock_code:
                    overlap_stock_codes.append(stock_code)
                continue
            missing_candidates.append(entry)
            if len(candidate_not_in_scope_examples) < 20:
                candidate_not_in_scope_examples.append(entry)
            if other_date_evidence:
                date_mismatch_candidates.append(entry)
                if len(date_mismatch_examples) < 20:
                    date_mismatch_examples.append(entry)

        run_target_entries = [_news_evidence_run_scope_target_entry(run, evidence_rows) for run in runs]
        candidate_stock_codes = [str(entry["stock_code"]) for entry in candidate_entries if str(entry["stock_code"])]
        run_target_stock_codes = sorted(
            {
                str(entry["stock_code"])
                for entry in run_target_entries
                if str(entry.get("stock_code") or "")
            }
        )
        candidate_code_set = set(candidate_stock_codes)
        non_candidate_run_stock_codes = [
            code
            for code in run_target_stock_codes
            if code not in candidate_code_set
        ]
        summary_counts["candidate_count"] += len(candidate_entries)
        summary_counts["run_count"] += len(runs)
        summary_counts["run_target_count"] += len(run_target_stock_codes)
        summary_counts["candidate_run_overlap_count"] += len({code for code in overlap_stock_codes if code})
        summary_counts["missing_candidate_count"] += len(missing_candidates)
        summary_counts["non_candidate_run_target_count"] += len(non_candidate_run_stock_codes)
        summary_counts["date_mismatch_candidate_count"] += len(date_mismatch_candidates)
        summary_counts["candidate_not_in_scope_count"] += len(missing_candidates)

        report_latest_collected_at = _news_evidence_scope_max_iso([report.collected_at for report in reports])
        summary_latest_generated_at = _news_evidence_scope_max_iso([summary.generated_at for summary in summaries])
        first_run_created_at = _news_evidence_scope_min_iso([run.created_at for run in runs])
        last_run_created_at = _news_evidence_scope_max_iso([run.created_at for run in runs])
        date_breakdown.append(
            {
                "business_date": business_date.isoformat(),
                "candidate_business_date": business_date.isoformat(),
                "candidate_generation_source": "build_web_view_candidate_evidence_snapshot",
                "candidate_stock_codes": candidate_stock_codes,
                "candidate_stocks": candidate_entries,
                "run_target_stock_codes": run_target_stock_codes,
                "run_targets": run_target_entries,
                "overlap_count": len({code for code in overlap_stock_codes if code}),
                "overlap_stock_codes": sorted({code for code in overlap_stock_codes if code}),
                "missing_top_candidate_count": len(missing_candidates),
                "missing_candidate_stock_codes": [str(entry["stock_code"]) for entry in missing_candidates if str(entry["stock_code"])],
                "missing_candidates": missing_candidates,
                "non_candidate_run_target_count": len(non_candidate_run_stock_codes),
                "non_candidate_run_stock_codes": non_candidate_run_stock_codes,
                "evidence_business_dates": [business_date.isoformat()] if evidence_rows else [],
                "same_date_evidence_count": len(evidence_rows),
                "date_mismatch_candidates": date_mismatch_candidates,
                "run_scope_inference": _news_evidence_run_scope_inference(
                    candidate_count=len(candidate_entries),
                    run_target_count=len(run_target_entries),
                    overlap_count=len({code for code in overlap_stock_codes if code}),
                    missing_candidate_count=len(missing_candidates),
                    non_candidate_run_target_count=len(non_candidate_run_stock_codes),
                ),
                "timing": {
                    "latest_report_collected_at": report_latest_collected_at,
                    "latest_candidate_summary_generated_at": summary_latest_generated_at,
                    "first_run_created_at": first_run_created_at,
                    "last_run_created_at": last_run_created_at,
                    "first_run_vs_summary": _news_evidence_scope_temporal_order(
                        summary_latest_generated_at,
                        first_run_created_at,
                    ),
                },
            }
        )

    return {
        "surface": "news-evidence-run-scope-audit",
        "read_only": True,
        "writes_db": False,
        "live_fetch": False,
        "scoring": False,
        "recommendation": False,
        "recent_business_days": recent_business_days,
        "candidate_limit": candidate_limit,
        "dates": [business_date.isoformat() for business_date in inspected_dates],
        "known_input_paths": _news_evidence_known_input_paths(),
        "summary": {
            "candidate_count": int(summary_counts["candidate_count"]),
            "run_count": int(summary_counts["run_count"]),
            "run_target_count": int(summary_counts["run_target_count"]),
            "candidate_run_overlap_count": int(summary_counts["candidate_run_overlap_count"]),
            "missing_candidate_count": int(summary_counts["missing_candidate_count"]),
            "non_candidate_run_target_count": int(summary_counts["non_candidate_run_target_count"]),
            "date_mismatch_candidate_count": int(summary_counts["date_mismatch_candidate_count"]),
            "candidate_not_in_scope_count": int(summary_counts["candidate_not_in_scope_count"]),
            "run_source_mode_distribution": dict(sorted(run_source_modes.items())),
        },
        "date_breakdown": date_breakdown,
        "candidate_not_in_scope_examples": candidate_not_in_scope_examples,
        "date_mismatch_examples": date_mismatch_examples,
        "judgment": _news_evidence_run_scope_judgment(summary_counts),
    }


def _news_evidence_run_scope_target_entry(
    run: object,
    evidence_rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    run_id = str(getattr(run, "run_id", "") or "")
    matching_evidence = [row for row in evidence_rows if row.run_id == run_id]
    return {
        "run_id": run_id,
        "target_date": getattr(run, "target_date").isoformat(),
        "stock_code": getattr(run, "stock_code", None),
        "stock_name": getattr(run, "stock_name", ""),
        "source_mode": getattr(run, "source_mode", ""),
        "source_command_or_run_type": _news_evidence_run_scope_source_type(run),
        "page_limit": getattr(run, "page_limit", None),
        "live_fetch": bool(getattr(run, "live_fetch", False)),
        "matched_count": int(getattr(run, "matched_count", 0) or 0),
        "saved_evidence_count": len(matching_evidence),
        "created_at": getattr(run, "created_at").isoformat(),
    }


def _news_evidence_run_scope_source_type(run: object) -> str:
    source_mode = str(getattr(run, "source_mode", "") or "")
    if source_mode == "naver_5_lane_preview":
        return "stored_naver_5_lane_preview_or_briefing_collect"
    return source_mode or "unknown_stored_news_intelligence_run"


def _news_evidence_run_scope_inference(
    *,
    candidate_count: int,
    run_target_count: int,
    overlap_count: int,
    missing_candidate_count: int,
    non_candidate_run_target_count: int,
) -> str:
    if candidate_count <= 0:
        return "no_candidates"
    if run_target_count <= 0:
        return "no_news_runs"
    if overlap_count <= 0:
        return "separate_news_run_universe"
    if missing_candidate_count <= 0 and non_candidate_run_target_count <= 0:
        return "candidate_universe_fully_collected"
    if non_candidate_run_target_count <= 0:
        return "candidate_universe_partial_limit_or_filter"
    return "mixed_or_partial_candidate_universe"


def _news_evidence_scope_max_iso(values: Sequence[datetime]) -> str | None:
    iso_values = [value.isoformat() for value in values if value is not None]
    return max(iso_values) if iso_values else None


def _news_evidence_scope_min_iso(values: Sequence[datetime]) -> str | None:
    iso_values = [value.isoformat() for value in values if value is not None]
    return min(iso_values) if iso_values else None


def _news_evidence_scope_temporal_order(
    summary_generated_at: str | None,
    first_run_created_at: str | None,
) -> str:
    if not summary_generated_at:
        return "candidate_summary_time_missing"
    if not first_run_created_at:
        return "no_news_run"
    if first_run_created_at >= summary_generated_at:
        return "first_run_at_or_after_candidate_summary"
    return "first_run_before_candidate_summary"


def _news_evidence_known_input_paths() -> list[dict[str, object]]:
    return [
        {
            "path": "news-intelligence-preview",
            "input_universe": "explicit operator --stock-name/--stock-code",
            "writes_db": "only with --save-observation",
        },
        {
            "path": "news-intelligence-briefing-collect",
            "input_universe": "stored daily summaries sorted by mention_count, optional --stock-code filter, bounded by --limit",
            "writes_db": "only with --save-observation --confirm-save",
        },
        {
            "path": "POST /api/news-observations/collect",
            "input_universe": "build_web_view_candidate_evidence_snapshot selected-date top candidates, bounded to 1..5",
            "writes_db": "access-gated operator action only",
        },
        {
            "path": "scheduled-market-briefing-slot",
            "input_universe": "same web-view candidate collector, bounded to top 2 after scheduler guards",
            "writes_db": "only during non-dry-run scheduled briefing after guards pass",
        },
    ]


def _news_evidence_run_scope_judgment(counts: Counter[str]) -> dict[str, object]:
    missing = int(counts["missing_candidate_count"])
    overlap = int(counts["candidate_run_overlap_count"])
    non_candidate = int(counts["non_candidate_run_target_count"])
    date_mismatch = int(counts["date_mismatch_candidate_count"])
    if missing > overlap and non_candidate > 0:
        primary = "news_run_uses_mixed_or_separate_universe"
    elif missing > overlap:
        primary = "top_candidate_news_collect_not_run_or_bounded"
    elif date_mismatch > 0:
        primary = "candidate_and_news_run_dates_misaligned"
    else:
        primary = "run_scope_overlap_sufficient"
    return {
        "primary_bottleneck": primary,
        "implements_collection_change": False,
        "matching_logic_changed": False,
    }


NEWS_NO_MATCH_REASON_ORDER = (
    "true_no_news",
    "source_coverage_gap",
    "alias_gap",
    "theme_only_mention",
    "date_window_gap",
    "parser_gap",
    "unknown",
)


def _run_news_no_match_diagnosis(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date | None,
    stock_code: str | None,
    stock_name: str | None,
    candidate_limit: int,
    top_n: int,
    as_json: bool,
) -> int:
    payload = _build_news_no_match_diagnosis(
        config,
        repository,
        business_date=business_date,
        stock_code=stock_code,
        stock_name=stock_name,
        candidate_limit=candidate_limit,
        top_n=top_n,
    )
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    summary = payload["summary"]
    print("News no-match diagnosis")
    print("- read_only: true")
    print("- writes_db: false")
    print(f"- business_date: {payload['business_date']}")
    print(f"- targets: {payload['target_count']}")
    print(f"- no matching article: {summary['no_matching_article_count']}")
    print(f"- reasons: {_format_count_map(summary['reason_distribution'])}")
    return 0


def _build_news_no_match_diagnosis(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date | None,
    stock_code: str | None,
    stock_name: str | None,
    candidate_limit: int,
    top_n: int,
) -> dict[str, object]:
    warnings: list[str] = []
    resolved_date = _resolve_news_intelligence_top_candidate_date(repository, business_date)
    bounded_candidate_limit = max(0, min(int(candidate_limit), 10))
    bounded_top_n = max(0, min(int(top_n), 10))
    if candidate_limit > 10:
        warnings.append("candidate_limit capped at 10")
    if top_n > 10:
        warnings.append("top_n capped at 10")
    targets = _news_no_match_targets(
        config,
        repository,
        business_date=resolved_date,
        stock_code=stock_code,
        stock_name=stock_name,
        candidate_limit=bounded_candidate_limit,
        top_n=bounded_top_n,
        warnings=warnings,
    )
    all_evidence_rows = _web_view_unique_news_evidence_rows(
        repository.list_report_linked_news_evidence(limit=50000)
    )
    same_date_evidence = [
        row for row in all_evidence_rows if resolved_date is not None and row.target_date == resolved_date
    ]
    target_diagnostics = [
        _news_no_match_target_diagnosis(
            repository,
            business_date=resolved_date,
            target=target,
            same_date_evidence=same_date_evidence,
            all_evidence_rows=all_evidence_rows,
        )
        for target in targets
    ]
    reason_counts: Counter[str] = Counter(
        str(item["likely_reason"])
        for item in target_diagnostics
        if item.get("likely_reason") in NEWS_NO_MATCH_REASON_ORDER
    )
    status_counts: Counter[str] = Counter(str(item["current_status"]) for item in target_diagnostics)
    return {
        "surface": "news-no-match-diagnosis",
        "read_only": True,
        "writes_db": False,
        "live_fetch": False,
        "scoring": False,
        "recommendation": False,
        "business_date": resolved_date.isoformat() if resolved_date is not None else None,
        "candidate_limit": bounded_candidate_limit,
        "top_n": bounded_top_n,
        "target_count": len(target_diagnostics),
        "summary": {
            "status_distribution": dict(sorted(status_counts.items())),
            "reason_distribution": _ordered_nonzero_count_map(reason_counts, NEWS_NO_MATCH_REASON_ORDER),
            "no_matching_article_count": int(status_counts.get("no_matching_article", 0)),
            "same_date_run_target_count": sum(1 for item in target_diagnostics if item["same_date_run_exists"]),
            "with_digest_count": sum(1 for item in target_diagnostics if item["current_status"] == "has_digest"),
        },
        "targets": target_diagnostics,
        "diagnostic_limitations": {
            "unmatched_article_titles_available": False,
            "reason": "Stored news_intelligence_runs keep aggregate parsed/deduped/matched counts and warnings, while report_linked_news_evidence stores matched evidence only.",
        },
        "warnings": warnings,
    }


def _news_no_match_targets(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date | None,
    stock_code: str | None,
    stock_name: str | None,
    candidate_limit: int,
    top_n: int,
    warnings: list[str],
) -> list[dict[str, object]]:
    if business_date is None:
        warnings.append("no stored business_date found")
        return []
    snapshot = build_web_view_candidate_evidence_snapshot(
        config,
        repository,
        business_date=business_date,
        limit=max(candidate_limit, top_n, 0),
        include_internal=True,
    )
    candidate_rows = list(snapshot.get("rows") or [])
    if stock_code or stock_name:
        resolved = _news_no_match_resolve_explicit_target(
            repository,
            business_date=business_date,
            candidate_rows=candidate_rows,
            stock_code=(stock_code or "").strip(),
            stock_name=(stock_name or "").strip(),
        )
        return [resolved] if resolved is not None else []
    targets: list[dict[str, object]] = []
    for rank, row in enumerate(candidate_rows[:top_n], start=1):
        targets.append(
            {
                "rank": rank,
                "selected_top2": rank <= 2,
                "selected_top5": rank <= 5,
                "stock_code": str(row.get("stock_code") or "").strip(),
                "stock_name": str(row.get("stock_name") or "").strip(),
                "news_digest": _news_evidence_candidate_has_digest(row),
            }
        )
    return targets


def _news_no_match_resolve_explicit_target(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    candidate_rows: Sequence[dict[str, object]],
    stock_code: str,
    stock_name: str,
) -> dict[str, object] | None:
    normalized_name = _web_view_normalize_news_identity(stock_name)
    for rank, row in enumerate(candidate_rows, start=1):
        row_code = str(row.get("stock_code") or "").strip()
        row_name = str(row.get("stock_name") or "").strip()
        if stock_code and row_code == stock_code:
            return {
                "rank": rank,
                "selected_top2": rank <= 2,
                "selected_top5": rank <= 5,
                "stock_code": row_code,
                "stock_name": stock_name or row_name,
                "news_digest": _news_evidence_candidate_has_digest(row),
            }
        if normalized_name and _web_view_normalize_news_identity(row_name) == normalized_name:
            return {
                "rank": rank,
                "selected_top2": rank <= 2,
                "selected_top5": rank <= 5,
                "stock_code": stock_code or row_code,
                "stock_name": row_name,
                "news_digest": _news_evidence_candidate_has_digest(row),
            }
    for summary in repository.list_daily_summaries(business_date):
        if stock_code and summary.stock_code == stock_code:
            return {
                "rank": None,
                "selected_top2": False,
                "selected_top5": False,
                "stock_code": stock_code,
                "stock_name": stock_name or summary.stock_name,
                "news_digest": False,
            }
        if normalized_name and _web_view_normalize_news_identity(summary.stock_name) == normalized_name:
            return {
                "rank": None,
                "selected_top2": False,
                "selected_top5": False,
                "stock_code": stock_code or (summary.stock_code or ""),
                "stock_name": summary.stock_name,
                "news_digest": False,
            }
    if stock_code or stock_name:
        return {
            "rank": None,
            "selected_top2": False,
            "selected_top5": False,
            "stock_code": stock_code,
            "stock_name": stock_name,
            "news_digest": False,
        }
    return None


def _news_no_match_target_diagnosis(
    repository: StockMonitorRepository,
    *,
    business_date: date | None,
    target: dict[str, object],
    same_date_evidence: Sequence[ReportLinkedNewsEvidenceRecord],
    all_evidence_rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> dict[str, object]:
    stock_code = str(target.get("stock_code") or "").strip()
    stock_name = str(target.get("stock_name") or "").strip()
    runs = (
        repository.list_news_intelligence_runs(target_date=business_date, limit=1000)
        if business_date is not None
        else []
    )
    matching_runs = [
        run for run in runs if _news_evidence_run_matches_candidate(run, stock_code=stock_code, stock_name=stock_name)
    ]
    latest_run = matching_runs[0] if matching_runs else None
    matching_rows = (
        _web_view_news_observation_rows_for_stock(
            repository,
            business_date=business_date,
            stock_code=stock_code,
            stock_name=stock_name,
        )
        if business_date is not None
        else []
    )
    other_date_evidence = [
        row
        for row in all_evidence_rows
        if business_date is not None
        and row.target_date != business_date
        and _news_evidence_match_row_related(row, stock_code=stock_code, stock_name=stock_name)
    ]
    same_date_text_hits = [
        row
        for row in same_date_evidence
        if not _news_evidence_match_row_related(row, stock_code=stock_code, stock_name=stock_name)
        and _news_no_match_evidence_text_mentions_candidate(row, stock_code=stock_code, stock_name=stock_name)
    ]
    alias_hits = _news_no_match_alias_hits(latest_run, same_date_evidence)
    current_status = _news_no_match_current_status(
        same_date_run_exists=bool(matching_runs),
        matching_rows=matching_rows,
        news_digest=bool(target.get("news_digest")),
    )
    likely_reason = _news_no_match_likely_reason(
        current_status=current_status,
        latest_run=latest_run,
        matching_rows=matching_rows,
        other_date_evidence=other_date_evidence,
        same_date_text_hits=same_date_text_hits,
        alias_hits=alias_hits,
    )
    return {
        "business_date": business_date.isoformat() if business_date is not None else None,
        "rank": target.get("rank"),
        "selected_top2": bool(target.get("selected_top2")),
        "selected_top5": bool(target.get("selected_top5")),
        "stock_code": stock_code,
        "stock_name": stock_name,
        "current_status": current_status,
        "same_date_run_exists": bool(matching_runs),
        "matching_run_count": len(matching_runs),
        "latest_run_id": getattr(latest_run, "run_id", None),
        "latest_run_created_at": getattr(latest_run, "created_at", None).isoformat() if latest_run is not None else None,
        "parsed_article_count": int(getattr(latest_run, "parsed_count", 0) or 0),
        "deduped_article_count": int(getattr(latest_run, "deduped_count", 0) or 0),
        "matched_count": int(getattr(latest_run, "matched_count", 0) or 0),
        "saved_evidence_count": len(matching_rows),
        "candidate_alias_hits": alias_hits,
        "nearby_theme_hits": _news_no_match_nearby_theme_hits(stock_name, same_date_evidence),
        "same_date_text_hit_count": len(same_date_text_hits),
        "same_date_text_hits": [
            _news_no_match_evidence_example(row) for row in same_date_text_hits[:5]
        ],
        "other_date_evidence_count": len(other_date_evidence),
        "other_date_evidence_dates": _web_view_unique_texts(
            [row.target_date.isoformat() for row in other_date_evidence],
            limit=10,
        ),
        "other_date_evidence": [
            _news_no_match_evidence_example(row) for row in other_date_evidence[:5]
        ],
        "warnings": list(getattr(latest_run, "warnings", ()) or ()) if latest_run is not None else [],
        "likely_reason": likely_reason,
    }


def _news_no_match_current_status(
    *,
    same_date_run_exists: bool,
    matching_rows: Sequence[ReportLinkedNewsEvidenceRecord],
    news_digest: bool,
) -> str:
    if news_digest or any(row.relevance == "direct" for row in matching_rows):
        return "has_digest"
    if matching_rows:
        return "only_market_or_reference"
    if same_date_run_exists:
        return "no_matching_article"
    return "no_same_date_run"


def _news_no_match_likely_reason(
    *,
    current_status: str,
    latest_run: object | None,
    matching_rows: Sequence[ReportLinkedNewsEvidenceRecord],
    other_date_evidence: Sequence[ReportLinkedNewsEvidenceRecord],
    same_date_text_hits: Sequence[ReportLinkedNewsEvidenceRecord],
    alias_hits: Sequence[str],
) -> str | None:
    if current_status == "has_digest":
        return None
    if matching_rows:
        return "theme_only_mention"
    if other_date_evidence:
        return "date_window_gap"
    if alias_hits:
        return "alias_gap"
    if same_date_text_hits:
        return "parser_gap"
    if latest_run is None:
        return "unknown"
    parsed_count = int(getattr(latest_run, "parsed_count", 0) or 0)
    deduped_count = int(getattr(latest_run, "deduped_count", 0) or 0)
    matched_count = int(getattr(latest_run, "matched_count", 0) or 0)
    if matched_count <= 0 and (parsed_count > 0 or deduped_count > 0):
        return "source_coverage_gap"
    if matched_count <= 0:
        return "true_no_news"
    return "unknown"


def _news_no_match_evidence_text_mentions_candidate(
    row: ReportLinkedNewsEvidenceRecord,
    *,
    stock_code: str,
    stock_name: str,
) -> bool:
    haystack = _news_no_match_evidence_text(row)
    if stock_code and stock_code in haystack:
        return True
    normalized_haystack = _web_view_normalize_news_identity(haystack)
    normalized_name = _web_view_normalize_news_identity(stock_name)
    return bool(normalized_name and normalized_name in normalized_haystack)


def _news_no_match_alias_hits(
    run: object | None,
    evidence_rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> list[str]:
    if run is None:
        return []
    aliases = [str(alias).strip() for alias in getattr(run, "aliases", ()) or () if str(alias).strip()]
    if not aliases:
        return []
    text = "\n".join(_news_no_match_evidence_text(row) for row in evidence_rows)
    normalized_text = _web_view_normalize_news_identity(text)
    hits = [
        alias
        for alias in aliases
        if _web_view_normalize_news_identity(alias) and _web_view_normalize_news_identity(alias) in normalized_text
    ]
    return _web_view_unique_texts(hits, limit=10)


def _news_no_match_nearby_theme_hits(
    stock_name: str,
    evidence_rows: Sequence[ReportLinkedNewsEvidenceRecord],
) -> list[str]:
    keywords = [
        token
        for token in re.split(r"[^0-9A-Za-z]+", stock_name)
        if len(token) >= 3
    ]
    if not keywords:
        return []
    hits: list[str] = []
    for row in evidence_rows:
        text = _news_no_match_evidence_text(row).casefold()
        if any(keyword.casefold() in text for keyword in keywords):
            hits.append(row.title)
    return _web_view_unique_texts(hits, limit=5)


def _news_no_match_evidence_text(row: ReportLinkedNewsEvidenceRecord) -> str:
    return "\n".join(
        str(value or "")
        for value in (
            row.stock_code,
            row.stock_name,
            row.title,
            row.summary,
            row.source,
            row.matched_alias,
            row.match_reason,
            row.relevance_reason,
        )
    )


def _news_no_match_evidence_example(row: ReportLinkedNewsEvidenceRecord) -> dict[str, object]:
    return {
        "target_date": row.target_date.isoformat(),
        "stock_code": row.stock_code,
        "stock_name": row.stock_name,
        "relevance": _news_evidence_coverage_relevance_bucket(row.relevance),
        "source_lane": row.source_lane,
        "title": row.title,
        "published_at": row.published_at.isoformat() if row.published_at is not None else None,
    }


def _build_candidate_evidence_readiness_date(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    limit: int,
) -> dict[str, object]:
    summaries = [summary for summary in repository.list_daily_summaries(business_date) if summary.stock_code]
    snapshot = build_web_view_candidate_evidence_snapshot(
        config,
        repository,
        business_date=business_date,
        limit=limit,
        include_internal=True,
    )
    rows = list(snapshot.get("rows") or [])
    issues: list[dict] = []
    warnings: list[dict] = []
    _collect_web_view_value_qa_issues(
        snapshot,
        path=f"candidate_evidence[{business_date.isoformat()}]",
        issues=issues,
        warnings=warnings,
    )
    quality_flag_counts: Counter[str] = Counter()
    for row in rows:
        quality_flag_counts.update(str(flag) for flag in row.get("quality_flags") or [])
    target_progress_rows = [row.get("target_price_progress") or {} for row in rows]
    observation_priority_counts: Counter[str] = Counter(
        str(row.get("observation_priority")) for row in rows if str(row.get("observation_priority") or "").strip()
    )
    why_notable_counts = _count_web_view_candidate_list_values(rows, "why_notable")
    missing_information_counts = _count_web_view_candidate_list_values(rows, "missing_information")
    internal_candidate_signal_counts = _count_web_view_candidate_list_values(rows, "internal_candidate_signals")
    internal_missing_information_counts = _count_web_view_candidate_list_values(rows, "internal_missing_information")
    explanation_quality_by_code = {
        str(row.get("stock_code") or ""): _candidate_explanation_quality_labels(row)
        for row in rows
    }
    explanation_quality_counts: Counter[str] = Counter()
    for labels in explanation_quality_by_code.values():
        explanation_quality_counts.update(labels)
    top_rows = [
        {
            "stock_code": row.get("stock_code"),
            "stock_name": row.get("stock_name"),
            "report_count": (row.get("report_summary") or {}).get("report_count"),
            "broker_count": (row.get("report_summary") or {}).get("broker_count"),
            "quality_flags": row.get("quality_flags") or [],
            "observation_priority": row.get("observation_priority"),
            "why_notable": row.get("why_notable") or [],
            "missing_information": row.get("missing_information") or [],
            "evidence_layers": row.get("evidence_layers") or {"primary": [], "support": [], "gap": []},
            "internal_candidate_signals": row.get("internal_candidate_signals") or [],
            "internal_missing_information": row.get("internal_missing_information") or [],
            "explanation_quality": explanation_quality_by_code.get(str(row.get("stock_code") or ""), []),
            "target_validation_available": (row.get("target_price_progress") or {}).get("validation_available"),
            "stock_flow_available": (row.get("stock_flow_reference") or {}).get("available"),
            "foreign_top_rank": (row.get("rank_reference") or {}).get("foreign_top_rank"),
        }
        for row in rows
    ]
    top_candidate_maturity = _candidate_evidence_top_maturity_summary(top_rows[:2])
    return {
        "business_date": business_date.isoformat(),
        "eligible_summary_count": len(summaries),
        "visible_row_count": len(rows),
        "available": bool(snapshot.get("available")),
        "target_progress_available_count": sum(1 for item in target_progress_rows if item.get("available")),
        "target_validation_available_count": sum(1 for item in target_progress_rows if item.get("validation_available")),
        "target_hit_count": sum(
            1
            for item in target_progress_rows
            if item.get("hit_min_horizon_days") is not None or item.get("hit_max_horizon_days") is not None
        ),
        "progress_caution_count": sum(1 for item in target_progress_rows if item.get("progress_caution")),
        "market_reference_available_count": sum(1 for row in rows if row.get("market_reference")),
        "stock_flow_available_count": sum(
            1 for row in rows if (row.get("stock_flow_reference") or {}).get("available")
        ),
        "foreign_rank_available_count": sum(
            1 for row in rows if (row.get("rank_reference") or {}).get("foreign_top_rank") is not None
        ),
        "observation_priority_counts": dict(sorted(observation_priority_counts.items())),
        "visible_observation_priority_counts": dict(sorted(observation_priority_counts.items())),
        "why_notable_counts": why_notable_counts,
        "visible_why_notable_counts": why_notable_counts,
        "missing_information_counts": missing_information_counts,
        "visible_missing_information_counts": missing_information_counts,
        "internal_candidate_signal_counts": internal_candidate_signal_counts,
        "internal_missing_information_counts": internal_missing_information_counts,
        "explanation_quality_counts": dict(sorted(explanation_quality_counts.items())),
        "top_candidate_explanation_quality_counts": top_candidate_maturity["explanation_quality_counts"],
        "top_candidate_support_counts": top_candidate_maturity["support_counts"],
        "top_candidate_gap_counts": top_candidate_maturity["gap_counts"],
        "top_candidate_next_evidence_gap_counts": top_candidate_maturity["next_evidence_gap_counts"],
        "top_candidate_review_reason_counts": top_candidate_maturity["review_reason_counts"],
        "top_candidate_review_priority_counts": top_candidate_maturity["review_priority_counts"],
        "top_candidate_maturity": top_candidate_maturity["summary"],
        "quality_flag_counts": dict(sorted(quality_flag_counts.items())),
        "qa_issue_count": len(issues),
        "qa_warning_count": len(warnings),
        "qa_issues": issues,
        "qa_warnings": warnings,
        "review_ready": bool(rows) and not issues,
        "top_rows": top_rows,
    }


def _candidate_evidence_top_maturity_summary(top_rows: list[dict[str, object]]) -> dict[str, object]:
    explanation_quality_counts: Counter[str] = Counter()
    support_counts: Counter[str] = Counter()
    gap_counts: Counter[str] = Counter()
    for row in top_rows:
        explanation_quality_counts.update(_public_label_list(row.get("explanation_quality")))
        layers = row.get("evidence_layers") if isinstance(row.get("evidence_layers"), dict) else {}
        support_counts.update(_public_label_list((layers or {}).get("support")))
        gap_counts.update(_public_label_list((layers or {}).get("gap")))

    candidate_count = len(top_rows)
    composite_count = explanation_quality_counts.get("composite_evidence", 0)
    weak_support_count = max(candidate_count - composite_count, 0)
    reason_rules = [
        ("top_missing_krx_reference", explanation_quality_counts.get("missing_krx_reference", 0)),
        ("top_missing_price_volume_context", explanation_quality_counts.get("missing_price_volume_context", 0)),
        ("top_missing_stock_flow_reference", explanation_quality_counts.get("missing_stock_flow_reference", 0)),
        ("top_rank_without_stock_flow", explanation_quality_counts.get("rank_without_stock_flow", 0)),
        ("top_report_only_candidate", explanation_quality_counts.get("report_only_candidate", 0)),
        ("top_weak_support", weak_support_count),
    ]
    review_reasons = [reason for reason, count in reason_rules if count]
    next_evidence_gap = _candidate_evidence_next_gap(gap_counts)
    review_priority = _candidate_evidence_review_priority(
        explanation_quality_counts=explanation_quality_counts,
        weak_support_count=weak_support_count,
        next_evidence_gap=next_evidence_gap,
    )
    summary = {
        "candidate_count": candidate_count,
        "composite_evidence_count": composite_count,
        "weak_support_count": weak_support_count,
        "report_only_count": explanation_quality_counts.get("report_only_candidate", 0),
        "rank_without_stock_flow_count": explanation_quality_counts.get("rank_without_stock_flow", 0),
        "missing_stock_flow_count": explanation_quality_counts.get("missing_stock_flow_reference", 0),
        "missing_krx_count": explanation_quality_counts.get("missing_krx_reference", 0),
        "missing_price_volume_context_count": explanation_quality_counts.get("missing_price_volume_context", 0),
        "missing_52w_position_count": explanation_quality_counts.get("missing_52w_position", 0),
        "support_counts": dict(sorted(support_counts.items())),
        "gap_counts": dict(sorted(gap_counts.items())),
        "next_evidence_gap": next_evidence_gap,
        "review_needed": bool(review_reasons),
        "review_priority": review_priority,
        "review_reasons": review_reasons,
    }
    next_gap_counts = {next_evidence_gap: 1} if next_evidence_gap else {}
    review_priority_counts = {review_priority: 1} if review_priority != "none" else {}
    return {
        "explanation_quality_counts": dict(sorted(explanation_quality_counts.items())),
        "support_counts": dict(sorted(support_counts.items())),
        "gap_counts": dict(sorted(gap_counts.items())),
        "next_evidence_gap_counts": next_gap_counts,
        "review_reason_counts": {reason: 1 for reason in review_reasons},
        "review_priority_counts": review_priority_counts,
        "summary": summary,
    }


def _candidate_evidence_next_gap(gap_counts: Counter[str]) -> str | None:
    if not gap_counts:
        return None
    priority = {
        "종목 수급 저장값 없음": 0,
        "선택일 KRX 저장값 없음": 1,
        "목표가 정보 없음": 2,
        "투자의견 정보 없음": 3,
    }
    return sorted(gap_counts, key=lambda label: (-gap_counts[label], priority.get(label, 99), label))[0]


def _candidate_evidence_review_priority(
    *,
    explanation_quality_counts: Counter[str],
    weak_support_count: int,
    next_evidence_gap: str | None,
) -> str:
    if next_evidence_gap == "종목 수급 저장값 없음":
        return "flow_backfill"
    if next_evidence_gap == "선택일 KRX 저장값 없음":
        return "krx_backfill"
    if explanation_quality_counts.get("missing_price_volume_context", 0):
        return "price_volume_review"
    if explanation_quality_counts.get("rank_without_stock_flow", 0):
        return "rank_reference_review"
    if explanation_quality_counts.get("report_only_candidate", 0):
        return "report_context_review"
    if weak_support_count:
        return "weak_support_review"
    return "none"


def _candidate_explanation_quality_labels(row: dict[str, object]) -> list[str]:
    layers = row.get("evidence_layers") if isinstance(row.get("evidence_layers"), dict) else {}
    primary = _public_label_list((layers or {}).get("primary"))
    flags = {str(flag) for flag in row.get("quality_flags") or []}
    stock_flow_available = bool((row.get("stock_flow_reference") or {}).get("available"))
    rank_available = (row.get("rank_reference") or {}).get("foreign_top_rank") is not None
    price_volume_reference = row.get("price_volume_reference") if isinstance(row.get("price_volume_reference"), dict) else {}
    price_volume_available = bool((price_volume_reference or {}).get("available"))
    position_52w_available = (price_volume_reference or {}).get("close_position_52w_percent") is not None
    has_public_gap = any(
        (
            "missing_krx_stock_snapshot" in flags,
            not stock_flow_available,
            not price_volume_available,
        )
    )

    labels: list[str] = []
    if primary == ["리포트 집중"]:
        labels.append("report_only_candidate")
    if "missing_krx_stock_snapshot" in flags or not row.get("market_reference"):
        labels.append("missing_krx_reference")
    if not stock_flow_available:
        labels.append("missing_stock_flow_reference")
    if rank_available and not stock_flow_available:
        labels.append("rank_without_stock_flow")
    if not price_volume_available:
        labels.append("missing_price_volume_context")
    elif not position_52w_available:
        labels.append("missing_52w_position")
    if not has_public_gap and any(label != "리포트 집중" for label in primary):
        labels.append("composite_evidence")
    return labels


def _run_market_briefing(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    explicit_date: date | None,
    limit: int,
    send: bool,
    slot: str = "mood",
    layout: str = "default",
    as_json: bool = False,
    news_flow_source_urls: tuple[str, ...] = (),
    news_flow_fixture: Path | None = None,
) -> int:
    if layout == "realtime-first" and send:
        print("realtime-first layout is preview-only and cannot be used with --send")
        return 1
    if as_json and send:
        raise ValueError("--json cannot be combined with --send for market-briefing.")
    if bool(news_flow_source_urls) != bool(news_flow_fixture):
        print("--news-flow-source-url and --news-flow-fixture must be provided together")
        return 1
    if send and news_flow_source_urls:
        print("news-flow source preview is not allowed with --send")
        return 1
    business_date = explicit_date or datetime.now(ZoneInfo(config.timezone)).date()
    toss_context = _build_market_briefing_toss_priority_context(
        config,
        repository,
        business_date=business_date,
    )
    message = _build_market_briefing_message(
        config,
        repository,
        business_date=business_date,
        limit=limit,
        slot=slot,
        layout=layout,
        toss_context=toss_context,
    )
    news_flow_lines: list[str] | None = None
    if news_flow_source_urls and news_flow_fixture:
        try:
            news_flow_lines = _build_market_briefing_news_flow_lines(
                source_urls=news_flow_source_urls,
                fixture=news_flow_fixture,
                slot=slot,
            )
        except Exception as exc:
            print(f"news-flow source preview failed: {exc}")
            return 1
        message = _insert_market_briefing_section_before_check_points(message, news_flow_lines)
    issues = _collect_market_briefing_message_issues(message)
    if as_json:
        summaries = repository.list_daily_summaries(business_date)
        candidate_snapshot = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=2,
        )
        priority_stock_codes = tuple(
            str(row.get("stock_code") or "").strip()
            for row in candidate_snapshot.get("rows", [])
            if isinstance(row, dict) and str(row.get("stock_code") or "").strip()
        )
        source_freshness_summary = _build_market_briefing_source_freshness_summary(
            repository,
            business_date,
            toss_context=toss_context,
            summaries=summaries,
            priority_stock_codes=priority_stock_codes,
        )
        payload = {
            "surface": "market-briefing",
            "read_only_preview": True,
            "business_date": business_date.isoformat(),
            "slot": slot,
            "slot_label": MARKET_BRIEFING_SLOT_LABELS.get(slot, MARKET_BRIEFING_SLOT_LABELS["mood"]),
            "layout": layout,
            "preview_only": True,
            "send_blocked_reason": None,
            "limit": limit,
            "sends_telegram": False,
            "registers_scheduler": False,
            "public_safe_issue_count": len(issues),
            "public_safe_issues": issues,
            "news_observation_summary": _build_web_view_news_observation_summary(
                repository,
                business_date,
                stock_codes=priority_stock_codes,
            ),
            "news_flow_source_preview": {
                "enabled": bool(news_flow_lines),
                "source_urls": list(news_flow_source_urls),
                "fixture": str(news_flow_fixture) if news_flow_fixture else None,
                "sends_telegram": False,
                "writes_db": False,
                "registers_scheduler": False,
                "connects_web_view": False,
            },
            "source_freshness_summary": source_freshness_summary,
            "message": message,
        }
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 1 if issues else 0
    if not send:
        print(message)
        return 0
    _ensure_market_briefing_message_public_safe(message)
    _send_market_briefing_message(config, repository, business_date=business_date, message=message, source="manual")
    print(f"Market briefing sent for {business_date.isoformat()}.")
    return 0


def _run_realtime_first_review_snapshot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    date_arg: str,
    snapshot_time: str,
    output_format: str,
    output_dir: Path,
    toss_quote_provider: object | None = None,
) -> int:
    try:
        business_date = _resolve_realtime_first_snapshot_date(config, date_arg)
        snapshot_time_value = _parse_realtime_first_snapshot_time(snapshot_time)
    except ValueError as exc:
        print(f"realtime-first review snapshot argument error: {exc}")
        return 1

    generated_at = datetime.now(ZoneInfo(config.timezone))
    payload = _build_realtime_first_review_snapshot_payload(
        config,
        repository,
        business_date=business_date,
        snapshot_time=snapshot_time_value,
        generated_at=generated_at,
        toss_quote_provider=toss_quote_provider,
    )
    markdown = _format_realtime_first_review_snapshot_markdown(payload)

    output_dir.mkdir(parents=True, exist_ok=True)
    stem = f"{business_date.isoformat()}_{snapshot_time_value.strftime('%H%M')}"
    written_paths: list[Path] = []
    if output_format in {"all", "json"}:
        json_path = output_dir / f"{stem}.json"
        json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        written_paths.append(json_path)
    if output_format in {"all", "markdown"}:
        markdown_path = output_dir / f"{stem}.md"
        markdown_path.write_text(markdown, encoding="utf-8")
        written_paths.append(markdown_path)

    metadata = payload["metadata"]
    top2 = payload.get("top2") or []
    top2_text = ", ".join(
        f"{item.get('stock_name')}({item.get('stock_code')})"
        for item in top2
        if isinstance(item, dict) and item.get("stock_code")
    ) or "none"
    print(f"realtime-first review snapshot: {metadata.get('status')}")
    print(f"date: {metadata.get('date')} {metadata.get('snapshot_time_kst')} KST")
    for path in written_paths:
        print(f"- wrote: {path}")
    print(f"top2: {top2_text}")
    return 0


def _resolve_realtime_first_snapshot_date(config: RuntimeConfig, date_arg: str) -> date:
    value = str(date_arg or "today").strip().lower()
    if value == "today":
        return datetime.now(ZoneInfo(config.timezone)).date()
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("--date must be today or YYYY-MM-DD") from exc


def _parse_realtime_first_snapshot_time(value: str) -> datetime_time:
    text = str(value or "").strip()
    try:
        parsed = datetime_time.fromisoformat(text)
    except ValueError as exc:
        raise ValueError("--time must be HH:MM") from exc
    return datetime_time(hour=parsed.hour, minute=parsed.minute)


def _build_realtime_first_review_snapshot_payload(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    snapshot_time: datetime_time,
    generated_at: datetime,
    toss_quote_provider: object | None = None,
) -> dict[str, object]:
    metadata = {
        "status": "ready",
        "reason": None,
        "date": business_date.isoformat(),
        "snapshot_time_kst": snapshot_time.strftime("%H:%M"),
        "generated_at_kst": generated_at.isoformat(),
        "read_only": True,
        "writes_db": False,
        "sends_telegram": False,
        "registers_scheduler": False,
    }
    if not is_business_day(business_date, config.holiday_overrides):
        metadata["status"] = "skipped"
        metadata["reason"] = "non_business_day"
        return {
            "metadata": metadata,
            "top2": [],
            "previous_day_reference": _empty_realtime_previous_day_reference(),
            "telegram_realtime_first_preview": _realtime_first_preview_sections(summary="non_business_day"),
            "web_view_first_10_seconds": {
                "summary": "Skipped because the selected date is not a business day.",
                "warnings": ["non_business_day"],
            },
            "decisions": {
                "keep": [],
                "lower": [],
                "research_only": ["reaction", "backtest"],
                "next_day_checks": ["Run again on the next business day at 15:00 KST."],
            },
        }

    summaries = repository.list_daily_summaries(business_date)
    report_count = sum(summary.mention_count for summary in summaries)
    candidate_snapshot = build_web_view_candidate_evidence_snapshot(
        config,
        repository,
        business_date=business_date,
        limit=2,
    )
    candidate_rows = [row for row in candidate_snapshot.get("rows", []) if isinstance(row, dict)][:2]
    priority_stock_codes = tuple(
        str(row.get("stock_code") or "").strip()
        for row in candidate_rows
        if str(row.get("stock_code") or "").strip()
    )
    toss_context = _build_market_briefing_toss_priority_context(
        config,
        repository,
        business_date=business_date,
        toss_quote_provider=toss_quote_provider,
        candidate_rows=candidate_rows,
    )
    source_freshness = _build_market_briefing_source_freshness_summary(
        repository,
        business_date,
        report_count=report_count,
        toss_context=toss_context,
        summaries=summaries,
        priority_stock_codes=priority_stock_codes,
    )
    news_summary = _build_web_view_news_observation_summary(
        repository,
        business_date,
        limit=2,
        stock_codes=priority_stock_codes,
    )
    source_gaps = _realtime_first_source_gaps(source_freshness, business_date)
    top2 = [
        _realtime_first_snapshot_candidate(
            row,
            rank=index,
            business_date=business_date,
            snapshot_time=snapshot_time,
            toss_context=toss_context,
            news_summary=news_summary,
            source_gaps=source_gaps,
        )
        for index, row in enumerate(candidate_rows, start=1)
    ]
    if not top2:
        source_gaps.append("top2_missing")

    previous_day_reference = _realtime_first_previous_day_reference(source_freshness)
    warnings = sorted({gap for item in top2 for gap in item.get("missing_evidence", [])})
    if source_gaps:
        warnings.extend(gap for gap in source_gaps if gap not in warnings)
    return {
        "metadata": metadata,
        "top2": top2,
        "previous_day_reference": previous_day_reference,
        "telegram_realtime_first_preview": _realtime_first_preview_sections(
            summary=_realtime_first_preview_summary(top2, source_gaps)
        ),
        "web_view_first_10_seconds": {
            "summary": (
                "오늘 볼 것: Top2 후보와 현재 확인 가능한 근거만 먼저 봅니다. "
                "전일 KRX/수급/ETF는 참고 영역입니다."
            ),
            "warnings": warnings,
        },
        "decisions": _realtime_first_snapshot_decisions(top2, source_gaps),
    }


def _empty_realtime_previous_day_reference() -> dict[str, object]:
    return {
        "krx_daily_index": {"status": "not_checked", "judgement": "reference_only"},
        "flow": {"status": "not_checked", "judgement": "reference_only"},
        "etf": {"status": "not_checked", "judgement": "reference_only"},
    }


def _realtime_first_snapshot_candidate(
    row: dict[str, object],
    *,
    rank: int,
    business_date: date,
    snapshot_time: datetime_time,
    toss_context: dict[str, object],
    news_summary: dict[str, object],
    source_gaps: list[str],
) -> dict[str, object]:
    stock_code = str(row.get("stock_code") or "").strip()
    stock_name = str(row.get("stock_name") or "").strip()
    news_evidence = _realtime_first_news_evidence(stock_code, news_summary, business_date)
    quote_evidence = _realtime_first_quote_evidence(stock_code, toss_context, snapshot_time)
    turnover_evidence = {"status": "missing", "promoted": False, "source": None, "checked_time": None}
    freshness_evidence = _realtime_first_candidate_freshness(source_gaps)
    missing = []
    if news_evidence["status"] in {"none", "waiting", "stale", "missing"}:
        missing.append(f"news_{news_evidence['status']}")
    if quote_evidence["status"] == "missing":
        missing.append("quote_missing")
    elif quote_evidence["status"] in {"time_mismatch", "source_gap"}:
        missing.append(f"quote_{quote_evidence['status']}")
    if turnover_evidence["status"] == "missing":
        missing.append("current_turnover_missing")
    missing.extend(source_gaps)
    return {
        "rank": rank,
        "stock_name": stock_name,
        "stock_code": stock_code,
        "current_evidence": {
            "same_day_news": news_evidence,
            "quote": quote_evidence,
            "turnover": turnover_evidence,
            "source_freshness": freshness_evidence,
        },
        "missing_evidence": sorted(set(missing)),
    }


def _realtime_first_news_evidence(
    stock_code: str,
    news_summary: dict[str, object],
    business_date: date,
) -> dict[str, object]:
    items = [item for item in news_summary.get("items", []) if isinstance(item, dict)]
    item = next((item for item in items if str(item.get("stock_code") or "").strip() == stock_code), None)
    if not item:
        return {"status": "none", "direct": 0, "caution": 0, "market_context": 0, "observed_at": None}
    observed_at = item.get("observed_at")
    status = "direct" if int(item.get("direct_count") or 0) > 0 else "none"
    if status == "none" and int(item.get("caution_count") or 0) > 0:
        status = "caution"
    if status == "none" and int(item.get("market_context_count") or 0) > 0:
        status = "market_context"
    if observed_at and _realtime_first_iso_date_status(observed_at, business_date) == "stale":
        status = "stale"
    return {
        "status": status,
        "direct": int(item.get("direct_count") or 0),
        "caution": int(item.get("caution_count") or 0),
        "market_context": int(item.get("market_context_count") or 0),
        "observed_at": observed_at,
    }


def _realtime_first_quote_evidence(
    stock_code: str,
    toss_context: dict[str, object],
    snapshot_time: datetime_time,
) -> dict[str, object]:
    payload = toss_context.get("payload") if isinstance(toss_context, dict) else None
    if not isinstance(payload, dict) or payload.get("live_fetch") is not True:
        return {
            "status": "missing",
            "promoted": False,
            "source": "toss_openapi",
            "checked_time": None,
            "price": None,
        }
    quote = next(
        (
            item
            for item in payload.get("quotes", [])
            if isinstance(item, dict) and str(item.get("symbol") or "").strip() == stock_code
        ),
        None,
    )
    if not isinstance(quote, dict):
        return {
            "status": "missing",
            "promoted": False,
            "source": "toss_openapi",
            "checked_time": _market_briefing_toss_checked_time(payload.get("fetched_at")),
            "price": None,
        }
    checked_time = _market_briefing_toss_checked_time(quote.get("timestamp") or payload.get("fetched_at"))
    status = "current"
    promoted = True
    if not checked_time:
        status = "source_gap"
        promoted = False
    elif checked_time != snapshot_time.strftime("%H:%M"):
        status = "time_mismatch"
        promoted = False
    price = quote.get("lastPrice", quote.get("last_price"))
    return {
        "status": status,
        "promoted": promoted,
        "source": "toss_openapi",
        "checked_time": checked_time,
        "price": price,
        "currency": quote.get("currency", "KRW"),
    }


def _realtime_first_candidate_freshness(source_gaps: list[str]) -> dict[str, object]:
    return {
        "status": "source_gap" if source_gaps else "checked",
        "gaps": list(source_gaps),
        "checked_time": None,
    }


def _realtime_first_source_gaps(source_freshness: dict[str, object], business_date: date) -> list[str]:
    gaps: list[str] = []
    for item in source_freshness.get("items", []):
        if not isinstance(item, dict):
            continue
        key = str(item.get("key") or "")
        status = str(item.get("status") or "missing")
        if key == "toss_openapi":
            if item.get("live_fetch") is not True:
                gaps.append("toss_quote_missing")
            continue
        if status == "missing":
            gaps.append(f"{key}_missing")
        elif status == "stale":
            gaps.append(f"{key}_stale")
        elif item.get("reference_date") and _realtime_first_iso_date_status(item.get("reference_date"), business_date) == "stale":
            gaps.append(f"{key}_stale")
    return sorted(set(gaps))


def _realtime_first_previous_day_reference(source_freshness: dict[str, object]) -> dict[str, object]:
    items = {
        str(item.get("key") or ""): item
        for item in source_freshness.get("items", [])
        if isinstance(item, dict)
    }
    return {
        "krx_daily_index": _realtime_first_reference_item(items.get("krx_market")),
        "flow": _realtime_first_reference_item(items.get("investor_flow")),
        "etf": _realtime_first_reference_item(items.get("etf_daily")),
    }


def _realtime_first_reference_item(item: dict[str, object] | None) -> dict[str, object]:
    if not item:
        return {"status": "missing", "reference_date": None, "judgement": "source_gap"}
    status = str(item.get("status") or "missing")
    judgement = "reference_only"
    if status == "missing":
        judgement = "source_gap"
    elif status == "exact":
        judgement = "helps_as_same_day_fallback"
    elif status == "stale":
        judgement = "may_distract_if_promoted"
    return {
        "status": status,
        "reference_date": item.get("reference_date"),
        "judgement": judgement,
    }


def _realtime_first_preview_sections(*, summary: str) -> dict[str, object]:
    return {
        "sections": ["오늘 볼 것", "현재 근거", "전일 참고", "부족한 근거", "복기/연구"],
        "summary": summary,
    }


def _realtime_first_preview_summary(top2: list[dict[str, object]], source_gaps: list[str]) -> str:
    if not top2:
        return "Top2 후보 없음; today data/source gap 확인 필요."
    names = ", ".join(
        f"{item.get('stock_name')}({item.get('stock_code')})"
        for item in top2
        if item.get("stock_code")
    )
    gap_text = ", ".join(source_gaps) if source_gaps else "none"
    return f"Top2: {names}; gaps: {gap_text}"


def _realtime_first_snapshot_decisions(
    top2: list[dict[str, object]],
    source_gaps: list[str],
) -> dict[str, object]:
    keep = ["top2_first_read_block"] if top2 else []
    lower = ["krx_daily_index_flow_etf"]
    if any("quote_" in gap or "news_" in gap for item in top2 for gap in item.get("missing_evidence", [])):
        lower.append("current_evidence_claims")
    next_day_checks = [
        "Confirm whether same-day news exists for Top2.",
        "Confirm quote/turnover checked time is at or before the snapshot target.",
    ]
    if source_gaps:
        next_day_checks.append("Review source freshness gaps before promoting evidence.")
    return {
        "keep": keep,
        "lower": sorted(set(lower)),
        "research_only": ["reaction", "backtest"],
        "next_day_checks": next_day_checks,
    }


def _realtime_first_iso_date_status(value: object, business_date: date) -> str:
    try:
        reference_date = date.fromisoformat(str(value)[:10])
    except ValueError:
        return "unknown"
    return "exact" if reference_date == business_date else "stale"


def _format_realtime_first_review_snapshot_markdown(payload: dict[str, object]) -> str:
    metadata = payload["metadata"]
    top2 = [item for item in payload.get("top2", []) if isinstance(item, dict)]
    previous = payload.get("previous_day_reference", {})
    web_view = payload.get("web_view_first_10_seconds", {})
    decisions = payload.get("decisions", {})
    lines = [
        f"# Realtime-first Review Snapshot {metadata.get('date')} {metadata.get('snapshot_time_kst')} KST",
        "",
        f"- status: {metadata.get('status')}",
        f"- reason: {metadata.get('reason') or 'none'}",
        f"- read_only: {str(metadata.get('read_only')).lower()}",
        f"- writes_db: {str(metadata.get('writes_db')).lower()}",
        f"- sends_telegram: {str(metadata.get('sends_telegram')).lower()}",
        "",
        "## 오늘 볼 것",
    ]
    if top2:
        for item in top2:
            lines.append(f"- {item.get('rank')}. {item.get('stock_name')} ({item.get('stock_code')})")
    else:
        lines.append("- Top2 후보 없음")
    lines.extend(["", "## 현재 근거"])
    for item in top2:
        current = item.get("current_evidence", {})
        if not isinstance(current, dict):
            continue
        news = current.get("same_day_news", {})
        quote = current.get("quote", {})
        freshness = current.get("source_freshness", {})
        lines.append(
            f"- {item.get('stock_name')}: news={news.get('status') if isinstance(news, dict) else 'unknown'}, "
            f"quote={quote.get('status') if isinstance(quote, dict) else 'unknown'} "
            f"checked={quote.get('checked_time') if isinstance(quote, dict) else None}, "
            f"freshness={freshness.get('status') if isinstance(freshness, dict) else 'unknown'}"
        )
    if not top2:
        lines.append("- 현재 근거 없음")
    lines.extend(["", "## 전일 참고"])
    if isinstance(previous, dict):
        for key in ("krx_daily_index", "flow", "etf"):
            item = previous.get(key, {})
            if isinstance(item, dict):
                lines.append(
                    f"- {key}: status={item.get('status')}, reference_date={item.get('reference_date')}, "
                    f"judgement={item.get('judgement')}"
                )
    lines.extend(["", "## 부족한 근거"])
    gaps = sorted({gap for item in top2 for gap in item.get("missing_evidence", [])})
    if gaps:
        lines.extend(f"- {gap}" for gap in gaps)
    else:
        lines.append("- none")
    lines.extend(["", "## 복기/연구", "- reaction/backtest는 research/review only"])
    lines.extend(["", "## web-view 첫 10초 블록", f"- {web_view.get('summary') if isinstance(web_view, dict) else ''}"])
    lines.extend(["", "## 오늘 유지/하향/삭제 판단"])
    if isinstance(decisions, dict):
        lines.append(f"- keep: {', '.join(decisions.get('keep', []) or ['none'])}")
        lines.append(f"- lower: {', '.join(decisions.get('lower', []) or ['none'])}")
        lines.append(f"- research_only: {', '.join(decisions.get('research_only', []) or ['none'])}")
        lines.append("- next_day_checks:")
        lines.extend(f"  - {item}" for item in decisions.get("next_day_checks", []))
    return "\n".join(lines) + "\n"


def _run_market_briefing_readiness(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    recent_business_days: int,
    limit: int,
    min_manual_reviews: int,
    as_json: bool,
) -> int:
    inspected_dates = [business_date for business_date, _ in repository.count_summaries_by_business_date(limit=recent_business_days)]
    date_rows = [
        _build_market_briefing_readiness_date(config, repository, business_date=business_date, limit=limit)
        for business_date in inspected_dates
    ]
    manual_review_dates = _market_briefing_manual_review_dates(repository)
    phone_review_accepted = _effective_bool_setting(config, repository, MARKET_BRIEFING_PHONE_REVIEW_SETTING)
    enforced_min_manual_reviews = max(min_manual_reviews, MARKET_BRIEFING_MIN_MANUAL_REVIEW_SENDS)
    unsafe_dates = [row["business_date"] for row in date_rows if row["public_safe_issue_count"]]
    no_report_dates = [row["business_date"] for row in date_rows if row["report_count"] == 0]
    data_warning_dates = [row["business_date"] for row in date_rows if row["data_warnings"]]
    block_reasons: list[str] = []
    if unsafe_dates:
        block_reasons.append(f"public-safe QA issues on {', '.join(unsafe_dates)}")
    if no_report_dates:
        block_reasons.append(f"no stored report summaries on {', '.join(no_report_dates)}")
    if len(manual_review_dates) < enforced_min_manual_reviews:
        block_reasons.append(
            f"manual Telegram review sends {len(manual_review_dates)}/{enforced_min_manual_reviews}"
        )
    elif not phone_review_accepted:
        block_reasons.append("operator phone readability acceptance missing")
    manual_review_commands = _market_briefing_manual_review_commands(
        date_rows,
        reviewed_dates=set(manual_review_dates),
        limit=limit,
        max_commands=max(enforced_min_manual_reviews - len(manual_review_dates), 0),
    )
    schedule_window = _market_briefing_schedule_window_payload()
    phone_review_gate = _market_briefing_phone_review_gate_payload(
        manual_review_dates=manual_review_dates,
        min_manual_reviews=enforced_min_manual_reviews,
        phone_review_accepted=phone_review_accepted,
    )
    payload = {
        "surface": "operator-cli",
        "read_only": True,
        "live_fetch": False,
        "sends_telegram": False,
        "registers_scheduler": False,
        "scoring": False,
        "recommendation": False,
        "recent_business_days": recent_business_days,
        "recent_report_dates": recent_business_days,
        "limit": limit,
        "requested_min_manual_reviews": min_manual_reviews,
        "enforced_min_manual_reviews": enforced_min_manual_reviews,
        "min_manual_reviews": enforced_min_manual_reviews,
        "inspected_date_count": len(date_rows),
        "manual_review_send_count": len(manual_review_dates),
        "manual_review_dates": manual_review_dates,
        "phone_review_accepted": phone_review_accepted,
        "phone_review_gate": phone_review_gate,
        "preview_ready_count": sum(1 for row in date_rows if row["preview_ready"]),
        "data_warning_count": len(data_warning_dates),
        "schedule_candidate_ready": not block_reasons,
        "schedule_candidate_window": schedule_window,
        "schedule_block_reasons": block_reasons,
        "manual_review_next_commands": manual_review_commands,
        "phone_review_acceptance_command": (
            "python -m stock_monitor operator-settings set "
            f"{MARKET_BRIEFING_PHONE_REVIEW_SETTING} true "
            "--reason phone_readability_accepted --confirm"
            if len(manual_review_dates) >= enforced_min_manual_reviews and not phone_review_accepted
            else None
        ),
        "dates": date_rows,
    }
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    print("Market briefing readiness")
    print("- read_only: true")
    print("- live_fetch: false")
    print("- sends_telegram: false")
    print("- registers_scheduler: false")
    print("- scoring: false")
    print("- recommendation: false")
    print(f"- inspected dates: {payload['inspected_date_count']}")
    print(f"- preview ready: {payload['preview_ready_count']}/{payload['inspected_date_count']}")
    print(f"- manual Telegram review sends: {payload['manual_review_send_count']}/{enforced_min_manual_reviews}")
    print(f"- phone review accepted: {str(payload['phone_review_accepted']).lower()}")
    print(f"- schedule_candidate_ready: {str(payload['schedule_candidate_ready']).lower()}")
    slot_windows = ", ".join(
        f"{item['slot']} {item['scheduled_time']}~{item['latest_time']}"
        for item in schedule_window["slots"]
    )
    print(f"- schedule windows: {slot_windows} ({schedule_window['flow_backfill_conflict_guard']})")
    if block_reasons:
        print("- schedule block reasons:")
        for reason in block_reasons:
            print(f"  - {reason}")
    if manual_review_commands:
        print("- manual review next commands:")
        for command in manual_review_commands:
            print(f"  - {command}")
    if payload["phone_review_acceptance_command"]:
        print("- phone review acceptance command:")
        print(f"  - {payload['phone_review_acceptance_command']}")
    for row in date_rows:
        warnings = ", ".join(row["data_warnings"]) or "none"
        print(
            f"- {row['business_date']} | reports={row['report_count']} | stocks={row['stock_count']} | "
            f"preview_ready={str(row['preview_ready']).lower()} | warnings={warnings}"
        )
    return 0


def _market_briefing_schedule_window_payload() -> dict[str, object]:
    return {
        "slots": [
            {
                "slot": slot,
                "scheduled_time": start.strftime("%H:%M"),
                "latest_time": _market_briefing_slot_window(slot)[1].strftime("%H:%M"),
            }
            for slot, start in SCHEDULED_MARKET_BRIEFING_SLOT_TIMES.items()
        ],
        "flow_backfill_time": "16:00",
        "flow_backfill_conflict_guard": (
            "preclose slot ends before the 16:00 KRX mentioned-stock flow backfill window"
        ),
    }


def _market_briefing_phone_review_gate_payload(
    *,
    manual_review_dates: list[str],
    min_manual_reviews: int,
    phone_review_accepted: bool,
) -> dict[str, object]:
    required = max(min_manual_reviews, 0)
    recorded = len(manual_review_dates)
    return {
        "required_manual_review_sends": required,
        "recorded_manual_review_sends": recorded,
        "manual_review_dates": manual_review_dates,
        "recorded_review_ready": recorded >= required,
        "phone_review_accepted": phone_review_accepted,
        "operator_settings_cli_enforced": True,
        "admin_gui_settings_api_enforced": True,
        "scheduled_live_send_enforced": True,
        "acceptance_setting_key": MARKET_BRIEFING_PHONE_REVIEW_SETTING,
        "ready": recorded >= required and phone_review_accepted,
    }


