def _build_external_web_view_sharing_plan_payload(
    repository: StockMonitorRepository,
    *,
    python_exe: str = r".\.venv\Scripts\python.exe",
) -> dict[str, object]:
    provider_smoke = _latest_external_web_view_provider_smoke(repository, python_exe=python_exe)
    plan = _build_external_web_view_sharing_plan(
        provider_smoke_ready=bool(provider_smoke.get("ready")),
        python_exe=python_exe,
    )
    next_commands = [
        str(plan["preflight_command"]),
        str(plan["cloudflare_connection_sequence"][2]["command"]),
    ]
    if not provider_smoke.get("ready"):
        next_commands.append(str(plan["provider_verification_command"]))
    return {
        "surface": "external-web-view-sharing-plan",
        "read_only": True,
        "live_fetch": False,
        "writes_database": False,
        "sends_telegram": False,
        "registers_scheduler": False,
        "candidate_surface": plan["candidate_surface"],
        "forbidden_surface": plan["forbidden_surface"],
        "local_tunnel_target": plan["local_tunnel_target"],
        "provider_setup_done": bool(provider_smoke.get("ready")),
        "provider_smoke": provider_smoke,
        "cloudflare_connection_sequence": plan["cloudflare_connection_sequence"],
        "required_provider_controls": plan["required_provider_controls"],
        "provider_smoke_checks": plan["provider_smoke_checks"],
        "next_commands": next_commands,
        "note": "Read-only plan only; does not configure Cloudflare, Tailscale, DNS, router rules, scheduler tasks, or secrets.",
    }


def _run_external_web_view_sharing_plan(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    as_json: bool,
) -> int:
    payload = _build_external_web_view_sharing_plan_payload(
        repository,
        python_exe=_operator_python_exe_display(config),
    )
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 0

    print("External web-view sharing plan")
    print(f"- read-only: {str(payload['read_only']).lower()}")
    print(f"- allowed surface: {payload['candidate_surface']}")
    print(f"- forbidden surface: {payload['forbidden_surface']}")
    print(f"- local tunnel target: {payload['local_tunnel_target']}")
    print(f"- provider smoke ready: {str(payload['provider_setup_done']).lower()}")
    print("- required provider controls:")
    for control in payload["required_provider_controls"]:
        print(f"  - {control}")
    print("- Cloudflare sequence:")
    for step in payload["cloudflare_connection_sequence"]:
        command = step.get("command") or step.get("provider_target") or step.get("expectation")
        print(f"  - {step['step']}: {command}")
    print("- next commands:")
    for command in payload["next_commands"]:
        print(f"  - {command}")
    print(f"- note: {payload['note']}")
    return 0


