def _build_next_market_day_observation(config: RuntimeConfig, *, now: datetime | None = None) -> dict[str, object]:
    current = now or datetime.now(ZoneInfo(config.timezone))
    if current.tzinfo is None:
        current = current.replace(tzinfo=ZoneInfo(config.timezone))
    operator_python_exe = _operator_python_exe_display(config)
    today = current.date()
    observation_date = today if is_business_day(today, config.holiday_overrides) else next_business_day(
        today,
        config.holiday_overrides,
    )
    return {
        "today": today.isoformat(),
        "observation_business_date": observation_date.isoformat(),
        "is_today_business_day": is_business_day(today, config.holiday_overrides),
        "expected_tasks": [
            {
                "task_name": "StockMonitor-TelegramCommands",
                "scheduled_time": "08:00",
                "verify_after": "08:05",
                "evidence": "worker_state.telegram_command_loop or live_observation.telegram_command_loop",
            },
            {
                "task_name": "StockMonitor-KrxDailyBackfill",
                "scheduled_time": "08:10",
                "verify_after": "08:20",
                "evidence": "operation_events component=krx event_type=backfill-missing",
            },
            {
                "task_name": "StockMonitor-Notify",
                "scheduled_time": "08:20",
                "verify_after": "08:30",
                "evidence": "delivery_log telegram daily summary/briefing records",
            },
            {
                "task_name": "StockMonitor-Poll",
                "scheduled_time": "08:30~16:30",
                "verify_after": "09:00 and after 16:30",
                "evidence": "operation_events component=poll and intraday alert batches",
            },
            {
                "task_name": "StockMonitor-KrxMentionedFlowBackfill",
                "scheduled_time": "16:00",
                "verify_after": "16:10",
                "evidence": "operation_events component=krx-flow and stock_investor_flow_daily deltas",
            },
        ],
        "verification_commands": [
            _market_day_observation_wrapper_command(observation_date, python_exe=operator_python_exe),
            "python -m stock_monitor operator-status --json --health-exit",
            (
                "powershell.exe -NoProfile -ExecutionPolicy Bypass -File "
                f".\\scripts\\verify_task_scheduler_registration.ps1 -PythonExe {operator_python_exe}"
            ),
            f"python -m stock_monitor market-day-observation --date {observation_date.isoformat()} --json",
            "python -m stock_monitor db-verify --json",
            "python -m stock_monitor next-phase-readiness --recent-report-dates 5 --stock-limit 20 --json",
        ],
        "note": (
            "StockMonitor-Shutdown policy depends on operation_profile: mini-pc should keep it "
            "unregistered, while desktop-validation should keep any existing shutdown task disabled."
        ),
    }


def _build_market_day_observation_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    now: datetime | None = None,
) -> dict[str, object]:
    current = now or datetime.now(ZoneInfo(config.timezone))
    if current.tzinfo is None:
        current = current.replace(tzinfo=ZoneInfo(config.timezone))
    operator_python_exe = _operator_python_exe_display(config)
    is_observation_business_day = is_business_day(business_date, config.holiday_overrides)
    events = repository.list_recent_operation_events(limit=1000)
    deliveries = repository.list_recent_deliveries(limit=500)
    worker_states = _build_worker_states_snapshot(config, repository, current)
    checks = [
        _build_market_day_observation_check(
            config,
            business_date=business_date,
            now=current,
            events=events,
            deliveries=deliveries,
            worker_states=worker_states,
            key="telegram_command_loop",
            task_name="StockMonitor-TelegramCommands",
            scheduled_time="08:00",
            verify_after="08:05",
            component="telegram-command-loop",
            event_types={"time-window", "run-guard", "iteration"},
            evidence_label="worker_state.telegram_command_loop or operation_events telegram-command-loop",
        ),
        _build_market_day_observation_check(
            config,
            business_date=business_date,
            now=current,
            events=events,
            deliveries=deliveries,
            worker_states=worker_states,
            key="krx_daily_backfill",
            task_name="StockMonitor-KrxDailyBackfill",
            scheduled_time="08:10",
            verify_after="08:20",
            component="krx",
            event_types={"scheduled-daily-backfill", "backfill-missing"},
            evidence_label="operation_events component=krx",
        ),
        _build_market_day_observation_check(
            config,
            business_date=business_date,
            now=current,
            events=events,
            deliveries=deliveries,
            worker_states=worker_states,
            key="notify",
            task_name="StockMonitor-Notify",
            scheduled_time="08:20",
            verify_after="08:30",
            component="notify",
            event_types={"send", "fragment", "early_notify", "late_notify", "run-guard"},
            evidence_label="delivery_log channel=telegram source=scheduled or operation_events notify",
        ),
        _build_market_day_observation_check(
            config,
            business_date=business_date,
            now=current,
            events=events,
            deliveries=deliveries,
            worker_states=worker_states,
            key="poll",
            task_name="StockMonitor-Poll",
            scheduled_time="08:30~16:30",
            verify_after="09:00",
            component="poll",
            event_types={"manual-poll", "time-window", "run-guard"},
            evidence_label="operation_events component=poll",
        ),
        _build_market_day_observation_check(
            config,
            business_date=business_date,
            now=current,
            events=events,
            deliveries=deliveries,
            worker_states=worker_states,
            key="krx_mentioned_flow_backfill",
            task_name="StockMonitor-KrxMentionedFlowBackfill",
            scheduled_time="16:00",
            verify_after="16:10",
            component="krx-flow",
            event_types={"scheduled-mentioned-flow-backfill"},
            evidence_label="operation_events component=krx-flow",
        ),
    ]
    if not is_observation_business_day:
        status = "non_business_day"
        observed_enough = False
    else:
        statuses = {str(check["evidence_status"]) for check in checks}
        if any(status in statuses for status in {"missing", "failed"}):
            status = "incomplete"
        elif "pending" in statuses:
            status = "pending"
        elif "attention" in statuses:
            status = "attention"
        else:
            status = "observed"
        observed_enough = statuses.issubset({"observed", "attention"})
    pending_checks = [check for check in checks if check["evidence_status"] == "pending"]
    next_due_check = min(
        pending_checks,
        key=lambda check: str(check.get("verify_after_at") or ""),
        default=None,
    )
    return {
        "surface": "market-day-observation",
        "read_only": True,
        "live_fetch": False,
        "writes_database": False,
        "sends_telegram": False,
        "registers_scheduler": False,
        "business_date": business_date.isoformat(),
        "now": current.isoformat(),
        "is_business_day": is_observation_business_day,
        "status": status,
        "observed_enough_for_scheduler": observed_enough,
        "next_due_check": (
            {
                "key": next_due_check["key"],
                "task_name": next_due_check["task_name"],
                "scheduled_time": next_due_check["scheduled_time"],
                "verify_after": next_due_check["verify_after"],
                "verify_after_at": next_due_check.get("verify_after_at"),
            }
            if next_due_check
            else None
        ),
        "checks": checks,
        "next_commands": [
            f"python -m stock_monitor market-day-observation --date {business_date.isoformat()} --json",
            "python -m stock_monitor operator-status --json --health-exit",
            (
                "powershell.exe -NoProfile -ExecutionPolicy Bypass -File "
                f".\\scripts\\verify_task_scheduler_registration.ps1 -PythonExe {operator_python_exe}"
            ),
            "python -m stock_monitor db-verify --json",
        ],
        "note": "This audit proves scheduled-run evidence only; KRX latest-row availability and phone readability acceptance are evaluated by separate readiness checks.",
    }


def _build_market_day_observation_check(
    config: RuntimeConfig,
    *,
    business_date: date,
    now: datetime,
    events: list[OperationEvent],
    deliveries: list[DeliveryLog],
    worker_states: dict[str, dict],
    key: str,
    task_name: str,
    scheduled_time: str,
    verify_after: str,
    component: str,
    event_types: set[str],
    evidence_label: str,
) -> dict[str, object]:
    verify_time = datetime_time.fromisoformat(verify_after)
    verify_at = datetime.combine(business_date, verify_time, tzinfo=ZoneInfo(config.timezone))
    if business_date > now.date() or (business_date == now.date() and now.timetz().replace(tzinfo=None) < verify_time):
        return {
            "key": key,
            "task_name": task_name,
            "scheduled_time": scheduled_time,
            "verify_after": verify_after,
            "verify_after_at": verify_at.isoformat(),
            "evidence_status": "pending",
            "evidence_summary": "not yet due",
            "evidence": None,
            "evidence_source": evidence_label,
        }

    if key == "telegram_command_loop":
        worker_evidence = _market_day_telegram_worker_evidence(config, business_date, worker_states)
        if worker_evidence:
            return {
                "key": key,
                "task_name": task_name,
                "scheduled_time": scheduled_time,
                "verify_after": verify_after,
                "verify_after_at": verify_at.isoformat(),
                "evidence_status": worker_evidence["status"],
                "evidence_summary": worker_evidence["summary"],
                "evidence": worker_evidence["evidence"],
                "evidence_source": evidence_label,
            }

    if key == "notify":
        delivery_evidence = _market_day_notify_delivery_evidence(business_date, deliveries)
        if delivery_evidence:
            return {
                "key": key,
                "task_name": task_name,
                "scheduled_time": scheduled_time,
                "verify_after": verify_after,
                "verify_after_at": verify_at.isoformat(),
                "evidence_status": delivery_evidence["status"],
                "evidence_summary": delivery_evidence["summary"],
                "evidence": delivery_evidence["evidence"],
                "evidence_source": evidence_label,
            }

    event = _latest_market_day_event(events, business_date=business_date, component=component, event_types=event_types)
    evidence_status = _live_event_evidence_status(event)
    if key == "krx_daily_backfill" and event and event.status in {"empty", "partial"}:
        evidence_status = "attention"
    return {
        "key": key,
        "task_name": task_name,
        "scheduled_time": scheduled_time,
        "verify_after": verify_after,
        "verify_after_at": verify_at.isoformat(),
        "evidence_status": evidence_status,
        "evidence_summary": _market_day_evidence_summary(event),
        "evidence": _operation_event_to_status_dict(event) if event else None,
        "evidence_source": evidence_label,
    }


def _latest_market_day_event(
    events: list[OperationEvent],
    *,
    business_date: date,
    component: str,
    event_types: set[str],
) -> OperationEvent | None:
    candidates = [
        event
        for event in events
        if event.event_time.date() == business_date and event.component == component and event.event_type in event_types
    ]
    if not candidates:
        return None
    return sorted(candidates, key=_live_event_sort_key, reverse=True)[0]


def _market_day_evidence_summary(event: OperationEvent | None) -> str:
    if event is None:
        return "no evidence after verify_after"
    return f"{event.component}.{event.event_type} {event.status} at {event.event_time.isoformat()}"


def _market_day_telegram_worker_evidence(
    config: RuntimeConfig,
    business_date: date,
    worker_states: dict[str, dict],
) -> dict[str, object] | None:
    worker = worker_states.get(TELEGRAM_COMMAND_LOOP_WORKER)
    if not worker:
        return None
    updated_at = _parse_status_datetime(worker.get("updated_at"), config.timezone)
    if not updated_at or updated_at.date() != business_date:
        return None
    worker_status = str(worker.get("status") or "unknown")
    evidence_status = "failed" if worker_status == "error" else "observed"
    return {
        "status": evidence_status,
        "summary": f"worker_state {worker_status} at {updated_at.isoformat()}",
        "evidence": {
            "event_time": updated_at.isoformat(),
            "component": "telegram-command-loop",
            "event_type": "worker-state",
            "status": worker_status,
            "business_date": business_date.isoformat(),
            "detail": f"last_success_at={worker.get('last_success_at') or '-'}",
        },
    }


def _market_day_notify_delivery_evidence(
    business_date: date,
    deliveries: list[DeliveryLog],
) -> dict[str, object] | None:
    candidates = [
        delivery
        for delivery in deliveries
        if delivery.delivered_at.date() == business_date
        and delivery.channel == PRODUCTION_DELIVERY_CHANNEL
        and "source=scheduled" in (delivery.detail or "")
    ]
    if not candidates:
        return None
    delivery = sorted(candidates, key=lambda item: item.delivered_at, reverse=True)[0]
    evidence_status = "failed" if delivery.status in {"failed", "error"} else "observed"
    return {
        "status": evidence_status,
        "summary": f"delivery_log {delivery.channel} {delivery.status} at {delivery.delivered_at.isoformat()}",
        "evidence": {
            "event_time": delivery.delivered_at.isoformat(),
            "component": "notify",
            "event_type": "delivery-log",
            "status": delivery.status,
            "business_date": delivery.business_date.isoformat(),
            "detail": delivery.detail or "",
        },
    }


def _run_dev_fixture_db(
    *,
    scenario: str,
    output_path: Path,
    overwrite: bool,
    as_json: bool,
) -> int:
    if scenario != "visible-product-flow":
        raise ValueError(f"Unsupported fixture scenario: {scenario}")
    resolved_output = output_path.expanduser().resolve()
    if resolved_output.exists():
        if not overwrite:
            raise FileExistsError(f"Fixture DB already exists: {resolved_output}")
        if not resolved_output.is_file() or resolved_output.suffix.lower() not in {".db", ".sqlite", ".sqlite3"}:
            raise ValueError(f"--overwrite only supports SQLite fixture files: {resolved_output}")
        resolved_output.unlink()
    resolved_output.parent.mkdir(parents=True, exist_ok=True)

    config = RuntimeConfig.from_env(root_dir=Path.cwd(), db_path=resolved_output)
    config.ensure_runtime_dirs()
    repository = StockMonitorRepository(resolved_output, timezone=config.timezone)
    repository.initialize()
    business_date = date(2026, 5, 8)
    _seed_visible_product_flow_fixture(repository, business_date=business_date)

    commands = [
        f"$env:STOCK_MONITOR_DB_PATH = '{resolved_output}'",
        f"python -m stock_monitor web-view-value-qa --date {business_date.isoformat()} --stock-limit 20 --json",
        f"python -m stock_monitor web-view-browser-smoke --date {business_date.isoformat()} --stock-limit 20 --json",
        f"python -m stock_monitor market-briefing --date {business_date.isoformat()} --slot lunch --limit 5 --json",
        f"python -m stock_monitor market-briefing --date {business_date.isoformat()} --slot preclose --limit 5",
        f"python -m stock_monitor market-briefing-readiness --recent-report-dates 1 --limit 5 --json",
    ]
    payload = {
        "surface": "dev-fixture-db",
        "scenario": scenario,
        "business_date": business_date.isoformat(),
        "db_path": str(resolved_output),
        "writes_production_db": False,
        "sends_telegram": False,
        "registers_scheduler": False,
        "verification_commands": commands,
    }
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
    else:
        print("Dev fixture DB")
        print(f"- scenario: {payload['scenario']}")
        print(f"- business date: {payload['business_date']}")
        print(f"- db: {payload['db_path']}")
        for command in commands:
            print(f"- verify: {command}")
    return 0


