def _build_market_briefing_readiness_date(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    limit: int,
) -> dict[str, object]:
    _ = config
    summaries = repository.list_daily_summaries(business_date)
    report_count = sum(summary.mention_count for summary in summaries)
    market_reference_lines = _build_daily_briefing_market_reference_lines(repository, business_date)
    turnover_reference_lines = _build_market_briefing_turnover_lines(repository, business_date)
    flow_reference_lines = _build_daily_briefing_flow_reference_lines(
        repository,
        business_date,
        summaries=summaries,
        stock_limit=limit,
    )
    notable_lines = _build_market_briefing_notable_lines(summaries, limit=limit)
    check_point_lines = _build_market_briefing_check_point_lines(repository, business_date)
    time_slot_mood_card = _build_web_view_market_briefing_context(
        repository,
        business_date,
        summaries=summaries,
    )["time_slot_mood_card"]
    message = format_market_close_briefing_message(
        business_date,
        report_count=report_count,
        stock_count=len(summaries),
        market_reference_lines=market_reference_lines,
        turnover_reference_lines=turnover_reference_lines,
        flow_reference_lines=flow_reference_lines,
        notable_lines=notable_lines,
        check_point_lines=check_point_lines,
    )
    issues = _collect_market_briefing_message_issues(message)
    snapshot_dates = repository.list_recent_krx_snapshot_dates(on_or_before=business_date, limit=1)
    flow_dates = repository.list_recent_investor_flow_dates(on_or_before=business_date, limit=1)
    data_warnings: list[str] = []
    if not market_reference_lines:
        data_warnings.append("missing_index_reference")
    if not turnover_reference_lines:
        data_warnings.append("missing_turnover_reference")
    if not flow_reference_lines:
        data_warnings.append("missing_flow_reference")
    if not notable_lines:
        data_warnings.append("missing_notable_stocks")
    if snapshot_dates and snapshot_dates[0] != business_date:
        data_warnings.append(f"krx_snapshot_fallback:{snapshot_dates[0].isoformat()}")
    if flow_dates and flow_dates[0] != business_date:
        data_warnings.append(f"flow_fallback:{flow_dates[0].isoformat()}")
    return {
        "business_date": business_date.isoformat(),
        "report_count": report_count,
        "stock_count": len(summaries),
        "message_line_count": len([line for line in message.splitlines() if line.strip()]),
        "krx_snapshot_date": snapshot_dates[0].isoformat() if snapshot_dates else None,
        "flow_reference_date": flow_dates[0].isoformat() if flow_dates else None,
        "has_market_reference": bool(market_reference_lines),
        "has_turnover_reference": bool(turnover_reference_lines),
        "has_flow_reference": bool(flow_reference_lines),
        "notable_stock_count": max(len(notable_lines) - 1, 0),
        "has_check_points": bool(check_point_lines),
        "time_slot_mood_card": time_slot_mood_card,
        "time_slot_mood_source_gap_count": len(time_slot_mood_card.get("source_gaps", [])),
        "public_safe_issue_count": len(issues),
        "public_safe_issues": issues,
        "data_warnings": data_warnings,
        "preview_ready": report_count > 0 and not issues and bool(check_point_lines),
    }


def _market_briefing_manual_review_dates(repository: StockMonitorRepository) -> list[str]:
    deliveries = repository.list_recent_deliveries(limit=200)
    dates = {
        delivery.business_date.isoformat()
        for delivery in deliveries
        if delivery.channel == MARKET_BRIEFING_DELIVERY_CHANNEL
        and delivery.status == "sent"
        and delivery.detail
        and "source=manual" in delivery.detail
    }
    return sorted(dates, reverse=True)


def _market_briefing_slot_delivery_channel(slot: str) -> str:
    if slot not in MARKET_BRIEFING_SLOT_LABELS:
        raise ValueError(f"Unknown market briefing slot: {slot}")
    return f"{MARKET_BRIEFING_DELIVERY_CHANNEL}_{slot}"


def _market_briefing_slot_window(slot: str) -> tuple[datetime_time, datetime_time]:
    try:
        start = SCHEDULED_MARKET_BRIEFING_SLOT_TIMES[slot]
    except KeyError as exc:
        raise ValueError(f"Unknown market briefing slot: {slot}") from exc
    end_dt = datetime.combine(date(2000, 1, 1), start) + timedelta(minutes=MARKET_BRIEFING_SLOT_WINDOW_MINUTES)
    return start, end_dt.time()


def _validate_market_briefing_phone_review_acceptance_change(
    repository: StockMonitorRepository,
    *,
    key: str,
    normalized_value: str,
    previous_value: str,
    now: datetime,
    actor: str,
) -> None:
    if key != MARKET_BRIEFING_PHONE_REVIEW_SETTING or normalized_value != "true":
        return
    manual_review_dates = _market_briefing_manual_review_dates(repository)
    if len(manual_review_dates) >= MARKET_BRIEFING_MIN_MANUAL_REVIEW_SENDS:
        return
    detail = (
        f"{MARKET_BRIEFING_PHONE_REVIEW_SETTING} requires "
        f"{MARKET_BRIEFING_MIN_MANUAL_REVIEW_SENDS} recorded manual Telegram review sends; "
        f"found {len(manual_review_dates)}."
    )
    repository.record_admin_audit_log(
        AdminAuditLog(
            event_time=now,
            actor=actor,
            action="set_app_setting",
            status="validation_failed",
            setting_key=key,
            old_value=previous_value,
            new_value=normalized_value,
            detail=detail,
        )
    )
    raise ValueError(detail)


def _market_briefing_manual_review_commands(
    date_rows: list[dict[str, object]],
    *,
    reviewed_dates: set[str],
    limit: int,
    max_commands: int,
) -> list[str]:
    if max_commands <= 0:
        return []
    commands: list[str] = []
    for row in date_rows:
        business_date = str(row.get("business_date") or "")
        if not business_date or business_date in reviewed_dates:
            continue
        if not row.get("preview_ready") or row.get("public_safe_issue_count"):
            continue
        commands.append(f"python -m stock_monitor market-briefing --date {business_date} --limit {limit} --send")
        if len(commands) >= max_commands:
            break
    return commands


def _build_market_briefing_news_flow_lines(
    *,
    source_urls: tuple[str, ...],
    fixture: Path,
    slot: str = "mood",
) -> list[str]:
    from stock_monitor.news.flow import (
        build_news_flow_preview,
        format_news_flow_slot_section,
        parse_news_flow_json,
    )

    collection = parse_news_flow_json(fixture.read_text(encoding="utf-8"), source_urls=source_urls)
    return format_news_flow_slot_section(build_news_flow_preview(collection), slot=slot)


def _build_market_briefing_message(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    limit: int,
    slot: str = "mood",
    toss_quote_provider: object | None = None,
    toss_context: dict[str, object] | None = None,
    include_live_candidate_quotes: bool = False,
    naver_quote_fetcher: Callable[..., StockQuoteSnapshot] | None = None,
    candidate_stock_codes: tuple[str, ...] | None = None,
    layout: str = "default",
) -> str:
    summaries = repository.list_daily_summaries(business_date)
    if not summaries:
        summaries = repository.rebuild_daily_summaries(business_date)
    report_count = sum(summary.mention_count for summary in summaries)
    requested_candidate_codes = tuple(
        code for code in (candidate_stock_codes or ()) if re.fullmatch(r"\d{6}", code)
    )
    candidate_snapshot = build_web_view_candidate_evidence_snapshot(
        config,
        repository,
        business_date=business_date,
        limit=max(len(summaries), len(requested_candidate_codes), 2),
    )
    all_candidate_rows = [row for row in candidate_snapshot.get("rows", []) if isinstance(row, dict)]
    if requested_candidate_codes:
        rows_by_code = {str(row.get("stock_code") or "").strip(): row for row in all_candidate_rows}
        candidate_rows = [rows_by_code[code] for code in requested_candidate_codes if code in rows_by_code][:2]
    else:
        candidate_rows = all_candidate_rows[:2]
    effective_toss_context = toss_context or _build_market_briefing_toss_priority_context(
        config,
        repository,
        business_date=business_date,
        toss_quote_provider=toss_quote_provider,
        candidate_rows=candidate_rows,
    )
    priority_lines = (
        _build_market_briefing_priority_candidate_lines(
            candidate_rows,
            toss_context=effective_toss_context,
            include_live_candidate_quotes=True,
            naver_quote_fetcher=naver_quote_fetcher,
            timeout_seconds=config.telegram_timeout_seconds,
        )
        if include_live_candidate_quotes
        else []
    )
    news_observation_lines = _build_market_briefing_news_observation_lines(
        repository,
        business_date,
        stock_codes=[str(row.get("stock_code") or "").strip() for row in candidate_rows],
    )
    source_freshness_lines = _build_market_briefing_source_freshness_lines(
        repository,
        business_date,
        report_count=report_count,
        toss_context=effective_toss_context,
        summaries=summaries,
        priority_stock_codes=tuple(str(row.get("stock_code") or "").strip() for row in candidate_rows),
    )
    toss_quote_lines = _build_market_briefing_toss_priority_quote_lines(
        effective_toss_context,
        candidate_rows=candidate_rows,
    )
    market_reference_lines = _build_daily_briefing_market_reference_lines(repository, business_date)
    turnover_reference_lines = [
        *_build_market_briefing_turnover_lines(repository, business_date),
        *_build_market_briefing_toss_market_context_lines(effective_toss_context),
    ]
    flow_reference_lines = _build_daily_briefing_flow_reference_lines(
        repository,
        business_date,
        summaries=summaries,
        stock_limit=limit,
        priority_stock_codes=tuple(str(row.get("stock_code") or "").strip() for row in candidate_rows),
    )
    notable_lines = _build_market_briefing_notable_lines(summaries, limit=limit)
    check_point_lines = _build_market_briefing_check_point_lines(repository, business_date)
    if layout == "realtime-first":
        message = _format_market_briefing_realtime_first_preview(
            business_date=business_date,
            candidate_rows=candidate_rows,
            report_count=report_count,
            stock_count=len(summaries),
            news_observation_lines=news_observation_lines,
            toss_context=effective_toss_context,
            market_reference_lines=market_reference_lines,
            turnover_reference_lines=turnover_reference_lines,
            flow_reference_lines=flow_reference_lines,
            source_freshness_summary=_build_market_briefing_source_freshness_summary(
                repository,
                business_date,
                report_count=report_count,
                toss_context=effective_toss_context,
                summaries=summaries,
                priority_stock_codes=tuple(str(row.get("stock_code") or "").strip() for row in candidate_rows),
            ),
        )
    else:
        message = format_market_close_briefing_message(
            business_date,
            report_count=report_count,
            stock_count=len(summaries),
            market_reference_lines=market_reference_lines,
            turnover_reference_lines=turnover_reference_lines,
            flow_reference_lines=flow_reference_lines,
            notable_lines=notable_lines,
            check_point_lines=check_point_lines,
        )
    message = _apply_market_briefing_slot_header(message, business_date=business_date, slot=slot)
    if layout == "realtime-first":
        _ensure_market_briefing_message_public_safe(message)
        return message
    if news_observation_lines:
        message = _insert_market_briefing_section_before_check_points(message, news_observation_lines)
    if priority_lines:
        message = _insert_market_briefing_section_before_check_points(message, priority_lines)
    if toss_quote_lines and not priority_lines:
        message = _insert_market_briefing_section_before_check_points(message, toss_quote_lines)
    if source_freshness_lines:
        message = _insert_market_briefing_section_before_check_points(message, source_freshness_lines)
    _ensure_market_briefing_message_public_safe(message)
    return message


def _format_market_briefing_realtime_first_preview(
    *,
    business_date: date,
    candidate_rows: list[dict[str, object]],
    report_count: int,
    stock_count: int,
    news_observation_lines: list[str],
    toss_context: dict[str, object],
    market_reference_lines: list[str],
    turnover_reference_lines: list[str],
    flow_reference_lines: list[str],
    source_freshness_summary: dict,
) -> str:
    current_lines = _market_briefing_realtime_current_quote_lines(toss_context, candidate_rows)
    if news_observation_lines:
        current_lines.extend(news_observation_lines[1:] or news_observation_lines)
    if not current_lines:
        current_lines.append("- 현재가/거래대금 현재 근거 없음; 저장 뉴스와 source gap 확인")

    previous_day_lines = [
        *(market_reference_lines or []),
        *(turnover_reference_lines or []),
        *(flow_reference_lines or []),
    ] or ["- KRX daily/index/flow/ETF 전일 참고 없음"]

    return "\n\n".join(
        "\n".join(section)
        for section in [
            [f"Realtime-first preview · {business_date.isoformat()}"],
            [
                "오늘 볼 것",
                *_market_briefing_realtime_candidate_lines(
                    candidate_rows,
                    report_count=report_count,
                    stock_count=stock_count,
                ),
            ],
            ["현재 근거", *current_lines],
            ["전일 참고", *previous_day_lines],
            ["부족한 근거", *_market_briefing_realtime_gap_lines(source_freshness_summary)],
            ["복기/연구", "- reaction/backtest는 preview 비교에서 후순위; 운영 검수표에만 기록"],
        ]
    )


def _market_briefing_realtime_candidate_lines(
    candidate_rows: list[dict[str, object]],
    *,
    report_count: int,
    stock_count: int,
) -> list[str]:
    if not candidate_rows:
        return [f"- Top2 후보 없음; 리포트 {report_count}건 / {stock_count}종목"]
    lines: list[str] = []
    for index, row in enumerate(candidate_rows[:2], start=1):
        stock_code = str(row.get("stock_code") or "").strip()
        stock_name = str(row.get("stock_name") or stock_code or "-").strip()
        value_profile = row.get("value_profile") if isinstance(row.get("value_profile"), dict) else {}
        reason = str(value_profile.get("value_reason") or "").strip()
        if not reason:
            reasons = [str(item).strip() for item in row.get("why_notable") or [] if str(item).strip()]
            reason = " / ".join(reasons[:2]) if reasons else "저장 리포트 근거 확인"
        lines.append(f"{index}. {stock_name} {stock_code} - {reason}")
    return lines


def _market_briefing_realtime_current_quote_lines(
    toss_context: dict[str, object],
    candidate_rows: list[dict[str, object]],
) -> list[str]:
    payload = toss_context.get("payload") if isinstance(toss_context.get("payload"), dict) else {}
    if payload.get("live_fetch") is not True:
        return []
    names_by_code = {
        str(row.get("stock_code") or "").strip(): str(row.get("stock_name") or row.get("stock_code") or "-").strip()
        for row in candidate_rows
    }
    lines: list[str] = []
    for quote in payload.get("quotes", []):
        if not isinstance(quote, dict):
            continue
        symbol = str(quote.get("symbol") or "").strip()
        price = _safe_optional_int(quote.get("lastPrice"))
        if not symbol or price is None:
            continue
        checked_at = _market_briefing_toss_checked_time(quote.get("timestamp") or payload.get("fetched_at"))
        suffix = f" · 조회 {checked_at}" if checked_at else ""
        lines.append(f"- {names_by_code.get(symbol, symbol)}: Toss 현재가 {price:,}원{suffix}")
    return lines


def _market_briefing_realtime_gap_lines(source_freshness_summary: dict) -> list[str]:
    lines: list[str] = []
    for item in source_freshness_summary.get("items", []):
        if not isinstance(item, dict):
            continue
        status = str(item.get("status") or "missing")
        if status in {"exact", "current", "ready"}:
            continue
        label = str(item.get("label") or item.get("key") or "source")
        lines.append(f"- {label}: {_market_briefing_source_freshness_item_text(item)}")
    return lines or ["- 주요 현재성 공백 없음"]


def _build_market_briefing_toss_priority_context(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    toss_quote_provider: object | None = None,
    candidate_rows: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    if candidate_rows is None:
        evidence = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=2,
        )
        candidate_rows = [row for row in evidence.get("rows", []) if isinstance(row, dict)][:2]
    symbols = tuple(
        str(row.get("stock_code") or "").strip()
        for row in candidate_rows
        if re.fullmatch(r"\d{6}", str(row.get("stock_code") or "").strip())
    )
    names_by_symbol = {
        str(row.get("stock_code") or "").strip(): str(row.get("stock_name") or "").strip()
        for row in candidate_rows
    }
    provider = toss_quote_provider or TossPriorityQuoteProvider(
        config=TossOpenApiLabConfig.from_env(config.root_dir)
    )
    try:
        payload = provider.get_quotes(priority_date=business_date, symbols=symbols)
    except RuntimeError:
        payload = {
            "configured": bool(getattr(provider, "configured", False)),
            "live_fetch": False,
            "priority_date": business_date.isoformat(),
            "quotes": [],
            "reason": "upstream_unavailable",
        }
    market_context = _build_toss_market_context(
        provider,
        reference_date=previous_business_day(business_date, config.holiday_overrides),
        priority_symbols=symbols,
    )
    return {
        "payload": payload,
        "market_context": market_context,
        "symbols": symbols,
        "names_by_symbol": names_by_symbol,
        "source_item": _market_briefing_toss_source_freshness_item(payload, business_date=business_date),
    }


def _build_toss_market_context(
    provider: object,
    *,
    reference_date: date,
    priority_symbols: tuple[str, ...],
) -> dict[str, object]:
    fetch_context = getattr(provider, "get_market_context", None)
    fallback = {
        "configured": bool(getattr(provider, "configured", False)),
        "live_fetch": False,
        "reference_date": reference_date.isoformat(),
        "rankings": [],
        "priority_overlap_symbols": [],
        "investor_flow": {"KOSPI": None, "KOSDAQ": None},
    }
    if not callable(fetch_context):
        return {**fallback, "reason": "provider_unavailable"}
    try:
        payload = fetch_context(reference_date=reference_date, priority_symbols=priority_symbols)
    except RuntimeError:
        return {**fallback, "reason": "upstream_unavailable"}
    return payload if isinstance(payload, dict) else {**fallback, "reason": "invalid_provider_payload"}


def _build_market_briefing_priority_candidate_lines(
    candidate_rows: list[dict[str, object]],
    *,
    toss_context: dict[str, object],
    include_live_candidate_quotes: bool,
    naver_quote_fetcher: Callable[..., StockQuoteSnapshot] | None,
    timeout_seconds: float,
) -> list[str]:
    if not candidate_rows:
        return []
    quote_fetcher = naver_quote_fetcher or fetch_stock_quote_snapshot
    toss_payload = toss_context.get("payload") if isinstance(toss_context.get("payload"), dict) else {}
    toss_quotes = {
        str(item.get("symbol") or "").strip(): item
        for item in toss_payload.get("quotes", [])
        if isinstance(item, dict) and str(item.get("symbol") or "").strip()
    }
    lines = ["우선 확인 후보"]
    for index, row in enumerate(candidate_rows, start=1):
        stock_code = str(row.get("stock_code") or "").strip()
        stock_name = str(row.get("stock_name") or stock_code or "-").strip()
        priority = str(row.get("observation_priority") or "확인 후보").strip()
        value_profile = row.get("value_profile") if isinstance(row.get("value_profile"), dict) else {}
        report_summary = row.get("report_summary") if isinstance(row.get("report_summary"), dict) else {}
        reason = str(value_profile.get("value_reason") or "").strip()
        decision_label = str(value_profile.get("value_label") or "저장 근거 확인").strip()
        if not reason:
            reasons = [str(item) for item in row.get("why_notable") or [] if str(item).strip()]
            reason = " · ".join(reasons[:2]) or "저장 리포트 근거를 확인합니다."
        report_count = int(report_summary.get("report_count") or 0)
        lines.append(f"{index}. {stock_name} {stock_code} · {priority}")
        lines.append(f"- 관찰 사유: {reason} / 리포트 {report_count}건")
        lines.append(f"- 판단 상태: {decision_label}")

        if include_live_candidate_quotes and stock_code:
            try:
                quote = quote_fetcher(stock_code, timeout_seconds=timeout_seconds)
            except Exception:
                lines.append("- 장중 참고: Naver 현재 참고값을 이번 회차에 확인하지 못했습니다.")
            else:
                lines.append(f"- 장중 참고: {_format_market_briefing_naver_quote(quote)}")

        badge = row.get("news_observation_badge") if isinstance(row.get("news_observation_badge"), dict) else {}
        news_label = str(badge.get("display_label") or badge.get("connection_label") or "뉴스 근거 수집 전").strip()
        news_reason = str(badge.get("top_title") or badge.get("reason") or "").strip()
        lines.append(f"- 뉴스 근거: {news_label}{f' · {news_reason}' if news_reason else ''}")

        toss_quote = toss_quotes.get(stock_code)
        toss_price = _safe_optional_int(toss_quote.get("lastPrice")) if toss_quote else None
        if toss_price is not None:
            checked_at = _market_briefing_toss_checked_time(
                toss_quote.get("timestamp") or toss_payload.get("fetched_at")
            )
            line = f"- Toss 현재가: {toss_price:,}원"
            if checked_at:
                line += f" · 조회 {checked_at}"
            lines.append(line)

        toss_baseline = row.get("toss_baseline_reference")
        if isinstance(toss_baseline, dict) and toss_baseline.get("available") is True:
            baseline_price = _safe_optional_int(toss_baseline.get("last_price"))
            if baseline_price is not None:
                baseline_time = str(toss_baseline.get("baseline_time") or "20:00")
                stored_at = _market_briefing_toss_checked_time(toss_baseline.get("reference_time"))
                line = f"- Toss {baseline_time} 기준: {baseline_price:,}원"
                if stored_at:
                    line += f" · 저장 {stored_at}"
                lines.append(line)
    return lines


def _format_market_briefing_naver_quote(quote: StockQuoteSnapshot) -> str:
    price = f"{quote.current_price:,}원" if quote.current_price is not None else "현재가 확인 불가"
    change = _format_signed_percent(quote.prev_change_rate)
    turnover = _format_krx_flow_amount(quote.trade_amount) if quote.trade_amount is not None else "거래대금 확인 불가"
    status = _market_briefing_naver_market_status(quote.market_status)
    checked_at = quote.trade_time.strftime("%H:%M") if quote.trade_time else None
    parts = [price]
    if change:
        parts.append(change)
    parts.append(f"거래대금 {turnover}")
    if status:
        parts.append(status)
    if checked_at:
        parts.append(f"확인 {checked_at}")
    return " · ".join(parts)


def _market_briefing_naver_market_status(value: object) -> str | None:
    status = str(value or "").strip().upper()
    if status in {"OPEN", "ACTIVE", "TRADING"}:
        return "장중"
    if status in {"CLOSE", "CLOSED", "AFTER_HOURS"}:
        return "마감"
    return str(value or "").strip() or None


def _market_briefing_toss_source_freshness_item(payload: dict[str, object], *, business_date: date) -> dict[str, object]:
    live_fetch = payload.get("live_fetch") is True
    configured = payload.get("configured") is True
    cache = str(payload.get("cache") or "").strip()
    if live_fetch:
        status = "stale" if cache == "stale" else "current"
    elif configured and str(payload.get("reason") or "") == "upstream_unavailable":
        status = "unavailable"
    elif configured:
        status = "missing"
    else:
        status = "disabled"
    return {
        "key": "toss_openapi",
        "label": "Toss OpenAPI",
        "source": "toss_openapi",
        "status": status,
        "reference_date": str(payload.get("priority_date") or business_date.isoformat()),
        "exact_date_available": False,
        "available": live_fetch,
        "data_scope": "market_briefing_priority_top_2_quotes" if live_fetch else "not_called_or_unavailable",
        "live_fetch": live_fetch,
        "affects_ordering": False,
        "notice": "Scheduled market briefing top-two current-price reference.",
    }


def _build_market_briefing_toss_priority_quote_lines(
    toss_context: dict[str, object],
    *,
    candidate_rows: list[dict[str, object]],
) -> list[str]:
    payload = toss_context.get("payload") if isinstance(toss_context.get("payload"), dict) else {}
    if payload.get("live_fetch") is not True:
        if payload.get("configured") is True and payload.get("reason") == "upstream_unavailable":
            lines = ["Toss 우선확인 현재가", "- 공급자 응답 없음"]
        else:
            lines = []
    else:
        names_by_symbol = toss_context.get("names_by_symbol")
        if not isinstance(names_by_symbol, dict):
            names_by_symbol = {}
        quote_rows = payload.get("quotes") if isinstance(payload.get("quotes"), list) else []
        fetched_at = payload.get("fetched_at")
        quote_lines: list[str] = []
        for quote in quote_rows:
            if not isinstance(quote, dict):
                continue
            symbol = str(quote.get("symbol") or "").strip()
            if not symbol:
                continue
            last_price = _safe_optional_int(quote.get("lastPrice"))
            if last_price is None:
                continue
            stock_name = str(names_by_symbol.get(symbol) or symbol)
            checked_at = _market_briefing_toss_checked_time(quote.get("timestamp") or fetched_at)
            line = f"- {stock_name} {last_price:,}원"
            if checked_at:
                line += f" · 조회 {checked_at}"
            quote_lines.append(line)
        lines = ["Toss 우선확인 현재가", *quote_lines] if quote_lines else ["Toss 우선확인 현재가", "- 조회 결과 없음"]

    baseline_lines: list[str] = []
    for row in candidate_rows:
        baseline = row.get("toss_baseline_reference")
        if not isinstance(baseline, dict) or baseline.get("available") is not True:
            continue
        last_price = _safe_optional_int(baseline.get("last_price"))
        if last_price is None:
            continue
        stock_name = str(row.get("stock_name") or row.get("stock_code") or "-")
        baseline_time = str(baseline.get("baseline_time") or "20:00")
        stored_at = _market_briefing_toss_checked_time(baseline.get("reference_time"))
        line = f"- {stock_name} Toss {baseline_time} 기준: {last_price:,}원"
        if stored_at:
            line += f" · 저장 {stored_at}"
        baseline_lines.append(line)
    if baseline_lines:
        if not lines:
            lines.append("Toss 우선확인 기준")
        lines.extend(baseline_lines)
    return lines


def _market_briefing_toss_checked_time(value: object) -> str | None:
    raw = str(value or "").strip().replace("T", " ")
    return raw[11:16] if len(raw) >= 16 and raw[11:16].count(":") == 1 else None


def _build_market_briefing_toss_market_context_lines(toss_context: dict[str, object]) -> list[str]:
    payload = toss_context.get("market_context") if isinstance(toss_context.get("market_context"), dict) else {}
    if payload.get("live_fetch") is not True:
        return []
    names_by_symbol = toss_context.get("names_by_symbol") if isinstance(toss_context.get("names_by_symbol"), dict) else {}
    rankings = payload.get("rankings") if isinstance(payload.get("rankings"), list) else []
    ranked_at = _market_briefing_toss_checked_time(payload.get("ranked_at") or payload.get("fetched_at"))
    ranking_symbols = [
        str(item.get("symbol") or "").strip()
        for item in rankings
        if isinstance(item, dict) and str(item.get("symbol") or "").strip()
    ]
    rank_display = ", ".join(str(names_by_symbol.get(symbol) or symbol) for symbol in ranking_symbols[:20])
    lines = ["Toss 거래대금 Top20"]
    lines.append(f"- {rank_display or '집계 종목 없음'}{f' · 집계 {ranked_at}' if ranked_at else ''}")
    overlaps = [str(item) for item in payload.get("priority_overlap_symbols", []) if str(item).strip()]
    overlap_display = ", ".join(str(names_by_symbol.get(symbol) or symbol) for symbol in overlaps)
    lines.append(f"- 우선 확인 겹침: {overlap_display or '없음'}")

    investor_flow = payload.get("investor_flow") if isinstance(payload.get("investor_flow"), dict) else {}
    lines.append("전일 시장 수급 참고")
    for market in ("KOSPI", "KOSDAQ"):
        record = investor_flow.get(market)
        if not isinstance(record, dict):
            lines.append(f"- {market}: 기준일 데이터 없음")
            continue
        fragments = []
        for key, label in (("foreigner", "외국인"), ("institution", "기관")):
            amount = record.get(key)
            if not isinstance(amount, dict):
                continue
            buy = _safe_optional_int(amount.get("buyAmount"))
            sell = _safe_optional_int(amount.get("sellAmount"))
            if buy is None or sell is None:
                continue
            fragments.append(f"{label} {_format_flow_reference_amount(buy - sell)}")
        lines.append(f"- {market}: {' · '.join(fragments) if fragments else '집계값 확인 필요'}")
    return lines


def _build_market_briefing_source_freshness_summary(
    repository: StockMonitorRepository,
    business_date: date,
    *,
    report_count: int | None = None,
    toss_context: dict[str, object] | None = None,
    summaries: list[DailyStockSummary] | None = None,
    priority_stock_codes: tuple[str, ...] | list[str] | None = None,
) -> dict:
    if report_count is None:
        report_count = sum(summary.mention_count for summary in repository.list_daily_summaries(business_date))
    summary = _build_web_view_source_freshness_summary(
        business_date=business_date,
        report_count=report_count,
        recent_krx_snapshot_dates=repository.list_recent_krx_snapshot_dates(on_or_before=business_date, limit=1),
        recent_flow_dates=repository.list_recent_investor_flow_dates(on_or_before=business_date, limit=1),
        investor_flow_item=(
            _build_stock_flow_source_freshness_item(
                repository,
                business_date,
                summaries=summaries,
                priority_stock_codes=priority_stock_codes,
            )
            if summaries is not None
            else None
        ),
    )
    if not toss_context:
        return summary
    toss_item = toss_context.get("source_item")
    if not isinstance(toss_item, dict):
        return summary
    summary["items"] = [
        toss_item if item.get("key") == "toss_openapi" else item
        for item in summary.get("items", [])
        if isinstance(item, dict)
    ]
    summary["live_fetch"] = toss_item.get("live_fetch") is True
    return summary


def _build_market_briefing_source_freshness_lines(
    repository: StockMonitorRepository,
    business_date: date,
    *,
    report_count: int,
    toss_context: dict[str, object] | None = None,
    summaries: list[DailyStockSummary] | None = None,
    priority_stock_codes: tuple[str, ...] | list[str] | None = None,
) -> list[str]:
    summary = _build_market_briefing_source_freshness_summary(
        repository,
        business_date,
        report_count=report_count,
        toss_context=toss_context,
        summaries=summaries,
        priority_stock_codes=priority_stock_codes,
    )
    return _market_briefing_source_freshness_lines(summary)


def _market_briefing_source_freshness_lines(summary: dict) -> list[str]:
    items = {
        str(item.get("key")): item
        for item in summary.get("items", [])
        if isinstance(item, dict) and item.get("key")
    }
    lines = ["데이터 기준"]
    for key in ("reports", "krx_market", "etf_daily", "investor_flow", "toss_openapi"):
        item = items.get(key)
        if not item:
            continue
        label = str(item.get("label") or key)
        lines.append(f"- {label}: {_market_briefing_source_freshness_item_text(item)}")
    return lines if len(lines) > 1 else []


def _market_briefing_source_freshness_item_text(item: dict[str, object]) -> str:
    status = _market_briefing_source_freshness_status_text(str(item.get("status") or "missing"))
    if item.get("key") == "toss_openapi":
        suffix = "우선확인 현재가" if item.get("live_fetch") else "호출 없음"
        return f"{status} ({suffix})"
    reference_date = _market_briefing_source_reference_date_text(item.get("reference_date"))
    count = item.get("count")
    count_suffix = f" ({int(count)}건)" if isinstance(count, int) else ""
    return f"{status}{(' ' + reference_date) if reference_date else ''}{count_suffix}"


def _market_briefing_source_freshness_status_text(status: str) -> str:
    if status == "lab_hold":
        return "lab-hold"
    if status == "ready":
        return "ready"
    if status == "configured":
        return "configured"
    if status == "current":
        return "current"
    if status == "disabled":
        return "disabled"
    return status


def _market_briefing_source_reference_date_text(value: object) -> str:
    if not value:
        return ""
    try:
        return date.fromisoformat(str(value)).strftime("%y.%m.%d")
    except ValueError:
        return str(value)


def _apply_market_briefing_slot_header(message: str, *, business_date: date, slot: str) -> str:
    lines = message.splitlines()
    if not lines:
        return message
    label = MARKET_BRIEFING_SLOT_LABELS.get(slot, MARKET_BRIEFING_SLOT_LABELS["mood"])
    lines[0] = f"{label} · {business_date.strftime('%y.%m.%d')}"
    return "\n".join(lines)


def _build_market_briefing_news_observation_lines(
    repository: StockMonitorRepository,
    business_date: date,
    *,
    limit: int = 3,
    stock_codes: list[str] | tuple[str, ...] | None = None,
) -> list[str]:
    summary = _build_web_view_news_observation_summary(
        repository,
        business_date,
        limit=limit,
        stock_codes=stock_codes,
    )
    if not summary.get("available"):
        return []
    lines = ["뉴스 관찰 / 뉴스 근거"]
    items = [item for item in summary.get("items", []) if isinstance(item, dict) and item.get("available")]
    if items:
        lines.append(
            "- "
            f"저장 관찰 {len(items)}종목 / "
            f"직접 {int(summary.get('direct_count') or 0)}건 / "
            f"주의 {int(summary.get('caution_count') or 0)}건 / "
            f"시장맥락 {int(summary.get('market_context_count') or 0)}건"
        )
    for item in items[: max(1, limit)]:
        stock = item.get("stock_name") or item.get("stock_code") or "-"
        label = item.get("display_label") or "뉴스 근거 있음"
        title = item.get("top_title") or item.get("reason") or ""
        count_text = (
            f"직접 {int(item.get('direct_count') or 0)}"
            f"/주의 {int(item.get('caution_count') or 0)}"
            f"/시장맥락 {int(item.get('market_context_count') or 0)}"
        )
        suffix = f" | {title}" if title else ""
        lines.append(f"- {stock}: {label} ({count_text}){suffix}")
    if len(lines) == 1:
        label = summary.get("display_label") or "뉴스 근거 있음"
        titles = [str(title) for title in summary.get("top_titles", []) if title]
        suffix = " | " + " / ".join(titles[:limit]) if titles else ""
        lines.append(f"- {label}{suffix}")
    return lines


def _insert_market_briefing_section_before_check_points(message: str, section_lines: list[str]) -> str:
    marker = "\n\n확인 포인트"
    section = "\n\n" + "\n".join(section_lines)
    if marker in message:
        return message.replace(marker, section + marker, 1)
    return message + section


def _ensure_market_briefing_message_public_safe(message: str) -> None:
    issues = _collect_market_briefing_message_issues(message)
    if not issues:
        return
    details = "; ".join(f"{issue['code']}@{issue['line']}: {issue['message']}" for issue in issues)
    raise ValueError(f"market briefing message failed public-safe QA: {details}")


def _collect_market_briefing_message_issues(message: str) -> list[dict[str, object]]:
    issues: list[dict[str, object]] = []
    for index, raw_line in enumerate(message.splitlines(), start=1):
        line = raw_line.strip()
        if not line:
            continue
        if _has_market_briefing_decision_wording(line):
            issues.append(
                {
                    "code": "market_briefing_decision_wording",
                    "line": index,
                    "text": line,
                    "message": "market briefing uses blocked recommendation/score/strategy wording",
                }
            )
        if _has_market_briefing_raw_missing_marker(line):
            issues.append(
                {
                    "code": "market_briefing_raw_missing_marker",
                    "line": index,
                    "text": line,
                    "message": "market briefing exposes raw missing-value marker",
                }
            )
    return issues


def _has_market_briefing_decision_wording(line: str) -> bool:
    normalized = re.sub(r"\s+", " ", line.strip()).lower()
    blocked_phrases = (
        "매수 추천",
        "매도 추천",
        "매수추천",
        "매도추천",
        "추천 종목",
        "추천 후보",
        "추천주",
        "매수 후보",
        "매도 후보",
        "매수 기회",
        "매도 기회",
        "전략 제안",
        "진입가",
        "청산가",
        "익절가",
        "손절가",
        "목표 수익률",
        "확신도",
        "buy signal",
        "sell signal",
        "trading call",
        "order routing",
    )
    if any(phrase in normalized for phrase in blocked_phrases):
        return True
    decision_patterns = (
        r"매수\s*(신호|타이밍|구간|진입|제안|권고|추천)",
        r"매도\s*(신호|타이밍|구간|진입|제안|권고|추천)",
        r"(신규|추가)\s*매수\b",
        r"(점수|score)\s*[:=]\s*[-+]?\d",
        r"(등급|grade)\s*[:=]\s*[0-9a-z가-힣]",
        r"(투자\s*)?등급\s*(상향|하향|a|b|c|1|2|3)",
    )
    return any(re.search(pattern, normalized, flags=re.IGNORECASE) for pattern in decision_patterns)


def _has_market_briefing_raw_missing_marker(line: str) -> bool:
    return re.search(r"(^|[\s|:;/()])(?:N/A|NA|NULL|NONE)(?=$|[\s|:;/()])", line, flags=re.IGNORECASE) is not None


def _send_market_briefing_message(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    message: str,
    source: str,
    channel: str = MARKET_BRIEFING_DELIVERY_CHANNEL,
) -> str:
    if not config.telegram_bot_token or not config.telegram_chat_id:
        raise RuntimeError(
            "Telegram configuration is missing. Set STOCK_MONITOR_TELEGRAM_BOT_TOKEN and "
            "STOCK_MONITOR_TELEGRAM_CHAT_ID."
        )
    message_id = send_telegram_message(
        config.telegram_bot_token,
        config.telegram_chat_id,
        message,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    repository.record_delivery(
        DeliveryLog(
            business_date=business_date,
            channel=channel,
            status="sent",
            delivered_at=datetime.now(ZoneInfo(config.timezone)),
            message_id=str(message_id),
            detail=f"source={source}; market briefing",
        )
    )
    repository.record_operation_event(
        _operation_event(
            config,
            component="market-briefing",
            event_type="telegram-send",
            status="sent",
            business_date=business_date,
            detail=f"message_id={message_id}; source={source}",
        )
    )
    return str(message_id)


def _run_scheduled_market_briefing_slot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    slot: str,
    dry_run: bool,
    allow_repeat: bool,
    allow_late: bool,
    limit: int,
) -> int:
    repository.initialize()
    if slot not in MARKET_BRIEFING_SLOT_LABELS:
        raise ValueError(f"Unknown market briefing slot: {slot}")
    now = datetime.now(ZoneInfo(config.timezone))
    today = now.date()
    component = f"market-briefing-{slot}"
    delivery_channel = _market_briefing_slot_delivery_channel(slot)
    skip_reason = _scheduled_skip_reason(config, today, repository) or _operation_profile_skip_reason(
        config,
        repository,
        component="market-briefing",
    )
    if skip_reason:
        if not dry_run:
            repository.record_operation_event(
                _operation_event(
                    config,
                    component=component,
                    event_type="run-guard",
                    status="skipped",
                    business_date=today,
                    detail=skip_reason,
                )
            )
        print(f"Skipping market briefing {slot}: {skip_reason}")
        return 0
    if not dry_run and not _effective_bool_setting(config, repository, MARKET_BRIEFING_PHONE_REVIEW_SETTING):
        detail = (
            "market_briefing_phone_review_accepted is false; run manual review sends and set the "
            "operator setting only after phone readability is accepted."
        )
        repository.record_operation_event(
            _operation_event(
                config,
                component=component,
                event_type="run-guard",
                status="skipped",
                business_date=today,
                detail=detail,
            )
        )
        print(f"Skipping market briefing {slot}: {detail}")
        return 0
    news_collection: dict[str, object] = {"target_stock_codes": []}
    if not dry_run:
        manual_review_dates = _market_briefing_manual_review_dates(repository)
        if len(manual_review_dates) < MARKET_BRIEFING_MIN_MANUAL_REVIEW_SENDS:
            detail = (
                f"market briefing requires {MARKET_BRIEFING_MIN_MANUAL_REVIEW_SENDS} recorded manual "
                f"Telegram review sends before scheduled live send; found {len(manual_review_dates)}."
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component=component,
                    event_type="run-guard",
                    status="skipped",
                    business_date=today,
                    detail=detail,
                )
            )
            print(f"Skipping market briefing {slot}: {detail}")
            return 0
    window_start, window_end = _market_briefing_slot_window(slot)
    current_time = now.timetz().replace(tzinfo=None)
    if current_time < window_start:
        detail = (
            f"{now.strftime('%H:%M')} is before the configured market briefing {slot} window "
            f"{window_start.strftime('%H:%M')}~{window_end.strftime('%H:%M')}."
        )
        if not dry_run:
            repository.record_operation_event(
                _operation_event(
                    config,
                    component=component,
                    event_type="time-window",
                    status="skipped",
                    business_date=today,
                    detail=detail,
                )
            )
        print(f"Skipping market briefing {slot}: {detail}")
        return 0
    if not allow_late and current_time > window_end:
        detail = (
            f"{now.strftime('%H:%M')} is after the configured market briefing {slot} window "
            f"{window_start.strftime('%H:%M')}~{window_end.strftime('%H:%M')}."
        )
        if not dry_run:
            repository.record_operation_event(
                _operation_event(
                    config,
                    component=component,
                    event_type="late-run",
                    status="skipped",
                    business_date=today,
                    detail=detail,
                )
            )
        print(f"Skipping market briefing {slot}: {detail}")
        return 0

    already_sent = repository.has_successful_delivery(today, delivery_channel)
    if not allow_repeat and already_sent:
        print(f"Market briefing {slot} already sent for {today.isoformat()}; skipping.")
        return 0

    send_channel = delivery_channel
    send_source = f"scheduled:{slot}"
    if allow_repeat and already_sent:
        send_channel = f"{delivery_channel}:repeat:{now.strftime('%Y%m%d%H%M%S')}"
        send_source = f"scheduled:{slot}:repeat"

    if not dry_run:
        news_collection = _collect_scheduled_market_briefing_news_observations(
            config,
            repository,
            business_date=today,
            limit=min(max(limit, 1), 2),
        )
        collection_status = "completed" if news_collection.get("ok") else "failed"
        collection_detail = (
            f"saved_observation_count={int(news_collection.get('saved_observation_count') or 0)}; "
            f"saved_evidence_count={int(news_collection.get('saved_evidence_count') or 0)}"
        )
        if news_collection.get("error"):
            collection_detail += f"; error={str(news_collection['error'])}"
        repository.record_operation_event(
            _operation_event(
                config,
                component=component,
                event_type="news-observation-collect",
                status=collection_status,
                business_date=today,
                detail=collection_detail,
            )
        )

    candidate_stock_codes = tuple(
        str(code).strip()
        for code in news_collection.get("target_stock_codes") or []
        if re.fullmatch(r"\d{6}", str(code).strip())
    )
    message = _build_market_briefing_message(
        config,
        repository,
        business_date=today,
        limit=limit,
        slot=slot,
        include_live_candidate_quotes=True,
        candidate_stock_codes=candidate_stock_codes or None,
    )
    if dry_run:
        print(message)
        return 0
    message_id = _send_market_briefing_message(
        config,
        repository,
        business_date=today,
        message=message,
        source=send_source,
        channel=send_channel,
    )
    print(f"Market briefing {slot} sent with message_id={message_id}")
    return 0


def _run_send_test_notification(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    explicit_date: date | None,
    custom_message: str | None,
    dry_run: bool,
    allow_repeat: bool,
    limit: int | None,
    min_mentions: int | None = None,
    include_no_target_price: bool = False,
    delivery_channel: str = TEST_DELIVERY_CHANNEL,
    notification_format: str = "summary",
) -> int:
    business_date = explicit_date or previous_business_day(
        datetime.now(ZoneInfo(config.timezone)).date(),
        config.holiday_overrides,
    )
    already_sent = repository.has_successful_delivery(business_date, delivery_channel)
    summaries = repository.list_daily_summaries(business_date)
    if not summaries:
        summaries = repository.rebuild_daily_summaries(business_date)
    effective_min_mentions = (
        min_mentions
        if min_mentions is not None
        else _effective_int_setting(config, repository, "daily_summary_min_mention_count")
    )
    require_target_price = (
        _effective_bool_setting(config, repository, "daily_summary_require_target_price")
        and not include_no_target_price
    )
    summaries = _filter_daily_summaries(
        summaries,
        min_mentions=effective_min_mentions,
        require_target_price=require_target_price,
    )
    effective_limit = limit
    quotes_by_stock_code = _fetch_daily_summary_quotes_by_stock_code(config, summaries, repository=repository)
    if custom_message:
        messages = [custom_message]
    elif notification_format == "briefing":
        market_reference_lines = _build_daily_briefing_market_reference_lines(repository, business_date)
        flow_reference_lines = _build_daily_briefing_flow_reference_lines(repository, business_date)
        core_point_lines = _build_daily_briefing_core_point_lines(
            repository,
            business_date,
            summaries,
            quotes_by_stock_code,
        )
        messages = format_daily_briefing_messages(
            business_date,
            summaries,
            briefing_date=next_business_day(business_date, config.holiday_overrides),
            quotes_by_stock_code=quotes_by_stock_code,
            market_reference_lines=market_reference_lines,
            flow_reference_lines=flow_reference_lines,
            core_point_lines=core_point_lines,
            max_items=effective_limit or 5,
        )
    elif effective_limit is None:
        messages = format_daily_summary_messages(
            business_date,
            summaries,
            quotes_by_stock_code=quotes_by_stock_code,
        )
    else:
        messages = [
            format_daily_summary_message(
                business_date,
                summaries,
                offset=0,
                limit=effective_limit,
                quotes_by_stock_code=quotes_by_stock_code,
            )
        ]

    if dry_run:
        print("\n\n--- message split ---\n\n".join(messages))
        return 0

    if not allow_repeat and already_sent:
        print(f"Telegram notification already sent for {business_date.isoformat()}; skipping.")
        return 0

    if not config.telegram_bot_token or not config.telegram_chat_id:
        raise RuntimeError(
            "Telegram configuration is missing. Set STOCK_MONITOR_TELEGRAM_BOT_TOKEN and "
            "STOCK_MONITOR_TELEGRAM_CHAT_ID."
        )

    if delivery_channel == PRODUCTION_DELIVERY_CHANNEL and custom_message is None:
        message_ids = _send_production_daily_summary_fragments(
            config,
            repository,
            business_date=business_date,
            messages=messages,
            effective_min_mentions=effective_min_mentions,
            require_target_price=require_target_price,
        )
    else:
        try:
            message_ids = []
            for message in messages:
                message_ids.append(
                    send_telegram_message(
                        config.telegram_bot_token,
                        config.telegram_chat_id,
                        message,
                        parse_mode=None,
                        timeout_seconds=config.telegram_timeout_seconds,
                        max_retries=config.telegram_max_retries,
                        retry_delay_seconds=config.telegram_retry_delay_seconds,
                    )
                )
        except Exception as exc:
            repository.record_delivery(
                DeliveryLog(
                    business_date=business_date,
                    channel=delivery_channel,
                    status="failed",
                    delivered_at=datetime.now(ZoneInfo(config.timezone)),
                    detail=f"source=manual_test; {exc}",
                )
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="notify",
                    event_type="send",
                    status="failed",
                    business_date=business_date,
                    detail=f"source=manual_test; {exc}",
                )
            )
            raise

    repository.record_delivery(
        DeliveryLog(
            business_date=business_date,
            channel=delivery_channel,
            status="sent_repeat" if allow_repeat and already_sent else "sent",
            delivered_at=datetime.now(ZoneInfo(config.timezone)),
            message_id=",".join(str(message_id) for message_id in message_ids),
            detail=(
                "source=scheduled; scheduled notification"
                if delivery_channel == PRODUCTION_DELIVERY_CHANNEL
                else (
                    "source=manual_test; manual test notification (repeat)"
                    if allow_repeat and already_sent
                    else "source=manual_test; manual test notification"
                )
            ),
        )
    )
    if custom_message is None and delivery_channel == PRODUCTION_DELIVERY_CHANNEL:
        state = load_control_state(config.telegram_control_state_path)
        delivered_count = len(summaries) if effective_limit is None else min(len(summaries), effective_limit)
        state.set_delivered_for(business_date, delivered_count)
        save_control_state(config.telegram_control_state_path, state)
    repository.record_operation_event(
        _operation_event(
            config,
            component="notify",
            event_type="send",
            status="sent",
            business_date=business_date,
            detail=(
                f"source={'scheduled' if delivery_channel == PRODUCTION_DELIVERY_CHANNEL else 'manual_test'}; "
                f"{delivery_channel}; messages={len(messages)}; summaries={len(summaries)}; "
                f"min_mentions={effective_min_mentions}; require_target_price={require_target_price}"
            ),
        )
    )
    print(f"Telegram message sent with message_id={','.join(str(message_id) for message_id in message_ids)}")
    return 0


def _send_production_daily_summary_fragments(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    messages: list[str],
    effective_min_mentions: int,
    require_target_price: bool,
) -> list[str]:
    started_at = datetime.now(ZoneInfo(config.timezone))
    summary_signature = _daily_summary_delivery_signature(
        business_date,
        channel=PRODUCTION_DELIVERY_CHANNEL,
        effective_min_mentions=effective_min_mentions,
        require_target_price=require_target_price,
        messages=messages,
    )
    run = repository.start_or_resume_daily_summary_run(
        business_date=business_date,
        channel=PRODUCTION_DELIVERY_CHANNEL,
        summary_signature=summary_signature,
        messages=messages,
        started_at=started_at,
    )
    pending_fragments = repository.list_pending_daily_summary_fragments(run.run_id)
    for fragment in pending_fragments:
        try:
            message_id = send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                fragment.message_text,
                parse_mode=None,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
        except Exception as exc:
            failed_at = datetime.now(ZoneInfo(config.timezone))
            message_hash = _hash_text(fragment.message_text)[:16]
            ambiguous_send = _is_ambiguous_telegram_send_error(exc)
            detail = (
                f"source=scheduled; run_id={run.run_id}; "
                f"fragment={fragment.fragment_index + 1}/{run.total_fragments}; "
                f"message_hash={message_hash}; ambiguous_send={str(ambiguous_send).lower()}; {exc}"
            )
            repository.mark_daily_summary_fragment_failed(
                run.run_id,
                fragment.fragment_index,
                error_detail=str(exc),
                failed_at=failed_at,
            )
            repository.record_delivery(
                DeliveryLog(
                    business_date=business_date,
                    channel=PRODUCTION_DELIVERY_CHANNEL,
                    status="failed",
                    delivered_at=failed_at,
                    detail=detail,
                )
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="notify",
                    event_type="fragment",
                    status="failed",
                    business_date=business_date,
                    detail=detail,
                )
            )
            raise

        sent_at = datetime.now(ZoneInfo(config.timezone))
        repository.mark_daily_summary_fragment_sent(
            run.run_id,
            fragment.fragment_index,
            message_id=str(message_id),
            sent_at=sent_at,
        )
        repository.record_operation_event(
            _operation_event(
                config,
                component="notify",
                event_type="fragment",
                status="sent",
                business_date=business_date,
                detail=(
                    f"source=scheduled; run_id={run.run_id}; "
                    f"fragment={fragment.fragment_index + 1}/{run.total_fragments}"
                ),
            )
        )

    finished_at = datetime.now(ZoneInfo(config.timezone))
    repository.complete_daily_summary_run(run.run_id, finished_at=finished_at)
    fragments = repository.list_daily_summary_fragments(run.run_id)
    return [str(fragment.message_id) for fragment in fragments if fragment.message_id]


def _is_ambiguous_telegram_send_error(exc: Exception) -> bool:
    if isinstance(exc, TimeoutError):
        return True
    text = str(exc).lower()
    ambiguous_markers = (
        "timed out",
        "timeout",
        "winerror 10060",
        "urlopen error",
        "connection aborted",
        "connection reset",
        "remote end closed",
    )
    return any(marker in text for marker in ambiguous_markers)


def _daily_summary_delivery_signature(
    business_date: date,
    *,
    channel: str,
    effective_min_mentions: int,
    require_target_price: bool,
    messages: list[str],
) -> str:
    payload = {
        "business_date": business_date.isoformat(),
        "channel": channel,
        "effective_min_mentions": effective_min_mentions,
        "require_target_price": require_target_price,
        "message_hashes": [_hash_text(message) for message in messages],
    }
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return _hash_text(encoded)


def _hash_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _run_scheduled_notify(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    dry_run: bool,
    allow_repeat: bool,
    allow_late: bool = False,
    min_mentions: int | None = None,
    include_no_target_price: bool = False,
    notification_format: str = "summary",
) -> int:
    repository.initialize()
    now = datetime.now(ZoneInfo(config.timezone))
    today = now.date()
    skip_reason = _scheduled_skip_reason(config, today, repository) or _operation_profile_skip_reason(
        config,
        repository,
        component="notify",
    )
    if skip_reason:
        repository.record_operation_event(
            _operation_event(
                config,
                component="notify",
                event_type="run-guard",
                status="skipped",
                business_date=today,
                detail=skip_reason,
            )
        )
        print(f"Skipping notification: {skip_reason}")
        return 0
    current_time = now.timetz().replace(tzinfo=None)
    if current_time < SCHEDULED_NOTIFY_EARLIEST_TIME:
        detail = (
            f"{now.strftime('%H:%M')} is before the scheduled-notify window "
            f"{SCHEDULED_NOTIFY_EARLIEST_TIME.strftime('%H:%M')}~{SCHEDULED_NOTIFY_LATEST_TIME.strftime('%H:%M')}."
        )
        repository.record_operation_event(
            _operation_event(
                config,
                component="notify",
                event_type="early_notify",
                status="skipped",
                business_date=today,
                detail=detail,
            )
        )
        print(f"Skipping notification: {detail}")
        return 0
    if not allow_late and current_time > SCHEDULED_NOTIFY_LATEST_TIME:
        detail = (
            f"{now.strftime('%H:%M')} is after the scheduled-notify late window "
            f"{SCHEDULED_NOTIFY_EARLIEST_TIME.strftime('%H:%M')}~{SCHEDULED_NOTIFY_LATEST_TIME.strftime('%H:%M')}."
        )
        repository.record_operation_event(
            _operation_event(
                config,
                component="notify",
                event_type="late_notify",
                status="skipped",
                business_date=today,
                detail=detail,
            )
        )
        print(f"Skipping notification: {detail}")
        return 0

    return _run_send_test_notification(
        config,
        repository,
        explicit_date=None,
        custom_message=None,
        dry_run=dry_run,
        allow_repeat=allow_repeat,
        limit=None,
        min_mentions=min_mentions,
        include_no_target_price=include_no_target_price,
        delivery_channel=PRODUCTION_DELIVERY_CHANNEL,
        notification_format=notification_format,
    )


def _run_operator_status(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    as_json: bool,
    limit: int,
    health_exit: bool = False,
) -> int:
    status = build_operator_status_snapshot(config, repository, limit=limit)

    if as_json:
        print(json.dumps(status, ensure_ascii=False, indent=2))
        return _operator_health_exit_code(status) if health_exit else 0

    print("운영 상태")
    print(f"- 건강 상태: {status['health']['level']} | {status['health']['summary']}")
    if status["health"]["failing_checks"]:
        print(f"- 실패 항목: {', '.join(status['health']['failing_checks'])}")
    if status["health"]["warning_checks"]:
        print(f"- 확인 항목: {', '.join(status['health']['warning_checks'])}")
    print(f"- 현재 시각: {_format_iso_datetime_short(status['now'])}")
    print(f"- 영업일 여부: {'Y' if status['is_business_day'] else 'N'}")
    print(f"- 운영 일시정지: {'Y' if status['is_operator_paused'] else 'N'}")
    print(f"- 실행 제외 여부: {'Y' if status['is_run_suppressed'] else 'N'}")
    if status["run_skip_reason"]:
        print(f"- 실행 제외 사유: {status['run_skip_reason']}")
    holiday_coverage = status["market_holiday_coverage"]
    print(
        f"- market holiday coverage: default through {holiday_coverage['default_max_date'] or 'N/A'} | "
        f"configured through {holiday_coverage['configured_max_date'] or 'N/A'}"
    )
    if holiday_coverage["renewal_required"]:
        print(f"- market holiday warning: {holiday_coverage['message']}")
    print(f"- DB: {status['db_path']}")
    print(f"- DB 갱신: {_format_iso_datetime_short(status['db_last_write']) if status['db_last_write'] else 'N/A'}")
    backup_status = status["backup"]
    print(f"- DB 백업: {'Y' if backup_status['exists'] else 'N'} | {backup_status['detail']}")
    for reminder in status["data_safety_reminders"]:
        print(f"- 데이터 안전 안내: {reminder}")
    print("복구 안내")
    for action in status["recovery_actions"]:
        print(
            f"- {action['severity']} | {action['title']} | "
            f"{action['safe_next_step']} | {action['detail']}"
        )
    print(
        f"- 전일 요약 최소 언급수: {status['daily_summary_min_mention_count']} "
        f"({status['safe_settings']['daily_summary_min_mention_count']['source']})"
    )
    print(
        f"- 전일 요약 목표가 필수: {'Y' if status['daily_summary_require_target_price'] else 'N'} "
        f"({status['safe_settings']['daily_summary_require_target_price']['source']})"
    )
    print(
        f"- 기본 알림 표시 수: {status['notification_default_limit']} "
        f"({status['safe_settings']['notification_default_limit']['source']})"
    )
    print(f"- 운영 프로필: {status['operation_profile']} ({status['safe_settings']['operation_profile']['source']})")
    print(f"- 종목 메타데이터: {status['stock_metadata_count']}")
    print(f"- 테마 매핑: {status['theme_membership_count']}")
    category_coverage = status["category_snapshot_coverage"]
    print(
        f"- 카테고리 스냅샷: fallback {category_coverage['fallback_date_count']} / "
        f"summary {category_coverage['summary_date_count']}"
    )
    for warning in status["category_snapshot_refreshability"]["warnings"]:
        print(f"- 카테고리 경고: {warning['code']} | {warning['message']}")
    print(f"- pending 장중 batch: {status['pending_intraday_batches']}")
    print("")
    print("실운영 관찰")
    print(f"- 스케줄러 메타데이터: {status['live_observation']['scheduler_metadata_status']}")
    if status["live_observation"]["scheduler_metadata_status"] in {"access_denied", "partial_access_denied"}:
        print("- 해석: strict health: 스케줄러 메타데이터 검증 불가. 당일 실행 흔적은 보조 증거입니다.")
    if status["live_observation"].get("operator_action"):
        print(f"- 조치: {status['live_observation']['operator_action']}")
    timeout_trace = status["live_observation"].get("telegram_timeout_trace") or {}
    timeout_count = int(timeout_trace.get("ambiguous_failure_count") or 0)
    if timeout_count:
        latest_timeout = timeout_trace.get("latest") or {}
        print(
            f"- Telegram timeout trace: {timeout_count} ambiguous fragment failure(s) | "
            f"run_id={latest_timeout.get('run_id') or '-'} | "
            f"fragment={latest_timeout.get('fragment') or '-'} | "
            f"message_hash={latest_timeout.get('message_hash') or '-'}"
        )
    for key, item in status["live_observation"]["components"].items():
        last_event = item.get("last_event")
        event_label = (
            f"{last_event['event_time']} | {last_event['component']} | {last_event['event_type']} | {last_event['status']}"
            if last_event
            else "no event"
        )
        evidence_label = item["evidence_status"]
        if item.get("attention_reason"):
            evidence_label = f"{evidence_label}({item['attention_reason']})"
        print(f"- {key}: {evidence_label} | {event_label}")
    print("")
    print("스케줄러 작업")
    for task in status["scheduler_tasks"]:
        if not task["available"]:
            print(f"- {task['task_name']}: 확인 불가 | {task['detail']}")
            continue
        if not task["exists"]:
            print(f"- {task['task_name']}: 미등록")
            continue
        print(
            f"- {task['task_name']}: {task['state']} | "
            f"{task.get('status_class', 'unknown')} | "
            f"다음 {task['next_run_time'] or 'N/A'} | "
            f"마지막 {task['last_run_time'] or 'N/A'} | "
            f"결과 {task['last_task_result']}"
        )
    print("")
    print("최근 리포트/요약")
    for item in status["reports_by_date"]:
        matching_summary = next(
            (summary for summary in status["summaries_by_date"] if summary["business_date"] == item["business_date"]),
            None,
        )
        summary_count = matching_summary["count"] if matching_summary else 0
        print(f"- {item['business_date']}: reports {item['count']} / summaries {summary_count}")
    print("")
    print("최근 발송")
    for delivery in status["recent_deliveries"]:
        print(
            f"- {delivery['delivered_at']} | {delivery['business_date']} | "
            f"{delivery['channel']} | {delivery['status']} | {delivery['detail'] or ''}"
        )
    print("")
    print("최근 운영 이벤트")
    for event in status["recent_events"]:
        print(
            f"- {event['event_time']} | {event['component']} | "
            f"{event['event_type']} | {event.get('status_display') or event['status']} | "
            f"{event.get('detail_display') or event['detail'] or ''}"
        )
    return _operator_health_exit_code(status) if health_exit else 0


def _run_admin_gui(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    host: str,
    port: int,
    limit: int,
    open_browser: bool,
    allow_non_loopback: bool,
) -> int:
    server = create_admin_gui_server(
        config,
        repository,
        host=host,
        port=port,
        limit=limit,
        allow_non_loopback=allow_non_loopback,
    )
    url = f"http://{host}:{server.server_port}/"
    print(f"Stock Monitor admin GUI: {url}")
    print("Press Ctrl+C to stop.")
    if open_browser:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("")
        print("Stopping admin GUI.")
    finally:
        server.server_close()
    return 0


