def _run_external_web_view_smoke(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    base_url: str,
    business_date: date | None,
    allow_http: bool,
    record_success: bool,
    as_json: bool,
) -> int:
    resolved_date = business_date or _resolve_web_view_browser_smoke_date(repository)
    payload = _probe_external_web_view_smoke(
        base_url=base_url,
        business_date=resolved_date,
        allow_http=allow_http,
    )
    payload["record_success_requested"] = record_success
    payload["recorded_success"] = False
    if record_success and not payload["issue_count"]:
        record_issue = _external_web_view_record_success_issue(str(payload["base_url"]))
        if record_issue:
            payload["issues"].append(record_issue)
            payload["issue_count"] = len(payload["issues"])
    if record_success and not payload["issue_count"]:
        recorded_at = datetime.now(ZoneInfo(config.timezone))
        detail = (
            f"url_origin={_external_web_view_url_origin(str(payload['base_url']))}; "
            f"business_date={resolved_date.isoformat()}; "
            f"http_checks={len(payload['http_checks'])}; "
            f"public_json_routes={len(payload['public_json_routes_checked'])}"
        )
        repository.record_operation_event(
            OperationEvent(
                event_time=recorded_at,
                component="external-web-view",
                event_type="provider-smoke",
                status="success",
                business_date=resolved_date,
                detail=detail,
            )
        )
        payload["read_only"] = False
        payload["writes_database"] = True
        payload["recorded_success"] = True
        payload["recorded_event"] = {
            "event_time": recorded_at.isoformat(),
            "component": "external-web-view",
            "event_type": "provider-smoke",
            "status": "success",
            "business_date": resolved_date.isoformat(),
            "detail": detail,
        }
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 1 if payload["issue_count"] else 0

    print("External web-view smoke")
    print(f"- read-only: {payload['read_only']}")
    print(f"- base_url: {payload['base_url']}")
    print(f"- business_date: {payload['business_date']}")
    print(f"- checks: {len(payload['http_checks'])}")
    print(f"- issues: {payload['issue_count']}")
    print(f"- recorded_success: {str(payload['recorded_success']).lower()}")
    for check in payload["http_checks"]:
        print(f"- http | {check['path']} | {check['method']} | {check['status']}")
    for issue in payload["issues"]:
        print(f"- issue | {issue['code']} | {issue['path']} | {issue['message']}")
    return 1 if payload["issue_count"] else 0


def _external_web_view_url_origin(base_url: str) -> str:
    parsed = url_parse.urlparse(base_url)
    if not parsed.scheme or not parsed.netloc:
        return "-"
    return f"{parsed.scheme}://{parsed.netloc}"


def _external_web_view_record_success_issue(base_url: str) -> dict[str, str] | None:
    parsed = url_parse.urlparse(base_url)
    hostname = (parsed.hostname or "").lower()
    if parsed.scheme != "https":
        return {
            "code": "record_success_requires_https_provider_url",
            "path": "base_url",
            "message": "--record-success requires the final external HTTPS provider URL.",
        }
    if hostname in {"127.0.0.1", "localhost", "::1"}:
        return {
            "code": "record_success_requires_external_provider_url",
            "path": "base_url",
            "message": "--record-success cannot be used with localhost or loopback smoke targets.",
        }
    if parsed.path not in {"", "/"} or parsed.query or parsed.fragment:
        return {
            "code": "record_success_requires_provider_origin",
            "path": "base_url",
            "message": "--record-success requires the provider origin only, without path, query, or fragment.",
        }
    return None


def _probe_external_web_view_smoke(
    *,
    base_url: str,
    business_date: date,
    allow_http: bool,
) -> dict[str, object]:
    normalized_base_url = base_url.rstrip("/")
    parsed = url_parse.urlparse(normalized_base_url)
    issues: list[dict[str, object]] = []
    http_checks: list[dict[str, object]] = []
    public_json_routes_checked: list[str] = []
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        issues.append(
            {
                "code": "invalid_url",
                "path": "base_url",
                "message": "URL must include http(s) scheme and host.",
            }
        )
    elif parsed.scheme != "https" and not allow_http and parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:
        issues.append(
            {
                "code": "external_url_not_https",
                "path": "base_url",
                "message": "External sharing should use HTTPS unless --allow-http is set for a private/local check.",
            }
        )

    if issues:
        return {
            "surface": "external-web-view-smoke",
            "read_only": True,
            "live_fetch": True,
            "writes_database": False,
            "sends_telegram": False,
            "registers_scheduler": False,
            "base_url": normalized_base_url,
            "business_date": business_date.isoformat(),
            "issue_count": len(issues),
            "issues": issues,
            "http_checks": http_checks,
            "public_json_routes_checked": public_json_routes_checked,
            "note": "No access-code value is accepted or printed; authenticated content review remains manual.",
        }

    def request_path(path: str, *, method: str = "GET", data: bytes | None = None) -> tuple[int, bytes, str]:
        status, body, content_type = _web_view_smoke_http_request(f"{normalized_base_url}{path}", method=method, data=data)
        http_checks.append({"path": path, "method": method, "status": status})
        return status, body, content_type

    def check_public_json_route(
        path: str,
        *,
        label: str,
        unexpected_code: str,
        not_json_code: str,
        exposed_keys_code: str,
        allowed_statuses: set[HTTPStatus] | None = None,
    ) -> object | None:
        public_json_routes_checked.append(path)
        allowed = allowed_statuses or {HTTPStatus.OK, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN}
        status, body, content_type = request_path(path)
        if status not in allowed and not _external_web_view_response_is_access_gated(status, body, content_type):
            issues.append(
                {
                    "code": unexpected_code,
                    "path": path,
                    "message": f"GET {label} returned {status}, expected {', '.join(str(item.value) for item in sorted(allowed, key=lambda item: item.value))}.",
                }
            )
            return None
        if status != HTTPStatus.OK or _external_web_view_response_is_access_gated(status, body, content_type):
            return None
        if "application/json" not in content_type:
            issues.append(
                {
                    "code": not_json_code,
                    "path": path,
                    "message": f"GET {label} returned content-type {content_type or '-'}, expected JSON.",
                }
            )
            return None
        forbidden_keys = _external_web_view_forbidden_public_json_keys(body)
        if forbidden_keys:
            issues.append(
                {
                    "code": exposed_keys_code,
                    "path": path,
                    "message": f"GET {label} API exposes operator/admin keys: {', '.join(forbidden_keys)}.",
                }
            )
        return _load_external_web_view_json_body(body)

    health_status, health_body, _health_content_type = request_path("/health")
    if _external_web_view_response_is_access_gated(health_status, health_body, _health_content_type):
        pass
    elif health_status != HTTPStatus.OK or health_body.strip() != b"ok":
        issues.append(
            {
                "code": "health_unavailable",
                "path": "/health",
                "message": f"GET /health returned {health_status}, expected 200 ok or an access gate.",
            }
        )

    root_status, root_body, root_content_type = request_path("/")
    if _external_web_view_response_is_access_gated(root_status, root_body, root_content_type):
        pass
    elif root_status not in {HTTPStatus.OK, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN}:
        issues.append(
            {
                "code": "root_unexpected_status",
                "path": "/",
                "message": f"GET / returned {root_status}, expected 200, 401, or 403.",
            }
        )
    elif root_status == HTTPStatus.OK and "text/html" not in root_content_type:
        issues.append(
            {
                "code": "root_not_html",
                "path": "/",
                "message": f"GET / returned content-type {root_content_type or '-'}, expected HTML.",
            }
        )
    elif root_status == HTTPStatus.OK and _external_web_view_body_looks_like_admin(root_body):
        issues.append(
            {
                "code": "root_looks_like_admin_gui",
                "path": "/",
                "message": "GET / looks like the control-capable admin-gui, not the read-only web-view.",
            }
        )

    public_json_routes_checked.append("/api/archive?limit=1")
    archive_status, archive_body, archive_content_type = request_path("/api/archive?limit=1")
    if _external_web_view_response_is_access_gated(archive_status, archive_body, archive_content_type):
        pass
    elif archive_status not in {HTTPStatus.OK, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN}:
        issues.append(
            {
                "code": "archive_unexpected_status",
                "path": "/api/archive",
                "message": f"GET archive returned {archive_status}, expected 200, 401, or 403.",
            }
        )
    elif archive_status == HTTPStatus.OK and "application/json" not in archive_content_type:
        issues.append(
            {
                "code": "archive_not_json",
                "path": "/api/archive",
                "message": f"GET archive returned content-type {archive_content_type or '-'}, expected JSON.",
            }
        )
    elif archive_status == HTTPStatus.OK:
        forbidden_keys = _external_web_view_forbidden_public_json_keys(archive_body)
        if forbidden_keys:
            issues.append(
                {
                    "code": "archive_json_exposes_operator_keys",
                    "path": "/api/archive",
                    "message": f"GET archive API exposes operator/admin keys: {', '.join(forbidden_keys)}.",
                }
            )

    daily_payload: object | None = None
    daily_path = f"/api/daily/{business_date.isoformat()}"
    public_json_routes_checked.append(daily_path)
    daily_status, daily_body, daily_content_type = request_path(daily_path)
    if _external_web_view_response_is_access_gated(daily_status, daily_body, daily_content_type):
        pass
    elif daily_status not in {HTTPStatus.OK, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN, HTTPStatus.NOT_FOUND}:
        issues.append(
            {
                "code": "daily_unexpected_status",
                "path": daily_path,
                "message": f"GET daily API returned {daily_status}, expected 200, 401, 403, or 404.",
            }
        )
    elif daily_status == HTTPStatus.OK and "application/json" not in daily_content_type:
        issues.append(
            {
                "code": "daily_not_json",
                "path": daily_path,
                "message": f"GET daily API returned content-type {daily_content_type or '-'}, expected JSON.",
            }
        )
    elif daily_status == HTTPStatus.OK:
        daily_payload = _load_external_web_view_json_body(daily_body)
        forbidden_keys = _external_web_view_forbidden_public_json_keys(daily_body)
        if forbidden_keys:
            issues.append(
                {
                    "code": "daily_json_exposes_operator_keys",
                    "path": daily_path,
                    "message": f"GET daily API exposes operator/admin keys: {', '.join(forbidden_keys)}.",
                }
            )

    candidate_path = f"/api/candidate-evidence?date={business_date.isoformat()}&limit=5"
    public_json_routes_checked.append(candidate_path)
    candidate_status, candidate_body, candidate_content_type = request_path(candidate_path)
    if _external_web_view_response_is_access_gated(candidate_status, candidate_body, candidate_content_type):
        pass
    elif candidate_status not in {HTTPStatus.OK, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN}:
        issues.append(
            {
                "code": "candidate_unexpected_status",
                "path": "/api/candidate-evidence",
                "message": f"GET candidate evidence returned {candidate_status}, expected 200, 401, or 403.",
            }
        )
    elif candidate_status == HTTPStatus.OK and "application/json" not in candidate_content_type:
        issues.append(
            {
                "code": "candidate_not_json",
                "path": "/api/candidate-evidence",
                "message": f"GET candidate evidence returned content-type {candidate_content_type or '-'}, expected JSON.",
            }
        )
    elif candidate_status == HTTPStatus.OK:
        forbidden_keys = _external_web_view_forbidden_public_json_keys(candidate_body)
        if forbidden_keys:
            issues.append(
                {
                    "code": "candidate_json_exposes_operator_keys",
                    "path": "/api/candidate-evidence",
                    "message": f"GET candidate evidence API exposes operator/admin keys: {', '.join(forbidden_keys)}.",
                }
            )

    first_stock_code = _external_web_view_first_stock_code(daily_payload)
    if first_stock_code:
        stock_path = f"/api/daily/{business_date.isoformat()}/stocks/{url_parse.quote(first_stock_code)}"
        public_json_routes_checked.append(stock_path)
        stock_status, stock_body, stock_content_type = request_path(stock_path)
        if _external_web_view_response_is_access_gated(stock_status, stock_body, stock_content_type):
            pass
        elif stock_status not in {HTTPStatus.OK, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN, HTTPStatus.NOT_FOUND}:
            issues.append(
                {
                    "code": "stock_detail_unexpected_status",
                    "path": "/api/daily/{date}/stocks/{stock_code}",
                    "message": f"GET stock detail returned {stock_status}, expected 200, 401, 403, or 404.",
                }
            )
        elif stock_status == HTTPStatus.OK and "application/json" not in stock_content_type:
            issues.append(
                {
                    "code": "stock_detail_not_json",
                    "path": "/api/daily/{date}/stocks/{stock_code}",
                    "message": f"GET stock detail returned content-type {stock_content_type or '-'}, expected JSON.",
                }
            )
        elif stock_status == HTTPStatus.OK:
            forbidden_keys = _external_web_view_forbidden_public_json_keys(stock_body)
            if forbidden_keys:
                issues.append(
                    {
                        "code": "stock_detail_json_exposes_operator_keys",
                        "path": "/api/daily/{date}/stocks/{stock_code}",
                        "message": f"GET stock detail API exposes operator/admin keys: {', '.join(forbidden_keys)}.",
                    }
                )

    check_public_json_route(
        f"/api/flow-trend?date={business_date.isoformat()}&limit=5",
        label="flow trend",
        unexpected_code="flow_trend_unexpected_status",
        not_json_code="flow_trend_not_json",
        exposed_keys_code="flow_trend_json_exposes_operator_keys",
    )
    check_public_json_route(
        f"/api/etf-trend?date={business_date.isoformat()}&limit=5",
        label="ETF trend",
        unexpected_code="etf_trend_unexpected_status",
        not_json_code="etf_trend_not_json",
        exposed_keys_code="etf_trend_json_exposes_operator_keys",
    )
    category_targets = _web_view_value_qa_category_targets(daily_payload, limit=1) if isinstance(daily_payload, dict) else []
    if category_targets:
        target = category_targets[0]
        category_path = (
            "/api/category-trend?"
            f"type={url_parse.quote(str(target['category_type']))}"
            f"&display_name={url_parse.quote(str(target['display_name']))}"
        )
        check_public_json_route(
            category_path,
            label="category trend",
            unexpected_code="category_trend_unexpected_status",
            not_json_code="category_trend_not_json",
            exposed_keys_code="category_trend_json_exposes_operator_keys",
        )

    post_status, _post_body, _post_content_type = request_path(daily_path, method="POST", data=b"{}")
    if post_status not in {HTTPStatus.METHOD_NOT_ALLOWED, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN} and not _external_web_view_response_is_access_gated(
        post_status, _post_body, _post_content_type
    ):
        issues.append(
            {
                "code": "write_method_not_blocked",
                "path": daily_path,
                "message": f"POST daily API returned {post_status}, expected 405 or access gate denial.",
            }
        )

    admin_status, _admin_body, _admin_content_type = request_path("/api/status")
    if admin_status not in {HTTPStatus.NOT_FOUND, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN} and not _external_web_view_response_is_access_gated(
        admin_status, _admin_body, _admin_content_type
    ):
        issues.append(
            {
                "code": "admin_status_exposed",
                "path": "/api/status",
                "message": f"GET /api/status returned {admin_status}, expected 404 or access gate denial.",
            }
        )

    forbidden_control_posts = [
        ("/api/scheduler/run-now", b'{"task":"poll"}'),
        ("/api/scheduler/set-enabled", b'{"task":"poll","enabled":false}'),
        ("/api/operator/pause", b'{"reason":"external smoke"}'),
        ("/api/settings/set", b'{"key":"operation_profile","value":"manual-only"}'),
    ]
    for path, body in forbidden_control_posts:
        status, _body, _content_type = request_path(path, method="POST", data=body)
        if status not in {HTTPStatus.NOT_FOUND, HTTPStatus.METHOD_NOT_ALLOWED, HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN} and not _external_web_view_response_is_access_gated(
            status, _body, _content_type
        ):
            issues.append(
                {
                    "code": "admin_control_route_exposed",
                    "path": path,
                    "message": (
                        f"POST {path} returned {status}, expected 404, 405, or access gate denial. "
                        "The tunnel may be pointed at admin-gui instead of web-view."
                    ),
                }
            )

    return {
        "surface": "external-web-view-smoke",
        "read_only": True,
        "live_fetch": True,
        "writes_database": False,
        "sends_telegram": False,
        "registers_scheduler": False,
        "base_url": normalized_base_url,
        "business_date": business_date.isoformat(),
        "issue_count": len(issues),
        "issues": issues,
        "http_checks": http_checks,
        "public_json_routes_checked": public_json_routes_checked,
        "note": "No access-code value is accepted or printed; authenticated content review remains manual.",
    }


def _external_web_view_response_is_access_gated(status: int, body: bytes, content_type: str) -> bool:
    if status in {HTTPStatus.UNAUTHORIZED, HTTPStatus.FORBIDDEN}:
        return True
    if status != HTTPStatus.OK or "text/html" not in content_type:
        return False
    if _external_web_view_body_looks_like_admin(body):
        return False
    return _external_web_view_body_looks_like_access_gate(body)


def _external_web_view_body_looks_like_access_gate(body: bytes) -> bool:
    try:
        text = body.decode("utf-8", errors="ignore").lower()
    except Exception:
        return False
    access_gate_markers = (
        "cloudflare access",
        "/cdn-cgi/access/",
        "cf-access",
        "access login",
    )
    return any(marker in text for marker in access_gate_markers)


def _external_web_view_body_looks_like_admin(body: bytes) -> bool:
    try:
        text = body.decode("utf-8", errors="ignore")
    except Exception:
        return False
    admin_markers = (
        "Stock Monitor Admin",
        "/api/scheduler/run-now",
        "/api/scheduler/set-enabled",
        "/api/operator/pause",
        "/api/settings/set",
        "스케줄러 작업",
    )
    return any(marker in text for marker in admin_markers)


def _load_external_web_view_json_body(body: bytes) -> object | None:
    try:
        return json.loads(body.decode("utf-8"))
    except Exception:
        return None


def _external_web_view_first_stock_code(payload: object | None) -> str | None:
    if not isinstance(payload, dict):
        return None
    stocks = payload.get("stocks")
    if not isinstance(stocks, list):
        return None
    first_stock = next((item for item in stocks if isinstance(item, dict) and item.get("stock_code")), None)
    if not first_stock:
        return None
    stock_code = str(first_stock["stock_code"]).strip()
    return stock_code or None


def _external_web_view_forbidden_public_json_keys(body: bytes) -> list[str]:
    from stock_monitor.web_view_runtime import forbidden_public_json_keys

    return forbidden_public_json_keys(body)


def _run_rotation_mapping_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date | None,
    limit: int,
    as_json: bool,
) -> int:
    if limit < 1:
        raise ValueError("--limit must be at least 1.")
    resolved_date = business_date or _resolve_rotation_mapping_audit_date(repository)
    payload = _build_rotation_mapping_audit(
        config,
        repository,
        business_date=resolved_date,
        limit=limit,
    )
    if as_json:
        print(json.dumps(payload, ensure_ascii=False, indent=2))
        return 1 if payload["issue_count"] else 0

    print("Rotation mapping audit")
    print(f"- read-only: {payload['read_only']}")
    print(f"- business date: {payload['business_date']}")
    print(f"- image: {payload['image']['path']} ({payload['image']['width']}x{payload['image']['height']})")
    print(f"- coordinates: {payload['coordinate_count']}")
    print(f"- active aliases: {payload['active_alias_count']}")
    print(f"- active ETF mappings: {payload['active_etf_mapping_count']}")
    print(f"- latest KRX ETF snapshot: {payload['latest_krx_snapshot_date'] or '-'}")
    print(f"- issues: {payload['issue_count']}")
    print(f"- warnings: {payload['warning_count']}")
    for row in payload["coordinates"]:
        categories = ", ".join(row["category_keys"]) if row["category_keys"] else "-"
        print(
            f"- {row['label']} | coordinate={row['coordinate_display_name']} | "
            f"status={row['review_status']} | categories={categories} | "
            f"stocks={row['candidate_stock_count']} | etfs={row['stored_etf_count']}/{row['etf_mapping_count']}"
        )
    for issue in payload["issues"]:
        print(f"- issue | {issue['code']} | {issue['path']} | {issue['message']}")
    for warning in payload["warnings"]:
        print(f"- warning | {warning['code']} | {warning['path']} | {warning['message']}")
    return 1 if payload["issue_count"] else 0


def _resolve_rotation_mapping_audit_date(repository: StockMonitorRepository) -> date:
    summary_dates = repository.count_summaries_by_business_date(limit=1)
    if summary_dates:
        return summary_dates[0][0]
    latest_krx_snapshot_date = repository.latest_krx_snapshot_date()
    if latest_krx_snapshot_date is not None:
        return latest_krx_snapshot_date
    raise ValueError("No daily summary or KRX snapshot date is available for rotation-mapping-audit.")


def _build_rotation_mapping_audit(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    limit: int,
) -> dict[str, object]:
    image_config, coordinates = _load_rotation_overlay_config(config)
    aliases = _load_rotation_image_aliases(config)
    etf_mappings = _load_rotation_etf_candidate_mappings(config)
    latest_krx_snapshot_date = repository.latest_krx_snapshot_date()
    issues: list[dict] = []
    warnings: list[dict] = []

    image_path = Path(str(image_config.get("path") or ""))
    resolved_image_path = image_path if image_path.is_absolute() else config.root_dir / image_path
    if not image_path or not resolved_image_path.exists():
        issues.append(
            {
                "code": "rotation_image_missing",
                "path": str(image_config.get("path") or ""),
                "message": "rotation image path does not exist under the project root",
            }
        )
    _collect_rotation_alias_mapping_qa_issues(config, issues=issues)
    _collect_rotation_etf_mapping_qa_issues(
        config,
        repository,
        latest_krx_snapshot_date=latest_krx_snapshot_date,
        issues=issues,
        warnings=warnings,
    )

    aliases_by_coordinate: dict[str, list[tuple[str, str, dict[str, str]]]] = {}
    for (category_type, display_name), alias in aliases.items():
        aliases_by_coordinate.setdefault(alias.get("coordinate_display_name") or "", []).append(
            (category_type, display_name, alias)
        )

    coordinate_rows: list[dict[str, object]] = []
    for coordinate_display_name, coordinate in sorted(coordinates.items()):
        linked_aliases = sorted(aliases_by_coordinate.get(coordinate_display_name, []))
        category_keys = [(category_type, display_name) for category_type, display_name, _alias in linked_aliases]
        if not category_keys:
            category_keys = [("sector", coordinate_display_name)]
        etf_codes = sorted(
            {
                etf_code
                for category_key in category_keys
                for etf_code in etf_mappings.get(category_key, [])
                if etf_code
            }
        )
        candidate_stocks: list[dict[str, object]] = []
        seen_stock_codes: set[str] = set()
        for category_type, display_name in category_keys:
            for stock in _build_rotation_candidate_stocks(
                repository,
                business_date=business_date,
                category_type=category_type,
                display_name=display_name,
                limit=limit,
            ):
                stock_code = str(stock.get("stock_code") or "")
                if stock_code in seen_stock_codes:
                    continue
                seen_stock_codes.add(stock_code)
                candidate_stocks.append(stock)
                if len(candidate_stocks) >= limit:
                    break
            if len(candidate_stocks) >= limit:
                break
        candidate_etfs = _build_rotation_candidate_etfs(
            repository,
            business_date=business_date,
            etf_codes=etf_codes,
            limit=max(limit, len(etf_codes) or 1),
        )
        if not linked_aliases:
            review_status = "coordinate_only_review_needed"
        elif etf_codes and len(candidate_etfs) < len(etf_codes):
            review_status = "etf_snapshot_missing"
        elif etf_codes:
            review_status = "mapped_with_etf"
        else:
            review_status = "mapped_no_etf"
        coordinate_rows.append(
            {
                "coordinate_display_name": coordinate_display_name,
                "label": str(coordinate.get("label") or coordinate_display_name),
                "x": coordinate.get("x"),
                "y": coordinate.get("y"),
                "radius": coordinate.get("radius"),
                "active_alias_count": len(linked_aliases),
                "category_keys": [f"{category_type}:{display_name}" for category_type, display_name in category_keys],
                "etf_codes": etf_codes,
                "etf_mapping_count": len(etf_codes),
                "stored_etf_count": len(candidate_etfs),
                "candidate_stock_count": len(candidate_stocks),
                "candidate_stocks": candidate_stocks,
                "candidate_etfs": candidate_etfs,
                "review_status": review_status,
            }
        )

    return {
        "surface": "rotation-mapping-audit",
        "read_only": True,
        "live_fetch": False,
        "scoring": False,
        "recommendation": False,
        "business_date": business_date.isoformat(),
        "image": {
            "path": str(image_config.get("path") or ""),
            "width": image_config.get("width"),
            "height": image_config.get("height"),
            "exists": resolved_image_path.exists(),
        },
        "latest_krx_snapshot_date": latest_krx_snapshot_date.isoformat() if latest_krx_snapshot_date else None,
        "coordinate_count": len(coordinates),
        "active_alias_count": len(aliases),
        "active_etf_mapping_count": len(etf_mappings),
        "coordinates_without_active_alias_count": sum(1 for row in coordinate_rows if row["active_alias_count"] == 0),
        "coordinates": coordinate_rows,
        "issue_count": len(issues),
        "warning_count": len(warnings),
        "issues": issues,
        "warnings": warnings,
        "notice": (
            "Read-only Cycle image mapping audit. ETF rows come only from operator-managed mappings "
            "and exact-date stored KRX ETF snapshots; this is not scoring or recommendation output."
        ),
    }


def _collect_rotation_etf_mapping_qa_issues(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    latest_krx_snapshot_date: date | None,
    issues: list[dict],
    warnings: list[dict],
) -> None:
    mappings = _load_rotation_etf_candidate_mappings(config)
    if not mappings:
        return
    _image_config, coordinates = _load_rotation_overlay_config(config)
    aliases = _load_rotation_image_aliases(config)
    directly_reachable_names = set(coordinates)
    alias_reachable_categories = {
        (category_type, display_name)
        for (category_type, display_name), alias in aliases.items()
        if alias.get("coordinate_display_name") in coordinates
    }
    for category_type, display_name in mappings:
        if display_name in directly_reachable_names or (category_type, display_name) in alias_reachable_categories:
            continue
        issues.append(
            {
                "code": "rotation_etf_mapping_unreachable_category",
                "path": f"rotation_etf_candidates[{category_type}:{display_name}]",
                "message": "active rotation ETF mapping has no overlay coordinate or active alias for this category",
            }
        )
    if latest_krx_snapshot_date is None:
        warnings.append(
            {
                "code": "rotation_etf_mapping_no_krx_snapshot",
                "path": "rotation_etf_candidates",
                "message": "active rotation ETF mappings exist but no stored KRX snapshot date is available",
            }
        )
        return
    for (category_type, display_name), etf_codes in mappings.items():
        existing_codes = {
            item.etf_code
            for item in repository.list_etf_daily_for_codes(latest_krx_snapshot_date, etf_codes)
        }
        for etf_code in sorted({code for code in etf_codes if code} - existing_codes):
            issues.append(
                {
                    "code": "rotation_etf_mapping_missing_snapshot",
                    "path": f"rotation_etf_candidates[{category_type}:{display_name}].{etf_code}",
                    "message": (
                        "active rotation ETF mapping code has no stored ETF snapshot on "
                        f"{latest_krx_snapshot_date.isoformat()}"
                    ),
                }
            )


def _collect_rotation_alias_mapping_qa_issues(
    config: RuntimeConfig,
    *,
    issues: list[dict],
) -> None:
    _image_config, coordinates = _load_rotation_overlay_config(config)
    aliases = _load_rotation_image_aliases(config)
    if not aliases:
        return
    for (category_type, display_name), alias in aliases.items():
        coordinate_display_name = alias.get("coordinate_display_name") or ""
        if coordinate_display_name and coordinate_display_name not in coordinates:
            issues.append(
                {
                    "code": "rotation_alias_missing_coordinate",
                    "path": f"rotation_image_aliases[{category_type}:{display_name}].coordinate_display_name",
                    "message": f"active rotation alias points to a missing overlay coordinate: {coordinate_display_name}",
                }
            )


def _run_access_code_command(config: RuntimeConfig, *, action: str, code: str | None, confirm: bool) -> int:
    if action == "status":
        if _access_code_enabled(config):
            print(f"access-code: enabled ({config.access_code_path})")
        else:
            print(f"access-code: disabled ({config.access_code_path})")
        return 0
    if action == "set":
        resolved_code = code if code is not None else getpass.getpass("입장코드: ")
        if len(resolved_code.strip()) < 4:
            print("ERROR: 입장코드는 4자 이상으로 지정하세요.", file=sys.stderr)
            return 2
        _write_access_code_record(config, resolved_code.strip())
        print(f"access-code: enabled ({config.access_code_path})")
        return 0
    if action == "clear":
        if not confirm:
            print("ERROR: pass --confirm to remove the access-code hash file.", file=sys.stderr)
            return 2
        try:
            config.access_code_path.unlink()
        except FileNotFoundError:
            pass
        print(f"access-code: disabled ({config.access_code_path})")
        return 0
    raise ValueError(f"Unsupported access-code action: {action}")


def create_admin_gui_server(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    host: str,
    port: int,
    limit: int,
    allow_non_loopback: bool = False,
) -> ThreadingHTTPServer:
    _validate_admin_gui_host(host, allow_non_loopback=allow_non_loopback)
    handler = _make_admin_gui_handler(config, repository, limit=limit)
    return ThreadingHTTPServer((host, port), handler)


def create_web_view_server(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    host: str,
    port: int,
    limit: int,
    allow_non_loopback: bool = False,
    toss_quote_provider: TossPriorityQuoteProvider | None = None,
) -> ThreadingHTTPServer:
    return web_view_server_module.create_web_view_server(
        config, repository, host=host, port=port, limit=limit, make_handler=_make_web_view_handler,
        allow_non_loopback=allow_non_loopback, toss_quote_provider=toss_quote_provider,
    )


def _validate_admin_gui_host(host: str, *, allow_non_loopback: bool = False) -> None:
    if allow_non_loopback or _is_loopback_admin_host(host):
        return
    raise ValueError(
        "admin-gui refuses non-loopback host by default. "
        "Use --host 127.0.0.1 for local control, or pass --allow-non-loopback only on a trusted private network."
    )


def _is_loopback_admin_host(host: str) -> bool:
    normalized = host.strip().lower()
    if normalized == "localhost":
        return True
    try:
        return ipaddress.ip_address(normalized).is_loopback
    except ValueError:
        return False


def _validate_web_view_host(host: str, *, allow_non_loopback: bool = False) -> None:
    return web_view_server_module._validate_web_view_host(host, allow_non_loopback=allow_non_loopback)


def _is_loopback_web_view_host(host: str) -> bool:
    return web_view_server_module._is_loopback_web_view_host(host)


def _make_admin_gui_handler(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    limit: int,
) -> type[BaseHTTPRequestHandler]:
    scheduler_cache_lock = threading.Lock()
    scheduler_cache: dict[str, object] = {"expires_at": 0.0, "tasks": None}

    def load_cached_scheduler_tasks(*, force: bool = False) -> list[dict]:
        current_time = time.monotonic()
        with scheduler_cache_lock:
            cached_tasks = scheduler_cache["tasks"]
            expires_at = float(scheduler_cache["expires_at"])
            if not force and cached_tasks is not None and current_time < expires_at:
                return cached_tasks  # type: ignore[return-value]
            tasks = _load_scheduler_task_statuses(config.scheduler_task_prefix)
            scheduler_cache["tasks"] = tasks
            scheduler_cache["expires_at"] = current_time + ADMIN_GUI_SCHEDULER_STATUS_CACHE_SECONDS
            return tasks

    def invalidate_scheduler_cache() -> None:
        with scheduler_cache_lock:
            scheduler_cache["tasks"] = None
            scheduler_cache["expires_at"] = 0.0

    class AdminGuiHandler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            if not _access_http_gate(self, config, surface_label="관리자 화면", surface_key="admin"):
                return
            if self.path in {"/", "/index.html"}:
                _write_http_response(
                    self,
                    HTTPStatus.OK,
                    _render_admin_gui_html(),
                    content_type="text/html; charset=utf-8",
                )
                return
            if self.path == "/api/status":
                payload = build_operator_status_snapshot(
                    config,
                    repository,
                    limit=limit,
                    scheduler_tasks=load_cached_scheduler_tasks(),
                )
                _write_http_response(
                    self,
                    HTTPStatus.OK,
                    json.dumps(payload, ensure_ascii=False),
                    content_type="application/json; charset=utf-8",
                )
                return
            if self.path == "/health":
                _write_http_response(self, HTTPStatus.OK, "ok", content_type="text/plain; charset=utf-8")
                return
            _write_http_response(self, HTTPStatus.NOT_FOUND, "not found", content_type="text/plain; charset=utf-8")

        def do_POST(self) -> None:
            if not _access_http_gate(self, config, surface_label="관리자 화면", surface_key="admin"):
                return
            try:
                request = _read_json_request(self)
                status, payload = _handle_admin_gui_post(config, repository, self.path, request)
                if status == HTTPStatus.OK and self.path.startswith("/api/scheduler/"):
                    invalidate_scheduler_cache()
            except Exception as exc:
                try:
                    repository.record_operation_event(
                        _operation_event(
                            config,
                            component="admin-gui",
                            event_type="post",
                            status="failed",
                            detail=f"{self.path}; {exc}",
                        )
                    )
                except Exception:
                    pass
                status = HTTPStatus.BAD_REQUEST
                payload = {"ok": False, "error": str(exc)}
            _write_http_response(
                self,
                status,
                json.dumps(payload, ensure_ascii=False),
                content_type="application/json; charset=utf-8",
            )

        def log_message(self, _format: str, *_args) -> None:
            return

    return AdminGuiHandler


def _make_web_view_handler(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    limit: int,
    toss_quote_provider: TossPriorityQuoteProvider | None = None,
) -> type[BaseHTTPRequestHandler]:
    response_cache: dict[str, tuple[float, bytes]] = {}
    response_cache_lock = threading.Lock()
    response_cache_ttl_seconds = 30.0
    api_perf_logger = ApiPerfLogger(config.root_dir / "logs")
    toss_provider = toss_quote_provider or TossPriorityQuoteProvider(
        config=TossOpenApiLabConfig.from_env(config.root_dir)
    )

    def read_cached_json_payload(cache_key: str) -> dict | None:
        now_monotonic = time.monotonic()
        with response_cache_lock:
            cached = response_cache.get(cache_key)
            if not cached or now_monotonic - cached[0] > response_cache_ttl_seconds:
                return None
            cached_body = cached[1]
        return json.loads(cached_body.decode("utf-8"))

    def store_cached_json_payload(cache_key: str, payload: dict) -> None:
        body = json_dumps_bytes(_compact_web_view_json_payload(cache_key, payload))
        with response_cache_lock:
            response_cache[cache_key] = (time.monotonic(), body)

    def cached_json_payload(cache_key: str, builder: Callable[[], dict]) -> tuple[bytes, str, float, float, float]:
        now_monotonic = time.monotonic()
        with response_cache_lock:
            cached = response_cache.get(cache_key)
            if cached and now_monotonic - cached[0] <= response_cache_ttl_seconds:
                return cached[1], "hit", 0.0, 0.0, 0.0
        metrics = RequestMetrics()
        build_start = time.perf_counter()
        with request_metrics_context(metrics):
            payload = _compact_web_view_json_payload(cache_key, builder())
        build_ms = elapsed_ms(build_start)
        json_start = time.perf_counter()
        body = json_dumps_bytes(payload)
        json_ms = elapsed_ms(json_start)
        with response_cache_lock:
            response_cache[cache_key] = (time.monotonic(), body)
        return body, "miss", json_ms, build_ms, metrics.db_ms

    def build_daily_payload_for_route(
        business_date: date,
        *,
        include_intraday_market_top: bool,
        market_top_limit: int,
        market_top_page_size: int,
    ) -> dict:
        if not include_intraday_market_top:
            return build_web_view_daily_snapshot(
                config,
                repository,
                business_date=business_date,
                include_observation_summary=False,
            )

        base_cache_key = f"daily:{business_date.isoformat()}"
        base_payload = read_cached_json_payload(base_cache_key)
        if base_payload is None:
            base_payload = build_web_view_daily_snapshot(
                config,
                repository,
                business_date=business_date,
                include_observation_summary=False,
            )
            store_cached_json_payload(base_cache_key, base_payload)
        return _overlay_web_view_daily_intraday_market_top(
            config,
            repository,
            base_payload,
            business_date=business_date,
            limit=market_top_limit,
            page_size=market_top_page_size,
        )

    def build_toss_priority_quotes_payload(business_date: date) -> tuple[HTTPStatus, dict]:
        archive = build_web_view_archive_snapshot(config, repository, limit=1)
        latest_business_date = archive.get("latest_business_date")
        if latest_business_date and business_date.isoformat() != latest_business_date:
            return HTTPStatus.CONFLICT, {
                "surface": "web-view-toss-priority-quotes",
                "read_only": True,
                "configured": getattr(toss_provider, "configured", False),
                "live_fetch": False,
                "writes_db": False,
                "sends_telegram": False,
                "registers_scheduler": False,
                "affects_ordering": False,
                "priority_date": business_date.isoformat(),
                "latest_business_date": latest_business_date,
                "symbols": [],
                "quotes": [],
                "reason": "latest_business_date_only",
            }
        evidence = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=2,
        )
        symbols = tuple(
            str(row.get("stock_code") or "").strip()
            for row in evidence.get("rows", [])
            if re.fullmatch(r"\d{6}", str(row.get("stock_code") or "").strip())
        )[:2]
        payload = toss_provider.get_quotes(priority_date=business_date, symbols=symbols)
        payload["latest_business_date"] = latest_business_date
        payload["derived_from"] = "web_view_candidate_evidence_top_2"
        return HTTPStatus.OK, payload

    def build_toss_market_context_payload(business_date: date) -> tuple[HTTPStatus, dict]:
        archive = build_web_view_archive_snapshot(config, repository, limit=1)
        latest_business_date = archive.get("latest_business_date")
        if latest_business_date and business_date.isoformat() != latest_business_date:
            return HTTPStatus.CONFLICT, {
                "surface": "web-view-toss-market-context",
                "read_only": True,
                "configured": getattr(toss_provider, "configured", False),
                "live_fetch": False,
                "writes_db": False,
                "sends_telegram": False,
                "registers_scheduler": False,
                "affects_ordering": False,
                "reference_date": None,
                "rankings": [],
                "priority_overlap_symbols": [],
                "investor_flow": {"KOSPI": None, "KOSDAQ": None},
                "latest_business_date": latest_business_date,
                "reason": "latest_business_date_only",
            }
        evidence = build_web_view_candidate_evidence_snapshot(
            config,
            repository,
            business_date=business_date,
            limit=2,
        )
        symbols = tuple(
            str(row.get("stock_code") or "").strip()
            for row in evidence.get("rows", [])
            if re.fullmatch(r"\d{6}", str(row.get("stock_code") or "").strip())
        )[:2]
        payload = _build_toss_market_context(
            toss_provider,
            reference_date=previous_business_day(business_date, config.holiday_overrides),
            priority_symbols=symbols,
        )
        return HTTPStatus.OK, {
            "surface": "web-view-toss-market-context",
            "read_only": True,
            "writes_db": False,
            "sends_telegram": False,
            "registers_scheduler": False,
            "affects_ordering": False,
            **payload,
            "latest_business_date": latest_business_date,
            "derived_from": "web_view_candidate_evidence_top_2",
        }

    def write_cached_json_response(handler: BaseHTTPRequestHandler, cache_key: str, builder: Callable[[], dict]) -> None:
        total_start = time.perf_counter()
        body, cache_status, json_ms, build_ms, db_ms = cached_json_payload(cache_key, builder)
        response_body, gzip_used = maybe_gzip(body, handler.headers.get("Accept-Encoding", ""))
        headers = {"Content-Encoding": "gzip"} if gzip_used else None
        _write_binary_http_response(
            handler,
            HTTPStatus.OK,
            response_body,
            content_type="application/json; charset=utf-8",
            headers=headers,
        )
        api_perf_logger.log(
            method=handler.command,
            path=handler.path,
            status=HTTPStatus.OK.value,
            total_ms=elapsed_ms(total_start),
            db_ms=db_ms,
            build_ms=build_ms,
            json_ms=json_ms,
            response_bytes=len(response_body),
            cache=cache_status,
            gzip_used=gzip_used,
        )

