def _web_view_stock_flow_window_item(
    repository: StockMonitorRepository,
    summary: DailyStockSummary,
    *,
    business_date: date,
) -> dict:
    if not summary.stock_code:
        return {"available": False, "stock_name": summary.stock_name, "stock_code": summary.stock_code}
    rows = _load_stock_flow_window_rows(repository, stock_code=summary.stock_code, business_date=business_date)
    return _web_view_stock_flow_window_item_from_rows(summary, business_date=business_date, rows=rows)


def _web_view_stock_flow_window_item_from_rows(
    summary: DailyStockSummary,
    *,
    business_date: date,
    rows: list[sqlite3.Row],
) -> dict:
    if not summary.stock_code:
        return {"available": False, "stock_name": summary.stock_name, "stock_code": summary.stock_code}
    flow_dates = sorted({date.fromisoformat(str(row["business_date"])) for row in rows}, reverse=True)
    if not flow_dates:
        return {
            "available": False,
            "stock_name": summary.stock_name,
            "stock_code": summary.stock_code,
            "windows": [],
        }
    windows = []
    for window_days in (5, 10, 20, 31):
        picked_dates = set(flow_dates[:window_days])
        window_rows = [row for row in rows if date.fromisoformat(str(row["business_date"])) in picked_dates]
        windows.append(
            {
                "days": window_days,
                "observed_days": len(picked_dates),
                "individual_net_buy_amount": _sum_flow_window_amount(window_rows, {"개인"}),
                "foreign_net_buy_amount": _sum_flow_window_amount(window_rows, {"외국인"}),
                "institution_net_buy_amount": _sum_flow_window_amount(window_rows, {"기관", "기관합계"}),
            }
        )
    latest = windows[0]
    persistence = {
        "foreign": _flow_persistence_summary(rows, {"외국인"}),
        "institution": _flow_persistence_summary(rows, {"기관", "기관합계"}),
    }
    persistence_text = _format_flow_persistence_parts(
        (("외국인", persistence["foreign"]), ("기관", persistence["institution"]))
    )
    return {
        "available": True,
        "stock_name": summary.stock_name,
        "stock_code": summary.stock_code,
        "reference_date": flow_dates[0].isoformat(),
        "observed_days": len(flow_dates),
        "windows": windows,
        "persistence": persistence,
        "display": (
            f"{summary.stock_name} 외국인 {_format_flow_reference_amount(latest['foreign_net_buy_amount'])} · "
            f"기관 {_format_flow_reference_amount(latest['institution_net_buy_amount'])}"
            f"{persistence_text}"
        ),
    }


def _load_stock_flow_window_rows(
    repository: StockMonitorRepository,
    *,
    stock_code: str,
    business_date: date,
) -> list[sqlite3.Row]:
    from_date = business_date - timedelta(days=60)
    with repository.connect() as connection:
        rows = connection.execute(
            """
            SELECT business_date, investor_type, net_buy_amount
            FROM stock_investor_flow_daily
            WHERE business_date BETWEEN ? AND ?
              AND stock_code = ?
              AND source = 'krx_data_market'
            ORDER BY business_date DESC, investor_type ASC
            """,
            (from_date.isoformat(), business_date.isoformat(), stock_code),
        ).fetchall()
    return rows


def _sum_flow_window_amount(rows: list[sqlite3.Row], labels: set[str]) -> int | None:
    values = [row["net_buy_amount"] for row in rows if row["investor_type"] in labels and row["net_buy_amount"] is not None]
    return sum(int(value) for value in values) if values else None


def _flow_direction(value: int | None) -> int:
    if value is None:
        return 0
    if value > 0:
        return 1
    if value < 0:
        return -1
    return 0


def _flow_direction_label(direction: int | None) -> str:
    if direction is None or direction == 0:
        return "중립"
    return "순유입" if direction > 0 else "순유출"


def _flow_persistence_summary(rows: list[sqlite3.Row], labels: set[str]) -> dict[str, object]:
    by_date: dict[date, int] = {}
    for row in rows:
        if row["investor_type"] not in labels or row["net_buy_amount"] is None:
            continue
        business_date = date.fromisoformat(str(row["business_date"]))
        by_date[business_date] = by_date.get(business_date, 0) + int(row["net_buy_amount"])
    ordered = sorted(by_date.items(), reverse=True)
    signed = [(business_date, amount, _flow_direction(amount)) for business_date, amount in ordered]
    non_zero = [(business_date, amount, direction) for business_date, amount, direction in signed if direction != 0]
    if not non_zero:
        return {
            "available": False,
            "direction": None,
            "direction_label": "중립",
            "streak_days": 0,
            "turn_date": None,
            "turn_available": False,
            "latest_amount": None,
        }
    latest_date, latest_amount, latest_direction = non_zero[0]
    streak_dates = [latest_date]
    for business_date, _amount, direction in non_zero[1:]:
        if direction != latest_direction:
            break
        streak_dates.append(business_date)
    streak_oldest = min(streak_dates)
    has_prior_opposite = any(direction != latest_direction for business_date, _amount, direction in non_zero if business_date < streak_oldest)
    return {
        "available": True,
        "direction": latest_direction,
        "direction_label": _flow_direction_label(latest_direction),
        "streak_days": len(streak_dates),
        "turn_date": streak_oldest.isoformat() if has_prior_opposite else None,
        "turn_available": has_prior_opposite,
        "latest_amount": latest_amount,
    }


def _format_flow_persistence_parts(items: tuple[tuple[str, dict[str, object]], ...]) -> str:
    parts = []
    for label, item in items:
        if not item.get("available"):
            continue
        direction_label = str(item.get("direction_label") or "중립")
        streak_days = int(item.get("streak_days") or 0)
        if streak_days < 2:
            continue
        turn_date = item.get("turn_date")
        if turn_date:
            parts.append(f"{label} {direction_label} 전환 {str(turn_date)[5:].replace('-', '.')}부터 {streak_days}일")
        else:
            parts.append(f"{label} {direction_label} 연속 {streak_days}일")
    return f" · {' · '.join(parts)}" if parts else ""


def _format_flow_reference_amount(value: int | None) -> str:
    if value is None:
        return "-"
    if value > 0:
        return f"순유입 {_format_krx_flow_amount(value)}"
    if value < 0:
        return f"순유출 {_format_krx_flow_amount(value)}"
    return "중립"


def _web_view_price_volume_position_item(
    repository: StockMonitorRepository,
    summary: DailyStockSummary,
    *,
    business_date: date,
) -> dict:
    if not summary.stock_code:
        return {"available": False, "stock_name": summary.stock_name, "stock_code": summary.stock_code}
    rows = repository.list_stock_market_daily_for_code_on_or_before(
        business_date,
        summary.stock_code,
        limit=252,
    )
    return _web_view_price_volume_position_item_from_rows(summary, rows=rows)


def _web_view_price_volume_position_item_from_rows(
    summary: DailyStockSummary,
    *,
    rows: list[StockMarketDailySnapshot],
) -> dict:
    if not summary.stock_code:
        return {"available": False, "stock_name": summary.stock_name, "stock_code": summary.stock_code}
    current = rows[0] if rows else None
    if current is None or current.close_price is None:
        return {"available": False, "stock_name": summary.stock_name, "stock_code": summary.stock_code}
    position_20d = _web_view_close_position_percent(rows[:20], current.close_price)
    position_60d = _web_view_close_position_percent(rows[:60], current.close_price)
    position_52w = _web_view_close_position_percent(rows[:252], current.close_price) if len(rows) >= 120 else None
    return_5d = _web_view_return_percent(rows, current.close_price, offset=4)
    return_20d = _web_view_return_percent(rows, current.close_price, offset=19)
    volume_multiple_20d = _web_view_volume_multiple(rows[:20], current.volume)
    position_parts = [f"{summary.stock_name} 20일 위치 {_format_optional_percent(position_20d)}"]
    if position_52w is not None:
        position_parts.append(f"52주 위치 {_format_optional_percent(position_52w)}")
    position_parts.append(f"5일 {_format_optional_signed_percent(return_5d)}")
    position_parts.append(f"거래량 {_format_optional_multiple(volume_multiple_20d)}")
    return {
        "available": True,
        "stock_name": summary.stock_name,
        "stock_code": summary.stock_code,
        "reference_date": current.business_date.isoformat(),
        "close_price": current.close_price,
        "change_percent": current.change_percent,
        "turnover": current.turnover,
        "turnover_display": _format_krx_flow_amount(current.turnover) if current.turnover is not None else "저장값 없음",
        "close_position_20d_percent": position_20d,
        "close_position_60d_percent": position_60d,
        "close_position_52w_percent": position_52w,
        "close_position_52w_observed_days": min(len(rows), 252),
        "return_5d_percent": return_5d,
        "return_20d_percent": return_20d,
        "volume_multiple_20d": volume_multiple_20d,
        "display": " · ".join(position_parts),
    }


def _web_view_close_position_percent(rows: list[StockMarketDailySnapshot], current_price: int) -> float | None:
    closes = [row.close_price for row in rows if row.close_price is not None]
    if len(closes) < 2:
        return None
    low = min(closes)
    high = max(closes)
    if high == low:
        return 50.0
    return round(((current_price - low) / (high - low)) * 100, 1)


def _web_view_return_percent(
    rows: list[StockMarketDailySnapshot],
    current_price: int,
    *,
    offset: int,
) -> float | None:
    if len(rows) <= offset or rows[offset].close_price in (None, 0):
        return None
    baseline = rows[offset].close_price
    return round(((current_price - baseline) / baseline) * 100, 2)


def _web_view_volume_multiple(rows: list[StockMarketDailySnapshot], current_volume: int | None) -> float | None:
    volumes = [row.volume for row in rows if row.volume is not None and row.volume > 0]
    if current_volume is None or current_volume <= 0 or not volumes:
        return None
    average = sum(volumes) / len(volumes)
    if average <= 0:
        return None
    return round(current_volume / average, 2)


def _format_optional_percent(value: float | None) -> str:
    return "-" if value is None else f"{value:.1f}%"


def _format_optional_signed_percent(value: float | None) -> str:
    if value is None:
        return "-"
    sign = "+" if value > 0 else ""
    return f"{sign}{value:.2f}%"


def _format_optional_multiple(value: float | None) -> str:
    return "-" if value is None else f"{value:.2f}배"


def _web_view_category_breadth_items(
    items: list[CategoryDailyRollup],
    *,
    category_label: str,
    total_report_count: int,
) -> list[dict]:
    max_report_count = max((item.report_count for item in items), default=0)
    return [
        _web_view_category_breadth_item(
            item,
            category_label=category_label,
            total_report_count=total_report_count,
            max_report_count=max_report_count,
        )
        for item in items
    ]


def _web_view_category_breadth_item(
    item: CategoryDailyRollup,
    *,
    category_label: str,
    total_report_count: int = 0,
    max_report_count: int = 0,
) -> dict:
    category_display_name = _web_view_category_display_name(item.display_name, category_type=item.category_type)
    share_percent = round((item.report_count / total_report_count) * 100, 1) if total_report_count > 0 else 0.0
    bar_width_percent = round((item.report_count / max_report_count) * 100, 1) if max_report_count > 0 else 0.0
    display_parts = [category_display_name, f"리포트 {item.report_count}건"]
    if not (item.report_count == 1 and item.stock_count == 1):
        display_parts.append(f"{item.stock_count}종목")
    return {
        "category_label": category_label,
        "category_type": item.category_type,
        "public_category_id": _web_view_public_category_id(item),
        "display_name": item.display_name,
        "category_display_name": category_display_name,
        "stock_count": item.stock_count,
        "report_count": item.report_count,
        "share_percent": share_percent,
        "bar_width_percent": bar_width_percent,
        "snapshot_date": item.snapshot_date.isoformat() if item.snapshot_date else None,
        "mapping_source": item.mapping_source,
        "display": " · ".join(display_parts),
    }


def _build_web_view_market_briefing_index_summary(
    repository: StockMonitorRepository,
    business_date: date,
) -> dict:
    snapshot_dates = repository.list_recent_krx_snapshot_dates(on_or_before=business_date, limit=1)
    reference_date = snapshot_dates[0] if snapshot_dates else None
    indices = repository.list_market_index_daily(reference_date, limit=200) if reference_date else []
    picked = [
        item
        for item in (
            _find_named_market_index(indices, series="KOSPI", name="코스피"),
            _find_named_market_index(indices, series="KOSDAQ", name="코스닥"),
        )
        if item is not None
    ]
    return {
        "available": bool(picked),
        "business_date": business_date.isoformat(),
        "reference_date": reference_date.isoformat() if reference_date else None,
        "exact_date_available": reference_date == business_date if reference_date else False,
        "indices": [_web_view_index_item(item) for item in picked],
    }


def _build_web_view_market_briefing_turnover_summary(
    repository: StockMonitorRepository,
    business_date: date,
    *,
    limit_per_market: int = 2,
) -> dict:
    snapshot_dates = repository.list_recent_krx_snapshot_dates(on_or_before=business_date, limit=1)
    reference_date = snapshot_dates[0] if snapshot_dates else None
    markets: list[dict[str, object]] = []
    if reference_date:
        for market in ("KOSPI", "KOSDAQ"):
            items = [
                _web_view_market_briefing_turnover_item(item)
                for item in repository.list_stock_market_daily_by_turnover(
                    reference_date,
                    market=market,
                    limit=limit_per_market,
                )
                if item.turnover is not None
            ]
            if items:
                markets.append({"market": market, "items": items})
    return {
        "available": bool(markets),
        "business_date": business_date.isoformat(),
        "reference_date": reference_date.isoformat() if reference_date else None,
        "exact_date_available": reference_date == business_date if reference_date else False,
        "markets": markets,
    }


def _build_web_view_market_briefing_flow_summary(
    repository: StockMonitorRepository,
    business_date: date,
) -> dict:
    flow_dates = repository.list_recent_investor_flow_dates(on_or_before=business_date, limit=1)
    reference_date = flow_dates[0] if flow_dates else None
    items: list[dict[str, object]] = []
    if reference_date:
        by_investor = {
            row.investor_type: row
            for row in repository.list_market_investor_flow_daily(reference_date, "STK")
        }
        for _, investor_key in (("개인", "개인"), ("외국인", "외국인"), ("기관", "기관합계")):
            row = by_investor.get(investor_key)
            if row is None:
                continue
            payload = _web_view_market_investor_flow_item(row)
            payload["direction_label"] = _flow_direction_label(row.net_buy_amount)
            items.append(payload)
    return {
        "available": bool(items),
        "business_date": business_date.isoformat(),
        "reference_date": reference_date.isoformat() if reference_date else None,
        "exact_date_available": reference_date == business_date if reference_date else False,
        "market": "STK",
        "market_label": "KOSPI",
        "items": items,
    }


def _build_web_view_market_briefing_notable_stocks(
    summaries: list[DailyStockSummary],
    *,
    limit: int = 5,
) -> list[dict]:
    ordered = sorted(summaries, key=lambda item: (-item.mention_count, item.stock_name))
    notable = [item for item in ordered if item.mention_count >= 2][: max(limit, 0)]
    return [
        {
            "stock_name": summary.stock_name,
            "stock_code": summary.stock_code,
            "mention_count": summary.mention_count,
            "target_price_min": summary.target_price_min,
            "target_price_max": summary.target_price_max,
            "target_price_display": _web_view_target_price_range(summary),
        }
        for summary in notable
    ]


def _web_view_market_briefing_check_points(lines: list[str]) -> list[str]:
    if not lines:
        return []
    points: list[str] = []
    for line in lines[1:]:
        point = line.removeprefix("- ").strip()
        if not point:
            continue
        if "사용자 웹뷰" in point:
            point = "아래 종목/관찰 탭에서 세부 근거 확인"
        points.append(point)
    return points


def _web_view_archive_category_mapping(repository: StockMonitorRepository, business_date: date) -> dict:
    sector_snapshot = repository.latest_category_snapshot_date(
        category_type="sector",
        business_date=business_date,
        enabled_only=True,
    )
    theme_snapshot = repository.latest_category_snapshot_date(
        category_type="theme",
        business_date=business_date,
        enabled_only=True,
    )
    dated = bool(sector_snapshot and theme_snapshot)
    return {
        "mapping_basis": "dated_snapshot" if dated else "latest_mapping_fallback",
        "sector_snapshot_date": sector_snapshot.isoformat() if sector_snapshot else None,
        "theme_snapshot_date": theme_snapshot.isoformat() if theme_snapshot else None,
        "label": "카테고리 스냅샷" if dated else "최신 저장 분류",
    }


def _web_view_archive_category_mappings(repository: StockMonitorRepository, business_dates: list[date]) -> dict[date, dict]:
    if not business_dates:
        return {}
    max_date = max(business_dates)
    snapshots_by_type: dict[str, list[date]] = {"sector": [], "theme": []}
    with repository.connect() as connection:
        rows = connection.execute(
            """
            SELECT cms.category_type, cms.snapshot_date
            FROM category_membership_snapshots cms
            JOIN category_master cm
              ON cm.category_type = cms.category_type
             AND cm.category_key = cms.category_key
            WHERE cms.category_type IN ('sector', 'theme')
              AND cms.snapshot_date <= ?
              AND cm.enabled = 1
            GROUP BY cms.category_type, cms.snapshot_date
            ORDER BY cms.category_type ASC, cms.snapshot_date ASC
            """,
            (max_date.isoformat(),),
        ).fetchall()
    for row in rows:
        snapshots_by_type[str(row["category_type"])].append(date.fromisoformat(str(row["snapshot_date"])))

    def latest_snapshot(category_type: str, business_date: date) -> date | None:
        snapshots = snapshots_by_type.get(category_type, [])
        index = bisect_right(snapshots, business_date) - 1
        return snapshots[index] if index >= 0 else None

    mappings: dict[date, dict] = {}
    for business_date in business_dates:
        sector_snapshot = latest_snapshot("sector", business_date)
        theme_snapshot = latest_snapshot("theme", business_date)
        dated = bool(sector_snapshot and theme_snapshot)
        mappings[business_date] = {
            "mapping_basis": "dated_snapshot" if dated else "latest_mapping_fallback",
            "sector_snapshot_date": sector_snapshot.isoformat() if sector_snapshot else None,
            "theme_snapshot_date": theme_snapshot.isoformat() if theme_snapshot else None,
            "label": "카테고리 스냅샷" if dated else "최신 저장 분류",
        }
    return mappings


def _web_view_archive_category_mapping_summary(dates: list[dict[str, object]]) -> dict:
    dated_count = sum(
        1
        for item in dates
        if isinstance(item.get("category_mapping"), dict)
        and item["category_mapping"].get("mapping_basis") == "dated_snapshot"
    )
    fallback_count = len(dates) - dated_count
    return {
        "dated_snapshot_count": dated_count,
        "fallback_count": fallback_count,
        "notice": (
            "일부 날짜는 과거 source-date 카테고리 스냅샷이 없어 최신 저장 분류 기준으로 표시합니다."
            if fallback_count
            else "모든 날짜가 dated category snapshot 기준입니다."
        ),
    }


def _web_view_public_contract() -> dict:
    return {
        "read_only": True,
        "source_scope": "저장 데이터 기준",
        "missing_value_policy": "누락값은 계산에서 제외하고 상세에 '-'로 표시합니다.",
        "recommendation": False,
        "control_exposed": False,
    }


def _web_view_broker_count(broker_display: str | None) -> int:
    brokers = [
        re.sub(r"\(\d+\)$", "", item.strip()).strip()
        for item in (broker_display or "").split(",")
        if item.strip()
    ]
    return len({broker for broker in brokers if broker})


def _web_view_target_price_range(summary: DailyStockSummary) -> dict:
    return {
        "min": summary.target_price_min,
        "max": summary.target_price_max,
        "available": summary.target_price_min is not None or summary.target_price_max is not None,
    }


def _web_view_stock_flow_totals(rows: list[StockInvestorFlowDaily]) -> dict:
    def total_for(labels: set[str]) -> int | None:
        value = _stock_flow_value(rows, labels)
        return value if value is not None else None

    return {
        "individual_net_buy_volume": total_for({"개인"}),
        "foreign_net_buy_volume": total_for({"외국인"}),
        "institution_net_buy_volume": total_for({"기관", "기관합계"}),
        "individual_net_buy_amount": _stock_flow_side_value(rows, {"개인"}, "net_buy_amount"),
        "foreign_net_buy_amount": _stock_flow_side_value(rows, {"외국인"}, "net_buy_amount"),
        "institution_net_buy_amount": _stock_flow_side_value(rows, {"기관", "기관합계"}, "net_buy_amount"),
        "volume_unit": rows[0].volume_unit if rows else None,
        "amount_unit": rows[0].amount_unit if rows else None,
        "snapshot_date": rows[0].business_date.isoformat() if rows else None,
        "available": bool(rows),
    }


def _web_view_news_collection_status(news_reference: dict[str, object] | None) -> str:
    if not news_reference or news_reference.get("available") is not True:
        return "next_check_needed"
    direct_count = int(news_reference.get("direct_count") or 0)
    caution_count = int(news_reference.get("caution_count") or 0)
    market_context_count = int(news_reference.get("market_context_count") or 0)
    if direct_count > 0 or caution_count > 0 or market_context_count > 0:
        return "stored_evidence"
    return "stored_no_match"


def _web_view_value_context(
    *,
    report_reference_date: date | str | None,
    market_reference: StockMarketDailySnapshot | None,
    stock_flow_reference: dict[str, object] | None,
    news_reference: dict[str, object] | None,
    toss_baseline_reference: dict[str, object] | None = None,
) -> dict[str, object]:
    report_date = report_reference_date.isoformat() if isinstance(report_reference_date, date) else report_reference_date
    krx_date = market_reference.business_date.isoformat() if market_reference else None
    turnover_date = krx_date if market_reference and market_reference.turnover is not None else None
    flow_date = str(
        (stock_flow_reference or {}).get("snapshot_date")
        or (stock_flow_reference or {}).get("reference_date")
        or ""
    ) or None
    has_toss_baseline = bool(toss_baseline_reference and toss_baseline_reference.get("available") is True)
    if has_toss_baseline:
        current_price_reference_time = toss_baseline_reference.get("reference_time")
        current_price_basis = "20:00 stored"
    elif market_reference is not None and market_reference.close_price is not None:
        current_price_reference_time = krx_date
        current_price_basis = "KRX close"
    else:
        current_price_reference_time = None
        current_price_basis = None
    context = {
        "report_reference_date": report_date,
        "krx_reference_date": krx_date,
        "current_price_reference_time": current_price_reference_time,
        "current_price_basis": current_price_basis,
        "turnover_reference_date": turnover_date,
        "investor_flow_reference_date": flow_date,
        "news_collection_status": _web_view_news_collection_status(news_reference),
    }
    context["missing_labels"] = [
        label
        for label, value in (
            ("report", context["report_reference_date"]),
            ("krx", context["krx_reference_date"]),
            ("current_price", context["current_price_reference_time"]),
            ("turnover", context["turnover_reference_date"]),
            ("investor_flow", context["investor_flow_reference_date"]),
        )
        if not value
    ]
    return context


def _web_view_percent(numerator: float, denominator: float) -> float | None:
    if denominator == 0:
        return None
    return round((numerator / denominator) * 100, 2)


def _web_view_target_progress_percent(current_price: int, baseline_price: int, target_price: int) -> float | None:
    numerator = current_price - baseline_price
    denominator = target_price - baseline_price
    if denominator == 0:
        return 0.0 if numerator == 0 else None
    return _web_view_percent(numerator, denominator)


def _web_view_target_progress_notice(baseline_price: int | None, target_min: int, target_max: int) -> str | None:
    if baseline_price is None:
        return None
    if baseline_price < target_min:
        return "baseline_below_target_range"
    if baseline_price > target_max:
        return "baseline_above_target_range"
    return "baseline_inside_target_range"


def _web_view_empty_target_validation(reason: str) -> dict[str, object]:
    return {
        "validation_available": False,
        "validation_window_days": None,
        "max_progress_to_min_percent": None,
        "max_progress_to_max_percent": None,
        "hit_min_horizon_days": None,
        "hit_max_horizon_days": None,
        "validation_notice": reason,
    }


def _web_view_target_validation(
    market_series: list[StockMarketDailySnapshot],
    *,
    baseline_price: int | None,
    target_min: int,
    target_max: int,
    progress_notice: str | None,
) -> dict[str, object]:
    if baseline_price is None:
        return _web_view_empty_target_validation("missing_baseline_price")
    if progress_notice != "baseline_below_target_range":
        return _web_view_empty_target_validation(progress_notice or "unsupported_target_direction")
    observed = [
        (index, item)
        for index, item in enumerate(market_series)
        if item.close_price is not None
    ]
    if not observed:
        return _web_view_empty_target_validation("missing_market_series")
    progress_to_min = [
        _web_view_target_progress_percent(item.close_price, baseline_price, target_min)
        for _index, item in observed
    ]
    progress_to_max = [
        _web_view_target_progress_percent(item.close_price, baseline_price, target_max)
        for _index, item in observed
    ]
    valid_min_progress = [value for value in progress_to_min if value is not None]
    valid_max_progress = [value for value in progress_to_max if value is not None]
    hit_min = next((index for index, item in observed if item.close_price >= target_min), None)
    hit_max = next((index for index, item in observed if item.close_price >= target_max), None)
    return {
        "validation_available": bool(valid_min_progress or valid_max_progress or hit_min is not None or hit_max is not None),
        "validation_window_days": max(index for index, _item in observed),
        "max_progress_to_min_percent": max(valid_min_progress) if valid_min_progress else None,
        "max_progress_to_max_percent": max(valid_max_progress) if valid_max_progress else None,
        "hit_min_horizon_days": hit_min,
        "hit_max_horizon_days": hit_max,
        "validation_notice": "stored_window_only",
    }


def _web_view_target_price_progress(
    repository: StockMonitorRepository,
    summary: DailyStockSummary,
    market_reference: StockMarketDailySnapshot | None,
) -> dict:
    market_series = (
        repository.list_stock_market_daily_for_code_on_or_after(
            summary.business_date,
            summary.stock_code,
            limit=21,
        )
        if summary.stock_code
        else []
    )
    return _web_view_target_price_progress_from_rows(
        summary,
        market_reference,
        baseline_date=summary.business_date if summary.stock_code else None,
        baseline_market=market_reference,
        market_series=market_series,
    )


def _web_view_target_price_progress_from_rows(
    summary: DailyStockSummary,
    market_reference: StockMarketDailySnapshot | None,
    *,
    baseline_date: date | None,
    baseline_market: StockMarketDailySnapshot | None,
    market_series: list[StockMarketDailySnapshot],
) -> dict:
    target_values = [
        value
        for value in (summary.target_price_min, summary.target_price_max)
        if value is not None
    ]
    if not summary.stock_code or not target_values or market_reference is None or market_reference.close_price is None:
        return {
            "available": False,
            "gap_available": False,
            "progress_available": False,
            **_web_view_empty_target_validation("missing_target_or_market_reference"),
            "policy": "range_only",
            "notice": "목표가, 종목코드, 또는 선택일 KRX 종가가 없어 계산하지 않습니다.",
        }

    target_min = min(target_values)
    target_max = max(target_values)
    current_price = market_reference.close_price
    baseline_price = baseline_market.close_price if baseline_market else None
    gap_values = [
        _web_view_percent(target_min - current_price, current_price),
        _web_view_percent(target_max - current_price, current_price),
    ]
    progress_to_min = None
    progress_to_max = None
    if baseline_price is not None:
        progress_to_min = _web_view_target_progress_percent(current_price, baseline_price, target_min)
        progress_to_max = _web_view_target_progress_percent(current_price, baseline_price, target_max)
    valid_gaps = [value for value in gap_values if value is not None]
    valid_progress = [value for value in (progress_to_min, progress_to_max) if value is not None]
    progress_notice = _web_view_target_progress_notice(baseline_price, target_min, target_max)
    validation = _web_view_target_validation(
        market_series,
        baseline_price=baseline_price,
        target_min=target_min,
        target_max=target_max,
        progress_notice=progress_notice,
    )
    return {
        "available": bool(valid_gaps or valid_progress),
        "gap_available": bool(valid_gaps),
        "progress_available": bool(valid_progress),
        **validation,
        "policy": "range_only",
        "baseline_date": baseline_date.isoformat() if baseline_date else None,
        "baseline_price": baseline_price,
        "current_date": summary.business_date.isoformat(),
        "current_price": current_price,
        "target_price_min": target_min,
        "target_price_max": target_max,
        "target_gap_min_percent": min(valid_gaps) if valid_gaps else None,
        "target_gap_max_percent": max(valid_gaps) if valid_gaps else None,
        "progress_to_min_percent": progress_to_min,
        "progress_to_max_percent": progress_to_max,
        "progress_caution": progress_notice != "baseline_below_target_range",
        "progress_notice": progress_notice,
        "notice": "목표가 범위 기준 괴리율/진행률입니다. 저장 데이터 기반 확인용입니다.",
    }


def _build_web_view_target_journey(
    repository: StockMonitorRepository,
    business_date: date,
    stock_code: str,
    *,
    limit: int = 6,
    market_limit: int = 120,
) -> dict[str, object]:
    with repository.connect() as connection:
        rows = connection.execute(
            """
            SELECT
                business_date,
                broker_name,
                published_at,
                target_price_value
            FROM reports
            WHERE stock_code = ?
              AND business_date <= ?
              AND target_price_value IS NOT NULL
            ORDER BY business_date DESC, published_at DESC, broker_name ASC
            LIMIT 200
            """,
            (stock_code, business_date.isoformat()),
        ).fetchall()
    report_rows = [
        {
            "business_date": date.fromisoformat(row["business_date"]),
            "broker_name": row["broker_name"],
            "published_at": row["published_at"],
            "target_price_value": int(row["target_price_value"]),
        }
        for row in rows
    ]
    items: list[dict[str, object]] = []
    for index, report_row in enumerate(report_rows[: max(limit, 0)]):
        report_date = report_row["business_date"]
        target_price = int(report_row["target_price_value"])
        previous_target = int(report_rows[index + 1]["target_price_value"]) if index + 1 < len(report_rows) else None
        _direction, direction_label = _web_view_target_revision_direction(target_price, previous_target)
        market_series = repository.list_stock_market_daily_for_code_on_or_after(
            report_date,
            stock_code,
            limit=market_limit,
        )
        hit_index: int | None = None
        hit_date: date | None = None
        observed_prices: list[int] = []
        latest_close: int | None = None
        for market_index, market_row in enumerate(market_series):
            if market_row.close_price is not None:
                latest_close = market_row.close_price
            observed_price = market_row.high_price if market_row.high_price is not None else market_row.close_price
            if observed_price is None:
                continue
            observed_prices.append(observed_price)
            if hit_index is None and observed_price >= target_price:
                hit_index = market_index
                hit_date = market_row.business_date
        if not observed_prices:
            status = "no_market_data"
        elif hit_index is not None:
            status = "hit"
        else:
            status = "in_progress"
        current_attainment_percent = (
            round((latest_close / target_price) * 100, 1)
            if latest_close is not None and target_price
            else None
        )
        max_attainment_percent = (
            round((max(observed_prices) / target_price) * 100, 1)
            if observed_prices and target_price
            else None
        )
        items.append(
            {
                "report_date": report_date.isoformat(),
                "broker_name": report_row["broker_name"],
                "published_at": report_row["published_at"],
                "target_price_value": target_price,
                "target_price_display": _web_view_target_price_range_display(target_price, target_price),
                "revision_direction_label": direction_label,
                "status": status,
                "hit_date": hit_date.isoformat() if hit_date else None,
                "hit_trading_days": hit_index,
                "current_attainment_percent": current_attainment_percent,
                "max_attainment_percent": max_attainment_percent,
            }
        )
    return {
        "available": bool(items),
        "source": "stored_reports_and_stock_market_daily",
        "live_fetch": False,
        "scoring": False,
        "recommendation": False,
        "business_date": business_date.isoformat(),
        "stock_code": stock_code,
        "price_basis": "high_price_then_close_price",
        "items": items,
        "notice": (
            "저장 리포트 목표가별 도달 기록입니다. 달성 여부는 판단 문구가 아니라 저장 가격 흐름 기준 기록입니다."
            if items
            else "저장된 목표가 리포트가 없어 목표가 Journey를 계산하지 않습니다."
        ),
    }


def _web_view_candidate_news_badges_by_code(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    stock_codes: list[str],
    stock_names_by_code: dict[str, str] | None = None,
) -> dict[str, dict[str, object]]:
    stock_code_set = {stock_code for stock_code in stock_codes if stock_code}
    if not stock_code_set:
        return {}
    normalized_names_by_code = {
        stock_code: _web_view_normalize_news_identity(stock_name)
        for stock_code, stock_name in (stock_names_by_code or {}).items()
        if stock_code and stock_name
    }
    code_by_normalized_name = {
        normalized_name: stock_code
        for stock_code, normalized_name in normalized_names_by_code.items()
        if normalized_name and stock_code in stock_code_set
    }
    rows_by_code: dict[str, list[ReportLinkedNewsEvidenceRecord]] = {stock_code: [] for stock_code in stock_code_set}
    collected_without_evidence_by_code: dict[str, bool] = {stock_code: False for stock_code in stock_code_set}
    runs = repository.list_news_intelligence_runs(target_date=business_date, limit=100)
    for run in runs:
        target_stock_code = run.stock_code if run.stock_code in stock_code_set else None
        if target_stock_code is None:
            target_stock_code = code_by_normalized_name.get(_web_view_normalize_news_identity(run.stock_name))
        if target_stock_code is None:
            continue
        evidence_rows = repository.list_report_linked_news_evidence(run_id=run.run_id, limit=20)
        if not evidence_rows:
            collected_without_evidence_by_code[target_stock_code] = True
        target_stock_name = normalized_names_by_code.get(target_stock_code, "")
        rows_by_code.setdefault(target_stock_code, []).extend(
            row
            for row in evidence_rows
            if row.stock_code == target_stock_code
            or (target_stock_name and _web_view_normalize_news_identity(row.stock_name) == target_stock_name)
        )
    return {
        stock_code: (
            _web_view_candidate_news_badge(
                rows,
                business_date=business_date,
            )
            if rows
            else _web_view_collected_empty_candidate_news_badge()
            if collected_without_evidence_by_code.get(stock_code)
            else _web_view_empty_candidate_news_badge()
        )
        for stock_code, rows in rows_by_code.items()
    }


def _web_view_normalize_news_identity(value: str | None) -> str:
    return (value or "").strip().casefold()


def _web_view_empty_candidate_news_badge() -> dict[str, object]:
    return {
        "available": False,
        "display_label": "뉴스 근거 수집 전",
        "reason": "저장 뉴스 근거를 아직 수집하지 않았습니다.",
        "connection_label": "뉴스 근거 수집 전",
        "connection_reason": "웹뷰에서 뉴스 근거 저장을 실행하면 후보와 연결됩니다.",
        "direct_count": 0,
        "caution_count": 0,
        "market_context_count": 0,
        "krx_reference_status": "missing",
        "observed_at": None,
        "top_title": None,
        "digest_label": None,
        "news_digest": [],
    }


def _web_view_collected_empty_candidate_news_badge() -> dict[str, object]:
    return {
        "available": True,
        "display_label": "매칭 뉴스 없음",
        "reason": "수집은 완료됐지만 이 후보와 직접 연결된 뉴스는 없었습니다.",
        "connection_label": "매칭 뉴스 없음",
        "connection_reason": "수집은 실행됐고, 선택 날짜의 후보와 직접 연결된 뉴스는 없었습니다.",
        "direct_count": 0,
        "caution_count": 0,
        "market_context_count": 0,
        "krx_reference_status": "missing",
        "observed_at": None,
        "top_title": None,
        "digest_label": None,
        "news_digest": [],
    }


def _web_view_news_digest_kind(row: ReportLinkedNewsEvidenceRecord) -> str:
    if row.relevance == "direct":
        return "직접 근거"
    if row.relevance == "market_context":
        return "시장 맥락"
    return "참고 뉴스"


def _web_view_news_digest_priority(row: ReportLinkedNewsEvidenceRecord) -> int:
    if row.relevance == "direct":
        return 0
    if row.relevance == "market_context":
        return 1
    return 2


def _web_view_news_digest_label(row: ReportLinkedNewsEvidenceRecord, *, limit: int = 44) -> str:
    text = re.sub(r"\s+", " ", (row.title or row.summary or "").strip())
    stock_name = (row.stock_name or "").strip()
    if stock_name:
        text = re.sub(rf"^{re.escape(stock_name)}\s*[,，:：·-]?\s*", "", text).strip()
    text = text.strip(" -:：,，·")
    if not text:
        text = row.relevance_reason or row.match_reason or _web_view_news_digest_kind(row)
    if len(text) <= limit:
        return text
    return f"{text[: max(limit - 1, 1)].rstrip()}…"


def _web_view_news_digest_items(
    rows: list[ReportLinkedNewsEvidenceRecord],
    *,
    limit: int,
) -> list[dict[str, object]]:
    items: list[dict[str, object]] = []
    seen: set[tuple[str, str, str]] = set()
    ordered_rows = sorted(
        rows,
        key=lambda row: (_web_view_news_digest_priority(row), -row.published_at.timestamp(), row.title),
    )
    for row in ordered_rows:
        label = _web_view_news_digest_label(row)
        key = (row.published_at.date().isoformat(), _web_view_news_digest_kind(row), label)
        if key in seen:
            continue
        seen.add(key)
        items.append(
            {
                "date": row.published_at.date().isoformat(),
                "stock_name": row.stock_name or row.stock_code or "-",
                "label": label,
                "evidence_label": _web_view_news_digest_kind(row),
                "relevance": row.relevance,
                "source_lane": row.source_lane,
            }
        )
        if len(items) >= max(limit, 0):
            break
    return items


def _web_view_candidate_news_badge(
    rows: list[ReportLinkedNewsEvidenceRecord],
    *,
    business_date: date,
) -> dict[str, object]:
    rows = _web_view_unique_news_evidence_rows(rows)
    if not rows:
        return _web_view_empty_candidate_news_badge()
    direct_count = sum(1 for row in rows if row.relevance == "direct")
    caution_count = sum(1 for row in rows if _web_view_news_observation_is_caution(row))
    positive_direct_count = _web_view_news_observation_positive_direct_count(rows)
    primary_caution_count = _web_view_news_observation_primary_caution_count(rows)
    market_context_count = sum(1 for row in rows if row.relevance == "market_context")
    krx_reference_status = _web_view_news_observation_krx_status(rows, business_date)
    evidence_direction, evidence_direction_reason = _web_view_news_evidence_direction(
        direct_count=direct_count,
        positive_direct_count=positive_direct_count,
        primary_caution_count=primary_caution_count,
    )
    connection_label, connection_reason = _web_view_news_observation_connection(
        direct_count=direct_count,
        caution_count=caution_count,
        positive_direct_count=positive_direct_count,
        primary_caution_count=primary_caution_count,
        market_context_count=market_context_count,
        krx_reference_status=krx_reference_status,
    )
    ordered_rows = sorted(
        rows,
        key=lambda row: (
            0 if row.relevance == "direct" else 1 if row.relevance == "indirect" else 2,
            row.created_at,
            row.title,
        ),
    )
    top_title = next((title for title in _web_view_unique_texts([row.title for row in ordered_rows], limit=1)), None)
    display_label = connection_label
    digest_items = _web_view_news_digest_items(rows, limit=3)
    return {
        "available": True,
        "display_label": display_label,
        "reason": top_title or "저장 뉴스 observation이 같은 후보와 연결됩니다.",
        "direct_count": direct_count,
        "positive_direct_count": positive_direct_count,
        "primary_caution_count": primary_caution_count,
        "caution_count": caution_count,
        "market_context_count": market_context_count,
        "krx_reference_status": krx_reference_status,
        "observed_at": max(row.created_at for row in rows).isoformat(),
        "evidence_direction": evidence_direction,
        "evidence_direction_reason": evidence_direction_reason,
        "top_title": top_title,
        "digest_label": (digest_items[0]["label"] if digest_items else None),
        "news_digest": digest_items,
        "connection_label": connection_label,
        "connection_reason": connection_reason,
    }


def _web_view_news_observation_rows_for_stock(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    stock_code: str,
    stock_name: str | None = None,
) -> list[ReportLinkedNewsEvidenceRecord]:
    normalized_stock_name = _web_view_normalize_news_identity(stock_name)
    if not stock_code and not normalized_stock_name:
        return []
    rows: list[ReportLinkedNewsEvidenceRecord] = []
    runs = repository.list_news_intelligence_runs(target_date=business_date, limit=100)
    for run in runs:
        if stock_code and run.stock_code not in {stock_code, None}:
            continue
        if run.stock_code is None and normalized_stock_name and _web_view_normalize_news_identity(run.stock_name) != normalized_stock_name:
            continue
        rows.extend(
            row
            for row in repository.list_report_linked_news_evidence(run_id=run.run_id, limit=20)
            if row.stock_code == stock_code
            or (normalized_stock_name and _web_view_normalize_news_identity(row.stock_name) == normalized_stock_name)
        )
    return _web_view_unique_news_evidence_rows(rows)


def _web_view_unique_news_evidence_rows(
    rows: list[ReportLinkedNewsEvidenceRecord],
) -> list[ReportLinkedNewsEvidenceRecord]:
    latest_by_key: dict[str, ReportLinkedNewsEvidenceRecord] = {}
    for row in rows:
        key = row.evidence_key or row.url or f"{row.stock_code}:{row.title}:{row.published_at.isoformat()}"
        previous = latest_by_key.get(key)
        if previous is None or (row.created_at, row.run_id) > (previous.created_at, previous.run_id):
            latest_by_key[key] = row
    return list(latest_by_key.values())


def _web_view_stock_news_observation_detail(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    stock_code: str,
    stock_name: str | None = None,
) -> dict[str, object]:
    rows = _web_view_news_observation_rows_for_stock(
        repository,
        business_date=business_date,
        stock_code=stock_code,
        stock_name=stock_name,
    )
    if not rows:
        normalized_stock_name = _web_view_normalize_news_identity(stock_name)
        matching_runs = [
            run
            for run in repository.list_news_intelligence_runs(target_date=business_date, limit=100)
            if run.stock_code == stock_code
            or (normalized_stock_name and _web_view_normalize_news_identity(run.stock_name) == normalized_stock_name)
        ]
        empty = (
            _web_view_collected_empty_candidate_news_badge()
            if matching_runs
            else _web_view_empty_candidate_news_badge()
        )
        return {
            "source": "stored_news_intelligence_observation",
            "read_only": True,
            "live_fetch": False,
            **empty,
            "top_titles": [],
            "empty_state": empty["display_label"],
            "missing_context": ["stored_news_observation"],
        }
    badge = _web_view_candidate_news_badge(rows, business_date=business_date)
    ordered_rows = sorted(
        rows,
        key=lambda row: (
            0 if row.relevance == "direct" else 1 if row.relevance == "indirect" else 2,
            row.created_at,
            row.title,
        ),
    )
    return {
        "source": "stored_news_intelligence_observation",
        "read_only": True,
        "live_fetch": False,
        **badge,
        "top_titles": _web_view_unique_texts([row.title for row in ordered_rows], limit=3),
        "news_digest": _web_view_news_digest_items(rows, limit=5),
    }


def _candidate_evidence_stock_codes(summaries: list[DailyStockSummary]) -> list[str]:
    return sorted({summary.stock_code.strip() for summary in summaries if summary.stock_code and summary.stock_code.strip()})


def _build_candidate_evidence_batch_context(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    summaries: list[DailyStockSummary],
    holiday_overrides: set[date] | frozenset[date] | None = None,
) -> dict[str, object]:
    stock_codes = _candidate_evidence_stock_codes(summaries)
    report_context = _load_candidate_report_context(
        repository,
        business_date=business_date,
        summaries=summaries,
        stock_codes=stock_codes,
        holiday_overrides=holiday_overrides,
    )
    flow_context = _load_candidate_flow_context(repository, business_date=business_date, stock_codes=stock_codes)
    market_history_by_code = _load_candidate_market_history_by_code(
        repository,
        business_date=business_date,
        stock_codes=stock_codes,
    )
    first_target_dates = report_context["first_target_date_by_code"]
    baseline_market_by_code = _candidate_baseline_market_by_code(
        market_history_by_code,
        first_target_dates=first_target_dates,
    )
    market_series_by_code = {
        stock_code: [
            item
            for item in sorted(rows, key=lambda row: row.business_date)
            if item.business_date >= business_date
        ][:21]
        for stock_code, rows in market_history_by_code.items()
    }
    price_history_by_code = {
        stock_code: [
            item
            for item in sorted(rows, key=lambda row: row.business_date, reverse=True)
            if item.business_date <= business_date
        ][:252]
        for stock_code, rows in market_history_by_code.items()
    }
    return {
        **report_context,
        **flow_context,
        "baseline_market_by_code": baseline_market_by_code,
        "market_series_by_code": market_series_by_code,
        "price_history_by_code": price_history_by_code,
    }


def _load_candidate_report_context(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    summaries: list[DailyStockSummary],
    stock_codes: list[str],
    holiday_overrides: set[date] | frozenset[date] | None,
) -> dict[str, object]:
    intensity_by_code: dict[str, dict[str, object]] = {}
    first_target_date_by_code: dict[str, date | None] = {}
    previous_target_by_code: dict[str, dict[str, object]] = {}
    recent_dates = _web_view_recent_business_dates(business_date, count=5, holiday_overrides=holiday_overrides)
    for summary in summaries:
        if summary.stock_code:
            intensity_by_code[summary.stock_code] = {
                "available": False,
                "one_day_report_count": summary.mention_count,
                "five_business_day_report_count": summary.mention_count,
                "five_business_day_active_dates": 1 if summary.mention_count else 0,
                "five_business_day_broker_count": 0,
                "window_business_dates": [item.isoformat() for item in recent_dates],
            }
            first_target_date_by_code[summary.stock_code] = (
                business_date
                if summary.target_price_min is not None or summary.target_price_max is not None
                else None
            )
    if not stock_codes:
        return {
            "report_intensity_by_code": intensity_by_code,
            "first_target_date_by_code": first_target_date_by_code,
            "previous_target_by_code": previous_target_by_code,
        }
    stock_placeholders = ", ".join("?" for _ in stock_codes)
    date_placeholders = ", ".join("?" for _ in recent_dates)
    with repository.connect() as connection:
        intensity_rows = connection.execute(
            f"""
            SELECT
                stock_code,
                COUNT(*) AS report_count,
                COUNT(DISTINCT business_date) AS active_dates,
                COUNT(DISTINCT NULLIF(TRIM(broker_name), '')) AS broker_count
            FROM reports
            WHERE stock_code IN ({stock_placeholders})
              AND business_date IN ({date_placeholders})
            GROUP BY stock_code
            """,
            (*stock_codes, *(item.isoformat() for item in recent_dates)),
        ).fetchall()
        previous_rows = connection.execute(
            f"""
            WITH latest_previous AS (
                SELECT stock_code, MAX(business_date) AS business_date
                FROM reports
                WHERE stock_code IN ({stock_placeholders})
                  AND business_date < ?
                  AND target_price_value IS NOT NULL
                GROUP BY stock_code
            )
            SELECT
                r.stock_code,
                r.business_date,
                MIN(r.target_price_value) AS target_min,
                MAX(r.target_price_value) AS target_max,
                COUNT(*) AS report_count,
                COUNT(DISTINCT NULLIF(TRIM(r.broker_name), '')) AS broker_count
            FROM reports r
            JOIN latest_previous p
              ON p.stock_code = r.stock_code
             AND p.business_date = r.business_date
            WHERE r.target_price_value IS NOT NULL
            GROUP BY r.stock_code, r.business_date
            """,
            (*stock_codes, business_date.isoformat()),
        ).fetchall()
    for row in intensity_rows:
        stock_code = str(row["stock_code"])
        summary = next((item for item in summaries if item.stock_code == stock_code), None)
        one_day_count = summary.mention_count if summary else 0
        report_count = int(row["report_count"] or 0)
        intensity_by_code[stock_code] = {
            "available": report_count > 0,
            "one_day_report_count": one_day_count,
            "five_business_day_report_count": report_count,
            "five_business_day_active_dates": int(row["active_dates"] or 0),
            "five_business_day_broker_count": int(row["broker_count"] or 0),
            "window_business_dates": [item.isoformat() for item in recent_dates],
        }
    for row in previous_rows:
        previous_target_by_code[str(row["stock_code"])] = {
            "previous_date": str(row["business_date"]),
            "previous_min": int(row["target_min"]),
            "previous_max": int(row["target_max"]),
            "previous_report_count": int(row["report_count"] or 0),
            "previous_broker_count": int(row["broker_count"] or 0),
        }
    return {
        "report_intensity_by_code": intensity_by_code,
        "first_target_date_by_code": first_target_date_by_code,
        "previous_target_by_code": previous_target_by_code,
    }


def _load_candidate_flow_context(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    stock_codes: list[str],
) -> dict[str, object]:
    same_day_flow_by_code: dict[str, list[StockInvestorFlowDaily]] = {stock_code: [] for stock_code in stock_codes}
    flow_window_rows_by_code: dict[str, list[sqlite3.Row]] = {stock_code: [] for stock_code in stock_codes}
    if not stock_codes:
        return {
            "same_day_flow_by_code": same_day_flow_by_code,
            "flow_window_rows_by_code": flow_window_rows_by_code,
        }
    placeholders = ", ".join("?" for _ in stock_codes)
    from_date = business_date - timedelta(days=60)
    with repository.connect() as connection:
        rows = connection.execute(
            f"""
            SELECT
                business_date, stock_code, stock_name, market, investor_type,
                sell_volume, buy_volume, net_buy_volume,
                sell_amount, buy_amount, net_buy_amount,
                volume_unit, amount_unit, candidate_score, candidate_reasons,
                fetched_at, source
            FROM stock_investor_flow_daily
            WHERE business_date BETWEEN ? AND ?
              AND stock_code IN ({placeholders})
              AND source = 'krx_data_market'
            ORDER BY stock_code ASC, business_date DESC, investor_type ASC
            """,
            (from_date.isoformat(), business_date.isoformat(), *stock_codes),
        ).fetchall()
    for row in rows:
        stock_code = str(row["stock_code"])
        flow_window_rows_by_code.setdefault(stock_code, []).append(row)
        if row["business_date"] == business_date.isoformat():
            same_day_flow_by_code.setdefault(stock_code, []).append(repository._row_to_stock_investor_flow_daily(row))
    return {
        "same_day_flow_by_code": same_day_flow_by_code,
        "flow_window_rows_by_code": flow_window_rows_by_code,
    }


def _load_candidate_market_history_by_code(
    repository: StockMonitorRepository,
    *,
    business_date: date,
    stock_codes: list[str],
) -> dict[str, list[StockMarketDailySnapshot]]:
    market_history_by_code: dict[str, list[StockMarketDailySnapshot]] = {stock_code: [] for stock_code in stock_codes}
    if not stock_codes:
        return market_history_by_code
    placeholders = ", ".join("?" for _ in stock_codes)
    from_date = business_date - timedelta(days=500)
    to_date = business_date + timedelta(days=90)
    with repository.connect() as connection:
        rows = connection.execute(
            f"""
            SELECT
                business_date, stock_code, stock_name, market, section_name,
                close_price, change_amount, change_percent, open_price, high_price,
                low_price, volume, turnover, market_cap, listed_shares,
                fetched_at, source
            FROM stock_market_daily
            WHERE business_date BETWEEN ? AND ?
              AND stock_code IN ({placeholders})
              AND source = 'krx'
            ORDER BY stock_code ASC, business_date DESC
            """,
            (from_date.isoformat(), to_date.isoformat(), *stock_codes),
        ).fetchall()
    for row in rows:
        item = repository._row_to_stock_market_daily_snapshot(row)
        market_history_by_code.setdefault(item.stock_code, []).append(item)
    return market_history_by_code


def _candidate_baseline_market_by_code(
    market_history_by_code: dict[str, list[StockMarketDailySnapshot]],
    *,
    first_target_dates: dict[str, date | None],
) -> dict[str, StockMarketDailySnapshot | None]:
    baseline_by_code: dict[str, StockMarketDailySnapshot | None] = {}
    for stock_code, baseline_date in first_target_dates.items():
        baseline_by_code[stock_code] = next(
            (
                item
                for item in market_history_by_code.get(stock_code, [])
                if item.business_date == baseline_date
            ),
            None,
        )
    return baseline_by_code


@_web_view_read_session
def build_web_view_candidate_evidence_snapshot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    limit: int = 5,
    now: datetime | None = None,
    include_internal: bool = False,
) -> dict:
    current = now or datetime.now(ZoneInfo(config.timezone))
    summaries = [summary for summary in repository.list_daily_summaries(business_date) if summary.stock_code]
    reports_by_code: dict[str, list[Report]] = {}
    for report in repository.list_reports_for_business_date(business_date):
        if not report.stock_code:
            continue
        reports_by_code.setdefault(report.stock_code, []).append(report)
    market_refs = {
        item.stock_code: item
        for item in repository.list_stock_market_daily_for_codes(
            business_date,
            [summary.stock_code for summary in summaries if summary.stock_code],
        )
    }
    market_flow_rows: list[MarketInvestorFlowDaily] = []
    rank_rows: list[InvestorNetBuyTopDaily] = []
    for market in ("STK", "KSQ", "ALL"):
        market_flow_rows.extend(repository.list_market_investor_flow_daily(business_date, market))
        rank_rows.extend(repository.list_investor_net_buy_top_daily(business_date, market, "foreign", limit=20))
    foreign_rank_by_code = {
        item.stock_code: item
        for item in sorted(rank_rows, key=lambda row: (_web_view_market_sort_key(row.market), row.rank))
        if item.stock_code
    }
    batch_context = _build_candidate_evidence_batch_context(
        repository,
        business_date=business_date,
        summaries=summaries,
        holiday_overrides=config.holiday_overrides,
    )
    news_badges_by_code = _web_view_candidate_news_badges_by_code(
        repository,
        business_date=business_date,
        stock_codes=[summary.stock_code or "" for summary in summaries],
        stock_names_by_code={summary.stock_code or "": summary.stock_name for summary in summaries if summary.stock_code},
    )
    toss_baselines_by_code = {
        row.stock_code: row
        for row in repository.list_toss_priority_quote_baselines(
            business_date=business_date,
            stock_codes=[summary.stock_code or "" for summary in summaries],
            baseline_time="20:00",
        )
    }
    same_day_flow_by_code = batch_context["same_day_flow_by_code"]
    flow_window_rows_by_code = batch_context["flow_window_rows_by_code"]
    price_history_by_code = batch_context["price_history_by_code"]
    report_intensity_by_code = batch_context["report_intensity_by_code"]
    previous_target_by_code = batch_context["previous_target_by_code"]
    first_target_date_by_code = batch_context["first_target_date_by_code"]
    baseline_market_by_code = batch_context["baseline_market_by_code"]
    market_series_by_code = batch_context["market_series_by_code"]
    rows: list[dict[str, object]] = []
    for summary in summaries:
        stock_code = summary.stock_code or ""
        market_reference = market_refs.get(stock_code)
        stock_flow_rows = same_day_flow_by_code.get(stock_code, [])
        reports = reports_by_code.get(stock_code, [])
        broker_count = len({report.broker_name.strip() for report in reports if report.broker_name.strip()})
        if broker_count <= 0:
            broker_count = _web_view_broker_count(summary.broker_display)
        target_range = _web_view_target_price_range(summary)
        rank_reference = foreign_rank_by_code.get(stock_code)
        quality_flags: list[str] = []
        if market_reference is None:
            quality_flags.append("missing_krx_stock_snapshot")
        if not stock_flow_rows:
            quality_flags.append("missing_stock_flow")
        if not target_range["available"]:
            quality_flags.append("missing_target_price")
        if not summary.dominant_opinion or summary.dominant_opinion == "N/A":
            quality_flags.append("missing_valid_opinion")
        if rank_reference is None:
            quality_flags.append("rank_not_present")
        notes = [f"리포트 {summary.mention_count}건"]
        if broker_count:
            notes.append(f"증권사 {broker_count}곳")
        if target_range["available"]:
            notes.append("목표가 범위 있음")
        if market_reference and market_reference.turnover is not None:
            notes.append("KRX 거래대금 있음")
        if stock_flow_rows:
            notes.append("종목별 수급 있음")
        if rank_reference:
            notes.append(f"외국인 순매수 {rank_reference.rank}위")
        report_intensity = report_intensity_by_code.get(stock_code) or _web_view_report_intensity_summary(
            repository,
            stock_code=summary.stock_code,
            business_date=business_date,
            one_day_report_count=summary.mention_count,
            holiday_overrides=config.holiday_overrides,
        )
        target_revision = _web_view_target_revision_summary_from_previous(
            previous_target_by_code.get(stock_code),
            current_min=summary.target_price_min,
            current_max=summary.target_price_max,
        )
        flow_window_reference = _web_view_stock_flow_window_item_from_rows(
            summary,
            business_date=business_date,
            rows=flow_window_rows_by_code.get(stock_code, []),
        )
        price_volume_reference = _web_view_price_volume_position_item_from_rows(
            summary,
            rows=price_history_by_code.get(stock_code, []),
        )
        candidate_profile = _web_view_observation_candidate_profile(
            summary,
            broker_count=broker_count,
            target_range=target_range,
            market_reference=market_reference,
            stock_flow_rows=stock_flow_rows,
            rank_reference=rank_reference,
            report_intensity=report_intensity,
            target_revision=target_revision,
            flow_window_reference=flow_window_reference,
            price_volume_reference=price_volume_reference,
        )
        news_badge = news_badges_by_code.get(
            stock_code,
            _web_view_empty_candidate_news_badge(),
        )
        toss_baseline_reference = _web_view_toss_baseline_reference(
            toss_baselines_by_code.get(stock_code),
            baseline_time="20:00",
        )
        value_profile = _web_view_candidate_value_profile(
            candidate_profile=candidate_profile,
            news_badge=news_badge,
            toss_baseline_reference=toss_baseline_reference,
            market_reference=market_reference,
            stock_flow_rows=stock_flow_rows,
            rank_reference=rank_reference,
            current=current,
            business_date=business_date,
        )
        evidence_layers = _web_view_candidate_evidence_layers(
            primary=candidate_profile["why_notable"],
            support=_web_view_candidate_support_evidence(
                market_reference=market_reference,
                price_volume_reference=price_volume_reference,
                rank_reference=rank_reference,
            ),
            gap=candidate_profile["missing_information"],
        )
        stock_flow_reference = _web_view_stock_flow_totals(stock_flow_rows)
        rows.append(
            {
                "business_date": summary.business_date.isoformat(),
                "stock_code": stock_code,
                "stock_name": summary.stock_name,
                "observation_priority": value_profile["observation_priority"],
                "value_profile": value_profile,
                "why_notable": candidate_profile["why_notable"],
                "missing_information": candidate_profile["missing_information"],
                "evidence_layers": evidence_layers,
                "report_summary": {
                    "report_count": summary.mention_count,
                    "broker_count": broker_count,
                    "broker_display": summary.broker_display,
                    "target_price_min": summary.target_price_min,
                    "target_price_max": summary.target_price_max,
                    "dominant_opinion": summary.dominant_opinion,
                },
                "target_price_range": target_range,
                "report_intensity": report_intensity,
                "target_price_revision": target_revision,
                "target_price_progress": _web_view_target_price_progress_from_rows(
                    summary,
                    market_reference,
                    baseline_date=first_target_date_by_code.get(stock_code),
                    baseline_market=baseline_market_by_code.get(stock_code),
                    market_series=market_series_by_code.get(stock_code, []),
                ),
                "opinion_summary": summary.dominant_opinion,
                "market_reference": _web_view_stock_market_reference(market_reference),
                "stock_flow_reference": stock_flow_reference,
                "value_context": _web_view_value_context(
                    report_reference_date=summary.business_date,
                    market_reference=market_reference,
                    stock_flow_reference=stock_flow_reference,
                    news_reference=news_badge,
                    toss_baseline_reference=toss_baseline_reference,
                ),
                "flow_window_reference": flow_window_reference,
                "price_volume_reference": price_volume_reference,
                "rank_reference": {
                    "foreign_top_rank": rank_reference.rank if rank_reference else None,
                    "market": _web_view_market_display(rank_reference.market) if rank_reference else None,
                },
                "news_observation_badge": news_badge,
                "toss_baseline_reference": toss_baseline_reference,
                "quality_flags": quality_flags,
                "evidence_notes": notes,
                "_internal_candidate_signals": candidate_profile["internal_candidate_signals"],
                "_internal_missing_information": candidate_profile["internal_missing_information"],
                "_sort_density": candidate_profile["sort_density"],
                "_sort_signal": candidate_profile["sort_signal"],
                "_sort_value_signal": value_profile["sort_value_signal"],
            }
        )
    rows.sort(
        key=lambda item: (
            int(item.get("_sort_value_signal") or 0),
            int(item.get("_sort_signal") or 0),
            int(item.get("_sort_density") or 0),
            int((item["report_summary"] or {}).get("report_count") or 0),
            int((item["report_summary"] or {}).get("broker_count") or 0),
            int((item["market_reference"] or {}).get("turnover") or 0),
            str(item["stock_code"]),
        ),
        reverse=True,
    )
    picked_rows: list[dict[str, object]] = []
    internal_keys = {
        "_internal_candidate_signals",
        "_internal_missing_information",
        "_sort_density",
        "_sort_signal",
        "_sort_value_signal",
    }
    for index, row in enumerate(rows[:limit]):
        item = {key: value for key, value in row.items() if key not in internal_keys}
        if index < 2:
            item["intraday_reference"] = _web_view_candidate_intraday_reference_placeholder()
        if include_internal:
            item["internal_candidate_signals"] = row.get("_internal_candidate_signals") or []
            item["internal_missing_information"] = row.get("_internal_missing_information") or []
            item["sort_tuple"] = {
                "sort_value_signal": int(row.get("_sort_value_signal") or 0),
                "sort_signal": int(row.get("_sort_signal") or 0),
                "sort_density": int(row.get("_sort_density") or 0),
                "report_count": int((row.get("report_summary") or {}).get("report_count") or 0),
                "broker_count": int((row.get("report_summary") or {}).get("broker_count") or 0),
                "turnover": int((row.get("market_reference") or {}).get("turnover") or 0),
                "stock_code": str(row.get("stock_code") or ""),
            }
        else:
            report_summary = dict(item.get("report_summary") or {})
            item["report_summary"] = {
                "report_count": report_summary.get("report_count"),
                "target_price_min": report_summary.get("target_price_min"),
                "target_price_max": report_summary.get("target_price_max"),
            }
            item.pop("quality_flags", None)
            item.pop("evidence_notes", None)
            item.pop("opinion_summary", None)
            report_intensity = dict(item.get("report_intensity") or {})
            report_intensity.pop("five_business_day_broker_count", None)
            item["report_intensity"] = report_intensity
            target_price_revision = dict(item.get("target_price_revision") or {})
            target_price_revision.pop("previous_broker_count", None)
            item["target_price_revision"] = target_price_revision
        picked_rows.append(item)
    return {
        "now": current.isoformat(),
        "timezone": config.timezone,
        "surface": "web-view",
        "read_only": True,
        "business_date": business_date.isoformat(),
        "available": bool(picked_rows),
        "data_scope": "stored_report_krx_evidence",
        "live_fetch": False,
        "scoring": False,
        "recommendation": False,
        "display_policy": "관찰 후보는 저장된 리포트와 KRX/수급 참고값을 확인용으로 묶어 보여줍니다.",
        "notice": "오늘의 관찰 후보는 저장된 리포트/KRX/[12009] 수급 참고값 기준입니다. 실시간 시세가 아닙니다.",
        "market_flow_context": [_web_view_market_investor_flow_item(item) for item in sorted(
            market_flow_rows,
            key=lambda row: (_web_view_market_sort_key(row.market), _web_view_investor_sort_key(row.investor_type)),
        )],
        "rows": picked_rows,
    }


def _web_view_toss_baseline_reference(
    row: TossPriorityQuoteBaseline | None,
    *,
    baseline_time: str,
) -> dict[str, object]:
    base = {
        "source": "toss_openapi",
        "read_only": True,
        "live_fetch": False,
        "writes_db": False,
        "baseline_time": baseline_time,
        "affects_ordering": False,
    }
    if row is None:
        return {
            **base,
            "available": False,
            "reference_time": None,
            "last_price": None,
            "currency": None,
            "notice": "Toss 20:00 기준 저장값 없음",
        }
    return {
        **base,
        "available": True,
        "reference_time": row.fetched_at.isoformat(),
        "last_price": row.last_price,
        "currency": row.currency,
        "notice": "Toss 20:00 기준 저장값",
    }


def _web_view_candidate_intraday_reference_placeholder() -> dict[str, object]:
    return {
        "available": False,
        "source_configured": False,
        "read_only": True,
        "live_fetch": False,
        "scope": "top_2_priority_candidates",
        "cadence_minutes": 5,
        "reference_time": None,
        "price": None,
        "change_percent": None,
        "turnover": None,
        "affects_ordering": False,
        "notice": "장중 실시간 참고 소스가 아직 확정되지 않았습니다.",
    }


def _web_view_candidate_evidence_layers(
    *,
    primary: object,
    support: object,
    gap: object,
) -> dict[str, list[str]]:
    return {
        "primary": _public_label_list(primary),
        "support": _public_label_list(support),
        "gap": _public_label_list(gap),
    }


def _public_label_list(values: object) -> list[str]:
    if not isinstance(values, list):
        return []
    labels: list[str] = []
    for value in values:
        label = str(value or "").strip()
        if label and label not in labels:
            labels.append(label)
    return labels


def _web_view_candidate_support_evidence(
    *,
    market_reference: StockMarketDailySnapshot | None,
    price_volume_reference: dict,
    rank_reference: InvestorNetBuyTopDaily | None,
) -> list[str]:
    labels: list[str] = []
    if market_reference is not None and market_reference.close_price is not None:
        labels.append("KRX 가격 참고")
    if market_reference is not None and market_reference.turnover is not None:
        labels.append("거래대금 참고")
    if price_volume_reference.get("available"):
        if price_volume_reference.get("close_position_52w_percent") is not None:
            labels.append("52주 위치 참고")
        if price_volume_reference.get("volume_multiple_20d") is not None:
            labels.append("거래량 위치 참고")
        if not any(label in labels for label in ("52주 위치 참고", "거래량 위치 참고")):
            labels.append("가격 위치 참고")
    if rank_reference is not None:
        labels.append("외국인 순매수 상위 참고")
    return labels


def _web_view_observation_candidate_profile(
    summary: DailyStockSummary,
    *,
    broker_count: int,
    target_range: dict,
    market_reference: StockMarketDailySnapshot | None,
    stock_flow_rows: list[StockInvestorFlowDaily],
    rank_reference: InvestorNetBuyTopDaily | None,
    report_intensity: dict[str, object],
    target_revision: dict[str, object],
    flow_window_reference: dict,
    price_volume_reference: dict,
) -> dict[str, object]:
    reasons: list[str] = []
    internal_signals: list[str] = []
    if summary.mention_count >= 2:
        reasons.append("리포트 집중")
        internal_signals.append("리포트 집중")
    elif summary.mention_count > 0:
        internal_signals.append("리포트 언급")
    if broker_count >= 2:
        internal_signals.append("브로커 폭")
    if target_range.get("available"):
        internal_signals.append("목표가 범위")
    if target_revision.get("available"):
        direction_label = str(target_revision.get("direction_label") or "").strip()
        revision_label = f"목표가 {direction_label}" if direction_label else "목표가 변화"
        reasons.append(revision_label)
        internal_signals.append(revision_label)
    if market_reference is not None and market_reference.turnover is not None:
        internal_signals.append("거래대금 참고")
    has_stock_flow = bool(stock_flow_rows)
    has_flow_persistence = _web_view_flow_reference_has_persistence(flow_window_reference)
    if has_stock_flow:
        internal_signals.append("종목별 수급")
    if has_flow_persistence:
        internal_signals.append("수급 전환 지속")
        if has_stock_flow:
            reasons.append("수급 전환 지속")
    if price_volume_reference.get("available"):
        internal_signals.append("가격/거래량 위치")
    if rank_reference is not None:
        internal_signals.append("외국인 순매수 상위")

    missing: list[str] = []
    internal_missing: list[str] = []
    if market_reference is None:
        missing.append("선택일 KRX 저장값 없음")
        internal_missing.append("당일 KRX 없음")
    if not stock_flow_rows:
        missing.append("종목 수급 저장값 없음")
        internal_missing.append("종목 수급 데이터 없음")
    if not target_range.get("available"):
        missing.append("목표가 정보 없음")
        internal_missing.append("목표가 정보 없음")
    if not summary.dominant_opinion or summary.dominant_opinion == "N/A":
        missing.append("투자의견 정보 없음")
        internal_missing.append("투자의견 정보 없음")
    if rank_reference is None:
        internal_missing.append("외국인 순매수 상위 미포함")
    if not price_volume_reference.get("available"):
        internal_missing.append("가격/거래량 위치 없음")

    sort_density = len(reasons)
    priority_signal = 0
    if has_flow_persistence and has_stock_flow:
        priority_signal += 2
    if target_revision.get("available"):
        priority_signal += 1
    if summary.mention_count >= 2:
        priority_signal += 1
    sort_signal = priority_signal
    if has_stock_flow and any(label != "리포트 집중" for label in reasons):
        sort_signal += 2
    if priority_signal >= 3:
        priority = "우선 확인"
    elif priority_signal >= 1:
        priority = "확인 후보"
    else:
        priority = "정보 보강"
    return {
        "observation_priority": priority,
        "why_notable": reasons,
        "missing_information": missing,
        "internal_candidate_signals": internal_signals,
        "internal_missing_information": internal_missing,
        "sort_density": sort_density,
        "sort_signal": sort_signal,
    }


def _web_view_candidate_value_profile(
    *,
    candidate_profile: dict,
    news_badge: dict,
    toss_baseline_reference: dict,
    market_reference: object | None,
    stock_flow_rows: list[object],
    rank_reference: object | None,
    current: datetime,
    business_date: date,
) -> dict[str, object]:
    direct_count = int(news_badge.get("direct_count") or 0)
    positive_direct_count = int(news_badge.get("positive_direct_count") or 0)
    primary_caution_count = int(news_badge.get("primary_caution_count") or 0)
    caution_count = int(news_badge.get("caution_count") or 0)
    market_context_count = int(news_badge.get("market_context_count") or 0)
    news_available = news_badge.get("available") is True
    news_label = str(news_badge.get("display_label") or news_badge.get("connection_label") or "").strip()
    has_actionable_news = direct_count > 0 or caution_count > 0 or market_context_count > 0
    news_collected_no_match = news_available and not has_actionable_news
    has_market_reference = market_reference is not None
    has_stock_flow = bool(stock_flow_rows)
    has_toss_baseline = toss_baseline_reference.get("available") is True
    has_rank_reference = rank_reference is not None
    why_notable = [str(item) for item in candidate_profile.get("why_notable") or []]
    target_only = bool(why_notable) and all(item.startswith("목표가") for item in why_notable)
    base_signal = int(candidate_profile.get("sort_signal") or 0)
    value_signal = base_signal
    evidence_direction, evidence_direction_reason = _web_view_news_evidence_direction(
        direct_count=direct_count,
        positive_direct_count=positive_direct_count,
        primary_caution_count=primary_caution_count,
    )
    same_day = business_date == current.date()
    current_time = current.time()
    if same_day and datetime_time(9, 0) <= current_time <= datetime_time(15, 30):
        time_mode = "intraday"
    elif same_day and current_time >= datetime_time(20, 0):
        time_mode = "toss_20_baseline"
    elif same_day:
        time_mode = "same_day_after_hours"
    else:
        time_mode = "stored_history"

    if positive_direct_count > 0 and primary_caution_count == 0:
        observation_priority = "우선 확인"
        value_label = evidence_direction
        value_reason = evidence_direction_reason
        if direct_count > 0:
            support_parts = []
            if caution_count > 0:
                support_parts.append(f"보조 확인 {caution_count}건")
            if market_context_count > 0:
                support_parts.append(f"시장맥락 {market_context_count}건")
            support_note = " · " + " · ".join(support_parts) if support_parts else ""
            value_reason = f"{value_reason}{support_note}"
    elif positive_direct_count > 0 and primary_caution_count > 0:
        observation_priority = "근거 엇갈림"
        value_label = evidence_direction
        value_reason = evidence_direction_reason
    elif primary_caution_count > 0:
        observation_priority = "주의 확인"
        value_label = evidence_direction
        value_reason = evidence_direction_reason
    elif direct_count > 0:
        observation_priority = str(candidate_profile.get("observation_priority") or "확인 후보")
        value_label = evidence_direction
        value_reason = evidence_direction_reason
    elif market_context_count > 0:
        observation_priority = str(candidate_profile.get("observation_priority") or "확인 후보")
        value_label = "시장 맥락 참고"
        value_reason = "시장맥락 뉴스는 직접 후보 판단과 분리해 확인합니다."
    elif target_only and news_collected_no_match and (not has_market_reference or not has_stock_flow):
        observation_priority = "정보 보강"
        value_label = "정보 보강"
        value_reason = "목표가 변화 단독이고 뉴스 매칭/KRX/수급 확인이 부족합니다."
    elif news_collected_no_match:
        observation_priority = str(candidate_profile.get("observation_priority") or "확인 후보")
        value_label = "뉴스 매칭 없음"
        value_reason = "뉴스 수집은 완료됐지만 후보와 직접 연결된 기사는 없었습니다."
    elif not news_available and time_mode == "intraday":
        observation_priority = str(candidate_profile.get("observation_priority") or "확인 후보")
        value_label = "실시간 확인 대기"
        value_reason = "장중에는 뉴스/거래대금 확인 후 우선순위를 다시 봐야 합니다."
    else:
        observation_priority = str(candidate_profile.get("observation_priority") or "확인 후보")
        value_label = "저장 근거 확인"
        value_reason = "저장 리포트와 시장 참고값 기준 후보입니다."

    reference_notes: list[str] = []
    if has_actionable_news:
        if direct_count > 0 or caution_count > 0:
            reference_notes.append("뉴스: 후보 직접 근거 있음")
        else:
            reference_notes.append("뉴스: 시장 맥락 근거 있음")
    elif news_available:
        reference_notes.append("뉴스: 직접 매칭 없음")
    else:
        reference_notes.append("뉴스: 수집 전")
    if not has_market_reference:
        reference_notes.append("KRX: 선택일 저장값 없음")
    if not has_stock_flow:
        reference_notes.append("수급: 저장값 없음")
    if has_toss_baseline:
        reference_notes.append("20:00 저장 현재가 기준")
    return {
        "observation_priority": observation_priority,
        "value_label": value_label,
        "value_reason": value_reason,
        "evidence_direction": evidence_direction,
        "evidence_direction_reason": evidence_direction_reason,
        "time_mode": time_mode,
        "news_confirmed": has_actionable_news,
        "news_collected": news_available,
        "market_reference_available": has_market_reference,
        "stock_flow_available": has_stock_flow,
        "toss_20_available": has_toss_baseline,
        "rank_reference_available": has_rank_reference,
        "reference_notes": reference_notes[:4],
        "sort_value_signal": value_signal,
    }


def _web_view_flow_reference_has_persistence(flow_window_reference: dict) -> bool:
    persistence = flow_window_reference.get("persistence") if isinstance(flow_window_reference, dict) else None
    if not isinstance(persistence, dict):
        return False
    for item in persistence.values():
        if isinstance(item, dict) and item.get("available") and int(item.get("streak_days") or 0) >= 2:
            return True
    return False


def build_web_view_backtest_observation_snapshot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    business_date: date,
    mention_threshold: int = 2,
    limit: int = 20,
    now: datetime | None = None,
) -> dict:
    current = now or datetime.now(ZoneInfo(config.timezone))
    rows = build_backtest_observation_rows(
        repository,
        business_date=business_date,
        mention_threshold=mention_threshold,
    )
    picked_rows = rows[:limit]
    return {
        "now": current.isoformat(),
        "timezone": config.timezone,
        "surface": "web-view",
        "read_only": True,
        "business_date": business_date.isoformat(),
        "available": bool(picked_rows),
        "data_scope": "stored_report_krx_backtest_observation",
        "live_fetch": False,
        "scoring": False,
        "recommendation": False,
        "mention_threshold": mention_threshold,
        "horizons": [1, 5, 10, 20],
        "notice": "저장된 2026년 리포트/KRX 가격/수급 기준의 리포트 후 흐름입니다. 저장 데이터 기반 확인용입니다.",
        "rows": [_web_view_backtest_observation_row(item) for item in picked_rows],
    }


def _web_view_backtest_observation_row(item) -> dict:
    summary = item.summary
    row = {
        "business_date": summary.business_date.isoformat(),
        "stock_code": summary.stock_code,
        "stock_name": summary.stock_name,
        "report_summary": {
            "report_count": summary.mention_count,
            "broker_count": _web_view_broker_count(summary.broker_display),
            "broker_display": summary.broker_display,
            "target_price_min": summary.target_price_min,
            "target_price_max": summary.target_price_max,
            "dominant_opinion": summary.dominant_opinion,
        },
        "base_market": _web_view_stock_market_reference(item.base_market),
        "reaction_windows": [_web_view_reaction_window(row) for row in item.reaction_windows],
        "target_observation": _web_view_target_observation(item.target_observation),
        "stock_flow_observation": _web_view_stock_flow_observation(item.stock_flow_observation),
        "net_buy_top_observation": _web_view_net_buy_top_observation(item.net_buy_top_observation),
    }
    row["evidence_notes"] = _web_view_backtest_evidence_notes(row)
    return row


def _web_view_backtest_evidence_notes(row: dict) -> list[str]:
    report_summary = row.get("report_summary") or {}
    target = row.get("target_observation") or {}
    flow = row.get("stock_flow_observation") or {}
    top = row.get("net_buy_top_observation") or {}
    reactions = row.get("reaction_windows") or []

    notes: list[str] = []
    report_count = report_summary.get("report_count")
    if report_count is not None:
        notes.append(f"리포트 {int(report_count)}건")
    target_values = [
        report_summary.get("target_price_min"),
        report_summary.get("target_price_max"),
        target.get("target_price_min"),
        target.get("target_price_max"),
    ]
    has_target_price = any(value is not None for value in target_values)
    if has_target_price:
        notes.append("목표가 있음")
        if not target.get("available") and target.get("unavailable_reason") == "missing_base_close_price":
            notes.append("KRX 기준가 대기")
    else:
        notes.append("목표가 없음")
    notes.append("당일 수급 있음" if flow.get("available") else "당일 수급 없음")
    notes.append("외국인 순매수 상위 포함" if top.get("available") else "외국인 순매수 상위 미포함")

    available_horizons = [
        f"D+{int(item['horizon_days'])}"
        for item in reactions
        if item.get("available") and item.get("horizon_days") is not None
    ]
    pending_horizons = [
        f"D+{int(item['horizon_days'])}"
        for item in reactions
        if not item.get("available") and item.get("horizon_days") is not None
    ]
    if available_horizons:
        notes.append(f"{'/'.join(available_horizons)} 반응 가능")
    if pending_horizons:
        notes.append(f"{'/'.join(pending_horizons)} 대기")
    return notes


