def _web_view_category_contract(
    rollups: list[object] | None = None,
    *,
    category_mapping: dict[str, object] | None = None,
) -> dict:
    rollups = rollups or []
    snapshot_dates = sorted(
        {
            item.snapshot_date.isoformat()
            for item in rollups
            if getattr(item, "snapshot_date", None) is not None
        },
        reverse=True,
    )
    if not snapshot_dates and category_mapping and category_mapping.get("mapping_basis") == "dated_snapshot":
        snapshot_dates = sorted(
            {
                str(value)
                for key, value in category_mapping.items()
                if key.endswith("_snapshot_date") and value
            },
            reverse=True,
        )
    if snapshot_dates:
        return {
            "mapping_basis": "dated_snapshot",
            "dated_snapshots_available": True,
            "snapshot_dates": snapshot_dates,
            "notice": "업종/테마는 선택 날짜 이하의 가장 가까운 저장 스냅샷 기준입니다. 실시간 갱신이나 확정 판단은 포함하지 않습니다.",
        }
    return {
        "mapping_basis": "latest_mapping_fallback",
        "dated_snapshots_available": False,
        "snapshot_dates": [],
        "notice": "선택 날짜 이전의 카테고리 스냅샷이 없어 최신 저장 분류 기준으로 표시합니다.",
    }


def _web_view_category_notice(rollups: list[object]) -> str:
    return _web_view_category_contract(rollups)["notice"]


