def _web_view_intraday_status_label(status: str) -> str:
    if status == "sent":
        return "발송됨"
    if status == "pending":
        return "대기"
    return "확인필요"


def _build_web_view_watch_candidates(summaries: list[DailyStockSummary], *, limit: int = 5) -> list[dict]:
    candidates: list[dict] = []
    for summary in summaries:
        reasons: list[str] = []
        if summary.mention_count >= 2:
            reasons.append(f"리포트 {summary.mention_count}건")
        if summary.target_price_min is not None or summary.target_price_max is not None:
            reasons.append("목표가 있음")
        if len(reasons) < 2:
            continue
        candidates.append(
            {
                "stock_name": summary.stock_name,
                "stock_code": summary.stock_code,
                "mention_count": summary.mention_count,
                "target_price_min": summary.target_price_min,
                "target_price_max": summary.target_price_max,
                "dominant_opinion": summary.dominant_opinion,
                "reason": " · ".join(reasons),
            }
        )
    candidates.sort(
        key=lambda item: (
            int(item["mention_count"] or 0),
            int(item["target_price_max"] or item["target_price_min"] or 0),
            str(item["stock_name"]),
        ),
        reverse=True,
    )
    return candidates[:limit]


def _build_market_mood_snapshot(
    business_date: date | None,
    summaries: list[DailyStockSummary],
    sector_rollups: list[object],
) -> dict:
    active_sector_rollups = [
        item
        for item in sector_rollups
        if (getattr(item, "sector_name", None) or getattr(item, "display_name", None))
        and (getattr(item, "sector_name", None) or getattr(item, "display_name", None)) != "N/A"
    ]
    top_sector = active_sector_rollups[0] if active_sector_rollups else None
    return {
        "business_date": business_date.isoformat() if business_date else None,
        "total_reports": sum(summary.mention_count for summary in summaries),
        "stock_count": len(summaries),
        "active_sector_count": len(active_sector_rollups),
        "top_sector_name": (getattr(top_sector, "sector_name", None) or getattr(top_sector, "display_name", None)) if top_sector else None,
        "top_sector_report_count": getattr(top_sector, "report_count", 0) if top_sector else 0,
        "multi_report_stock_count": sum(1 for summary in summaries if summary.mention_count >= 2),
        "target_price_stock_count": sum(
            1
            for summary in summaries
            if summary.target_price_min is not None or summary.target_price_max is not None
        ),
    }


def _db_run_suppressed_date_details(repository: StockMonitorRepository) -> dict[str, str]:
    details: dict[str, str] = {}
    for control in repository.list_operator_controls(prefix="run_suppressed_date:"):
        _, raw_date = control.control_key.split(":", 1)
        details[raw_date] = control.detail or ""
    return details


def _worker_state_to_snapshot(state: WorkerState) -> dict:
    return {
        "worker_name": state.worker_name,
        "status": state.status,
        "updated_at": state.updated_at.isoformat(),
        "last_started_at": state.last_started_at.isoformat() if state.last_started_at else None,
        "last_success_at": state.last_success_at.isoformat() if state.last_success_at else None,
        "last_error_at": state.last_error_at.isoformat() if state.last_error_at else None,
        "last_error": state.last_error,
        "interval_seconds": state.interval_seconds,
        "end_time": state.end_time,
    }


def _build_worker_states_snapshot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    current: datetime,
) -> dict[str, dict]:
    states = {state.worker_name: _worker_state_to_snapshot(state) for state in repository.list_worker_states()}
    telegram_state = states.get(TELEGRAM_COMMAND_LOOP_WORKER)
    if telegram_state is None:
        telegram_state = {
            "worker_name": TELEGRAM_COMMAND_LOOP_WORKER,
            "status": "unknown",
            "updated_at": None,
            "last_started_at": None,
            "last_success_at": None,
            "last_error_at": None,
            "last_error": None,
            "interval_seconds": None,
            "end_time": "16:30",
        }
    telegram_state = dict(telegram_state)
    telegram_state["is_stale"] = _is_telegram_worker_stale(config, repository, current, telegram_state)
    states[TELEGRAM_COMMAND_LOOP_WORKER] = telegram_state
    return states


def _is_telegram_worker_stale(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    current: datetime,
    state: dict,
) -> bool:
    current_time = current.timetz().replace(tzinfo=None)
    if _scheduled_skip_reason(config, current.date(), repository):
        return False
    if current_time < datetime_time(hour=8, minute=0) or current_time > config.poll_end_time:
        return False
    last_success_raw = state.get("last_success_at")
    if not last_success_raw:
        return True
    last_success = _parse_status_datetime(last_success_raw, config.timezone)
    interval = int(state.get("interval_seconds") or 60)
    grace_seconds = max(interval * 3, 180)
    return (current - last_success).total_seconds() > grace_seconds


def _build_operator_health_snapshot(
    config: RuntimeConfig,
    current: datetime,
    scheduler_tasks: list[dict],
    worker_states: dict[str, dict],
    live_observation: dict | None = None,
    market_holiday_coverage: dict | None = None,
) -> dict:
    failing_checks: list[str] = []
    warning_checks: list[str] = []
    for task in scheduler_tasks:
        task_key = _scheduler_task_key(config.scheduler_task_prefix, task["task_name"])
        status_class = task.get("status_class")
        if task_key == "shutdown":
            continue
        if task_key == "krx-flow-login-reminder" and status_class in {"disabled", "missing", "unavailable"}:
            continue
        if task_key == "krx-flow-login-reminder" and status_class == "access_denied":
            warning_checks.append(f"scheduler.{task_key}.{status_class}")
            continue
        if status_class in {"failed", "access_denied", "stale"}:
            failing_checks.append(f"scheduler.{task_key}.{status_class}")
        elif status_class in {"missing", "disabled", "unavailable"}:
            warning_checks.append(f"scheduler.{task_key}.{status_class}")

    telegram_worker = worker_states.get(TELEGRAM_COMMAND_LOOP_WORKER, {})
    if telegram_worker.get("is_stale"):
        failing_checks.append("telegram_worker.heartbeat_stale")
    elif telegram_worker.get("status") == "error":
        warning_checks.append("telegram_worker.error")

    timeout_trace = (live_observation or {}).get("telegram_timeout_trace", {})
    if timeout_trace.get("ambiguous_failure_count", 0):
        warning_checks.append("telegram.timeout_trace.ambiguous_send")

    for component_key, component in (live_observation or {}).get("components", {}).items():
        if component.get("evidence_status") != "attention":
            continue
        last_event = component.get("last_event") or {}
        reason = str(component.get("attention_reason") or last_event.get("status") or "attention")
        warning_checks.append(f"live_observation.{component_key}.{reason}")

    if (market_holiday_coverage or {}).get("renewal_required"):
        warning_checks.append("market_holidays.default_coverage_expiring")

    level = "fail" if failing_checks else "warn" if warning_checks else "ok"
    total = len(failing_checks) + len(warning_checks)
    return {
        "level": level,
        "failing_checks": failing_checks,
        "warning_checks": warning_checks,
        "summary": "ok" if total == 0 else f"{total} health check(s) need attention",
    }


def _build_live_observation_snapshot(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    current: datetime,
    scheduler_tasks: list[dict],
    worker_states: dict[str, dict],
    events: list[OperationEvent],
) -> dict:
    non_shutdown_tasks = [
        task
        for task in scheduler_tasks
        if _scheduler_task_key(config.scheduler_task_prefix, task["task_name"]) != "shutdown"
    ]
    access_denied_count = sum(1 for task in non_shutdown_tasks if task.get("status_class") == "access_denied")
    if non_shutdown_tasks and access_denied_count == len(non_shutdown_tasks):
        scheduler_metadata_status = "access_denied"
    elif access_denied_count:
        scheduler_metadata_status = "partial_access_denied"
    elif scheduler_tasks:
        scheduler_metadata_status = "available"
    else:
        scheduler_metadata_status = "not_returned"

    specs = {
        "notify": ("notify", {"send", "fragment", "early_notify", "late_notify", "run-guard"}),
        "poll": ("poll", {"manual-poll", "time-window", "run-guard"}),
        "krx_daily_backfill": ("krx", {"scheduled-daily-backfill", "backfill-missing"}),
        "krx_mentioned_flow_backfill": ("krx-flow", {"scheduled-mentioned-flow-backfill"}),
        "telegram_command_loop": ("telegram-command-loop", {"time-window", "run-guard", "iteration"}),
    }
    components: dict[str, dict] = {}
    for key, (component, event_types) in specs.items():
        event = _latest_live_event_for(
            current,
            events,
            component=component,
            event_types=event_types,
            prefer_latest_time=key == "krx_daily_backfill",
        )
        evidence_status = _live_event_evidence_status(event)
        attention_reason = None
        if key == "krx_daily_backfill" and event and event.status in {"empty", "partial"}:
            attention_reason = event.status
        elif key == "krx_daily_backfill" and _krx_daily_backfill_event_has_incomplete_snapshots(repository, event):
            evidence_status = "attention"
            attention_reason = "incomplete_snapshot"
        if event is None and _live_observation_component_not_yet_due(config, current, key):
            evidence_status = "pending"
        component_status = {
            "evidence_status": evidence_status,
            "last_event": _operation_event_to_status_dict(event) if event else None,
        }
        if attention_reason:
            component_status["attention_reason"] = attention_reason
        components[key] = component_status

    telegram_worker = worker_states.get(TELEGRAM_COMMAND_LOOP_WORKER)
    if telegram_worker and components["telegram_command_loop"]["evidence_status"] == "missing":
        worker_updated_at = _parse_status_datetime(telegram_worker.get("updated_at"), config.timezone)
        if worker_updated_at and worker_updated_at.date() == current.date():
            components["telegram_command_loop"] = {
                "evidence_status": "observed" if telegram_worker.get("status") != "error" else "failed",
                "last_event": {
                    "event_time": worker_updated_at.isoformat(),
                    "component": "telegram-command-loop",
                    "event_type": "worker-state",
                    "status": str(telegram_worker.get("status") or "unknown"),
                    "business_date": current.date().isoformat(),
                    "detail": f"last_success_at={telegram_worker.get('last_success_at') or '-'}",
                },
            }

    operator_action = None
    if scheduler_metadata_status in {"access_denied", "partial_access_denied"}:
        operator_action = "Run operator-status from an elevated local shell to verify Task Scheduler metadata."
    return {
        "scheduler_metadata_status": scheduler_metadata_status,
        "components": components,
        "telegram_timeout_trace": _build_telegram_timeout_trace(current, events),
        "operator_action": operator_action,
    }


def _build_telegram_timeout_trace(current: datetime, events: list[OperationEvent]) -> dict:
    ambiguous_events = [
        event
        for event in events
        if event.event_time.date() == current.date()
        and event.component == "notify"
        and event.event_type == "fragment"
        and event.status == "failed"
        and "ambiguous_send=true" in event.detail
    ]
    latest = sorted(ambiguous_events, key=lambda event: event.event_time, reverse=True)[0] if ambiguous_events else None
    return {
        "ambiguous_failure_count": len(ambiguous_events),
        "latest": _telegram_timeout_trace_event(latest) if latest else None,
    }


def _telegram_timeout_trace_event(event: OperationEvent) -> dict:
    return {
        "event_time": event.event_time.isoformat(),
        "business_date": event.business_date.isoformat() if event.business_date else None,
        "run_id": _extract_detail_field(event.detail, "run_id"),
        "fragment": _extract_detail_field(event.detail, "fragment"),
        "message_hash": _extract_detail_field(event.detail, "message_hash"),
        "detail": event.detail,
    }


def _extract_detail_field(detail: str | None, key: str) -> str | None:
    if not detail:
        return None
    prefix = f"{key}="
    for part in detail.split(";"):
        stripped = part.strip()
        if stripped.startswith(prefix):
            return stripped.removeprefix(prefix).strip() or None
    return None


def _latest_live_event_for(
    current: datetime,
    events: list[OperationEvent],
    *,
    component: str,
    event_types: set[str],
    prefer_latest_time: bool = False,
) -> OperationEvent | None:
    candidates: list[OperationEvent] = []
    for event in events:
        if event.event_time.date() != current.date():
            continue
        if event.component != component:
            continue
        if event.event_type not in event_types:
            continue
        candidates.append(event)
    if not candidates:
        return None
    sort_key = _live_event_time_sort_key if prefer_latest_time else _live_event_sort_key
    return sorted(candidates, key=sort_key, reverse=True)[0]


def _live_event_status_priority(event: OperationEvent) -> int:
    status_priority = {
        "empty": 5,
        "partial": 5,
        "success": 4,
        "sent": 4,
        "sent_empty": 4,
        "requested": 3,
        "stopped": 2,
        "skipped": 1,
        "failed": 0,
        "error": 0,
    }
    return status_priority.get(event.status, 2)


def _live_event_sort_key(event: OperationEvent) -> tuple[int, datetime]:
    return (_live_event_status_priority(event), event.event_time)


def _live_event_time_sort_key(event: OperationEvent) -> tuple[datetime, int]:
    return (event.event_time, _live_event_status_priority(event))


def _live_event_evidence_status(event: OperationEvent | None) -> str:
    if event is None:
        return "missing"
    if event.status in {"failed", "error"}:
        return "failed"
    if event.status in {"empty", "partial"}:
        return "attention"
    return "observed"


def _krx_daily_backfill_event_has_incomplete_snapshots(
    repository: StockMonitorRepository,
    event: OperationEvent | None,
) -> bool:
    if event is None or event.component != "krx" or event.event_type != "backfill-missing":
        return False
    if event.business_date is None:
        return False
    endpoint_selector = _extract_detail_field(event.detail, "endpoint") or "daily"
    try:
        endpoint_keys = _resolve_krx_backfill_endpoint_keys(endpoint_selector)
    except ValueError:
        endpoint_keys = KRX_DAILY_BACKFILL_ENDPOINT_KEYS
    counts = repository.count_krx_snapshot_rows_for_date(event.business_date)
    return bool(_incomplete_krx_daily_endpoints(counts, endpoint_keys))


def _live_observation_component_not_yet_due(config: RuntimeConfig, current: datetime, component_key: str) -> bool:
    if not is_business_day(current.date(), config.holiday_overrides):
        return False
    current_time = current.timetz().replace(tzinfo=None)
    pending_until = {
        "notify": SCHEDULED_NOTIFY_LATEST_TIME,
        "poll": config.poll_start_time,
        "krx_daily_backfill": datetime_time(hour=8, minute=40),
        "krx_mentioned_flow_backfill": datetime_time(hour=16, minute=30),
        "telegram_command_loop": datetime_time(hour=8, minute=5),
    }.get(component_key)
    return pending_until is not None and current_time < pending_until


def _operation_event_to_status_dict(event: OperationEvent) -> dict:
    return {
        "event_time": event.event_time.isoformat(),
        "component": event.component,
        "event_type": event.event_type,
        "status": event.status,
        "business_date": event.business_date.isoformat() if event.business_date else None,
        "detail": event.detail,
    }


def _display_operation_event_status(repository: StockMonitorRepository, event: OperationEvent) -> str:
    if event.component != "krx" or event.event_type not in {"fetch-snapshot", "backfill-missing"}:
        return event.status
    if event.status in {"empty", "partial"}:
        return event.status
    if _krx_fetch_snapshot_event_has_no_rows(event):
        return f"{event.status}(attention:empty_rows)"
    if _krx_daily_backfill_event_has_incomplete_snapshots(repository, event):
        return f"{event.status}(attention:incomplete_snapshot)"
    return event.status


def _display_operation_event_detail(event: OperationEvent) -> str | None:
    detail = (event.detail or "").strip()
    if not detail:
        return None
    if event.component == "admin-gui" and event.event_type == "post" and event.status == "failed":
        path, _separator, error = detail.partition(";")
        if error.strip():
            return f"요청 실패: {path.strip()} ({error.strip()})"
        return f"요청 실패: {path.strip()}"
    if event.component in {"admin-gui", "scheduler-control"} and event.event_type.startswith("scheduler-"):
        task_name = detail.split(";", 1)[0].strip()
        state = _extract_detail_field(detail, "state")
        if task_name and state:
            return f"{task_name} 상태 {state}"
        return task_name or detail
    if event.component == "db" and event.event_type == "restore-smoke":
        backup = _extract_detail_field(detail, "backup") or "-"
        copy_retained = _extract_detail_field(detail, "copy_retained")
        exit_code = _extract_detail_field(detail, "exit_code")
        parts = [f"backup {backup}"]
        if exit_code is not None:
            parts.append(f"exit {exit_code}")
        if copy_retained is not None:
            parts.append(f"copy_retained {copy_retained}")
        return "restore-smoke: " + ", ".join(parts)
    if event.component == "krx" and event.event_type == "fetch-snapshot":
        endpoint = _extract_detail_field(detail, "endpoint") or "KRX"
        rows = _extract_detail_field(detail, "rows")
        stored_parts = [
            f"{label} {value}"
            for key, label in (
                ("stock_market", "주식"),
                ("etf", "ETF"),
                ("metadata", "메타"),
                ("index", "지수"),
            )
            if (value := _extract_detail_field(detail, key)) is not None
        ]
        if rows is not None and stored_parts:
            return f"{endpoint}: 원본 {rows}건, 저장 {' / '.join(stored_parts)}"
        if stored_parts:
            return f"{endpoint}: 저장 {' / '.join(stored_parts)}"
        return f"{endpoint}: {detail}"
    if event.component == "krx" and event.event_type in {"backfill-missing", "scheduled-daily-backfill"}:
        endpoint = _extract_detail_field(detail, "endpoint") or "daily"
        dates = _extract_detail_field(detail, "dates")
        endpoints = _extract_detail_field(detail, "endpoints")
        incomplete = _extract_detail_field(detail, "incomplete_endpoints")
        if dates or endpoints or incomplete:
            parts = []
            if dates is not None:
                parts.append(f"날짜 {dates}개")
            if endpoints is not None:
                parts.append(f"endpoint {endpoints}개")
            if incomplete is not None:
                parts.append(f"미완료 {incomplete}개")
            return f"{endpoint} 보강: {', '.join(parts)}"
    if event.component == "krx-flow" and event.event_type in {
        "scheduled-mentioned-flow-backfill",
        "latest-anchor-mentioned-flow-backfill",
    }:
        calls = _extract_detail_field(detail, "calls")
        rows = _extract_detail_field(detail, "stock_rows")
        stocks = _extract_detail_field(detail, "stocks")
        dropped = _extract_detail_field(detail, "dropped_calls")
        unresolved = _extract_detail_field(detail, "skipped_unresolved_stock_count")
        if calls or rows or stocks:
            parts = []
            if stocks is not None:
                parts.append(f"종목 {stocks}개")
            if calls is not None:
                parts.append(f"호출 {calls}회")
            if rows is not None:
                parts.append(f"저장 {rows}행")
            if dropped not in {None, "0"}:
                parts.append(f"잔여 {dropped}회")
            if unresolved not in {None, "0"}:
                parts.append(f"미해결 코드 {unresolved}개")
            return ", ".join(parts)
    if event.component == "notify" and event.event_type == "send":
        source = _extract_detail_field(detail, "source")
        messages = _extract_detail_field(detail, "messages")
        summaries = _extract_detail_field(detail, "summaries")
        if source or messages or summaries:
            parts = []
            if source:
                parts.append("예약 발송" if source == "scheduled" else "수동 발송")
            if messages is not None:
                parts.append(f"메시지 {messages}개")
            if summaries is not None:
                parts.append(f"요약 {summaries}개")
            return ", ".join(parts)
    if event.component == "notify" and event.event_type == "fragment":
        fragment = _extract_detail_field(detail, "fragment")
        ambiguous = _extract_detail_field(detail, "ambiguous_send")
        if fragment:
            suffix = "전송 결과 불확실" if ambiguous == "true" else None
            return f"조각 {fragment}" + (f", {suffix}" if suffix else "")
    return detail


def _krx_fetch_snapshot_event_has_no_rows(event: OperationEvent) -> bool:
    if event.component != "krx" or event.event_type != "fetch-snapshot":
        return False
    row_keys = ("rows", "stock_market", "etf", "metadata", "index")
    parsed_values: list[int] = []
    for key in row_keys:
        raw_value = _extract_detail_field(event.detail, key)
        if raw_value is None:
            continue
        try:
            parsed_values.append(int(raw_value))
        except ValueError:
            return False
    return bool(parsed_values) and sum(parsed_values) == 0


def _operator_health_exit_code(status: dict) -> int:
    return 0 if status.get("health", {}).get("level") == "ok" else OPERATOR_HEALTH_BAD_EXIT_CODE


def _format_iso_datetime_short(value: str) -> str:
    return datetime.fromisoformat(value).strftime("%y.%m.%d %H:%M:%S")


def _run_scheduler_control(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    action: str,
    task_selector: str,
    dry_run: bool,
    confirm: bool,
) -> int:
    task_names = _resolve_scheduler_control_task_names(config.scheduler_task_prefix, task_selector)
    shutdown_task_name = _scheduler_task_names(config.scheduler_task_prefix)[-1]
    if action == "run-now":
        if task_selector == "shutdown":
            print("Refusing to run the Shutdown task manually. Use enable/disable only for Shutdown.")
            return 2
        task_names = tuple(task_name for task_name in task_names if task_name != shutdown_task_name)
    if action == "restart" and task_selector != "telegram-commands":
        print("Refusing scheduler restart except for TelegramCommands recovery.")
        return 2
    command_name = _scheduler_control_action_command(action)
    if not confirm and not dry_run:
        print("Refusing to change scheduler state without --confirm. Use --dry-run to preview.")
        return 2

    if dry_run:
        print("Scheduler control dry-run")
        for task_name in task_names:
            print(f"- {task_name}: {command_name}")
        return 0

    failures: list[str] = []
    for task_name in task_names:
        try:
            result = _execute_scheduler_control_action(action, task_name)
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="scheduler-control",
                    event_type=action,
                    status="success",
                    detail=f"{task_name}; state={result.get('state')}",
                )
            )
            print(f"{task_name}: {action} requested; state={result.get('state') or 'unknown'}")
        except Exception as exc:
            failures.append(f"{task_name}: {exc}")
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="scheduler-control",
                    event_type=action,
                    status="failed",
                    detail=f"{task_name}; {exc}",
                )
            )
            print(f"{task_name}: failed: {exc}", file=sys.stderr)

    return 1 if failures else 0


def _run_operator_control(config: RuntimeConfig, repository: StockMonitorRepository, args: argparse.Namespace) -> int:
    now = datetime.now(ZoneInfo(config.timezone))
    action = args.operator_action
    if action == "status":
        print("운영 제어 상태")
        print(f"- 운영 일시정지: {'Y' if repository.is_operator_paused() else 'N'}")
        print("- DB 실행 제외일:")
        dates = repository.list_db_run_suppressed_dates()
        if not dates:
            print("- 없음")
        else:
            for item in dates:
                print(f"- {item.isoformat()}")
        return 0

    if action == "pause":
        reason = args.reason or "operator pause"
        repository.set_operator_pause(paused=True, updated_at=now, detail=reason)
        repository.record_operation_event(
            _operation_event(
                config,
                component="operator-control",
                event_type="pause",
                status="success",
                detail=reason,
            )
        )
        print("운영 일시정지 완료")
        return 0

    if action == "resume":
        repository.set_operator_pause(paused=False, updated_at=now)
        repository.record_operation_event(
            _operation_event(
                config,
                component="operator-control",
                event_type="resume",
                status="success",
            )
        )
        print("운영 재개 완료")
        return 0

    if action == "add-no-run-date":
        reason = args.reason or "operator no-run date"
        _validate_operator_no_run_date_target(config, args.date, current_date=now.date())
        repository.add_run_suppressed_date(args.date, updated_at=now, detail=reason)
        repository.record_operation_event(
            _operation_event(
                config,
                component="operator-control",
                event_type="add-no-run-date",
                status="success",
                business_date=args.date,
                detail=reason,
            )
        )
        print(f"실행 제외일 추가 완료: {args.date.isoformat()}")
        return 0

    if action == "remove-no-run-date":
        repository.remove_run_suppressed_date(args.date)
        repository.record_operation_event(
            _operation_event(
                config,
                component="operator-control",
                event_type="remove-no-run-date",
                status="success",
                business_date=args.date,
            )
        )
        print(f"실행 제외일 제거 완료: {args.date.isoformat()}")
        return 0

    if action == "list-no-run-dates":
        dates = repository.list_db_run_suppressed_dates()
        if not dates:
            print("DB 실행 제외일 없음")
            return 0
        for item in dates:
            print(item.isoformat())
        return 0

    if action == "explain-date":
        explanation = _explain_run_date(config, repository, args.date)
        if args.json:
            print(json.dumps(explanation, ensure_ascii=False, indent=2))
            return 0
        print(f"실행일 판단: {explanation['date']} | {'실행 가능' if explanation['runnable'] else '실행 제외'}")
        if explanation["effective_reason"]:
            print(f"- 대표 사유: {explanation['effective_reason']}")
        print(f"- 영업일: {'Y' if explanation['is_business_day'] else 'N'}")
        print(f"- 시장 휴장일: {'Y' if explanation['is_market_holiday'] else 'N'}")
        print(f"- 운영 일시정지: {'Y' if explanation['is_operator_paused'] else 'N'}")
        print(f"- env 실행 제외: {'Y' if explanation['is_env_run_suppressed'] else 'N'}")
        print(f"- DB 실행 제외: {'Y' if explanation['is_db_run_suppressed'] else 'N'}")
        if explanation["db_reason"]:
            print(f"- DB 사유: {explanation['db_reason']}")
        print(f"- 이전 영업일: {explanation['previous_business_day']}")
        print(f"- 다음 영업일: {explanation['next_business_day']}")
        return 0

    raise ValueError(f"Unsupported operator-control action: {action}")


def _run_operator_settings(config: RuntimeConfig, repository: StockMonitorRepository, args: argparse.Namespace) -> int:
    action = args.settings_action
    if action == "list":
        settings = _effective_safe_settings(config, repository)
        if args.json:
            print(json.dumps(settings, ensure_ascii=False, indent=2))
            return 0
        print("안전 설정")
        for item in settings:
            print(
                f"- {item['setting_key']} | value={item['effective_value']} | "
                f"source={item['source']} | restart={'Y' if item['restart_required'] else 'N'} | "
                f"updated={item['updated_at'] or '-'} | {item['description']}"
            )
        return 0

    if action == "set":
        if not args.confirm:
            print("ERROR: --confirm is required to change safe settings.", file=sys.stderr)
            return 2
        now = datetime.now(ZoneInfo(config.timezone))
        try:
            normalized_value = _validate_safe_setting_value(args.key, args.value)
        except ValueError as exc:
            repository.record_admin_audit_log(
                AdminAuditLog(
                    event_time=now,
                    actor=args.actor,
                    action="set_app_setting",
                    status="validation_failed",
                    setting_key=args.key,
                    new_value=args.value,
                    detail=str(exc),
                )
            )
            raise
        previous = repository.get_app_setting(args.key)
        previous_value = previous.setting_value if previous else _safe_setting_default(config, args.key)
        if previous_value == normalized_value:
            print(f"변경 없음 | {args.key} | {normalized_value}")
            return 0
        _validate_market_briefing_phone_review_acceptance_change(
            repository,
            key=args.key,
            normalized_value=normalized_value,
            previous_value=previous_value,
            now=now,
            actor=args.actor,
        )
        definition = SAFE_APP_SETTING_DEFINITIONS[args.key]
        repository.set_app_setting(
            AppSetting(
                setting_key=args.key,
                setting_value=normalized_value,
                value_type=str(definition["type"]),
                updated_at=now,
                updated_by=args.actor,
                detail=args.reason,
                restart_required=bool(definition["restart_required"]),
            ),
            audit_actor=args.actor,
            audit_detail=args.reason,
        )
        repository.record_operation_event(
            _operation_event(
                config,
                component="operator-settings",
                event_type="set",
                status="success",
                detail=f"{args.key}: {previous_value} -> {normalized_value}; reason={args.reason}",
            )
        )
        print(f"설정 변경 완료 | {args.key} | {previous_value} -> {normalized_value} | source=db")
        return 0

    if action in {"audit-log", "history"}:
        rows = repository.list_admin_audit_logs(limit=args.limit)
        payload = [
            {
                "id": item.id,
                "event_time": item.event_time.isoformat(),
                "actor": item.actor,
                "action": item.action,
                "setting_key": item.setting_key,
                "old_value": item.old_value,
                "new_value": item.new_value,
                "status": item.status,
                "detail": item.detail,
            }
            for item in rows
        ]
        if args.json:
            print(json.dumps(payload, ensure_ascii=False, indent=2))
            return 0
        if not rows:
            print("안전 설정 감사 로그 없음")
            return 0
        for item in payload:
            print(
                f"- {item['event_time']} | {item['actor']} | {item['setting_key']} | "
                f"{item['old_value']} -> {item['new_value']} | {item['status']} | {item['detail'] or ''}"
            )
        return 0

    raise ValueError(f"Unsupported operator-settings action: {action}")


def _validate_operator_no_run_date_target(
    config: RuntimeConfig,
    target: date,
    *,
    current_date: date | None = None,
) -> None:
    if target in config.run_suppressed_dates:
        raise ValueError(f"{target.isoformat()} is already configured as an env no-run date.")
    if not is_business_day(target, config.holiday_overrides):
        raise ValueError(f"{target.isoformat()} is not a market business day; no DB no-run override is needed.")
    if current_date is not None and target < current_date:
        raise ValueError(f"{target.isoformat()} is in the past; no DB no-run override is useful.")


def _resolve_scheduler_control_task_names(task_prefix: str, task_selector: str) -> tuple[str, ...]:
    (
        notify,
        poll,
        krx_daily_backfill,
        krx_mentioned_flow_backfill,
        krx_flow_login_reminder,
        market_briefing_mood,
        market_briefing_lunch,
        market_briefing_preclose,
        telegram_commands,
        web_view_hourly_restart,
        shutdown,
    ) = _scheduler_task_names(task_prefix)
    mapping = {
        "notify": notify,
        "poll": poll,
        "krx-daily-backfill": krx_daily_backfill,
        "krx-mentioned-flow-backfill": krx_mentioned_flow_backfill,
        "krx-flow-login-reminder": krx_flow_login_reminder,
        "market-briefing-mood": market_briefing_mood,
        "market-briefing-lunch": market_briefing_lunch,
        "market-briefing-preclose": market_briefing_preclose,
        "telegram-commands": telegram_commands,
        "web-view-hourly-restart": web_view_hourly_restart,
        "web-view-manual": f"{task_prefix}-WebViewManual",
        "shutdown": shutdown,
    }
    if task_selector == "all":
        return (
            notify,
            poll,
            krx_daily_backfill,
            krx_mentioned_flow_backfill,
            krx_flow_login_reminder,
            market_briefing_mood,
            market_briefing_lunch,
            market_briefing_preclose,
            telegram_commands,
            web_view_hourly_restart,
            f"{task_prefix}-WebViewManual",
            shutdown,
        )
    return (mapping[task_selector],)


def _scheduler_control_action_command(action: str) -> str:
    mapping = {
        "run-now": "Start-ScheduledTask",
        "enable": "Enable-ScheduledTask",
        "disable": "Disable-ScheduledTask",
        "restart": "Restart-ScheduledTask",
    }
    return mapping[action]


def _execute_scheduler_control_action(action: str, task_name: str) -> dict:
    if not sys.platform.startswith("win"):
        raise RuntimeError("Windows Task Scheduler is only available on Windows.")

    task_name_literal = _powershell_single_quote(task_name)
    if action == "restart":
        action_script = """
$task = Get-ScheduledTask -TaskName $taskName
if ([string]$task.State -eq "Running") {
    Stop-ScheduledTask -TaskName $taskName | Out-Null
    Start-Sleep -Seconds 1
}
Start-ScheduledTask -TaskName $taskName | Out-Null
"""
    else:
        command_name = _scheduler_control_action_command(action)
        action_script = f"{command_name} -TaskName $taskName | Out-Null"
    script = f"""
$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8
$taskName = {task_name_literal}
{action_script}
$task = Get-ScheduledTask -TaskName $taskName
[pscustomobject]@{{
    task_name = $taskName
    action = { _powershell_single_quote(action) }
    state = [string]$task.State
}} | ConvertTo-Json -Depth 3 -Compress
"""
    completed = subprocess.run(
        ["powershell.exe", "-NoProfile", "-Command", script],
        check=False,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or f"PowerShell exited with {completed.returncode}").strip()
        raise RuntimeError(detail)
    try:
        payload = json.loads(completed.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"Failed to parse scheduler control result: {exc}") from exc
    if not isinstance(payload, dict):
        raise RuntimeError("Unexpected scheduler control result.")
    return payload


def _powershell_single_quote(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def _run_telegram_get_updates(config: RuntimeConfig) -> int:
    if not config.telegram_bot_token:
        raise RuntimeError("Set STOCK_MONITOR_TELEGRAM_BOT_TOKEN before calling telegram-get-updates.")
    data = get_telegram_updates(
        config.telegram_bot_token,
        offset=None,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    print(json.dumps(data, ensure_ascii=False, indent=2))
    return 0


def _run_scheduled_telegram_commands(config: RuntimeConfig, repository: StockMonitorRepository) -> int:
    repository.initialize()
    today = datetime.now(ZoneInfo(config.timezone)).date()
    skip_reason = _scheduled_skip_reason(config, today, repository) or _operation_profile_skip_reason(
        config,
        repository,
        component="telegram-commands",
    )
    if skip_reason:
        repository.record_operation_event(
            _operation_event(
                config,
                component="telegram-commands",
                event_type="run-guard",
                status="skipped",
                business_date=today,
                detail=skip_reason,
            )
        )
        print(f"Skipping Telegram commands: {skip_reason}")
        return 0

    return _run_process_telegram_commands(config, repository)


def _run_scheduled_telegram_command_loop(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    end_time: datetime_time,
    interval_seconds: int,
) -> int:
    if interval_seconds < 1:
        raise ValueError("interval_seconds must be at least 1.")
    repository.initialize()
    _record_telegram_worker_state(
        config,
        repository,
        status="starting",
        interval_seconds=interval_seconds,
        end_time=end_time,
        last_started=True,
    )

    while True:
        now = datetime.now(ZoneInfo(config.timezone))
        today = now.date()
        skip_reason = _scheduled_skip_reason(config, today, repository) or _operation_profile_skip_reason(
            config,
            repository,
            component="telegram-command-loop",
        )
        if skip_reason:
            _record_telegram_worker_state(
                config,
                repository,
                status="stopped",
                interval_seconds=interval_seconds,
                end_time=end_time,
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="telegram-command-loop",
                    event_type="run-guard",
                    status="skipped",
                    business_date=today,
                    detail=skip_reason,
                )
            )
            print(f"Skipping Telegram command loop: {skip_reason}")
            return 0
        if now.timetz().replace(tzinfo=None) > end_time:
            detail = f"{now.strftime('%H:%M')} is after {end_time.strftime('%H:%M')}."
            _record_telegram_worker_state(
                config,
                repository,
                status="stopped",
                interval_seconds=interval_seconds,
                end_time=end_time,
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="telegram-command-loop",
                    event_type="time-window",
                    status="stopped",
                    business_date=today,
                    detail=detail,
                )
            )
            print(f"Stopping Telegram command loop: {detail}")
            return 0

        try:
            _run_process_telegram_commands(config, repository)
            _record_telegram_worker_state(
                config,
                repository,
                status="ok",
                interval_seconds=interval_seconds,
                end_time=end_time,
                last_success=True,
            )
        except Exception as exc:  # keep the scheduled worker alive through transient Telegram/network failures
            _record_telegram_worker_state(
                config,
                repository,
                status="error",
                interval_seconds=interval_seconds,
                end_time=end_time,
                last_error=str(exc),
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="telegram-command-loop",
                    event_type="iteration",
                    status="failed",
                    business_date=today,
                    detail=str(exc),
                )
            )
            print(f"Telegram command loop iteration failed: {exc}", file=sys.stderr)

        time.sleep(interval_seconds)


def _record_telegram_worker_state(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    status: str,
    interval_seconds: int,
    end_time: datetime_time,
    last_started: bool = False,
    last_success: bool = False,
    last_error: str | None = None,
) -> None:
    current = datetime.now(ZoneInfo(config.timezone))
    repository.upsert_worker_state(
        WorkerState(
            worker_name=TELEGRAM_COMMAND_LOOP_WORKER,
            status=status,
            updated_at=current,
            last_started_at=current if last_started else None,
            last_success_at=current if last_success else None,
            last_error_at=current if last_error is not None else None,
            last_error=last_error,
            interval_seconds=interval_seconds,
            end_time=end_time.strftime("%H:%M"),
        )
    )


def _parse_telegram_optional_date(argument: str | None) -> date | None:
    raw = (argument or "").strip()
    if not raw or raw.lower() == "latest":
        return None
    try:
        return date.fromisoformat(raw)
    except ValueError:
        return None


def _format_market_commentary_telegram_message(payload: dict[str, object]) -> str:
    business_date = str(payload.get("business_date") or "-")
    comments = payload.get("comments") if isinstance(payload.get("comments"), list) else []
    lines = [
        f"한줄 코멘트 · {business_date}",
        str(payload.get("market_reference") or "저장된 시장 참고값 없음"),
        "",
    ]
    if not comments:
        lines.append("저장된 리포트 기준 코멘트가 없습니다.")
    else:
        for item in comments:
            if not isinstance(item, dict):
                continue
            label = str(item.get("label") or "-")
            comment = str(item.get("comment") or "저장된 데이터가 없습니다.")
            lines.append(f"{label}: {comment}")
    lines.extend(["", "관찰 참고 전용입니다."])
    message = "\n".join(lines)
    _ensure_market_briefing_message_public_safe(message)
    return message


def _telegram_image_attachment(message: dict[str, object]) -> dict[str, object] | None:
    photos = message.get("photo")
    if isinstance(photos, list) and photos:
        candidates = [item for item in photos if isinstance(item, dict) and item.get("file_id")]
        if candidates:
            picked = max(candidates, key=lambda item: int(item.get("file_size") or 0))
            return {
                "kind": "photo",
                "file_id": str(picked.get("file_id") or ""),
                "file_unique_id": str(picked.get("file_unique_id") or ""),
                "file_size": int(picked.get("file_size") or 0),
                "mime_type": "image/jpeg",
            }
    document = message.get("document")
    if isinstance(document, dict) and document.get("file_id"):
        mime_type = str(document.get("mime_type") or "")
        file_name = str(document.get("file_name") or "")
        if mime_type.startswith("image/") or Path(file_name).suffix.lower() in _PHOTO_INBOX_EXTENSIONS:
            return {
                "kind": "document",
                "file_id": str(document.get("file_id") or ""),
                "file_unique_id": str(document.get("file_unique_id") or ""),
                "file_size": int(document.get("file_size") or 0),
                "mime_type": mime_type,
                "file_name": file_name,
            }
    return None


def _telegram_photo_extension(file_path: str, attachment: dict[str, object]) -> str:
    suffix = Path(file_path).suffix.lower()
    if suffix in _PHOTO_INBOX_EXTENSIONS:
        return suffix
    mime_type = str(attachment.get("mime_type") or "").lower()
    if mime_type == "image/png":
        return ".png"
    if mime_type == "image/webp":
        return ".webp"
    if mime_type == "image/gif":
        return ".gif"
    if mime_type == "image/bmp":
        return ".bmp"
    return ".jpg"


def _build_telegram_photo_command_response(
    config: RuntimeConfig,
    *,
    message: dict[str, object],
    update_id: int,
    note: str | None,
    now: datetime,
    state: TelegramControlState,
) -> str:
    normalized_note = (note or "").strip() or state.pending_photo_note or "사진 참고자료"
    attachment = _telegram_image_attachment(message)
    if attachment is None:
        state.set_pending_photo_note(normalized_note)
        return "다음 사진을 저장합니다. 사진을 이어서 보내면 로컬 operator_photo_inbox에 저장합니다."

    if state.has_applied_photo_update(update_id):
        return "사진 저장 완료"

    file_id = str(attachment.get("file_id") or "")
    if not file_id:
        return "사진 파일 ID를 확인하지 못했습니다."

    file_path = get_telegram_file_path(
        config.telegram_bot_token,
        file_id,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    content = download_telegram_file(
        config.telegram_bot_token,
        file_path,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    inbox = config.data_dir / "operator_photo_inbox"
    inbox.mkdir(parents=True, exist_ok=True)
    extension = _telegram_photo_extension(file_path, attachment)
    saved_name = f"telegram_{update_id}_{now.strftime('%Y%m%d_%H%M%S')}{extension}"
    saved_path = inbox / saved_name
    saved_path.write_bytes(content)
    metadata = {
        "source": "telegram",
        "update_id": update_id,
        "saved_at": now.isoformat(),
        "note": normalized_note,
        "file_name": saved_name,
        "file_size_bytes": len(content),
        "telegram_file_path": file_path,
        "attachment_kind": attachment.get("kind"),
        "mime_type": attachment.get("mime_type"),
        "file_unique_id": attachment.get("file_unique_id"),
    }
    saved_path.with_suffix(".json").write_text(json.dumps(metadata, ensure_ascii=False, indent=2), encoding="utf-8")
    state.mark_photo_update_applied(update_id)
    state.clear_pending_photo_note()
    return f"사진 저장 완료 · {saved_name}"


def _run_process_telegram_commands(config: RuntimeConfig, repository: StockMonitorRepository) -> int:
    if not config.telegram_bot_token or not config.telegram_chat_id:
        raise RuntimeError(
            "Telegram configuration is missing. Set STOCK_MONITOR_TELEGRAM_BOT_TOKEN and "
            "STOCK_MONITOR_TELEGRAM_CHAT_ID."
        )

    state = load_control_state(config.telegram_control_state_path)
    offset = state.last_update_id + 1 if state.last_update_id else None
    data = get_telegram_updates(
        config.telegram_bot_token,
        offset=offset,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    updates = data.get("result", [])
    if not updates:
        print("No new Telegram commands.")
        return 0

    processed = 0
    for update in updates:
        update_id = int(update.get("update_id", 0))
        message = update.get("message") or {}
        chat = message.get("chat") or {}
        if str(chat.get("id")) != str(config.telegram_chat_id):
            state.last_update_id = max(state.last_update_id, update_id)
            save_control_state(config.telegram_control_state_path, state)
            continue
        text = str(message.get("text") or message.get("caption") or "").strip()
        attachment = _telegram_image_attachment(message)
        if not text and attachment is None:
            state.last_update_id = max(state.last_update_id, update_id)
            save_control_state(config.telegram_control_state_path, state)
            continue
        command, argument = parse_telegram_command(text) if text else (None, None)
        if not command and attachment is not None and state.pending_photo_note:
            command, argument = "photo", state.pending_photo_note
        if not command:
            state.last_update_id = max(state.last_update_id, update_id)
            save_control_state(config.telegram_control_state_path, state)
            continue
        now = datetime.now(ZoneInfo(config.timezone))

        if command == "selection":
            response_text = _build_stock_selection_followup_response(
                config,
                state,
                selection_text=argument,
                now=now,
            )
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "help":
            state.clear_pending_stock_selection()
            help_title = "도움말 안내" if "도움말" in text else "명령어 안내"
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                _build_help_command_response(title=help_title),
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "market_commentary":
            state.clear_pending_stock_selection()
            explicit_date = _parse_telegram_optional_date(argument)
            response_text = _format_market_commentary_telegram_message(
                _build_market_commentary_practice_snapshot(config, repository, explicit_date)
            )
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "photo":
            state.clear_pending_stock_selection()
            response_text = _build_telegram_photo_command_response(
                config,
                message=message,
                update_id=update_id,
                note=argument,
                now=now,
                state=state,
            )
            save_control_state(config.telegram_control_state_path, state)
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "memo":
            state.clear_pending_stock_selection()
            response_text = _build_memo_command_response(
                config,
                memo_text=argument,
                now=now,
                update_id=update_id,
                state=state,
            )
            save_control_state(config.telegram_control_state_path, state)
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "progress_request":
            state.clear_pending_stock_selection()
            response_text = _build_progress_request_command_response(
                config,
                repository=repository,
                request_text=argument,
                now=now,
                update_id=update_id,
                state=state,
            )
            save_control_state(config.telegram_control_state_path, state)
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "check":
            state.clear_pending_stock_selection()
            response_text = _build_check_command_response(
                config,
                repository,
                check_text=argument,
                now=now,
                update_id=update_id,
                state=state,
            )
            save_control_state(config.telegram_control_state_path, state)
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command in {"operator_status", "today_status", "schedule_status", "webview_url"}:
            state.clear_pending_stock_selection()
            response_text = _build_read_only_status_command_response(config, repository, command=command, now=now)
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "unknown_slash":
            state.clear_pending_stock_selection()
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                "\n".join(
                    [
                        f"알 수 없는 명령어: {argument}",
                        "",
                        _build_help_command_response(title="명령어 안내"),
                    ]
                ),
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "stock_code_lookup":
            state.clear_pending_stock_selection()
            response_text = _build_stock_code_command_response(
                config,
                query=argument,
            )
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        if command == "stock_lookup":
            response_text = _build_stock_lookup_command_response(
                config,
                state,
                query=argument,
                now=now,
                lookback_days=15,
                entry_limit=5,
            )
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                response_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            state.last_update_id = max(state.last_update_id, update_id)
            processed += 1
            save_control_state(config.telegram_control_state_path, state)
            continue

        state.clear_pending_stock_selection()
        if state.active_message_kind == "intraday" and state.active_intraday_batch_id and state.active_intraday_created_at:
            handled = _try_process_intraday_paging_command_with_fallback(
                config,
                repository,
                state,
                command=command,
            )
            if handled:
                state.last_update_id = max(state.last_update_id, update_id)
                processed += 1
                save_control_state(config.telegram_control_state_path, state)
                continue

        business_date = _resolve_active_business_date(config, state)
        summaries = repository.list_daily_summaries(business_date)
        if not summaries:
            summaries = repository.rebuild_daily_summaries(business_date)
        summaries = _filter_daily_summaries(
            summaries,
            min_mentions=_effective_int_setting(config, repository, "daily_summary_min_mention_count"),
            require_target_price=_effective_bool_setting(config, repository, "daily_summary_require_target_price"),
        )

        current_offset = state.delivered_for(business_date)
        default_limit = _effective_int_setting(config, repository, "notification_default_limit")
        if command == "reset":
            current_offset = 0
            limit = default_limit
        elif command == "next":
            limit = default_limit
        else:
            limit = None

        if current_offset >= len(summaries):
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                "추가로 표시할 종목이 없습니다.\n/처음 또는 /명령어를 입력해보세요.",
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
        else:
            quotes_by_stock_code = _fetch_daily_summary_quotes_by_stock_code(config, summaries, repository=repository)
            message_text = format_daily_summary_message(
                business_date,
                summaries,
                offset=current_offset,
                limit=limit,
                quotes_by_stock_code=quotes_by_stock_code,
            )
            send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                message_text,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
            delivered_now = len(summaries[current_offset:]) if limit is None else min(limit, len(summaries) - current_offset)
            state.set_delivered_for(business_date, current_offset + delivered_now)

        state.last_update_id = max(state.last_update_id, update_id)
        processed += 1
        save_control_state(config.telegram_control_state_path, state)

    save_control_state(config.telegram_control_state_path, state)
    print(f"Processed {processed} queued Telegram command(s).")
    return 0


def _run_scheduled_shutdown(
    config: RuntimeConfig,
    *,
    dry_run: bool,
    delay_seconds: int,
) -> int:
    now = datetime.now(ZoneInfo(config.timezone))
    today = now.date()
    repository = StockMonitorRepository(config.db_path, timezone=config.timezone)
    repository.initialize()
    skip_reason = _scheduled_skip_reason(config, today, repository) or _operation_profile_skip_reason(
        config,
        repository,
        component="shutdown",
    )
    if skip_reason:
        repository.record_operation_event(
            _operation_event(config, component="shutdown", event_type="run-guard", status="skipped", business_date=today, detail=skip_reason)
        )
        print(f"Skipping shutdown: {skip_reason}")
        return 0

    command = [
        "shutdown.exe",
        "/s",
        "/t",
        str(delay_seconds),
        "/c",
        "Stock Monitor scheduled shutdown",
    ]
    if dry_run:
        print("Would run: " + " ".join(command))
        return 0

    subprocess.run(command, check=True)
    repository.record_operation_event(
        _operation_event(
            config,
            component="shutdown",
            event_type="request",
            status="requested",
            business_date=today,
            detail=f"delay_seconds={delay_seconds}",
        )
    )
    print(f"Scheduled shutdown requested for {now.strftime('%Y-%m-%d %H:%M:%S')}.")
    return 0


def _load_scheduler_task_statuses(task_prefix: str = "StockMonitor") -> list[dict]:
    task_names = _scheduler_task_names(task_prefix)
    if not sys.platform.startswith("win"):
        return [_unavailable_scheduler_task_status(task_name, "Windows Task Scheduler is only available on Windows.") for task_name in task_names]

    powershell_task_names = ", ".join(f'"{task_name}"' for task_name in task_names)
    script = f"""
$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8
function Convert-TaskDate($value) {{
    if ($null -eq $value -or $value.Year -le 1) {{
        return $null
    }}
    return $value.ToString("s")
}}
$names = @({powershell_task_names})
$rows = foreach ($name in $names) {{
    try {{
        $task = Get-ScheduledTask -TaskName $name -ErrorAction Stop
    }}
    catch {{
        $message = $_.Exception.Message
        if ($message -like "*No MSFT_ScheduledTask objects*" -or $message -like "*찾을 수 없습니다*") {{
            [pscustomobject]@{{
                task_name = $name
                available = $true
                exists = $false
                state = $null
                enabled = $false
                next_run_time = $null
                last_run_time = $null
                last_task_result = $null
                detail = $null
            }}
        }}
        else {{
            [pscustomobject]@{{
                task_name = $name
                available = $false
                exists = $false
                state = $null
                enabled = $false
                next_run_time = $null
                last_run_time = $null
                last_task_result = $null
                detail = $message
            }}
        }}
        continue
    }}
    try {{
        $info = Get-ScheduledTaskInfo -TaskName $name -ErrorAction Stop
    }}
    catch {{
        [pscustomobject]@{{
            task_name = $name
            available = $false
            exists = $true
            state = [string]$task.State
            enabled = ([string]$task.State -ne "Disabled")
            next_run_time = $null
            last_run_time = $null
            last_task_result = $null
            detail = $_.Exception.Message
        }}
        continue
    }}
    [pscustomobject]@{{
        task_name = $name
        available = $true
        exists = $true
        state = [string]$task.State
        enabled = ([string]$task.State -ne "Disabled")
        next_run_time = Convert-TaskDate $info.NextRunTime
        last_run_time = Convert-TaskDate $info.LastRunTime
        last_task_result = $info.LastTaskResult
        detail = $null
    }}
}}
$rows | ConvertTo-Json -Depth 4 -Compress
"""
    try:
        completed = subprocess.run(
            ["powershell.exe", "-NoProfile", "-Command", script],
            check=False,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
    except Exception as exc:
        return [_unavailable_scheduler_task_status(task_name, str(exc)) for task_name in task_names]

    if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or f"PowerShell exited with {completed.returncode}").strip()
        return [_unavailable_scheduler_task_status(task_name, detail) for task_name in task_names]

    try:
        raw_payload = json.loads(completed.stdout or "[]")
    except json.JSONDecodeError as exc:
        return [_unavailable_scheduler_task_status(task_name, f"Failed to parse scheduler status: {exc}") for task_name in task_names]

    payload = raw_payload if isinstance(raw_payload, list) else [raw_payload]
    by_name = {str(item.get("task_name")): item for item in payload if isinstance(item, dict)}
    return [_normalize_scheduler_task_status(task_name, by_name.get(task_name)) for task_name in task_names]


def _scheduler_task_names(task_prefix: str) -> tuple[str, ...]:
    return (
        f"{task_prefix}-Notify",
        f"{task_prefix}-Poll",
        f"{task_prefix}-KrxDailyBackfill",
        f"{task_prefix}-KrxMentionedFlowBackfill",
        f"{task_prefix}-KrxFlowLoginReminder",
        f"{task_prefix}-MarketBriefingMood",
        f"{task_prefix}-MarketBriefingLunch",
        f"{task_prefix}-MarketBriefingPreclose",
        f"{task_prefix}-TelegramCommands",
        f"{task_prefix}-WebViewHourlyRestart",
        f"{task_prefix}-Shutdown",
    )


def _normalize_scheduler_task_status(task_name: str, item: dict | None) -> dict:
    if item is None:
        return {
            "task_name": task_name,
            "available": True,
            "exists": False,
            "state": None,
            "enabled": False,
            "next_run_time": None,
            "last_run_time": None,
            "last_task_result": None,
            "detail": None,
            "status_class": "missing",
            "status_reason": "Task was not returned by scheduler status query.",
        }
    return {
        "task_name": task_name,
        "available": bool(item.get("available", True)),
        "exists": bool(item.get("exists", False)),
        "state": item.get("state"),
        "enabled": bool(item.get("enabled", False)),
        "next_run_time": item.get("next_run_time"),
        "last_run_time": item.get("last_run_time"),
        "last_task_result": item.get("last_task_result"),
        "detail": item.get("detail"),
    }


def _classify_scheduler_task_statuses(
    config: RuntimeConfig,
    repository: StockMonitorRepository | None,
    current: datetime,
    tasks: list[dict],
) -> list[dict]:
    return [_classify_scheduler_task_status(config, repository, current, task) for task in tasks]


def _classify_scheduler_task_status(
    config: RuntimeConfig,
    repository: StockMonitorRepository | None,
    current: datetime,
    task: dict,
) -> dict:
    classified = dict(task)
    status_class, status_reason = _scheduler_status_class_and_reason(config, repository, current, classified)
    classified["status_class"] = status_class
    classified["status_reason"] = status_reason
    return classified


def _scheduler_status_class_and_reason(
    config: RuntimeConfig,
    repository: StockMonitorRepository | None,
    current: datetime,
    task: dict,
) -> tuple[str, str]:
    detail = str(task.get("detail") or "")
    if not task.get("available", True):
        if _looks_like_access_denied(detail):
            return "access_denied", detail or "Scheduler access denied."
        return "unavailable", detail or "Scheduler status is unavailable."
    if not task.get("exists", False):
        return "missing", "Task is not registered."
    if not task.get("enabled", False):
        return "disabled", "Task is disabled."
    last_result = task.get("last_task_result")
    state = str(task.get("state") or "")
    if state.lower() == "running":
        return "running", "Task is currently running."
    next_run = _parse_status_datetime(task.get("next_run_time"), config.timezone)
    if _is_scheduler_never_ran_result(last_result) and next_run and next_run > current:
        return "healthy", "Task is registered and waiting for its first scheduled run."
    if _is_scheduler_task_stale(config, repository, current, task):
        return "stale", "Task has not run within the expected operating window."
    if _is_scheduler_never_ran_result(last_result):
        return "healthy", "Task is registered and waiting for its first scheduled run."
    if last_result not in (None, 0, "0"):
        return "failed", f"Last task result is {last_result}."
    return "healthy", "Task metadata looks healthy."


def _is_scheduler_never_ran_result(value: object) -> bool:
    return str(value).strip() in {"267011", "0x41303"}


def _looks_like_access_denied(detail: str) -> bool:
    normalized = detail.lower()
    return any(
        marker in normalized
        for marker in (
            "access denied",
            "unauthorized",
            "permission",
            "액세스",
            "권한",
            "거부",
        )
    )


def _is_scheduler_task_stale(
    config: RuntimeConfig,
    repository: StockMonitorRepository | None,
    current: datetime,
    task: dict,
) -> bool:
    if not is_business_day(current.date(), config.holiday_overrides):
        return False
    if _scheduled_skip_reason(config, current.date(), repository):
        return False
    task_key = _scheduler_task_key(config.scheduler_task_prefix, task["task_name"])
    current_time = current.timetz().replace(tzinfo=None)
    last_run = _parse_status_datetime(task.get("last_run_time"), config.timezone)
    if task_key == "poll":
        if not is_within_time_window(current_time, config.poll_start_time, config.poll_end_time):
            return False
        return last_run is None or (current - last_run).total_seconds() > 90 * 60
    if task_key == "notify":
        if current_time <= SCHEDULED_NOTIFY_LATEST_TIME:
            return False
        return last_run is None or last_run.date() != current.date()
    if task_key == "krx-daily-backfill":
        expected_time = datetime_time(hour=8, minute=10)
        grace_time = datetime_time(hour=8, minute=40)
        if current_time < grace_time:
            return False
        return last_run is None or last_run.date() != current.date() or last_run.timetz().replace(tzinfo=None) < expected_time
    if task_key == "krx-mentioned-flow-backfill":
        expected_time = datetime_time(hour=16, minute=0)
        grace_time = datetime_time(hour=16, minute=30)
        if current_time < grace_time:
            return False
        return last_run is None or last_run.date() != current.date() or last_run.timetz().replace(tzinfo=None) < expected_time
    if task_key == "krx-flow-login-reminder":
        expected_time = datetime_time(hour=16, minute=45)
        grace_time = datetime_time(hour=16, minute=55)
        if current_time < grace_time:
            return False
        return last_run is None or last_run.date() != current.date() or last_run.timetz().replace(tzinfo=None) < expected_time
    if task_key == "telegram-commands":
        if current_time < datetime_time(hour=8, minute=5) or current_time > config.poll_end_time:
            return False
        return last_run is None or last_run.date() != current.date()
    return False


def _scheduler_task_key(task_prefix: str, task_name: str) -> str:
    prefix = f"{task_prefix}-"
    suffix = task_name[len(prefix) :] if task_name.startswith(prefix) else task_name
    normalized = suffix.lower()
    mapping = {
        "notify": "notify",
        "poll": "poll",
        "krxdailybackfill": "krx-daily-backfill",
        "krxmentionedflowbackfill": "krx-mentioned-flow-backfill",
        "krxflowloginreminder": "krx-flow-login-reminder",
        "marketbriefingmood": "market-briefing-mood",
        "marketbriefinglunch": "market-briefing-lunch",
        "marketbriefingpreclose": "market-briefing-preclose",
        "telegramcommands": "telegram-commands",
        "webviewhourlyrestart": "web-view-hourly-restart",
        "shutdown": "shutdown",
    }
    return mapping.get(normalized, normalized)


def _parse_status_datetime(value: object, timezone: str) -> datetime | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=ZoneInfo(timezone))
    return parsed


def _unavailable_scheduler_task_status(task_name: str, detail: str) -> dict:
    return {
        "task_name": task_name,
        "available": False,
        "exists": False,
        "state": None,
        "enabled": False,
        "next_run_time": None,
        "last_run_time": None,
        "last_task_result": None,
        "detail": detail,
    }


def _parse_hhmm_time(value: str) -> datetime_time:
    hour_str, minute_str = value.strip().split(":", 1)
    return datetime_time(hour=int(hour_str), minute=int(minute_str))


def _filter_daily_summaries(
    summaries: list[DailyStockSummary],
    *,
    min_mentions: int,
    require_target_price: bool,
) -> list[DailyStockSummary]:
    filtered = summaries
    if min_mentions > 1:
        filtered = [summary for summary in filtered if summary.mention_count >= min_mentions]
    if require_target_price:
        filtered = [
            summary
            for summary in filtered
            if summary.target_price_min is not None or summary.target_price_max is not None
        ]
    return filtered


def _scheduled_skip_reason(
    config: RuntimeConfig,
    target: date,
    repository: StockMonitorRepository | None = None,
) -> str | None:
    return _explain_run_date(config, repository, target)["effective_reason"]


def _explain_run_date(
    config: RuntimeConfig,
    repository: StockMonitorRepository | None,
    target: date,
) -> dict:
    matched_reasons: list[str] = []
    is_market_holiday = target in config.holiday_overrides
    is_business = is_business_day(target, config.holiday_overrides)
    is_operator_paused = repository.is_operator_paused() if repository is not None else False
    is_env_run_suppressed = target in config.run_suppressed_dates
    is_db_run_suppressed = repository.is_db_run_suppressed_date(target) if repository is not None else False
    db_reason = ""
    if is_db_run_suppressed and repository is not None:
        control = repository.get_operator_control(f"run_suppressed_date:{target.isoformat()}")
        db_reason = control.detail or "" if control else ""

    effective_reason = None
    if not is_business:
        matched_reasons.append("market_non_business_day")
        effective_reason = f"{target.isoformat()} is not a configured market business day."
    if is_operator_paused:
        matched_reasons.append("operator_pause")
        effective_reason = effective_reason or "Stock Monitor is paused by operator control."
    if is_env_run_suppressed:
        matched_reasons.append("env_no_run_date")
        effective_reason = effective_reason or f"{target.isoformat()} is configured as an env no-run date."
    if is_db_run_suppressed:
        matched_reasons.append("db_no_run_date")
        effective_reason = effective_reason or f"{target.isoformat()} is configured as an operator no-run date."

    return {
        "date": target.isoformat(),
        "runnable": effective_reason is None,
        "effective_reason": effective_reason,
        "matched_reasons": matched_reasons,
        "is_business_day": is_business,
        "is_market_holiday": is_market_holiday,
        "is_operator_paused": is_operator_paused,
        "is_env_run_suppressed": is_env_run_suppressed,
        "is_db_run_suppressed": is_db_run_suppressed,
        "db_reason": db_reason,
        "previous_business_day": previous_business_day(target, config.holiday_overrides).isoformat(),
        "next_business_day": next_business_day(target, config.holiday_overrides).isoformat(),
    }


def _operation_event(
    config: RuntimeConfig,
    *,
    component: str,
    event_type: str,
    status: str,
    business_date: date | None = None,
    detail: str | None = None,
) -> OperationEvent:
    return OperationEvent(
        event_time=datetime.now(ZoneInfo(config.timezone)),
        component=component,
        event_type=event_type,
        status=status,
        business_date=business_date,
        detail=detail,
    )


def _build_stock_lookup_command_response(
    config: RuntimeConfig,
    state: TelegramControlState,
    *,
    query: str | None,
    now: datetime,
    lookback_days: int,
    entry_limit: int,
) -> str:
    normalized_query = (query or "").strip()
    if not normalized_query:
        state.clear_pending_stock_selection()
        return "\n".join(
            [
                "사용법",
                "/종목검색 삼성전자",
                "/종목검색 005930",
                "종목명 후보를 고르거나 종목코드로 최근 15일 리포트를 조회합니다.",
            ]
        )

    upper_query = normalized_query.upper()
    if ASCII_STOCK_CODE_PATTERN.fullmatch(upper_query):
        state.clear_pending_stock_selection()
        return _build_stock_lookup_result_message(
            config,
            stock_code=upper_query,
            lookback_days=lookback_days,
            entry_limit=entry_limit,
        )

    try:
        candidates = fetch_stock_code_candidates(
            normalized_query,
            timeout_seconds=config.telegram_timeout_seconds,
        )
    except Exception as exc:
        state.clear_pending_stock_selection()
        return f"종목검색 실패: {exc}"

    if not candidates:
        state.clear_pending_stock_selection()
        return format_stock_selection_message(normalized_query, candidates)

    state.set_pending_stock_selection(
        query=normalized_query,
        command_name="stock_lookup",
        candidates=[
            PendingStockSelectionCandidate(
                stock_code=candidate.stock_code,
                stock_name=candidate.stock_name,
                market_type=candidate.market_type,
                source_url=candidate.source_url,
            )
            for candidate in candidates
        ],
        expires_at=now + timedelta(minutes=5),
    )
    return format_stock_selection_message(normalized_query, candidates)


def _build_stock_selection_followup_response(
    config: RuntimeConfig,
    state: TelegramControlState,
    *,
    selection_text: str | None,
    now: datetime,
) -> str:
    pending = state.pending_stock_selection
    if pending is None:
        return "\n".join(
            [
                "선택 중인 종목이 없습니다.",
                "/종목검색 삼성전자 또는 /종목검색 005930",
            ]
        )

    if pending.is_expired(now):
        state.clear_pending_stock_selection()
        return "\n".join(
            [
                "종목 선택이 만료되었습니다.",
                f"/종목검색 {pending.query}",
            ]
        )

    if not selection_text or not selection_text.isdigit():
        return _build_pending_stock_selection_retry_message(pending)

    selection_index = int(selection_text)
    if selection_index < 1 or selection_index > len(pending.candidates):
        return _build_pending_stock_selection_retry_message(pending)

    selected = pending.candidates[selection_index - 1]
    state.clear_pending_stock_selection()
    return _build_stock_lookup_result_message(
        config,
        stock_code=selected.stock_code,
        lookback_days=15,
        entry_limit=5,
    )


def _build_pending_stock_selection_retry_message(pending: PendingStockSelection) -> str:
    candidates = [
        StockCodeLookupEntry(
            stock_code=candidate.stock_code,
            stock_name=candidate.stock_name,
            market_type=candidate.market_type,
            source_url=candidate.source_url,
        )
        for candidate in pending.candidates
    ]
    return "\n".join(
        [
            format_stock_selection_message(pending.query, candidates),
            "",
            "후보 번호 범위 안에서 숫자만 입력해주세요.",
        ]
    )


def _build_stock_lookup_result_message(
    config: RuntimeConfig,
    *,
    stock_code: str,
    lookback_days: int,
    entry_limit: int,
) -> str:
    normalized_stock_code = stock_code.strip().upper()

    try:
        result = fetch_stock_research_entries(
            normalized_stock_code,
            as_of_date=datetime.now(ZoneInfo(config.timezone)).date(),
            lookback_days=lookback_days,
            timeout_seconds=config.telegram_timeout_seconds,
        )
    except Exception as exc:
        return f"종목검색 실패: {exc}"

    quote = None
    try:
        quote = fetch_stock_quote_snapshot(
            normalized_stock_code,
            timeout_seconds=config.telegram_timeout_seconds,
        )
    except Exception:
        quote = None

    return format_stock_research_lookup_message(
        result.stock_code,
        result.stock_name,
        list(result.entries),
        lookback_days=lookback_days,
        quote=quote,
        entry_limit=entry_limit,
    )
