def _build_memo_command_response(
    config: RuntimeConfig,
    *,
    memo_text: str | None,
    now: datetime,
    update_id: int | None = None,
    state: TelegramControlState | None = None,
) -> str:
    normalized_text = (memo_text or "").strip()
    if not normalized_text:
        return "\n".join(
            [
                "사용법",
                "/메모 웹뷰에 섹터별 정리 추가",
            ]
        )

    if update_id is not None and state is not None and state.has_applied_memo_update(update_id):
        return "메모 완료"

    memo_path = config.data_dir / "operator_memos.md"
    memo_path.parent.mkdir(parents=True, exist_ok=True)
    if not memo_path.exists():
        memo_path.write_text("# Operator Memos\n\n", encoding="utf-8")

    timestamp = now.strftime("%y.%m.%d %H:%M")
    with memo_path.open("a", encoding="utf-8") as file:
        file.write(f"- [ ] {timestamp} | {normalized_text}\n")

    if update_id is not None and state is not None:
        state.mark_memo_update_applied(update_id)

    return "메모 완료"


def _build_progress_request_command_response(
    config: RuntimeConfig,
    *,
    repository: StockMonitorRepository | None = None,
    request_text: str | None,
    now: datetime,
    update_id: int | None = None,
    state: TelegramControlState | None = None,
) -> str:
    normalized_text = " ".join((request_text or "").strip().split())
    if not normalized_text:
        return "\n".join(
            [
                "사용법",
                "/진행 KRX 2026-05-18 OpenAPI 상태 확인",
                "",
                "요청은 작업 큐에 저장되고, 완료 보고는 Codex가 처리 후 다시 보냅니다.",
            ]
        )

    auto_action = _progress_auto_action_key(normalized_text)
    if repository is not None and auto_action is not None:
        if update_id is not None and state is not None and state.has_applied_progress_update(update_id):
            return _format_progress_auto_run_response(
                ProgressAutoRunResult(
                    title=_progress_auto_action_title(auto_action),
                    summary="이미 처리된 요청입니다.",
                    elapsed_seconds=0.0,
                    status="completed",
                )
            )
        result = _run_progress_auto_action(
            config,
            repository,
            action_key=auto_action,
            now=now,
        )
        if update_id is not None and state is not None and result.status.lower() not in {"failed", "error"}:
            state.mark_progress_update_applied(update_id)
        return _format_progress_auto_run_response(result)

    if repository is not None and _is_health_progress_request(normalized_text):
        return _build_progress_health_diagnosis_response(config, repository, now=now)

    task_id = f"P{update_id}" if update_id is not None else f"P{now.strftime('%Y%m%d%H%M%S')}"
    if update_id is not None and state is not None and state.has_applied_progress_update(update_id):
        return "\n".join(
            [
                f"작업 요청 {task_id} 접수 완료",
                "- 상태: queued",
                "- 다음: Codex가 operator-task-next로 확인 후 진행",
            ]
        )

    record = {
        "task_id": task_id,
        "status": "queued",
        "request_text": normalized_text,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
        "source": "telegram",
        "telegram_update_id": update_id,
    }
    _append_operator_task_record(_operator_task_queue_path(config), record)
    if update_id is not None and state is not None:
        state.mark_progress_update_applied(update_id)

    return "\n".join(
        [
            f"작업 요청 {task_id} 접수 완료",
            "- 상태: queued",
            "- 범위: operator task queue",
            "- 완료 후 작업 요약과 완료도를 다시 보냅니다.",
        ]
    )


@dataclass(frozen=True)
class ProgressAutoRunResult:
    title: str
    summary: str
    elapsed_seconds: float
    status: str = "completed"


_PROGRESS_AUTO_ACTION_TITLES = {
    "manual_poll": "오늘 리포트 수집",
    "ops_readiness": "운영 점검",
    "db_verify": "DB 검증",
    "web_view_check": "웹뷰 확인",
    "operator_task_next": "해야 할 일 확인",
}


def _progress_auto_action_key(text: str) -> str | None:
    compact = text.replace(" ", "").replace("_", "").replace("-", "").lower()
    if any(
        marker in compact
        for marker in (
            "오늘리포트수집",
            "리포트수집",
            "누락리포트복구",
            "manualpoll",
            "poll",
        )
    ):
        return "manual_poll"
    if any(marker in compact for marker in ("운영점검", "운영상태점검", "opsreadiness", "readiness", "준비상태")):
        return "ops_readiness"
    if any(marker in compact for marker in ("db검증", "디비검증", "dbverify")):
        return "db_verify"
    if any(marker in compact for marker in ("웹뷰확인", "웹뷰점검", "webviewcheck", "webview")):
        return "web_view_check"
    if any(marker in compact for marker in ("해야할일", "작업확인", "tasknext", "operatortasknext")):
        return "operator_task_next"
    return None


def _progress_auto_action_title(action_key: str) -> str:
    return _PROGRESS_AUTO_ACTION_TITLES.get(action_key, "진행 작업")


def _normalize_progress_auto_run_result(
    value: ProgressAutoRunResult | dict[str, object],
    *,
    fallback_title: str,
    fallback_elapsed_seconds: float,
) -> ProgressAutoRunResult:
    if isinstance(value, ProgressAutoRunResult):
        return value
    return ProgressAutoRunResult(
        title=str(value.get("title") or fallback_title),
        summary=str(value.get("summary") or "-"),
        elapsed_seconds=float(value.get("elapsed_seconds") or fallback_elapsed_seconds),
        status=str(value.get("status") or "completed"),
    )


def _run_progress_auto_action(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    action_key: str,
    now: datetime,
) -> ProgressAutoRunResult:
    title = _progress_auto_action_title(action_key)
    started = time.perf_counter()
    try:
        if action_key == "manual_poll":
            result = _run_progress_manual_poll_recovery(config, repository, now=now, limit=200)
        elif action_key == "ops_readiness":
            result = _run_progress_ops_readiness(config, repository)
        elif action_key == "db_verify":
            result = _run_progress_db_verify(repository)
        elif action_key == "web_view_check":
            result = _run_progress_web_view_check(config, repository)
        elif action_key == "operator_task_next":
            result = _run_progress_operator_task_next(config)
        else:
            return ProgressAutoRunResult(
                title=title,
                summary="허용된 자동 작업이 아닙니다. 작업 큐에 남겨 Codex가 확인해야 합니다.",
                elapsed_seconds=time.perf_counter() - started,
                status="blocked",
            )
        return _normalize_progress_auto_run_result(
            result,
            fallback_title=title,
            fallback_elapsed_seconds=time.perf_counter() - started,
        )
    except Exception as exc:
        return ProgressAutoRunResult(
            title=title,
            summary=f"실패: {_compact_telegram_detail(exc, limit=120)}",
            elapsed_seconds=time.perf_counter() - started,
            status="failed",
        )


def _format_progress_auto_run_response(result: ProgressAutoRunResult) -> str:
    status = result.status.lower()
    if status in {"failed", "error"}:
        header = "진행 실패"
    elif status in {"blocked", "skipped"}:
        header = "진행 보류"
    else:
        header = "진행 완료"
    return "\n".join(
        [
            header,
            f"작업: {result.title}",
            f"소요: {max(0.0, result.elapsed_seconds):.1f}초",
            f"결과: {result.summary}",
        ]
    )


def _run_progress_manual_poll_recovery(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    now: datetime,
    limit: int,
) -> ProgressAutoRunResult:
    started = time.perf_counter()
    repository.initialize()
    reports, _inspection = fetch_reports(config, limit=limit, headless=True)
    if not reports:
        return ProgressAutoRunResult(
            title="오늘 리포트 수집",
            summary="파싱된 리포트가 없어 저장하지 않았습니다.",
            elapsed_seconds=time.perf_counter() - started,
            status="blocked",
        )

    insert_result = repository.insert_reports(reports, queue_intraday_alerts=False)
    repository.record_operation_event(
        _operation_event(
            config,
            component="poll",
            event_type="manual-poll",
            status="success",
            detail=(
                "source=telegram-progress; "
                f"attempted={insert_result.attempted}; inserted={insert_result.inserted}; intraday_batches=0"
            ),
        )
    )
    rebuilt = []
    for business_date in sorted({report.business_date for report in reports}):
        summaries = repository.rebuild_daily_summaries(business_date)
        rebuilt.append((business_date, len(summaries)))
    latest_rebuilt = rebuilt[-1] if rebuilt else (now.date(), 0)
    duplicate_count = insert_result.attempted - insert_result.inserted
    return ProgressAutoRunResult(
        title="오늘 리포트 수집",
        summary=(
            f"신규 {insert_result.inserted}건 / 중복 {duplicate_count}건 / "
            f"최신요약 {latest_rebuilt[0].isoformat()} {latest_rebuilt[1]}개"
        ),
        elapsed_seconds=time.perf_counter() - started,
    )


def _run_progress_ops_readiness(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
) -> ProgressAutoRunResult:
    started = time.perf_counter()
    payload = _build_ops_readiness_payload(
        config,
        repository,
        recent_business_days=4,
        stock_limit=20,
        api_perf_log_path=None,
    )
    qa = payload.get("web_view_value_qa") if isinstance(payload.get("web_view_value_qa"), dict) else {}
    summary = (
        f"ready={str(payload.get('ready')).lower()} / "
        f"web-view issue {qa.get('issue_count', 0)} warning {qa.get('warning_count', 0)}"
    )
    return ProgressAutoRunResult(
        title="운영 점검",
        summary=summary,
        elapsed_seconds=time.perf_counter() - started,
        status="completed" if payload.get("ready") else "blocked",
    )


def _run_progress_db_verify(repository: StockMonitorRepository) -> ProgressAutoRunResult:
    started = time.perf_counter()
    payload = _build_db_verify_payload(repository)
    ready = _db_verify_payload_ready(payload)
    summary = (
        f"integrity={payload.get('integrity_check')} / "
        f"pending_migrations={len(payload.get('pending_migrations') or [])} / "
        f"flow_issues={payload.get('investor_flow_quality_issue_total')}"
    )
    return ProgressAutoRunResult(
        title="DB 검증",
        summary=summary,
        elapsed_seconds=time.perf_counter() - started,
        status="completed" if ready else "blocked",
    )


def _run_progress_web_view_check(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
) -> ProgressAutoRunResult:
    started = time.perf_counter()
    payload = _build_web_view_startup_fallback_status(config, repository)
    health = payload.get("health_check") if isinstance(payload.get("health_check"), dict) else {}
    summary = (
        f"ready={str(payload.get('ready')).lower()} / "
        f"health={health.get('status', '-')} / "
        f"blocking={payload.get('blocking_item') or '-'}"
    )
    return ProgressAutoRunResult(
        title="웹뷰 확인",
        summary=summary,
        elapsed_seconds=time.perf_counter() - started,
        status="completed" if int(payload.get("issue_count") or 0) == 0 else "blocked",
    )


def _run_progress_operator_task_next(config: RuntimeConfig) -> ProgressAutoRunResult:
    started = time.perf_counter()
    payload = _build_operator_task_next_snapshot(_operator_task_queue_path(config), include_completed=False)
    task = payload.get("next_task") if isinstance(payload.get("next_task"), dict) else None
    summary = f"pending={payload.get('pending_count', 0)}"
    if task:
        summary = f"{summary} / next={task.get('task_id') or '-'}"
    return ProgressAutoRunResult(
        title="해야 할 일 확인",
        summary=summary,
        elapsed_seconds=time.perf_counter() - started,
    )


def _is_health_progress_request(text: str) -> bool:
    compact = text.replace(" ", "").lower()
    markers = (
        "건강상태",
        "상태체크",
        "왜돌",
        "왜안",
        "안돌",
        "돌지않",
        "오늘리포트",
        "리포트안",
        "healthcheck",
        "why",
    )
    return any(marker in compact for marker in markers)


def _build_progress_health_diagnosis_response(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    now: datetime,
) -> str:
    try:
        snapshot = build_operator_status_snapshot(config, repository, limit=5, now=now)
    except Exception as exc:
        return "\n".join(["진행 진단", "", f"상태 조회 실패: {exc}"])

    health = snapshot.get("health", {}) if isinstance(snapshot.get("health"), dict) else {}
    reports = snapshot.get("reports_by_date", []) if isinstance(snapshot.get("reports_by_date"), list) else []
    summaries = snapshot.get("summaries_by_date", []) if isinstance(snapshot.get("summaries_by_date"), list) else []
    latest_report = reports[0] if reports else None
    latest_summary = summaries[0] if summaries else None
    today_report = next(
        (item for item in reports if isinstance(item, dict) and item.get("business_date") == now.date().isoformat()),
        None,
    )
    today_count = int(today_report.get("count") or 0) if isinstance(today_report, dict) else 0

    lines = [
        "진행 진단",
        "",
        f"기준: {now.strftime('%Y-%m-%d %H:%M')}",
        f"건강 상태: {health.get('level', 'unknown')}",
    ]
    if health.get("summary"):
        lines.append(f"요약: {health.get('summary')}")
    if _scheduler_metadata_access_denied(snapshot):
        lines.append("해석: 스케줄러 메타데이터 접근 거부가 health fail에 포함됐습니다.")
        lines.append("실제 실행 여부는 아래 최근 이벤트와 live observation을 같이 봐야 합니다.")
    lines.extend(
        [
            f"오늘 리포트: {now.date().isoformat()} / {today_count}건",
            f"리포트 최신: {_compact_count_by_date(latest_report)}",
            f"요약 최신: {_compact_count_by_date(latest_summary)}",
        ]
    )

    failure = _latest_failed_status_event(snapshot)
    if failure:
        component = str(failure.get("component") or "-")
        event_time = str(failure.get("event_time") or "-")
        detail = _compact_telegram_detail(failure.get("detail") or failure.get("detail_display") or "-")
        lines.extend(["", f"최근 실패: {component} / {event_time}", detail])
        if "playwright is not installed" in detail.lower():
            lines.append("우선 원인: scheduled poll 실행 Python 환경에 Playwright가 없습니다.")
            lines.append("조치: 해당 Python에 Playwright/Chromium 설치 후 poll 재확인.")

    recovery_actions = snapshot.get("recovery_actions") if isinstance(snapshot.get("recovery_actions"), list) else []
    if recovery_actions:
        first = recovery_actions[0]
        if isinstance(first, dict) and first.get("detail"):
            lines.extend(["", f"다음 조치: {_compact_telegram_detail(first.get('detail'))}"])
    return "\n".join(lines)


def _scheduler_metadata_access_denied(snapshot: dict[str, object]) -> bool:
    live_observation = snapshot.get("live_observation")
    if isinstance(live_observation, dict) and live_observation.get("scheduler_metadata_status") == "access_denied":
        return True
    scheduler_tasks = snapshot.get("scheduler_tasks")
    if not isinstance(scheduler_tasks, list):
        return False
    for task in scheduler_tasks:
        if isinstance(task, dict) and task.get("status_class") == "access_denied":
            return True
    return False


def _latest_failed_status_event(snapshot: dict[str, object]) -> dict[str, object] | None:
    recent_events = snapshot.get("recent_events") if isinstance(snapshot.get("recent_events"), list) else []
    for event in recent_events:
        if isinstance(event, dict) and str(event.get("status") or "").lower() == "failed":
            return event
    live_observation = snapshot.get("live_observation")
    if not isinstance(live_observation, dict):
        return None
    components = live_observation.get("components")
    if not isinstance(components, dict):
        return None
    for key in ("poll", "notify", "krx_daily_backfill", "telegram_command_loop"):
        component = components.get(key)
        if not isinstance(component, dict):
            continue
        event = component.get("last_event")
        if isinstance(event, dict) and str(event.get("status") or "").lower() == "failed":
            return event
    return None


def _compact_telegram_detail(value: object, *, limit: int = 180) -> str:
    text = " ".join(str(value or "-").split())
    if len(text) <= limit:
        return text
    return f"{text[: limit - 1]}…"


def _build_check_command_response(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    check_text: str | None,
    now: datetime,
    update_id: int | None = None,
    state: TelegramControlState | None = None,
) -> str:
    normalized = " ".join((check_text or "").strip().split())
    if not normalized:
        return "\n".join(
            [
                "사용법",
                "/체크 로그인",
            ]
        )

    compact = normalized.replace(" ", "")
    lowered = normalized.lower()
    if compact not in {"로그인", "로그인완료", "연결", "연결완료"} and lowered not in {
        "login",
        "login-ok",
        "login ok",
        "connected",
    }:
        return "\n".join(
            [
                "체크 항목을 확인할 수 없습니다.",
                "",
                "사용법",
                "/체크 로그인",
            ]
        )

    already_applied = update_id is not None and state is not None and state.has_applied_check_update(update_id)
    if not already_applied:
        repository.record_operation_event(
            _operation_event(
                config,
                component="krx-flow",
                event_type="login-ack",
                status="acknowledged",
                detail=f"operator acknowledged KRX login readiness at {now.strftime('%Y-%m-%d %H:%M:%S')}",
            )
        )
        if update_id is not None and state is not None:
            state.mark_check_update_applied(update_id)
    return "\n".join(
        [
            "KRX 로그인 확인 접수",
            "",
            "운영자 확인: 로그인",
            "다음 단계: 16:50 수급 dry-run에서 실제 연결을 판정합니다.",
            "정상 응답이면 연결이 정상적입니다.",
            "LOGOUT/오류면 로그인정보 확인불가로 안내합니다.",
        ]
    )


def _build_read_only_status_command_response(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    command: str,
    now: datetime | None = None,
) -> str:
    current = now or datetime.now(ZoneInfo(config.timezone))
    today = current.date()
    if command == "webview_url":
        return "\n".join(
            [
                "웹뷰주소 안내",
                "",
                f"사용자용 웹뷰: {_web_view_default_base_url()}",
                "외부 공유 URL은 아직 설정되지 않았습니다.",
                "관리자 화면은 Telegram으로 열지 않습니다.",
            ]
        )
    if command == "today_status":
        skip_reason = _scheduled_skip_reason(config, today, repository)
        return "\n".join(
            [
                "오늘돌아? 안내",
                "",
                f"기준일: {today.isoformat()}",
                f"실행 가능: {'예' if not skip_reason else '아니오'}",
                f"사유: {skip_reason or '영업일/실행 제외 조건 없음'}",
            ]
        )
    try:
        snapshot = build_operator_status_snapshot(config, repository, limit=3, now=current)
    except Exception as exc:
        return "\n".join(["상태 안내", "", f"상태 조회 실패: {exc}"])
    if command == "schedule_status":
        rows = []
        for task in snapshot.get("scheduler_tasks", []):
            rows.append(
                f"- {task.get('task_key') or task.get('task_name')}: "
                f"{task.get('status_class') or 'unknown'} / {task.get('status_reason') or '-'}"
            )
        return "\n".join(["스케줄상태 안내", "", *(rows or ["스케줄러 상태 정보가 없습니다."])])
    health = snapshot.get("health", {})
    reports = snapshot.get("reports_by_date", [])
    summaries = snapshot.get("summaries_by_date", [])
    latest_report = reports[0] if reports else None
    latest_summary = summaries[0] if summaries else None
    lines = [
        "상태 안내",
        "",
        f"건강 상태: {health.get('level', 'unknown')}",
    ]
    if health.get("summary"):
        lines.append(f"요약: {health.get('summary')}")
    if _scheduler_metadata_access_denied(snapshot):
        lines.append("주의: 스케줄러 메타데이터 접근 거부가 포함됐습니다.")
        lines.append("등록 실패가 아니라 조회 권한 문제일 수 있어 최근 실행 이벤트를 같이 확인하세요.")
    failure = _latest_failed_status_event(snapshot)
    if failure:
        component = str(failure.get("component") or "-")
        detail = _compact_telegram_detail(failure.get("detail") or failure.get("detail_display") or "-")
        lines.append(f"최근 실패: {component} / {detail}")
    lines.extend(
        [
            f"리포트 최신: {_compact_count_by_date(latest_report)}",
            f"요약 최신: {_compact_count_by_date(latest_summary)}",
            f"DB 존재: {snapshot.get('db_path_exists')}",
        ]
    )
    return "\n".join(lines)


def _compact_count_by_date(item: object) -> str:
    if isinstance(item, dict):
        return f"{item.get('business_date') or '-'} / {item.get('count', 0)}건"
    if isinstance(item, (tuple, list)) and len(item) >= 2:
        raw_date = item[0].isoformat() if hasattr(item[0], "isoformat") else str(item[0])
        return f"{raw_date} / {item[1]}건"
    return "-"


def _build_stock_code_command_response(
    config: RuntimeConfig,
    *,
    query: str | None,
) -> str:
    normalized_query = (query or "").strip()
    if not normalized_query:
        return "\n".join(
            [
                "사용법",
                "/종목코드 삼성전자",
                "종목명으로 종목코드 후보를 찾습니다.",
            ]
        )

    try:
        candidates = fetch_stock_code_candidates(
            normalized_query,
            timeout_seconds=config.telegram_timeout_seconds,
        )
    except Exception as exc:
        return f"종목코드 조회 실패: {exc}"

    return format_stock_code_lookup_message(normalized_query, candidates)


def _run_process_intraday_alerts(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    dry_run: bool,
    batch_ids: set[str] | None = None,
) -> int:
    batches = repository.list_pending_intraday_alert_batches()
    if batch_ids is not None:
        batches = [batch for batch in batches if batch.batch_id in batch_ids]
    if not batches:
        print("No pending intraday alert batches.")
        return 0

    state = load_control_state(config.telegram_control_state_path)
    default_limit = _effective_int_setting(config, repository, "notification_default_limit")

    if not config.telegram_bot_token or not config.telegram_chat_id:
        if dry_run:
            for batch in batches:
                reports = repository.list_reports_for_intraday_batch(batch.batch_id)
                quotes_by_stock_code = _fetch_intraday_quotes_by_stock_code(config, reports)
                print(
                    format_intraday_batch_message(
                        batch.created_at,
                        reports,
                        quotes_by_stock_code=quotes_by_stock_code,
                        offset=0,
                        limit=default_limit,
                    )
                )
                print("")
            return 0
        raise RuntimeError(
            "Telegram configuration is missing. Set STOCK_MONITOR_TELEGRAM_BOT_TOKEN and "
            "STOCK_MONITOR_TELEGRAM_CHAT_ID."
        )

    processed = 0
    for batch in batches:
        reports = repository.list_reports_for_intraday_batch(batch.batch_id)
        if not reports:
            repository.mark_intraday_alert_batch_failed(
                batch.batch_id,
                attempted_at=datetime.now(ZoneInfo(config.timezone)),
                error_detail="No reports found for queued intraday batch.",
            )
            continue

        quotes_by_stock_code = _fetch_intraday_quotes_by_stock_code(config, reports, repository=repository)
        message = format_intraday_batch_message(
            batch.created_at,
            reports,
            quotes_by_stock_code=quotes_by_stock_code,
            offset=0,
            limit=default_limit,
        )
        if dry_run:
            print(message)
            print("")
            processed += 1
            continue

        attempted_at = datetime.now(ZoneInfo(config.timezone))
        try:
            message_id = send_telegram_message(
                config.telegram_bot_token,
                config.telegram_chat_id,
                message,
                timeout_seconds=config.telegram_timeout_seconds,
                max_retries=config.telegram_max_retries,
                retry_delay_seconds=config.telegram_retry_delay_seconds,
            )
        except Exception as exc:
            repository.mark_intraday_alert_batch_failed(
                batch.batch_id,
                attempted_at=attempted_at,
                error_detail=str(exc),
            )
            repository.record_operation_event(
                _operation_event(
                    config,
                    component="intraday",
                    event_type="send",
                    status="failed",
                    business_date=batch.business_date,
                    detail=str(exc),
                )
            )
            continue

        repository.mark_intraday_alert_batch_sent(
            batch.batch_id,
            sent_at=attempted_at,
            message_id=message_id,
        )
        repository.record_delivery(
            DeliveryLog(
                business_date=batch.business_date,
                channel="telegram_intraday",
                status="sent_batch",
                delivered_at=attempted_at,
                message_id=message_id,
                detail=f"intraday batch alert ({len(reports)} reports)",
            )
        )
        repository.record_operation_event(
            _operation_event(
                config,
                component="intraday",
                event_type="send",
                status="sent",
                business_date=batch.business_date,
                detail=f"batch={batch.batch_id}; reports={len(reports)}",
            )
        )
        total_stock_blocks = len(build_daily_summaries(reports, generated_at=batch.created_at))
        displayed_count = min(default_limit, total_stock_blocks)
        if displayed_count < total_stock_blocks:
            state.set_active_intraday_delivery(
                batch_id=batch.batch_id,
                created_at=batch.created_at,
                delivered_count=displayed_count,
            )
            processed += 1
            break
        else:
            state.clear_active_intraday_delivery()
        processed += 1

    save_control_state(config.telegram_control_state_path, state)
    print(f"Processed {processed} intraday alert batch(es).")
    return processed


def _send_intraday_empty_notification(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    *,
    polled_at: datetime | None = None,
    dry_run: bool = False,
) -> int:
    message_time = polled_at or datetime.now(ZoneInfo(config.timezone))
    message = format_intraday_empty_message(message_time)
    if dry_run:
        print(message)
        return 0

    if not config.telegram_bot_token or not config.telegram_chat_id:
        raise RuntimeError(
            "Telegram configuration is missing. Set STOCK_MONITOR_TELEGRAM_BOT_TOKEN and "
            "STOCK_MONITOR_TELEGRAM_CHAT_ID."
        )

    message_id = send_telegram_message(
        config.telegram_bot_token,
        config.telegram_chat_id,
        message,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    repository.record_delivery(
        DeliveryLog(
            business_date=message_time.date(),
            channel="telegram_intraday",
            status="sent_empty",
            delivered_at=message_time,
            message_id=message_id,
            detail="intraday empty alert",
        )
    )
    print(f"Intraday empty notification sent with message_id={message_id}")
    return 0


def _fetch_intraday_quotes_by_stock_code(
    config: RuntimeConfig,
    reports: list[Report],
    repository: StockMonitorRepository | None = None,
) -> dict[str, StockQuoteSnapshot]:
    quotes_by_stock_code: dict[str, StockQuoteSnapshot] = {}
    unique_codes = sorted({report.stock_code for report in reports if report.stock_code})
    for stock_code in unique_codes:
        try:
            quotes_by_stock_code[stock_code] = fetch_stock_quote_snapshot(
                stock_code,
                timeout_seconds=config.telegram_timeout_seconds,
            )
        except Exception:
            continue
    _cache_quote_snapshots(repository, quotes_by_stock_code)
    return quotes_by_stock_code


def _fetch_daily_summary_quotes_by_stock_code(
    config: RuntimeConfig,
    summaries: list[object],
    repository: StockMonitorRepository | None = None,
) -> dict[str, StockQuoteSnapshot]:
    quotes_by_stock_code: dict[str, StockQuoteSnapshot] = {}
    unique_codes = sorted({summary.stock_code for summary in summaries if getattr(summary, "stock_code", None)})
    for stock_code in unique_codes:
        try:
            quotes_by_stock_code[stock_code] = fetch_stock_quote_snapshot(
                stock_code,
                timeout_seconds=config.telegram_timeout_seconds,
            )
        except Exception:
            continue
    _cache_quote_snapshots(repository, quotes_by_stock_code)
    if repository is not None:
        quotes_by_stock_code = _fill_daily_summary_quote_metadata_fallbacks(repository, summaries, quotes_by_stock_code)
    return quotes_by_stock_code


def _fill_daily_summary_quote_metadata_fallbacks(
    repository: StockMonitorRepository,
    summaries: list[object],
    quotes_by_stock_code: dict[str, StockQuoteSnapshot],
) -> dict[str, StockQuoteSnapshot]:
    merged = dict(quotes_by_stock_code)
    unique_codes = sorted({summary.stock_code for summary in summaries if getattr(summary, "stock_code", None)})
    for stock_code in unique_codes:
        if stock_code in merged:
            continue
        metadata = repository.get_stock_metadata(stock_code)
        if metadata is None:
            continue
        merged[stock_code] = StockQuoteSnapshot(
            stock_code=metadata.stock_code,
            stock_name=metadata.stock_name,
            sector_code=metadata.sector_code,
            sector_name=metadata.sector_name,
            current_price=None,
            market_status=None,
            trade_time=None,
            prev_close_price=None,
        )
    return merged


def _cache_quote_snapshots(
    repository: StockMonitorRepository | None,
    quotes_by_stock_code: dict[str, StockQuoteSnapshot],
) -> None:
    if repository is None or not quotes_by_stock_code:
        return
    updated_at = datetime.now(ZoneInfo(repository.timezone))
    repository.upsert_stock_metadata_many(
        [
            StockMetadata(
                stock_code=quote.stock_code,
                stock_name=quote.stock_name,
                sector_code=quote.sector_code,
                sector_name=quote.sector_name,
                updated_at=updated_at,
                source="naver_quote",
            )
            for quote in quotes_by_stock_code.values()
        ]
    )


def _try_process_intraday_paging_command(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    state: TelegramControlState,
    *,
    command: str,
) -> bool:
    if not state.active_intraday_batch_id or not state.active_intraday_created_at:
        state.clear_active_intraday_delivery()
        return False

    reports = repository.list_reports_for_intraday_batch(state.active_intraday_batch_id)
    if not reports:
        state.clear_active_intraday_delivery()
        return False

    created_at = datetime.fromisoformat(state.active_intraday_created_at)
    total_stock_blocks = len(build_daily_summaries(reports, generated_at=created_at))
    current_offset = state.active_intraday_delivered_count
    default_limit = _effective_int_setting(config, repository, "notification_default_limit")
    if command == "reset":
        current_offset = 0
        limit = default_limit
    elif command == "next":
        limit = default_limit
    else:
        limit = None

    if current_offset >= total_stock_blocks:
        send_telegram_message(
            config.telegram_bot_token,
            config.telegram_chat_id,
            "추가로 표시할 종목이 없습니다.\n/처음 또는 /명령어를 입력해보세요.",
            timeout_seconds=config.telegram_timeout_seconds,
            max_retries=config.telegram_max_retries,
            retry_delay_seconds=config.telegram_retry_delay_seconds,
        )
        return True

    quotes_by_stock_code = _fetch_intraday_quotes_by_stock_code(config, reports, repository=repository)
    message = format_intraday_batch_message(
        created_at,
        reports,
        quotes_by_stock_code=quotes_by_stock_code,
        offset=current_offset,
        limit=limit,
    )
    send_telegram_message(
        config.telegram_bot_token,
        config.telegram_chat_id,
        message,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    delivered_now = total_stock_blocks - current_offset if limit is None else min(
        limit,
        total_stock_blocks - current_offset,
    )
    state.set_active_intraday_delivery(
        batch_id=state.active_intraday_batch_id,
        created_at=created_at,
        delivered_count=current_offset + delivered_now,
    )
    return True


def _try_process_intraday_paging_command_with_fallback(
    config: RuntimeConfig,
    repository: StockMonitorRepository,
    state: TelegramControlState,
    *,
    command: str,
) -> bool:
    if not state.active_intraday_batch_id or not state.active_intraday_created_at:
        state.clear_active_intraday_delivery()
        return False

    reports = repository.list_reports_for_intraday_batch(state.active_intraday_batch_id)
    if not reports:
        state.clear_active_intraday_delivery()
        return False

    created_at = datetime.fromisoformat(state.active_intraday_created_at)
    total_stock_blocks = len(build_daily_summaries(reports, generated_at=created_at))
    current_offset = state.active_intraday_delivered_count
    default_limit = _effective_int_setting(config, repository, "notification_default_limit")
    if command == "reset":
        current_offset = 0
        limit = default_limit
    elif command == "next":
        limit = default_limit
    else:
        limit = None

    if current_offset >= total_stock_blocks:
        state.clear_active_intraday_delivery()
        return False

    quotes_by_stock_code = _fetch_intraday_quotes_by_stock_code(config, reports, repository=repository)
    message = format_intraday_batch_message(
        created_at,
        reports,
        quotes_by_stock_code=quotes_by_stock_code,
        offset=current_offset,
        limit=limit,
    )
    send_telegram_message(
        config.telegram_bot_token,
        config.telegram_chat_id,
        message,
        timeout_seconds=config.telegram_timeout_seconds,
        max_retries=config.telegram_max_retries,
        retry_delay_seconds=config.telegram_retry_delay_seconds,
    )
    delivered_now = total_stock_blocks - current_offset if limit is None else min(
        limit,
        total_stock_blocks - current_offset,
    )
    updated_delivered_count = current_offset + delivered_now
    if updated_delivered_count >= total_stock_blocks:
        state.clear_active_intraday_delivery()
    else:
        state.set_active_intraday_delivery(
            batch_id=state.active_intraday_batch_id,
            created_at=created_at,
            delivered_count=updated_delivered_count,
        )
    return True


def _resolve_active_business_date(config: RuntimeConfig, state: TelegramControlState) -> date:
    if state.active_business_date:
        return date.fromisoformat(state.active_business_date)
    return previous_business_day(
        datetime.now(ZoneInfo(config.timezone)).date(),
        config.holiday_overrides,
    )
